let supabase = null;
let appMode = "real";
let isDemo = false;

const supabaseReady = (async () => {
  await loadRuntimeEnv();
  refreshConfig();
  appMode = APP_MODE;
  isDemo = APP_MODE === "demo";

  const client = await makeClient();
  if (!client) {
    dlog("[config] missing Supabase env");
    return null;
  }

  supabase = client;
  return client;
})();

