const WORK_ORDER_TYPES = ["INSTALL", "TROUBLE_TICKET", "MAINTENANCE", "SURVEY"];
const WORK_ORDER_STATUSES = ["NEW", "ASSIGNED", "EN_ROUTE", "ON_SITE", "IN_PROGRESS", "BLOCKED", "COMPLETE", "CANCELED"];

function normalizeRole(role){
  if (!state.user) return null;
  return String(role || "").trim().toUpperCase() || AUTHENTICATED_ACCESS_CODE;
}

function isPrivilegedIdentity(value){
  const text = String(value || "").trim().toLowerCase();
  if (!text) return false;
  return /\b(admin|owner|support)\b/.test(text);
}

function resolveProvisionedRoleCode(identity){
  if (!identity) return getRoleCode();
  return getRoleCode();
}

function getRoleCode(member = state.profile){
  if (!state.user) return null;
  const role = String(member?.role || "").trim().toUpperCase();
  return role || AUTHENTICATED_ACCESS_CODE;
}

function isEffectiveRootRole(){
  if (getRoleCode() === "ROOT") return true;
  const authoritativeRootCheck = SpecCom.helpers?.isRoot;
  return typeof authoritativeRootCheck === "function" && authoritativeRootCheck();
}

function bypassesFieldDayWorkflow(){
  return isEffectiveRootRole();
}

function canUseMasterLocationSearch(){
  if (isBreakGlassUser()) return true;
  return ["ROOT", "ADMIN"].includes(String(getRoleCode() || "").toUpperCase());
}

function isTechnician(x){
  return getRoleCode() === "TECHNICIAN";
}

function isSplicer(x){
  return getRoleCode() === "SPLICER";
}

function isPrime(x){
  return getRoleCode() === "PRIME";
}

function isTds(x){
  return getRoleCode() === "TDS";
}

function isSubcontractorRole(roleCode = getRoleCode()){
  const role = String(roleCode || "").trim().toUpperCase();
  return role === "SUBCONTRACTOR" || role === "SUB";
}

function isFieldSubcontractorMode(){
  const userId = String(state.user?.id || state.session?.user?.id || "").trim().toLowerCase();
  return Boolean(userId && FIELD_SUBCONTRACTOR_USER_IDS.has(userId));
}

function isOnboardingAdminRole(roleCode = getRoleCode()){
  const role = String(roleCode || "").trim().toUpperCase();
  return ["ROOT", "OWNER", "ADMIN", "OFFICE", "SUPPORT"].includes(role);
}

function formatRoleLabel(roleCode){
  if (!state.user) return "-";
  const labels = {
    ROOT: "Root", OWNER: "Owner", ADMIN: "Admin",
    OFFICE: "Office", SUPPORT: "Support",
    PRIME: "Prime", TDS: "TDS", SUB: "Sub",
    SUBCONTRACTOR: "Subcontractor",
    SPLICER: "Splicer", TECHNICIAN: "Technician",
  };
  return labels[String(roleCode || "").toUpperCase()] || roleCode || "Authenticated";
}

