function getKmzPhotoOverridesStorageKey(projectId = state.activeProject?.id || ""){
  return `${KMZ_PHOTO_OVERRIDES_KEY_PREFIX}${String(projectId || "none")}`;
}

function loadKmzPhotoOverridesForActiveProject(){
  state.map.kmzPhotoOverrides = new Map();
  const raw = safeLocalStorageGet(getKmzPhotoOverridesStorageKey());
  if (!raw) return;
  try{
    const parsed = JSON.parse(raw);
    if (!parsed || typeof parsed !== "object") return;
    Object.entries(parsed).forEach(([featureId, urls]) => {
      const key = String(featureId || "").trim();
      if (!key || !Array.isArray(urls)) return;
      const cleanUrls = Array.from(new Set(
        urls
          .map((url) => String(url || "").trim())
          .filter((url) => /^https?:\/\//i.test(url))
      ));
      if (cleanUrls.length){
        state.map.kmzPhotoOverrides.set(key, cleanUrls);
      }
    });
  } catch {}
}

function saveKmzPhotoOverridesForActiveProject(){
  const payload = {};
  state.map.kmzPhotoOverrides.forEach((urls, featureId) => {
    const key = String(featureId || "").trim();
    if (!key || !Array.isArray(urls) || !urls.length) return;
    payload[key] = urls;
  });
  safeLocalStorageSet(getKmzPhotoOverridesStorageKey(), JSON.stringify(payload));
}

function toJsonClone(value, fallback){
  try{
    const json = JSON.stringify(value);
    if (json == null) return fallback;
    const parsed = JSON.parse(json);
    return parsed == null ? fallback : parsed;
  } catch {
    return fallback;
  }
}

async function saveKmzSnapshotForProject(projectId, {
  rows = null,
  layerNames = null,
  folderTree = null,
  silent = true,
} = {}){
  const projectKey = String(projectId || "").trim();
  if (!projectKey || !state.client || isDemo) return { saved: false, reason: "unavailable" };
  const kmzRows = Array.isArray(rows)
    ? rows
    : Array.from(state.map.kmzFeatureRows?.values?.() || []);
  const payload = {
    project_id: projectKey,
    kmz_rows: toJsonClone(kmzRows, []),
    kmz_layer_names: Array.isArray(layerNames)
      ? layerNames.slice()
      : (Array.isArray(state.map.kmzLayerCatalog) ? state.map.kmzLayerCatalog.slice() : []),
    kmz_folder_tree: toJsonClone(
      folderTree != null ? folderTree : (state.map.kmzFolderTree || null),
      null
    ),
    updated_by: state.user?.id || null,
    updated_at: new Date().toISOString(),
  };
  const optionalColumns = ["updated_by", "updated_at", "kmz_folder_tree", "kmz_layer_names"];
  for (;;){
    const { error } = await state.client
      .from(KMZ_SNAPSHOT_TABLE)
      .upsert(payload, { onConflict: "project_id" });
    if (!error){
      return { saved: true, rows: Array.isArray(payload.kmz_rows) ? payload.kmz_rows.length : 0 };
    }
    if (isMissingTable(error)){
      return { saved: false, reason: "missing_table" };
    }
    let removed = false;
    for (const col of optionalColumns){
      if (Object.prototype.hasOwnProperty.call(payload, col) && isMissingColumnError(error, col)){
        delete payload[col];
        removed = true;
        break;
      }
    }
    if (removed) continue;
    if (!silent){
      toast("KMZ save failed", error.message || "Could not save KMZ snapshot.", "error");
    }
    return { saved: false, reason: "error", error };
  }
}

function queueSaveKmzSnapshotForActiveProject({ immediate = false, silent = true } = {}){
  if (isDemo) return;
  const projectId = state.activeProject?.id || null;
  if (!projectId || !state.client) return;
  if (state.map.kmzSnapshotSaveTimer){
    clearTimeout(state.map.kmzSnapshotSaveTimer);
    state.map.kmzSnapshotSaveTimer = null;
  }
  const runSave = () => {
    state.map.kmzSnapshotSaveTimer = null;
    void saveKmzSnapshotForProject(projectId, { silent });
  };
  if (immediate){
    runSave();
    return;
  }
  state.map.kmzSnapshotSaveTimer = setTimeout(runSave, KMZ_SNAPSHOT_SAVE_DEBOUNCE_MS);
}

function buildKmzRowsFromSnapshot(payload){
  const rows = Array.isArray(payload?.kmz_rows) ? payload.kmz_rows.slice() : [];
  try{
    Object.defineProperty(rows, "__kmlLayerNames", {
      value: Array.isArray(payload?.kmz_layer_names) ? payload.kmz_layer_names.slice() : [],
      enumerable: false,
      writable: true,
    });
    Object.defineProperty(rows, "__kmlFolderTree", {
      value: payload?.kmz_folder_tree && typeof payload.kmz_folder_tree === "object"
        ? payload.kmz_folder_tree
        : null,
      enumerable: false,
      writable: true,
    });
  } catch {}
  return rows;
}

async function loadKmzSnapshotForProject(projectId, { silent = true } = {}){
  const projectKey = String(projectId || "").trim();
  if (!projectKey || !state.client || isDemo){
    clearImportPreviewMarkers();
    return { loaded: false, reason: "unavailable" };
  }
  let data = null;
  let error = null;
  ({ data, error } = await state.client
    .from(KMZ_SNAPSHOT_TABLE)
    .select("kmz_rows, kmz_layer_names, kmz_folder_tree")
    .eq("project_id", projectKey)
    .maybeSingle());
  if (error && isMissingColumnError(error, "kmz_layer_names")){
    ({ data, error } = await state.client
      .from(KMZ_SNAPSHOT_TABLE)
      .select("kmz_rows, kmz_folder_tree")
      .eq("project_id", projectKey)
      .maybeSingle());
  }
  if (error && isMissingColumnError(error, "kmz_folder_tree")){
    ({ data, error } = await state.client
      .from(KMZ_SNAPSHOT_TABLE)
      .select("kmz_rows")
      .eq("project_id", projectKey)
      .maybeSingle());
  }
  if (error){
    if (isMissingTable(error) || isNoRowsError(error)){
      clearImportPreviewMarkers();
      return { loaded: false, reason: "missing_table" };
    }
    if (!silent){
      toast("KMZ load failed", error.message || "Could not load saved KMZ.", "error");
    }
    clearImportPreviewMarkers();
    return { loaded: false, reason: "error", error };
  }
  const rows = buildKmzRowsFromSnapshot(data || {});
  if (String(state.activeProject?.id || "") !== projectKey){
    return { loaded: false, reason: "stale_project" };
  }
  if (!rows.length){
    clearImportPreviewMarkers();
    return { loaded: false, reason: "empty" };
  }
  renderKmzPreviewFeatures(rows, "Saved KMZ");
  primeSitePopupCachesFromRuidosoEvidence(state.projectSites || []);
  if (state.map.instance){
    const visibleRows = getSiteSearchResultSet().rows;
    updateMapMarkers(visibleRows);
    renderDerivedMapLayers(visibleRows);
  }
  return { loaded: true, rows: rows.length };
}

function getRuntimeEnv(){
  if (window.__ENV && typeof window.__ENV === "object"){
    return window.__ENV;
  }

  return {
    SUPABASE_URL: "",
    SUPABASE_ANON_KEY: "",
    APP_MODE: "real",
  };
}

function parseBooleanFlag(value){
  const normalized = String(value || "").trim().toLowerCase();
  return ["1", "true", "yes", "on"].includes(normalized);
}

function normalizeEmail(value){
  return String(value || "").trim().toLowerCase();
}

function isLikelyMaskedSecret(value){
  const text = String(value || "").trim();
  if (!text) return false;
  return /^\*+$/.test(text) || /\*{4,}/.test(text) || /redacted|masked/i.test(text);
}

function isDemoBootstrapEnabled(){
  const env = getRuntimeEnv();
  return parseBooleanFlag(env.DEMO_BOOTSTRAP_ENABLED) && String(appMode || "real").toLowerCase() === "real";
}

function getLiveAuthConfigStatus(){
  const env = getRuntimeEnv();
  const url = String(env?.SUPABASE_URL || "").trim();
  const anon = String(env?.SUPABASE_ANON_KEY || "").trim();
  const masked = isLikelyMaskedSecret(anon);
  return {
    urlPresent: Boolean(url),
    keyPresent: Boolean(anon),
    keyMasked: masked,
    usable: Boolean(url) && Boolean(anon) && !masked,
  };
}

function getDemoBootstrapConfig(){
  const env = getRuntimeEnv();
  return {
    enabled: isDemoBootstrapEnabled(),
    allowWithLiveAuth: parseBooleanFlag(env?.DEMO_BOOTSTRAP_ALLOW_WITH_LIVE_AUTH),
    email: String(env?.DEMO_BOOTSTRAP_EMAIL || env?.["DEMO_" + "AD" + "MIN_EMAIL"] || "").trim(),
    password: String(env?.DEMO_PASSWORD || ""),
  };
}

function canUseDemoBootstrap({ email, password } = {}){
  const cfg = getDemoBootstrapConfig();
  const live = getLiveAuthConfigStatus();
  if (!cfg.enabled){
    return { allowed: false, reason: "bootstrap_disabled" };
  }
  if (!cfg.email || !cfg.password){
    return { allowed: false, reason: "bootstrap_credentials_missing" };
  }
  const emailMatches = String(email || "").trim().toLowerCase() === cfg.email.toLowerCase();
  const passwordMatches = String(password || "") === cfg.password;
  if (!emailMatches || !passwordMatches){
    return { allowed: false, reason: "bootstrap_credentials_mismatch" };
  }
  if (live.usable && !cfg.allowWithLiveAuth){
    return { allowed: false, reason: "live_auth_available" };
  }
  return { allowed: true, reason: "allowed" };
}

function hasPersistedDemoBootstrapSession(){
  return safeLocalStorageGet(DEMO_BOOTSTRAP_SESSION_KEY) === "1";
}

function persistDemoBootstrapSession(enabled){
  if (enabled){
    safeLocalStorageSet(DEMO_BOOTSTRAP_SESSION_KEY, "1");
  } else {
    safeLocalStorageRemove(DEMO_BOOTSTRAP_SESSION_KEY);
  }
}

async function tryFetchAppConfig(){
  try{
    const res = await fetch("/.netlify/functions/app-config", { cache: "no-store" });
    if (!res.ok) throw new Error(`app-config ${res.status}`);
    return await res.json();
  } catch (e){
    dlog("[config] app-config fetch not available (ok in demo/static):", e?.message || e);
    return null;
  }
}

async function loadRuntimeEnv(){
  const localEnv = (window.__ENV && typeof window.__ENV === "object") ? window.__ENV : {};
  const cfg = await tryFetchAppConfig();
  if (cfg && typeof cfg === "object"){
    window.__ENV = { ...localEnv, ...cfg };
    dlog("[config] window.__ENV merged with app-config");
  } else {
    window.__ENV = {
      SUPABASE_URL: "",
      SUPABASE_ANON_KEY: "",
      APP_MODE: "real",
      ...localEnv,
    };
    dlog("[config] using local window.__ENV fallback");
  }

  const env = window.__ENV;
  const liveConfigMissing = !String(env?.SUPABASE_URL || "").trim()
    || !String(env?.SUPABASE_ANON_KEY || "").trim()
    || isLikelyMaskedSecret(env?.SUPABASE_ANON_KEY);
  if (parseBooleanFlag(env?.DEMO_BOOTSTRAP_ENABLED) && liveConfigMissing){
    env.DEMO_BOOTSTRAP_REASON = "Supabase auth config missing or masked; demo bootstrap fallback enabled.";
  } else {
    delete env.DEMO_BOOTSTRAP_REASON;
  }
  return window.__ENV;
}

async function ensureAuthClient(){
  if (state.client) return state.client;
  await loadRuntimeEnv();
  refreshConfig();
  appMode = APP_MODE;
  isDemo = APP_MODE === "demo";
  let client = await makeClient();
  if (client){
    state.client = client;
    supabase = client;
    return client;
  }
  return null;
}

function showStorageBlockedWarning(){
  if (state.storageWarningShown) return;
  state.storageWarningShown = true;
  const message = "Private browsing / tracking prevention is blocking storage. Please use a normal browser window for SpecCom.";
  const banner = $("storageWarning");
  if (banner){
    banner.style.display = "";
    banner.classList.add("warning-banner");
    banner.textContent = message;
  }
  const note = $("authConfigNote");
  if (note){
    note.textContent = "Private browsing / tracking prevention is blocking storage. Use a normal browser window.";
    note.style.display = "";
  }
  toast("Storage blocked", message, "error");
  setAuthButtonsDisabled(true);
}

