function getSiteDisplayName(site){
  const raw = String(site?.name || "").trim();
  return raw || "Pinned site";
}

function toSiteIdKey(id){
  if (id == null) return "";
  return String(id);
}

// Number(null) and Number("") are 0, which reads as a valid coordinate or
// test value — treat null/undefined/blank as "no value" before converting.
function toFiniteNumberOrNull(value){
  if (value === null || value === undefined) return null;
  const text = String(value).trim();
  if (!text) return null;
  const num = Number(text);
  return Number.isFinite(num) ? num : null;
}

function getSiteCoords(site){
  const latNum = toFiniteNumberOrNull(site?.gps_lat ?? site?.lat ?? site?.latitude);
  const lngNum = toFiniteNumberOrNull(site?.gps_lng ?? site?.lng ?? site?.longitude);
  if (latNum === null || lngNum === null) return null;
  return { lat: latNum, lng: lngNum };
}

// Users need to see that a tap registered: while an async action runs, the
// pressed button shows a spinner and rejects further taps. Only buttons we
// disabled here get re-enabled, so intentionally-disabled buttons stay off.
function setButtonBusy(btn, busy){
  if (!btn || typeof btn.classList?.toggle !== "function") return;
  if (busy){
    if (btn.dataset.scBusy === "1" || btn.disabled) return;
    btn.dataset.scBusy = "1";
    btn.classList.add("is-busy");
    btn.disabled = true;
    // Buttons with data-busy-label announce what they're doing ("Starting…")
    // so a pressed workflow button never still reads as pressable.
    if (btn.dataset.busyLabel){
      btn.dataset.scRestoreLabel = btn.textContent;
      btn.textContent = btn.dataset.busyLabel;
    }
  } else if (btn.dataset.scBusy === "1"){
    delete btn.dataset.scBusy;
    btn.classList.remove("is-busy");
    btn.disabled = false;
    if (btn.dataset.scRestoreLabel !== undefined){
      btn.textContent = btn.dataset.scRestoreLabel;
      delete btn.dataset.scRestoreLabel;
    }
  }
}

// Enter in a text box triggers its obvious action (sign in, search, save)
// instead of doing nothing. Inputs with their own Enter handler call
// preventDefault, which this global fallback respects.
const ENTER_ACTION_BUTTON_BY_INPUT_ID = {
  email: "btnSignIn",
  password: "btnSignIn",
  resetPassword: "btnResetPassword",
  resetPasswordConfirm: "btnResetPassword",
};

function findEnterActionButton(input){
  const explicitId = String(input.dataset?.enterClick || "").trim();
  if (explicitId){
    const explicitBtn = document.getElementById(explicitId);
    if (explicitBtn && !explicitBtn.disabled) return explicitBtn;
  }
  const mappedId = ENTER_ACTION_BUTTON_BY_INPUT_ID[input.id];
  if (mappedId){
    const mappedBtn = document.getElementById(mappedId);
    if (mappedBtn && !mappedBtn.disabled) return mappedBtn;
  }
  // Row pattern: the input shares its parent with exactly one action button.
  const rowButtons = input.parentElement
    ? Array.from(input.parentElement.querySelectorAll("button")).filter((btn) => !btn.disabled)
    : [];
  return rowButtons.length === 1 ? rowButtons[0] : null;
}

document.addEventListener("keydown", (e) => {
  if (e.key !== "Enter" || e.defaultPrevented || e.isComposing) return;
  if (e.shiftKey || e.ctrlKey || e.altKey || e.metaKey) return;
  const input = e.target;
  if (!input || input.tagName !== "INPUT") return;
  const type = String(input.type || "text").toLowerCase();
  if (!["text", "search", "email", "password", "tel", "number", "url"].includes(type)) return;
  const actionBtn = findEnterActionButton(input);
  if (!actionBtn) return;
  e.preventDefault();
  if (typeof input.blur === "function") input.blur();
  actionBtn.click();
});

// Readings at or better than this are considered passing; anything more
// negative flags the location for a field revisit.
const TEST_RESULT_REVISIT_THRESHOLD_DB = -25;

function getSiteTestResult(site){
  const low = toFiniteNumberOrNull(site?.test_result_low);
  const high = toFiniteNumberOrNull(site?.test_result_high);
  const readings = [low, high].filter((value) => value !== null);
  if (!readings.length) return null;
  const worst = Math.min(...readings);
  return {
    low,
    high,
    worst,
    wavelength: toFiniteNumberOrNull(site?.testing_wavelength),
    needsRevisit: worst < TEST_RESULT_REVISIT_THRESHOLD_DB,
  };
}

function renderSiteTestResultChip(site){
  const result = getSiteTestResult(site);
  if (!result) return "";
  const readings = [
    result.low !== null ? `low ${result.low}` : "",
    result.high !== null ? `high ${result.high}` : "",
  ].filter(Boolean).join(" / ");
  const wavelengthText = result.wavelength ? `${result.wavelength}nm ` : "";
  const label = result.needsRevisit
    ? `REVISIT — worse than ${TEST_RESULT_REVISIT_THRESHOLD_DB} dB`
    : "PASS";
  return `
    <div class="map-field-test-result ${result.needsRevisit ? "is-revisit" : "is-pass"}">
      <span class="map-field-test-value">Test ${escapeHtml(`${wavelengthText}${readings} dBm`)}</span>
      <span class="map-field-test-flag">${escapeHtml(label)}</span>
    </div>
  `;
}

function normalizeMapFieldStatus(value){
  const normalized = String(value || "").trim().toUpperCase();
  if (normalized === MAP_FIELD_STATUS.IN_PROGRESS || normalized === MAP_FIELD_STATUS.COMPLETE){
    return normalized;
  }
  return MAP_FIELD_STATUS.NOT_STARTED;
}

function getSiteWorkflowStatus(site){
  const siteId = toSiteIdKey(site?.id);
  const overridden = siteId ? state.map.siteWorkflowById.get(siteId) : null;
  if (overridden) return normalizeMapFieldStatus(overridden);
  const status = String(site?.status || "").trim().toUpperCase();
  if (["COMPLETE", "COMPLETED", MAP_FIELD_STATUS.COMPLETE].includes(status)){
    return MAP_FIELD_STATUS.COMPLETE;
  }
  if (["IN_PROGRESS", "ON_SITE", "EN_ROUTE", "ASSIGNED", "ACTIVE", MAP_FIELD_STATUS.IN_PROGRESS].includes(status) || site?.is_pending){
    return MAP_FIELD_STATUS.IN_PROGRESS;
  }
  if (site && Object.prototype.hasOwnProperty.call(site, "completed") && site.completed){
    return MAP_FIELD_STATUS.COMPLETE;
  }
  return MAP_FIELD_STATUS.NOT_STARTED;
}

function getSiteStatusColor(site){
  const status = getSiteWorkflowStatus(site);
  return MAP_FIELD_STATUS_COLORS[status] || MAP_FIELD_STATUS_COLORS[MAP_FIELD_STATUS.NOT_STARTED];
}

function getSitePinColor(site){
  const status = getSiteWorkflowStatus(site);
  if (status === MAP_FIELD_STATUS.NOT_STARTED){
    const testResult = getSiteTestResult(site);
    // Passing points don't need a return visit — keep red for actual revisit work.
    if (testResult && !testResult.needsRevisit) return "#3b82f6";
  }
  return getSiteStatusColor(site);
}

function getMapFieldStatusLabel(status){
  if (status === MAP_FIELD_STATUS.COMPLETE) return "Complete";
  if (status === MAP_FIELD_STATUS.IN_PROGRESS) return "In Progress";
  return "Not Started";
}

function getMapFieldStatusClass(status){
  if (status === MAP_FIELD_STATUS.COMPLETE) return "complete";
  if (status === MAP_FIELD_STATUS.IN_PROGRESS) return "in-progress";
  return "not-started";
}

function formatDistanceFeetMeters(distanceM){
  if (!Number.isFinite(distanceM)) return "";
  const meters = Math.max(0, Math.round(distanceM));
  const feet = Math.max(0, Math.round(distanceM * 3.28084));
  return `${feet} ft (${meters} m)`;
}

function setLayersPanelOpen(openBool, { persist = true } = {}){
  const open = Boolean(openBool);
  state.map.layersPanelOpen = open;
  const panel = $("mapViewFloating");
  const showBtn = $("btnLayersShow");
  if (panel) panel.style.display = open ? "" : "none";
  if (showBtn) showBtn.style.display = open ? "none" : "";
  if (persist){
    safeLocalStorageSet(LAYERS_PANEL_OPEN_KEY, open ? "1" : "0");
  }
}

function normalizeCodeList(list){
  if (!Array.isArray(list)) return [];
  return Array.from(new Set(list.map((code) => String(code || "").trim()).filter(Boolean)));
}

function summarizeCodesForPopup(list, maxItems = 10){
  const cleaned = normalizeCodeList(list);
  if (!cleaned.length) return "(none)";
  if (cleaned.length <= maxItems) return cleaned.join(", ");
  return `${cleaned.slice(0, maxItems).join(", ")} (+${cleaned.length - maxItems} more)`;
}

function normalizeCodeForMatch(value){
  const raw = String(value || "").trim().toUpperCase();
  if (!raw) return "";
  return raw
    .replace(/\s+QTY\s*=\s*[\d.]+$/i, "")
    .replace(/\s+X\s*[\d.]+$/i, "")
    .replace(/\s*\([\d.]+\)\s*$/i, "")
    .trim();
}

function extractBillingCodesPayloadFromNotes(notes){
  const text = String(notes || "");
  if (!text) return "";
  const matches = Array.from(text.matchAll(/billing codes payload\s*\(imported[^)]*\)\s*:\s*([^\r\n]+)/gi));
  if (!matches.length) return "";
  return String(matches[matches.length - 1]?.[1] || "").trim();
}

function getSiteCodesPayload(site){
  const direct = String(site?.codes_payload || "").trim();
  if (direct) return direct;
  return extractBillingCodesPayloadFromNotes(site?.notes);
}

function getPopupBilledCodeDisplayList(site, siteCodes){
  const payloadRows = parseBillingCodesPayload(getSiteCodesPayload(site));
  if (!payloadRows.length){
    return normalizeCodeList(siteCodes);
  }
  return payloadRows
    .map((row) => {
      const code = String(row?.code || "").trim();
      if (!code) return "";
      const billedQty = Number(row?.billed);
      if (Number.isFinite(billedQty) && billedQty !== 0){
        return `${code} [${formatImportNumber(billedQty)}]`;
      }
      return code;
    })
    .filter(Boolean);
}

function evaluateCodeMatch(requiredCodes, billedCodes){
  const required = normalizeCodeList(requiredCodes).map(normalizeCodeForMatch).filter(Boolean);
  const billed = normalizeCodeList(billedCodes).map(normalizeCodeForMatch).filter(Boolean);
  const requiredSet = new Set(required);
  const billedSet = new Set(billed);
  const missing = required.filter((code) => !billedSet.has(code));
  const extra = billed.filter((code) => !requiredSet.has(code));
  return { ok: missing.length === 0 && extra.length === 0, missing, extra };
}

function getCachedSiteCodes(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const cached = state.map.siteCodesBySiteId.get(key);
  return Array.isArray(cached) ? cached : [];
}

function hasCachedSiteCodes(siteId){
  const key = toSiteIdKey(siteId);
  return Boolean(key) && state.map.siteCodesBySiteId.has(key);
}

function setCachedSiteCodes(siteId, codes){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const normalized = normalizeCodeList(codes);
  state.map.siteCodesBySiteId.set(key, normalized);
  return normalized;
}

async function fetchSiteCodesForMapPopup(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const cached = state.map.siteCodesBySiteId.get(key);
  if (Array.isArray(cached)) return cached;
  if (isDemo){
    const demoCodes = (state.demo.siteCodes || [])
      .filter((row) => toSiteIdKey(row?.site_id) === key)
      .map((row) => row.code);
    return setCachedSiteCodes(key, demoCodes);
  }
  if (!state.client) return setCachedSiteCodes(key, []);
  const { data, error } = await state.client
    .from("site_codes")
    .select("code")
    .eq("site_id", siteId)
    .order("created_at", { ascending: true });
  if (error){
    debugLog("[map] popup code fetch failed", error);
    return setCachedSiteCodes(key, []);
  }
  return setCachedSiteCodes(key, (data || []).map((row) => row.code));
}

function normalizePopupPhotos(items){
  if (!Array.isArray(items)) return [];
  return items
    .map((item) => {
      const url = String(item?.url || "").trim();
      if (!url) return null;
      return {
        id: item?.id || "",
        createdBy: item?.createdBy || item?.created_by || "",
        url,
        createdAt: item?.createdAt || "",
        gpsLat: Number.isFinite(Number(item?.gpsLat)) ? Number(item.gpsLat) : null,
        gpsLng: Number.isFinite(Number(item?.gpsLng)) ? Number(item.gpsLng) : null,
        gpsAccuracyM: Number.isFinite(Number(item?.gpsAccuracyM)) ? Number(item.gpsAccuracyM) : null,
        source: item?.source || "",
        proofType: item?.proofType || item?.proof_type || "",
        readonly: Boolean(item?.readonly),
      };
    })
    .filter(Boolean);
}

function getCachedSitePhotos(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const cached = state.map.sitePhotosBySiteId.get(key);
  return Array.isArray(cached) ? cached : [];
}

function hasCachedSitePhotos(siteId){
  const key = toSiteIdKey(siteId);
  return Boolean(key) && state.map.sitePhotosBySiteId.has(key);
}

function setCachedSitePhotos(siteId, photos){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const normalized = normalizePopupPhotos(photos);
  state.map.sitePhotosBySiteId.set(key, normalized);
  return normalized;
}

async function fetchSitePhotosForMapPopup(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const cached = state.map.sitePhotosBySiteId.get(key);
  if (Array.isArray(cached)) return cached;
  const archiveSite = (state.projectSites || []).find((row) => toSiteIdKey(row?.id) === key) || null;
  if (isDemo){
    const rows = (state.demo.siteMedia || [])
      .filter((row) => toSiteIdKey(row?.site_id) === key)
      .map((row) => ({
        id: row?.id || "",
        createdBy: row?.created_by || "",
        url: String(row?.previewUrl || row?.media_path || "").trim(),
        createdAt: row?.created_at || "",
        source: row?.source || "",
        proofType: row?.proof_type || "",
      }))
      .filter((row) => row.url);
    if (rows.length) return setCachedSitePhotos(key, rows);
    const archivePhotos = await getRuidosoArchivePhotosForSite(archiveSite);
    return setCachedSitePhotos(key, archivePhotos.map((row) => ({
      id: row?.id || "",
      createdBy: "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      proofType: row?.proof_type || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
  }
  if (!state.client){
    const archivePhotos = await getRuidosoArchivePhotosForSite(archiveSite);
    return setCachedSitePhotos(key, archivePhotos.map((row) => ({
      id: row?.id || "",
      createdBy: "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      proofType: row?.proof_type || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
  }
  let { data, error } = await state.client
    .from("site_media")
    .select("id, media_path, created_by, created_at, gps_lat, gps_lng, gps_accuracy_m, source, proof_type")
    .eq("site_id", siteId)
    .order("created_at", { ascending: false });
  if (error && isMissingColumnError(error, "created_by")){
    ({ data, error } = await state.client
      .from("site_media")
      .select("id, media_path, created_at, gps_lat, gps_lng, gps_accuracy_m, source, proof_type")
      .eq("site_id", siteId)
      .order("created_at", { ascending: false }));
  }
  if (error && ["source", "proof_type"].some((col) => isMissingColumnError(error, col))){
    ({ data, error } = await state.client
      .from("site_media")
      .select("id, media_path, created_by, created_at, gps_lat, gps_lng, gps_accuracy_m")
      .eq("site_id", siteId)
      .order("created_at", { ascending: false }));
  }
  if (error){
    debugLog("[map] popup photo fetch failed", error);
    const archivePhotos = await getRuidosoArchivePhotosForSite(archiveSite);
    return setCachedSitePhotos(key, archivePhotos.map((row) => ({
      id: row?.id || "",
      createdBy: "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      proofType: row?.proof_type || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
  }
  const rows = [];
  for (const row of data || []){
    let url = "";
    if (row?.media_path){
      const rawPath = String(row.media_path);
      if (/^https?:\/\//i.test(rawPath)){
        url = rawPath;
      } else {
        try{
          url = await getPublicOrSignedUrl("proof-photos", rawPath);
        } catch (error){
          debugLog("[map] popup photo url resolve failed", error);
          url = "";
        }
      }
    }
    if (!url) continue;
    rows.push({
      id: row?.id || "",
      createdBy: row?.created_by || "",
      url,
      createdAt: row?.created_at || "",
      gpsLat: row?.gps_lat ?? null,
      gpsLng: row?.gps_lng ?? null,
      gpsAccuracyM: row?.gps_accuracy_m ?? null,
      source: row?.source || "",
      proofType: row?.proof_type || "",
    });
  }
  if (!rows.length){
    const archivePhotos = await getRuidosoArchivePhotosForSite(archiveSite);
    return setCachedSitePhotos(key, archivePhotos.map((row) => ({
      id: row?.id || "",
      createdBy: "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
  }
  return setCachedSitePhotos(key, rows);
}

function getDemoCredentials(){
  const cfg = getDemoBootstrapConfig();
  return {
    email: cfg.email,
    password: cfg.password,
  };
}

function normalizeTerminalPorts(value){
  const parsed = Number.parseInt(value, 10);
  if (!Number.isFinite(parsed)) return DEFAULT_TERMINAL_PORTS;
  return Math.min(MAX_TERMINAL_PORTS, Math.max(1, parsed));
}

function getFixedPhotoSlots(){
  const slots = [];
  for (let i = 1; i <= FIXED_LOCATION_PHOTO_SLOTS; i += 1){
    slots.push(`photo_${i}`);
  }
  return slots;
}

function getSlotLabel(slotKey){
  const photoMatch = String(slotKey || "").match(/^photo_(\d+)$/);
  if (photoMatch) return `Photo ${photoMatch[1]}`;
  if (slotKey === "splice_completion") return "Splice completion";
  const match = String(slotKey || "").match(/^port_(\d+)$/);
  if (match) return `Port ${match[1]}`;
  return slotKey;
}

function getRequiredSlotsForLocation(loc){
  return getFixedPhotoSlots();
}

function countRequiredSlotUploads(loc){
  const photos = loc?.photosBySlot || {};
  const uploaded = Object.keys(photos).length > 0 ? 1 : 0;
  return { uploaded, required: 1 };
}

function hasAllRequiredSlotPhotos(loc){
  return Object.keys(loc?.photosBySlot || {}).length > 0;
}

function getSpliceLocationDefaultName(index){
  const safeIndex = Number.isFinite(index) && index >= 0 ? index : 0;
  return `${t("spliceLocationLabel")} ${safeIndex + 1}`;
}

function getSpliceLocationDisplayName(loc, index){
  const label = String(loc?.label ?? "").trim();
  if (label) return label;
  if (Number.isFinite(index)) return getSpliceLocationDefaultName(index);
  const legacy = String(loc?.location_label ?? loc?.name ?? "").trim();
  if (legacy) return legacy;
  return t("spliceLocationLabel");
}

function normalizeWorkCodes(input){
  return String(input || "")
    .split(",")
    .map((part) => part.trim().replace(/\s+/g, " ").toUpperCase())
    .filter(Boolean);
}

function renderCodesSection(loc){
  const codes = Array.isArray(loc.work_codes) ? loc.work_codes : [];
  const description = String(loc.work_description || "");
  const isEditing = Boolean(loc.isEditingCodes);
  const template = $("spliceCodesTemplate");
  const codesHtml = codes.length
    ? codes.map((code) => `<span class="code-chip">${escapeHtml(code)}</span>`).join("")
    : `<span class="muted small">${t("noneLabel")}</span>`;
  const descHtml = description.trim()
    ? `<div class="muted small">${escapeHtml(description)}</div>`
    : `<div class="muted small">${t("noneLabel")}</div>`;

  const editBody = isEditing
    ? `
      <div class="field-stack" style="margin-top:10px;">
        <input class="input code-input" data-action="codesInput" data-location-id="${loc.id}" value="${escapeHtml((loc.pending_work_codes || codes).join(", "))}" placeholder="${t("codesPlaceholder")}" />
        <textarea class="input desc-textarea" data-action="descInput" data-location-id="${loc.id}" maxlength="400" placeholder="${t("descriptionPlaceholder")}">${escapeHtml(loc.pending_work_description ?? description)}</textarea>
        <div class="row" style="justify-content:flex-end;">
          <button class="btn ghost small" data-action="cancelCodes" data-id="${loc.id}">${t("cancelLabel")}</button>
          <button class="btn secondary small" data-action="saveCodes" data-id="${loc.id}">${t("saveLabel")}</button>
        </div>
      </div>
    `
    : "";
  const actionsHtml = isEditing
    ? ""
    : `<button class="btn ghost small" data-action="editCodes" data-id="${loc.id}">${t("editCodesLabel")}</button>`;

  if (template){
    const fragment = template.content.cloneNode(true);
    const wrapper = document.createElement("div");
    wrapper.appendChild(fragment);
    const title = wrapper.querySelector("[data-role=\"codes-title\"]");
    if (title) title.textContent = t("codesUsedTitle");
    const descTitle = wrapper.querySelector("[data-role=\"desc-title\"]");
    if (descTitle) descTitle.textContent = t("briefDescriptionTitle");
    const actions = wrapper.querySelector("[data-role=\"codes-actions\"]");
    if (actions) actions.innerHTML = actionsHtml;
    const codesBody = wrapper.querySelector("[data-role=\"codes-body\"]");
    if (codesBody) codesBody.innerHTML = isEditing ? "" : codesHtml;
    const descBody = wrapper.querySelector("[data-role=\"desc-body\"]");
    if (descBody) descBody.innerHTML = isEditing ? "" : descHtml;
    if (isEditing){
      const editContainer = document.createElement("div");
      editContainer.innerHTML = editBody;
      wrapper.querySelector(".codes-section")?.appendChild(editContainer);
    }
    return wrapper.innerHTML;
  }

  return `
    <div class="codes-section">
      <div class="row" style="justify-content:space-between; align-items:center;">
        <div class="codes-title">${t("codesUsedTitle")}</div>
        ${actionsHtml}
      </div>
      ${isEditing ? "" : codesHtml}
      <div class="codes-title" style="margin-top:8px;">${t("briefDescriptionTitle")}</div>
      ${isEditing ? "" : descHtml}
      ${editBody}
    </div>
  `;
}

function getSortedSpliceLocations(node){
  const rows = [...(node?.splice_locations || [])];
  rows.sort((a, b) => {
    const aOrder = Number.isFinite(a.sort_order) ? a.sort_order : null;
    const bOrder = Number.isFinite(b.sort_order) ? b.sort_order : null;
    if (aOrder != null && bOrder != null && aOrder !== bOrder) return aOrder - bOrder;
    if (aOrder != null && bOrder == null) return -1;
    if (aOrder == null && bOrder != null) return 1;
    const aCreated = a.created_at ? new Date(a.created_at).getTime() : 0;
    const bCreated = b.created_at ? new Date(b.created_at).getTime() : 0;
    if (aCreated !== bCreated) return aCreated - bCreated;
    return String(a.id).localeCompare(String(b.id));
  });
  return rows;
}

function getBackfillSlotKey(loc, photoType){
  const photos = loc?.photosBySlot || {};
  const requiredSlots = getRequiredSlotsForLocation(loc);
  const missingRequired = requiredSlots.find(slot => !photos[slot]);
  if (missingRequired) return missingRequired;
  return null;
}

function setText(id, value){
  const el = $(id);
  if (el) el.textContent = value;
}

function setAppModeUI(){
  const badge = $("appModeBadge");
  if (!badge) return;
  const live = appMode === "real";
  badge.textContent = live ? "LIVE" : "DEMO";
  badge.classList.toggle("live", live);
  badge.classList.toggle("demo", !live);
}

function setEnvWarning(){
  const banner = $("envWarning");
  if (!banner) return;
  const live = getLiveAuthConfigStatus();
  if (appMode === "real" && !live.usable){
    banner.style.display = "";
    banner.classList.add("warning-banner");
    if (!isDemoBootstrapEnabled()){
      banner.textContent = "Supabase auth config is missing/invalid. Live sign-in is unavailable until SUPABASE_URL and SUPABASE_ANON_KEY are valid.";
    } else {
      banner.textContent = "Supabase auth config is missing/invalid. Demo bootstrap fallback is enabled for this environment.";
    }
  } else {
    const env = getRuntimeEnv();
    if (String(env?.DEMO_BOOTSTRAP_REASON || "").trim()){
      banner.style.display = "";
      banner.classList.add("warning-banner");
      banner.textContent = String(env.DEMO_BOOTSTRAP_REASON).trim();
      return;
    }
    banner.style.display = "none";
    banner.textContent = "";
  }
}

function getWeeklyBillingWindow(referenceDate = new Date()){
  const ref = referenceDate instanceof Date ? new Date(referenceDate.getTime()) : new Date(referenceDate);
  const start = new Date(ref.getTime());
  const dayOfWeek = start.getDay(); // 0 = Sunday
  start.setDate(start.getDate() - dayOfWeek);
  start.setHours(0, 1, 0, 0); // Sunday 12:01 AM
  const end = new Date(start.getTime());
  end.setDate(end.getDate() + 7);
  end.setMilliseconds(end.getMilliseconds() - 1); // Saturday 11:59:59.999 PM
  return { start, end };
}

function formatBillingWindowLabel(window){
  if (!window?.start || !window?.end) return "";
  const startLabel = window.start.toLocaleString();
  const endLabel = window.end.toLocaleString();
  return `${startLabel} to ${endLabel}`;
}

function setAuthButtonsDisabled(disabled){
  const ids = ["btnSignIn", "btnMagicLink", "btnSignUp", "btnDemoLogin"];
  ids.forEach((id) => {
    const el = $(id);
    if (el) el.disabled = disabled;
  });
  const note = $("authConfigNote");
  if (note) note.style.display = disabled ? "" : "none";
}

function hasAuthenticatedSession(){
  if (isDemo) return true;
  return Boolean(state.user?.id);
}

function syncMobileBottomNav(viewId){
  const nav = $("mobileBottomNav");
  if (!nav) return;
  const fieldMode = isFieldSubcontractorMode();
  const homeBtn = nav.querySelector('button[data-mobile-nav="home"]');
  const homeLabel = homeBtn?.querySelector("span");
  if (homeLabel) homeLabel.textContent = fieldMode ? "Projects" : "Home";
  const timeBtn = nav.querySelector('button[data-mobile-nav="timesheet"]');
  if (timeBtn) timeBtn.style.display = fieldMode ? "none" : "";
  const activeKey = (() => {
    if (viewId === "viewDashboard") return "home";
    if (viewId === "viewTechnician") return "timesheet";
    if (viewId === "viewMap") return "map";
    return "more";
  })();
  nav.querySelectorAll("button[data-mobile-nav]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.mobileNav === activeKey);
  });
}

function setActiveView(viewId, { syncHash = true } = {}){
  if (!CONTROL_CENTER_DEV_MODE && !hasAuthenticatedSession()){
    applySignedOutUi("set-active-view-blocked");
    return;
  }
  if (isFieldSubcontractorMode() && !FIELD_SUBCONTRACTOR_ALLOWED_VIEWS.has(viewId)){
    viewId = "viewMap";
  }
  if (isSubcontractorOnboardingLocked() && viewId !== "viewOnboarding"){
    viewId = "viewOnboarding";
  }
  if (viewId === "viewRootCommandCenter" && !isEffectiveRootRole()){
    viewId = getDefaultView();
    toast("ROOT access required", "The ROOT Command Center is not available for this account.", "error");
  }
  if (viewId !== "viewWarehouseScan"){
    stopWarehouseScanCamera();
  }
  if (viewId !== "viewMap"){
    setMapFieldCreateOpen(false);
  }
  document.body.classList.toggle("map-mode", viewId === "viewMap");
  document.querySelectorAll(".view").forEach((view) => {
    view.classList.toggle("active", view.id === viewId);
  });
  document.querySelectorAll(".nav-item").forEach((btn) => {
    btn.classList.toggle("active", btn.dataset.view === viewId);
  });
  syncMobileBottomNav(viewId);
  if (viewId === "viewAdmin"){
    renderAdminWorkspace(_activeAdminTab || "users");
    loadAdminMaterialSettings();
  }
  if (viewId === "viewRootCommandCenter"){
    renderRootCommandCenter();
    void loadRootCommandCenterData({ silent: true });
  }
  if (viewId === "viewOnboarding"){
    renderSubcontractorOnboarding();
    void loadSubcontractorOnboarding();
  }
  if (viewId === "viewTechnician"){
    if (state.features.labor) loadTechnicianTimesheet();
  }
  if (viewId === "viewDispatch"){
    if (state.features.dispatch){
      loadDispatchTechnicians();
      loadDispatchWorkOrders();
    }
  }
  if (viewId === "viewSupervisor"){
    if (state.features.dispatch){
      loadDispatchTechnicians();
      loadDispatchWorkOrders();
    }
    renderSupervisorOverview();
  }
  if (viewId === "viewLabor"){
    if (state.features.labor) loadLaborRows();
  }
  if (viewId === "viewWarehouseScan"){
    renderWarehouseScanView();
    renderWarehouseModeUi();
    queueMicrotask(() => focusWarehouseScanInput());
  }
  if (viewId === "viewMap"){
    forcePlainMapRedlineState();
    state.map.drawerTab = "data";
    ensureMap();
    initMapWorkspaceUi();
    applyDrawerUiState();
    queueMapInvalidate(90);
    refreshMaterialProjectData({ silent: true });
    refreshLocations();
    const now = Date.now();
    const isFirstLoad = !state.map.lastFieldGpsCheckAt;
    if (isFirstLoad || (now - state.map.lastFieldGpsCheckAt) > 30000){
      void requestMapCurrentLocation({ center: isFirstLoad, silent: true });
    } else {
      renderMapFieldPanel();
    }
  }
  if (viewId === "viewDailyReport"){
    syncDprProjectSelection();
    renderDprProjectOptions();
    void loadDprUsers();
    loadDailyProgressReport();
  }
  if (viewId === "viewInvoices"){
    syncInvoiceDeepLinkFromUrl({ activateView: false });
    if (state.user && !state.ksInvoices.loading){
      loadKsInvoiceWorkspace(state.activeProject?.id || null);
    }
  }
  if (syncHash){
    syncHashForView(viewId);
  }

  dlog("[route] setActiveView", {
    view: viewId,
    hash: window.location.hash,
    projectId: state.activeProject?.id || null,
    projectName: state.activeProject?.name || null,
    contextType: state.activeProject ? "project" : "company",
    userId: state.user?.id || null,
  });
}

