SpecCom.helpers.normalizeImportHeader = function(header){
  return String(header || "").trim().toLowerCase();
};

function parseDelimited(text, delimiter){
  const lines = text.split(/\r?\n/).filter(Boolean);
  if (lines.length < 2) return [];
  const headers = lines[0].split(delimiter).map(SpecCom.helpers.normalizeImportHeader);
  return lines.slice(1).map((line, idx) => {
    const values = line.split(delimiter);
    const row = Object.fromEntries(
      headers.map((h, i) => [h, values[i]?.trim()])
    );
    row.__rowNumber = idx + 2;
    return row;
  });
}

async function parseCsvFile(file){
  const text = await file.text();
  return parseDelimited(text, ",");
}

async function parseXlsxFile(file){
  if (!window.XLSX) throw new Error("XLSX parser not available");
  const buffer = await file.arrayBuffer();
  const workbook = window.XLSX.read(buffer, { type: "array" });
  const sheetName = workbook.SheetNames[0];
  const sheet = workbook.Sheets[sheetName];
  const rows = window.XLSX.utils.sheet_to_json(sheet, { header: 1 });
  if (!rows.length) return [];
  const headers = rows[0].map(SpecCom.helpers.normalizeImportHeader);
  return rows.slice(1).filter((r) => r && r.length).map((r, idx) => {
    const row = Object.fromEntries(
      headers.map((h, i) => [h, String(r[i] ?? "").trim()])
    );
    row.__rowNumber = idx + 2;
    return row;
  });
}

async function loadPdfJs(){
  if (window.pdfjsLib) return window.pdfjsLib;
  await new Promise((resolve, reject) => {
    const s = document.createElement("script");
    s.src = "https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.min.js";
    s.onload = resolve;
    s.onerror = reject;
    document.head.appendChild(s);
  });
  return window.pdfjsLib;
}

async function parsePdfFile(file){
  const pdfjsLib = await loadPdfJs();
  // TODO: PDF parsing assumes a text table with comma/tab or multi-space delimiters.
  const buffer = await file.arrayBuffer();
  const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
  let text = "";
  for (let i = 1; i <= pdf.numPages; i += 1){
    const page = await pdf.getPage(i);
    const content = await page.getTextContent();
    const pageText = content.items.map((item) => item.str).join(" ");
    text += `${pageText}\n`;
  }
  const wiredRows = parseWiredProductionPdfText(text);
  if (wiredRows.length){
    return wiredRows;
  }
  const lines = text.split(/\r?\n/).map((l) => l.trim()).filter(Boolean);
  if (!lines.length) return [];
  const headerLine = lines[0];
  let delimiter = ",";
  if (headerLine.includes("\t")) delimiter = "\t";
  else if (!headerLine.includes(",")) delimiter = null;
  if (delimiter){
    return parseDelimited(lines.join("\n"), delimiter);
  }
  // fallback to 2+ spaces
  const headers = headerLine.split(/\s{2,}/).map(SpecCom.helpers.normalizeImportHeader);
  return lines.slice(1).map((line, idx) => {
    const values = line.split(/\s{2,}/);
    const row = Object.fromEntries(
      headers.map((h, i) => [h, values[i]?.trim()])
    );
    row.__rowNumber = idx + 2;
    return row;
  });
}

function stripHtmlTags(value){
  return String(value || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
}

function parseKmlCoordinateText(coordText){
  const list = parseKmlCoordinateList(coordText);
  if (!list.length) return null;
  const [lng, lat] = list[0];
  return { lat, lng };
}

function parseKmlCoordinateList(coordText){
  const raw = String(coordText || "").trim();
  if (!raw) return [];
  const parts = raw.split(/\s+/).filter(Boolean);
  const points = [];
  for (const part of parts){
    const fields = part.split(",");
    if (fields.length < 2) continue;
    const lng = Number.parseFloat(fields[0]);
    const lat = Number.parseFloat(fields[1]);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) continue;
    if (lat < -90 || lat > 90 || lng < -180 || lng > 180) continue;
    points.push([lng, lat]);
  }
  return points;
}

function fnv1aHash(input){
  const text = String(input || "");
  let hash = 0x811c9dc5;
  for (let i = 0; i < text.length; i += 1){
    hash ^= text.charCodeAt(i);
    hash = (hash + ((hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24))) >>> 0;
  }
  return hash.toString(16).padStart(8, "0");
}

function buildStableFeatureId({
  placemarkId = "",
  placemarkName = "",
  folderPath = "",
  geometry = null,
} = {}){
  const explicitId = String(placemarkId || "").trim();
  if (explicitId){
    return `kmz-feature-${fnv1aHash(`id:${explicitId}`)}`;
  }
  const geomType = String(geometry?.type || "").trim();
  const geomCoords = (() => {
    try {
      return JSON.stringify(geometry?.coordinates || null);
    } catch {
      return "";
    }
  })();
  const seed = [
    String(placemarkName || "").trim(),
    String(folderPath || "").trim(),
    geomType,
    geomCoords,
  ].join("|");
  return `kmz-feature-${fnv1aHash(seed)}`;
}

function getDirectKmlChild(node, childName){
  if (!node) return null;
  const target = String(childName || "").toLowerCase();
  return Array.from(node.children || []).find((child) => {
    const local = String(child.localName || child.nodeName || "").toLowerCase();
    return local === target;
  }) || null;
}

function getDirectKmlChildText(node, childName){
  const child = getDirectKmlChild(node, childName);
  return String(child?.textContent || "").trim();
}

function getDirectKmlName(node){
  return getDirectKmlChildText(node, "name");
}

function inferKmzLayerType(pathParts = []){
  const normalized = (Array.isArray(pathParts) ? pathParts : [])
    .map((part) => canonicalKmzLayerName(part))
    .filter(Boolean)
    .map((part) => part.toLowerCase());
  const joined = normalized.join(" > ");
  if (joined.includes("connectivity point")) return "connectivityPoints";
  if (joined.includes("drop")) return "drops";
  if (joined.includes("cable") || joined.includes("path")) return "cable";
  if (joined.includes("network point") || joined.includes("network devices") || joined.includes("servicelocation")){
    return "networkPoints";
  }
  return "networkPoints";
}

function parsePlacemarkGeometry(placemark){
  if (!placemark) return null;
  const parsePoint = (pointNode) => {
    const coordText = pointNode?.getElementsByTagName("coordinates")[0]?.textContent || "";
    const coords = parseKmlCoordinateList(coordText);
    if (!coords.length) return null;
    return { type: "Point", coordinates: coords[0] };
  };
  const parseLineString = (lineNode) => {
    const coordText = lineNode?.getElementsByTagName("coordinates")[0]?.textContent || "";
    const coords = parseKmlCoordinateList(coordText);
    if (!coords.length) return null;
    return { type: "LineString", coordinates: coords };
  };
  const parseMultiLineString = (lineNodes) => {
    const lines = Array.from(lineNodes || [])
      .map((lineNode) => parseLineString(lineNode))
      .filter((geom) => geom?.type === "LineString" && Array.isArray(geom.coordinates) && geom.coordinates.length)
      .map((geom) => geom.coordinates);
    if (!lines.length) return null;
    if (lines.length === 1) return { type: "LineString", coordinates: lines[0] };
    return { type: "MultiLineString", coordinates: lines };
  };
  const parsePolygon = (polygonNode) => {
    const ringNode = polygonNode?.getElementsByTagName("outerBoundaryIs")[0]?.getElementsByTagName("LinearRing")[0]
      || polygonNode?.getElementsByTagName("LinearRing")[0]
      || null;
    const coordText = ringNode?.getElementsByTagName("coordinates")[0]?.textContent || "";
    const ring = parseKmlCoordinateList(coordText);
    if (!ring.length) return null;
    return { type: "Polygon", coordinates: [ring] };
  };
  const directChildren = Array.from(placemark.children || []);
  const pointNode = directChildren.find((child) => String(child.localName || child.nodeName || "").toLowerCase() === "point")
    || placemark.getElementsByTagName("Point")[0];
  if (pointNode){
    const geom = parsePoint(pointNode);
    if (geom) return geom;
  }
  const lineNode = directChildren.find((child) => String(child.localName || child.nodeName || "").toLowerCase() === "linestring")
    || placemark.getElementsByTagName("LineString")[0];
  if (lineNode){
    const geom = parseLineString(lineNode);
    if (geom) return geom;
  }
  const polygonNode = directChildren.find((child) => String(child.localName || child.nodeName || "").toLowerCase() === "polygon")
    || placemark.getElementsByTagName("Polygon")[0];
  if (polygonNode){
    const geom = parsePolygon(polygonNode);
    if (geom) return geom;
  }
  const multiNode = directChildren.find((child) => String(child.localName || child.nodeName || "").toLowerCase() === "multigeometry")
    || placemark.getElementsByTagName("MultiGeometry")[0];
  if (multiNode){
    const multiPoint = multiNode.getElementsByTagName("Point")[0];
    if (multiPoint){
      const geom = parsePoint(multiPoint);
      if (geom) return geom;
    }
    const multiLines = multiNode.getElementsByTagName("LineString");
    if (multiLines?.length){
      const geom = parseMultiLineString(multiLines);
      if (geom) return geom;
    }
    const multiPoly = multiNode.getElementsByTagName("Polygon")[0];
    if (multiPoly){
      const geom = parsePolygon(multiPoly);
      if (geom) return geom;
    }
  }
  return null;
}

function getGeometryCenter(geometry){
  if (!geometry) return null;
  if (geometry.type === "Point"){
    const lng = Number(geometry.coordinates?.[0]);
    const lat = Number(geometry.coordinates?.[1]);
    return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
  }
  if (geometry.type === "LineString"){
    const coords = Array.isArray(geometry.coordinates) ? geometry.coordinates : [];
    if (!coords.length) return null;
    const mid = coords[Math.floor(coords.length / 2)] || coords[0];
    const lng = Number(mid?.[0]);
    const lat = Number(mid?.[1]);
    return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
  }
  if (geometry.type === "MultiLineString"){
    const lines = Array.isArray(geometry.coordinates) ? geometry.coordinates : [];
    for (let i = 0; i < lines.length; i += 1){
      const coords = Array.isArray(lines[i]) ? lines[i] : [];
      if (!coords.length) continue;
      const mid = coords[Math.floor(coords.length / 2)] || coords[0];
      const lng = Number(mid?.[0]);
      const lat = Number(mid?.[1]);
      if (Number.isFinite(lat) && Number.isFinite(lng)){
        return { lat, lng };
      }
    }
    return null;
  }
  if (geometry.type === "Polygon"){
    const ring = Array.isArray(geometry.coordinates?.[0]) ? geometry.coordinates[0] : [];
    if (!ring.length) return null;
    let latSum = 0;
    let lngSum = 0;
    let count = 0;
    ring.forEach((coord) => {
      const lng = Number(coord?.[0]);
      const lat = Number(coord?.[1]);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      latSum += lat;
      lngSum += lng;
      count += 1;
    });
    if (!count) return null;
    return { lat: latSum / count, lng: lngSum / count };
  }
  return null;
}

const KMZ_CRITICAL_LAYERS = ["Project", "Drop", "Network Point", "Cable", "Connectivity Point"];

function canonicalKmzLayerName(value){
  const raw = String(value || "").replace(/\s+/g, " ").trim();
  if (!raw) return "";
  const normalized = raw.toLowerCase().replace(/[_-]+/g, " ");
  if (normalized === "project") return "Project";
  if (normalized === "drop") return "Drop";
  if (normalized === "cable") return "Cable";
  if (normalized === "connectivity point") return "Connectivity Point";
  if (normalized === "network point") return "Network Point";
  if (normalized === "servicelocation" || normalized === "service location") return "Network Point";
  if (normalized === "path") return "Path";
  if (normalized === "network devices") return "Network Devices";
  return raw
    .split(" ")
    .map((part) => (part ? (part[0].toUpperCase() + part.slice(1).toLowerCase()) : ""))
    .join(" ")
    .trim();
}

function normalizeKmzLayerList(values){
  const out = [];
  const seen = new Set();
  (Array.isArray(values) ? values : []).forEach((value) => {
    const name = canonicalKmzLayerName(value);
    if (!name || seen.has(name)) return;
    seen.add(name);
    out.push(name);
  });
  return out;
}

function getOrderedKmzLayerList(values, { includeCritical = false } = {}){
  const normalized = normalizeKmzLayerList(values);
  const critical = normalized
    .filter((name) => KMZ_CRITICAL_LAYERS.includes(name))
    .sort((a, b) => KMZ_CRITICAL_LAYERS.indexOf(a) - KMZ_CRITICAL_LAYERS.indexOf(b));
  const extras = normalized.filter((name) => !KMZ_CRITICAL_LAYERS.includes(name));
  extras.sort((a, b) => a.localeCompare(b));
  if (includeCritical){
    return [...KMZ_CRITICAL_LAYERS, ...extras];
  }
  return [...critical, ...extras];
}

// KML colors are aabbggrr hex (alpha, blue, green, red) — convert to a CSS
// hex color + 0..1 opacity so Leaflet can render the file's own styling.
function kmlColorToRgba(kmlColor){
  const raw = String(kmlColor || "").trim().replace(/^#/, "");
  if (raw.length !== 8) return null;
  const a = parseInt(raw.slice(0, 2), 16);
  const b = parseInt(raw.slice(2, 4), 16);
  const g = parseInt(raw.slice(4, 6), 16);
  const r = parseInt(raw.slice(6, 8), 16);
  if ([a, b, g, r].some((v) => Number.isNaN(v))) return null;
  const hex = `#${[r, g, b].map((v) => v.toString(16).padStart(2, "0")).join("")}`;
  return { hex, opacity: a / 255 };
}

function parseKmlStyleElement(styleEl){
  if (!styleEl) return null;
  const style = {};
  const iconStyle = styleEl.getElementsByTagName("IconStyle")[0];
  if (iconStyle){
    const rgba = kmlColorToRgba(iconStyle.getElementsByTagName("color")[0]?.textContent);
    const scale = Number(iconStyle.getElementsByTagName("scale")[0]?.textContent);
    const href = iconStyle.getElementsByTagName("href")[0]?.textContent?.trim() || "";
    style.icon = {
      color: rgba?.hex || null,
      opacity: rgba ? rgba.opacity : null,
      scale: Number.isFinite(scale) && scale > 0 ? scale : null,
      href: href || null,
    };
  }
  const lineStyle = styleEl.getElementsByTagName("LineStyle")[0];
  if (lineStyle){
    const rgba = kmlColorToRgba(lineStyle.getElementsByTagName("color")[0]?.textContent);
    const width = Number(lineStyle.getElementsByTagName("width")[0]?.textContent);
    style.line = {
      color: rgba?.hex || null,
      opacity: rgba ? rgba.opacity : null,
      width: Number.isFinite(width) && width > 0 ? width : null,
    };
  }
  const polyStyle = styleEl.getElementsByTagName("PolyStyle")[0];
  if (polyStyle){
    const rgba = kmlColorToRgba(polyStyle.getElementsByTagName("color")[0]?.textContent);
    const fillNode = polyStyle.getElementsByTagName("fill")[0]?.textContent?.trim();
    const outlineNode = polyStyle.getElementsByTagName("outline")[0]?.textContent?.trim();
    style.poly = {
      color: rgba?.hex || null,
      opacity: rgba ? rgba.opacity : null,
      fill: fillNode !== "0",
      outline: outlineNode !== "0",
    };
  }
  const labelStyle = styleEl.getElementsByTagName("LabelStyle")[0];
  if (labelStyle){
    const rgba = kmlColorToRgba(labelStyle.getElementsByTagName("color")[0]?.textContent);
    style.label = { color: rgba?.hex || null, hidden: rgba ? rgba.opacity === 0 : false };
  }
  return Object.keys(style).length ? style : null;
}

// Build a lookup of shared styles (id -> parsed style), resolving <StyleMap>
// to its "normal" <Style> so placemark styleUrl references can be applied.
function parseKmlStyleCatalog(xml){
  const catalog = new Map();
  const styleEls = Array.from(xml.getElementsByTagName("Style"));
  styleEls.forEach((el) => {
    const id = String(el.getAttribute("id") || "").trim();
    if (!id) return;
    const parsed = parseKmlStyleElement(el);
    if (parsed) catalog.set(id, parsed);
  });
  const styleMaps = Array.from(xml.getElementsByTagName("StyleMap"));
  styleMaps.forEach((mapEl) => {
    const id = String(mapEl.getAttribute("id") || "").trim();
    if (!id) return;
    const pairs = Array.from(mapEl.getElementsByTagName("Pair"));
    const normalPair = pairs.find((p) => p.getElementsByTagName("key")[0]?.textContent?.trim() === "normal") || pairs[0];
    const ref = String(normalPair?.getElementsByTagName("styleUrl")[0]?.textContent || "").trim().replace(/^#/, "");
    if (ref && catalog.has(ref)) catalog.set(id, catalog.get(ref));
  });
  return catalog;
}

function resolveKmlPlacemarkStyle(placemark, catalog){
  const inline = Array.from(placemark.children || []).find((c) => String(c.localName || c.nodeName || "").toLowerCase() === "style");
  const inlineStyle = inline ? parseKmlStyleElement(inline) : null;
  const ref = String(placemark.getElementsByTagName("styleUrl")[0]?.textContent || "").trim().replace(/^#/, "");
  const sharedStyle = ref && catalog.has(ref) ? catalog.get(ref) : null;
  if (inlineStyle && sharedStyle) return { ...sharedStyle, ...inlineStyle };
  return inlineStyle || sharedStyle || null;
}

function parseKmlText(kmlText){
  const parser = new DOMParser();
  const raw = String(kmlText || "");
  let xml = parser.parseFromString(raw, "application/xml");
  if (xml.getElementsByTagName("parsererror").length){
    const firstTag = raw.indexOf("<");
    if (firstTag > 0){
      xml = parser.parseFromString(raw.slice(firstTag), "application/xml");
    }
  }
  if (xml.getElementsByTagName("parsererror").length){
    // Some KMZ exports include xsi:schemaLocation but omit xmlns:xsi on <kml>.
    // Auto-heal that namespace declaration so otherwise-valid KML can parse.
    if (raw.includes("xsi:schemaLocation") && !raw.includes("xmlns:xsi")){
      const healed = raw.replace(
        /<kml\b([^>]*)>/i,
        '<kml xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"$1>'
      );
      if (healed !== raw){
        xml = parser.parseFromString(healed, "application/xml");
      }
    }
  }
  if (xml.getElementsByTagName("parsererror").length){
    throw new Error("Invalid KML inside KMZ.");
  }
  const rows = [];
  let rowNumber = 2;
  let featureSeq = 1;
  const featureIdCounts = new Map();
  const allLayerNames = [];
  const layerSeen = new Set();
  const styleCatalog = parseKmlStyleCatalog(xml);
  const treeRoot = {
    id: "kmz-root",
    type: "folder",
    label: "Project",
    children: [],
    path: [],
  };

  const nextNodeId = (prefix) => `${prefix}-${Math.random().toString(36).slice(2, 10)}-${Date.now().toString(36)}`;

  const addLayerCatalog = (value) => {
    const name = canonicalKmzLayerName(value);
    if (!name || layerSeen.has(name)) return;
    layerSeen.add(name);
    allLayerNames.push(name);
  };

  const visitContainer = (container, parentNode, parentPath = []) => {
    const children = Array.from(container?.children || []);
    children.forEach((child) => {
      const local = String(child.localName || child.nodeName || "").toLowerCase();
      if (local === "folder" || local === "document"){
        const folderName = getDirectKmlName(child) || (local === "document" ? "Project" : "Folder");
        const path = parentPath.concat(folderName);
        addLayerCatalog(folderName);
        const folderNode = {
          id: nextNodeId("kmz-folder"),
          type: "folder",
          label: folderName,
          children: [],
          path,
        };
        parentNode.children.push(folderNode);
        visitContainer(child, folderNode, path);
        return;
      }
      if (local !== "placemark") return;
      const placemarkName = getDirectKmlName(child) || `Placemark ${featureSeq}`;
      const geometry = parsePlacemarkGeometry(child);
      const addressText = String(getDirectKmlChildText(child, "address") || "").trim();
      const hasDataFields = child.getElementsByTagName("Data").length > 0
        || child.getElementsByTagName("SimpleData").length > 0;
      // Address-only exports carry no geometry; keep those placemarks so
      // coordinates can be resolved later (existing-site match or geocoding).
      if (!geometry && !addressText && !hasDataFields) return;
      const placemarkId = String(
        child.getAttribute("id")
        || child.getAttribute("targetId")
        || child.getAttributeNS?.("http://www.opengis.net/kml/2.2", "id")
        || ""
      ).trim();
      const stableBaseFeatureId = buildStableFeatureId({
        placemarkId,
        placemarkName,
        folderPath: parentPath.join(" / "),
        geometry,
      });
      const featureCount = (featureIdCounts.get(stableBaseFeatureId) || 0) + 1;
      featureIdCounts.set(stableBaseFeatureId, featureCount);
      const stableFeatureId = featureCount > 1
        ? `${stableBaseFeatureId}-${featureCount}`
        : stableBaseFeatureId;
      const center = getGeometryCenter(geometry);
      const folderName = parentPath[parentPath.length - 1] || "Project";
      const layerName = canonicalKmzLayerName(folderName);
      addLayerCatalog(folderName);
      const descriptionRaw = getDirectKmlChildText(child, "description");
      const hasLineGeometry = child.getElementsByTagName("LineString").length > 0;
      const hasPolygonGeometry = (
        child.getElementsByTagName("Polygon").length > 0
        || child.getElementsByTagName("LinearRing").length > 0
      );
      const row = {
        id: `${Date.now()}-${featureSeq}`,
        location_name: placemarkName,
        placemark_name: placemarkName,
        folder_name: folderName,
        folder_path: parentPath.join(" / "),
        latitude: center?.lat ?? null,
        longitude: center?.lng ?? null,
        geometry,
        __address: addressText || null,
        __kml_style: resolveKmlPlacemarkStyle(child, styleCatalog),
        raw_description_html: descriptionRaw || "",
        notes: stripHtmlTags(descriptionRaw) || null,
        __kml_layer: layerName || null,
        __kml_layer_raw: folderName || null,
        __layer_type: inferKmzLayerType(parentPath),
        __has_line_geometry: hasLineGeometry,
        __has_polygon_geometry: hasPolygonGeometry,
        __feature_id: stableFeatureId,
        __rowNumber: rowNumber,
      };
      const dataNodes = Array.from(child.getElementsByTagName("Data"));
      dataNodes.forEach((node) => {
        const key = SpecCom.helpers.normalizeImportHeader(node.getAttribute("name"));
        const value = node.getElementsByTagName("value")[0]?.textContent?.trim();
        if (key && value) row[key] = value;
      });
      const simpleNodes = Array.from(child.getElementsByTagName("SimpleData"));
      simpleNodes.forEach((node) => {
        const key = SpecCom.helpers.normalizeImportHeader(node.getAttribute("name"));
        const value = node.textContent?.trim();
        if (key && value) row[key] = value;
      });
      row.__display_name = getKmzPreferredLocationName(row) || placemarkName;
      rows.push(row);
      parentNode.children.push({
        id: `kmz-leaf-${row.__feature_id}`,
        type: "leaf",
        label: row.__display_name,
        featureId: row.__feature_id,
      });
      featureSeq += 1;
      rowNumber += 1;
    });
  };

  const kmlNode = xml.documentElement;
  const rootLabel = getDirectKmlName(kmlNode) || "Project";
  treeRoot.label = canonicalKmzLayerName(rootLabel) || rootLabel;
  visitContainer(kmlNode, treeRoot, []);

  if (!allLayerNames.length){
    allLayerNames.push(...KMZ_CRITICAL_LAYERS);
  }

  const attachLayerCatalog = (targetRows) => {
    try{
      Object.defineProperty(targetRows, "__kmlLayerNames", {
        value: allLayerNames.slice(),
        enumerable: false,
        writable: true,
      });
      Object.defineProperty(targetRows, "__kmlFolderTree", {
        value: treeRoot,
        enumerable: false,
        writable: true,
      });
    } catch {}
    return targetRows;
  };
  return attachLayerCatalog(rows);
}

function decodeKmzTextBytes(bytes){
  if (!bytes || !bytes.length) return "";
  const view = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  // BOM-aware decoding for KMZ KML files exported as UTF-8/UTF-16.
  if (view.length >= 2){
    if (view[0] === 0xFF && view[1] === 0xFE){
      return new TextDecoder("utf-16le").decode(view);
    }
    if (view[0] === 0xFE && view[1] === 0xFF){
      // Decode as LE after swapping bytes for BE payload.
      const swapped = new Uint8Array(view.length - (view.length % 2));
      for (let i = 0; i + 1 < view.length; i += 2){
        swapped[i] = view[i + 1];
        swapped[i + 1] = view[i];
      }
      return new TextDecoder("utf-16le").decode(swapped);
    }
  }
  if (view.length >= 3 && view[0] === 0xEF && view[1] === 0xBB && view[2] === 0xBF){
    return new TextDecoder("utf-8").decode(view);
  }
  return new TextDecoder("utf-8").decode(view);
}

async function parseKmzFile(file){
  const JSZip = await loadJsZip();
  const zip = await JSZip.loadAsync(file);
  const entries = Object.values(zip.files || {}).filter((entry) => !entry.dir);
  const kmlEntries = entries.filter((entry) => String(entry.name || "").toLowerCase().endsWith(".kml"));
  if (!kmlEntries.length){
    throw new Error("KMZ does not contain a .kml file.");
  }
  const preferred = kmlEntries.find((entry) => String(entry.name || "").toLowerCase().endsWith("doc.kml")) || kmlEntries[0];
  const ordered = [preferred, ...kmlEntries.filter((entry) => entry !== preferred)];
  let lastError = null;
  for (const entry of ordered){
    try{
      const kmlBytes = await entry.async("uint8array");
      const kmlText = decodeKmzTextBytes(kmlBytes);
      const rows = parseKmlText(kmlText);
      if (!rows.length) continue;
      const serviceRows = rows.filter((row) => /service\s*location/i.test(String(row?.__kml_layer_raw || "")));
      const selectedRows = serviceRows.length ? serviceRows : rows;
      const allRows = rows.slice();
      try{
        Object.defineProperty(allRows, "__kmlLayerNames", {
          value: Array.isArray(rows.__kmlLayerNames) ? rows.__kmlLayerNames.slice() : [],
          enumerable: false,
          writable: true,
        });
        Object.defineProperty(allRows, "__kmlFolderTree", {
          value: rows.__kmlFolderTree || null,
          enumerable: false,
          writable: true,
        });
      } catch {}
      try{
        Object.defineProperty(selectedRows, "__allKmzRows", {
          value: allRows,
          enumerable: false,
          writable: true,
        });
        Object.defineProperty(selectedRows, "__kmlLayerNames", {
          value: Array.isArray(rows.__kmlLayerNames) ? rows.__kmlLayerNames.slice() : [],
          enumerable: false,
          writable: true,
        });
        Object.defineProperty(selectedRows, "__kmlFolderTree", {
          value: rows.__kmlFolderTree || null,
          enumerable: false,
          writable: true,
        });
      } catch {}
      return selectedRows;
    } catch (err){
      lastError = err;
    }
  }
  if (lastError) throw lastError;
  throw new Error("KMZ contains KML files but no valid placemarks were found.");
}

async function parseKmlFile(file){
  const kmlText = await file.text();
  const rows = parseKmlText(kmlText);
  if (!rows.length){
    throw new Error("KML file has no placemarks.");
  }
  const serviceRows = rows.filter((row) => /service\s*location/i.test(String(row?.__kml_layer_raw || "")));
  const selectedRows = serviceRows.length ? serviceRows : rows;
  const allRows = rows.slice();
  try{
    Object.defineProperty(allRows, "__kmlLayerNames", {
      value: Array.isArray(rows.__kmlLayerNames) ? rows.__kmlLayerNames.slice() : [],
      enumerable: false,
      writable: true,
    });
    Object.defineProperty(allRows, "__kmlFolderTree", {
      value: rows.__kmlFolderTree || null,
      enumerable: false,
      writable: true,
    });
  } catch {}
  try{
    Object.defineProperty(selectedRows, "__allKmzRows", {
      value: allRows,
      enumerable: false,
      writable: true,
    });
    Object.defineProperty(selectedRows, "__kmlLayerNames", {
      value: Array.isArray(rows.__kmlLayerNames) ? rows.__kmlLayerNames.slice() : [],
      enumerable: false,
      writable: true,
    });
    Object.defineProperty(selectedRows, "__kmlFolderTree", {
      value: rows.__kmlFolderTree || null,
      enumerable: false,
      writable: true,
    });
  } catch {}
  return selectedRows;
}

const GEOCODE_ENDPOINT = "https://nominatim.openstreetmap.org/search";
const GEOCODE_MAX_ADDRESSES = 40;
const GEOCODE_DELAY_MS = 1100; // Nominatim usage policy: max 1 request/second

function parseImportNumberOrNull(value){
  const num = Number(String(value ?? "").trim());
  return String(value ?? "").trim() !== "" && Number.isFinite(num) ? num : null;
}

function getImportRowNameCandidates(row){
  return [
    row?.network_point_name,
    row?.name,
    row?.location_name,
    row?.placemark_name,
    row?.connectivity_point_name,
  ]
    .map((value) => String(value || "").trim().toLowerCase())
    .filter(Boolean);
}

async function geocodeImportAddress(query){
  const url = `${GEOCODE_ENDPOINT}?format=jsonv2&limit=1&q=${encodeURIComponent(query)}`;
  const res = await fetch(url, { headers: { Accept: "application/json" } });
  if (!res.ok) return null;
  const results = await res.json();
  const hit = Array.isArray(results) ? results[0] : null;
  const lat = Number(hit?.lat);
  const lng = Number(hit?.lon);
  return Number.isFinite(lat) && Number.isFinite(lng) ? { lat, lng } : null;
}

async function resolveImportRowCoordinates(rows){
  const summary = { matched: 0, geocoded: 0, unresolved: 0 };
  const pending = (Array.isArray(rows) ? rows : []).filter((row) => (
    toFiniteNumberOrNull(row?.latitude) === null || toFiniteNumberOrNull(row?.longitude) === null
  ));
  if (!pending.length) return summary;

  const siteCoordsByName = new Map();
  getVisibleSites().forEach((site) => {
    const coords = getSiteCoords(site);
    const key = String(site?.name || "").trim().toLowerCase();
    if (coords && key && !siteCoordsByName.has(key)) siteCoordsByName.set(key, coords);
  });

  const applyCoords = (row, coords, source) => {
    row.latitude = coords.lat;
    row.longitude = coords.lng;
    if (!row.geometry) row.geometry = { type: "Point", coordinates: [coords.lng, coords.lat] };
    if (!row.gps_status) row.gps_status = source;
  };

  const geocodeQueue = [];
  pending.forEach((row) => {
    let coords = null;
    for (const candidate of getImportRowNameCandidates(row)){
      if (siteCoordsByName.has(candidate)){
        coords = siteCoordsByName.get(candidate);
        break;
      }
    }
    if (coords){
      applyCoords(row, coords, "matched existing location");
      summary.matched += 1;
      return;
    }
    const address = String(row?.__address || row?.address || "").trim();
    if (address) geocodeQueue.push({ row, address });
    else summary.unresolved += 1;
  });

  if (!geocodeQueue.length) return summary;

  const uniqueAddresses = [...new Set(geocodeQueue.map((entry) => entry.address))];
  const lookupAddresses = uniqueAddresses.slice(0, GEOCODE_MAX_ADDRESSES);
  if (uniqueAddresses.length > lookupAddresses.length){
    toast("Address lookup capped", `Looking up the first ${GEOCODE_MAX_ADDRESSES} of ${uniqueAddresses.length} addresses.`);
  }
  toast("Looking up addresses", `Geocoding ${lookupAddresses.length} address${lookupAddresses.length === 1 ? "" : "es"} — about ${Math.ceil(lookupAddresses.length * GEOCODE_DELAY_MS / 1000)}s.`);
  const cache = new Map();
  for (let i = 0; i < lookupAddresses.length; i += 1){
    if (i > 0) await new Promise((resolve) => setTimeout(resolve, GEOCODE_DELAY_MS));
    try{
      cache.set(lookupAddresses[i], await geocodeImportAddress(lookupAddresses[i]));
    } catch {
      cache.set(lookupAddresses[i], null);
    }
  }
  geocodeQueue.forEach(({ row, address }) => {
    const coords = cache.get(address) || null;
    if (coords){
      applyCoords(row, coords, "geocoded from address");
      summary.geocoded += 1;
    } else {
      summary.unresolved += 1;
    }
  });
  return summary;
}

function parseWiredProductionPdfText(text){
  const src = String(text || "");
  if (!/\bJob\/Map\b/i.test(src) || !/\bEnclosure\b/i.test(src) || !/\bCodes\b/i.test(src)){
    return [];
  }
  const stopAt = src.search(/\bProduction Summary\b/i);
  const body = (stopAt >= 0 ? src.slice(0, stopAt) : src).replace(/\s+/g, " ").trim();
  if (!body) return [];
  const rowPattern = /([A-Za-z0-9]{20})\s+(.+?)\s+(\d{1,2}\/\d{1,2}\/\d{4})\s+([\s\S]*?)(?=([A-Za-z0-9]{20}\s+)|$)/g;
  const rows = [];
  let match;
  while ((match = rowPattern.exec(body))){
    const jobMap = String(match[1] || "").trim();
    const preDate = String(match[2] || "").trim();
    const prodDate = String(match[3] || "").trim();
    const payload = String(match[4] || "").trim();
    if (!jobMap || !preDate || !prodDate) continue;

    const enclosureMatch = preDate.match(/^(\d+(?:\/@[A-Za-z0-9.]+)?(?:\s*-\s*RE\s*ENTRY)?)\b/i);
    const enclosure = enclosureMatch ? enclosureMatch[1].replace(/\s+/g, " ").trim() : preDate.split(/\s+/)[0];
    const tech = enclosureMatch ? preDate.slice(enclosureMatch[0].length).trim() : preDate.split(/\s+/).slice(1).join(" ");

    // Keep only code-like fragments ending in [qty], drop wrapped names/test markers.
    const codes = [];
    const codePattern = /([^,\n]+?)\s*\[(\d+(?:\.\d+)?)\]/g;
    let codeMatch;
    while ((codeMatch = codePattern.exec(payload))){
      const code = String(codeMatch[1] || "").trim().replace(/\s+/g, " ");
      const qty = Number(codeMatch[2]);
      if (!code) continue;
      codes.push({ item: code, qty: Number.isFinite(qty) ? qty : 1 });
    }
    if (!codes.length){
      continue;
    }
    const billingCodes = Array.from(new Set(codes.map((item) => item.item)));
    rows.push({
      location_name: enclosure || `${jobMap}|${prodDate}`,
      enclosure,
      job_map: jobMap,
      external_ref: `${jobMap}|${enclosure}`,
      production_date: prodDate,
      tech,
      codes_raw: payload,
      billing_codes: billingCodes,
      items: codes,
      __rowNumber: rows.length + 2,
    });
  }
  return rows;
}

function buildItemsFromRow(row){
  const items = [];
  Object.keys(row).forEach((key) => {
    const match = key.match(/^item_(\d+)$/);
    if (!match) return;
    const idx = match[1];
    const item = String(row[key] || "").trim();
    if (!item) return;
    const qtyKey = `qty_${idx}`;
    const qtyRaw = row[qtyKey];
    const qty = qtyRaw == null || qtyRaw === "" ? null : Number(qtyRaw);
    items.push({ item, qty: Number.isFinite(qty) ? qty : null });
  });
  if (!items.length){
    const codesRaw = String(row?.codes || row?.codes_raw || "").trim();
    if (codesRaw){
      codesRaw.split(",").forEach((part) => {
        const value = String(part || "").trim();
        if (!value) return;
        const match = value.match(/^(.*?)\s*\[(\d+(?:\.\d+)?)\]\s*$/);
        const item = match ? String(match[1] || "").trim() : value;
        const qty = match ? Number(match[2]) : 1;
        if (!item) return;
        items.push({ item, qty: Number.isFinite(qty) ? qty : 1 });
      });
    }
  }
  return items;
}

function extractEnclosureToken(text){
  const raw = String(text || "").trim();
  if (!raw) return "";
  const numericTokens = raw.match(/\d+(?:\/@[\w.]+)?/g) || [];
  if (numericTokens.length > 1 && /(node\s*\d+|1635\s*ca)/i.test(raw)){
    const candidates = numericTokens.filter((token) => {
      const base = String(token).split("/@")[0] || token;
      const num = Number.parseInt(base, 10);
      return Number.isFinite(num) && (num >= 100 || base.length >= 3);
    });
    if (candidates.length){
      return candidates[candidates.length - 1];
    }
    return numericTokens[numericTokens.length - 1];
  }
  const direct = raw.match(/^\d+(?:\/@[\w.]+)?$/);
  if (direct) return direct[0];
  const token = raw.match(/\b(\d+(?:\/@[\w.]+)?)\b/);
  return token ? token[1] : "";
}

function getImportCoordsLookup(){
  const map = new Map();
  const rows = getVisibleSites();
  rows.forEach((site) => {
    const coords = getSiteCoords(site);
    if (!coords) return;
    const name = String(site?.name || "").trim();
    const display = String(getSiteDisplayName(site) || "").trim();
    const enclosure = extractEnclosureToken(name) || extractEnclosureToken(display);
    const keys = [name, display, enclosure]
      .map((v) => String(v || "").trim().toLowerCase())
      .filter(Boolean);
    keys.forEach((key) => {
      if (!map.has(key)) map.set(key, coords);
    });
  });
  return map;
}

function parseLatLngCandidate(value){
  const text = String(value ?? "").trim();
  if (!text) return null;
  const num = Number.parseFloat(text);
  return Number.isFinite(num) ? num : null;
}

function splitImportList(raw){
  return String(raw || "")
    .split(/[,\n;|]/)
    .map((part) => part.trim())
    .filter(Boolean);
}

function buildBillingCodesFromRow(row){
  const set = new Set();
  Object.keys(row || {}).forEach((key) => {
    const lower = String(key || "").trim().toLowerCase();
    if (/^(billing_)?code_\d+$/.test(lower) || /^work_code_\d+$/.test(lower)){
      const value = String(row[key] || "").trim();
      if (value) set.add(value);
      return;
    }
    if (["billing_codes", "billing_code", "codes", "work_codes"].includes(lower)){
      splitImportList(row[key]).forEach((code) => set.add(code));
    }
  });
  return Array.from(set);
}

function buildPhotoUrlsFromRow(row){
  const set = new Set();
  Object.keys(row || {}).forEach((key) => {
    const lower = String(key || "").trim().toLowerCase();
    if (/^(photo|image)(_url)?_\d+$/.test(lower)){
      const value = String(row[key] || "").trim();
      if (/^https?:\/\//i.test(value)) set.add(value);
      return;
    }
    if (["photo_urls", "photos", "image_urls"].includes(lower)){
      splitImportList(row[key]).forEach((url) => {
        if (/^https?:\/\//i.test(url)) set.add(url);
      });
    }
  });
  return Array.from(set);
}

function validateLocationImportRows(rows){
  const errors = [];
  const warnings = [];
  const validRows = [];
  const coordsLookup = getImportCoordsLookup();
  (rows || []).forEach((row) => {
    const rowId = row?.__rowNumber ?? "?";
    const name = String(
      row?.location_name || row?.enclosure || row?.name || row?.drop_number || ""
    ).trim();
    let lat = parseLatLngCandidate(row?.latitude ?? row?.lat);
    let lng = parseLatLngCandidate(row?.longitude ?? row?.lng);
    const latValid = Number.isFinite(lat) && lat >= -90 && lat <= 90;
    const lngValid = Number.isFinite(lng) && lng >= -180 && lng <= 180;
    if (!name){
      errors.push({ row: rowId, reason: "Missing location_name." });
      return;
    }
    if (!latValid || !lngValid){
      const enclosure = String(row?.enclosure || extractEnclosureToken(name)).trim();
      const externalRef = String(row?.external_ref || "").trim();
      const keys = [
        name,
        enclosure,
        externalRef,
        externalRef.includes("|") ? externalRef.split("|").pop() : "",
      ]
        .map((v) => String(v || "").trim().toLowerCase())
        .filter(Boolean);
      let matchedCoords = null;
      for (const key of keys){
        if (coordsLookup.has(key)){
          matchedCoords = coordsLookup.get(key);
          break;
        }
      }
      if (matchedCoords){
        lat = matchedCoords.lat;
        lng = matchedCoords.lng;
        warnings.push({ row: rowId, reason: "Coordinates auto-filled from existing project site match." });
      }
    }
    if (!Number.isFinite(lat) || lat < -90 || lat > 90){
      errors.push({ row: rowId, reason: "Latitude must be between -90 and 90 (or match an existing site)." });
      return;
    }
    if (!Number.isFinite(lng) || lng < -180 || lng > 180){
      errors.push({ row: rowId, reason: "Longitude must be between -180 and 180 (or match an existing site)." });
      return;
    }

    const next = {
      ...row,
      location_name: name,
      latitude: lat,
      longitude: lng,
      notes: row?.notes ? String(row.notes).trim() : null,
      items: Array.isArray(row?.items) ? row.items : [],
      billing_codes: Array.isArray(row?.billing_codes) ? row.billing_codes : [],
      photo_urls: Array.isArray(row?.photo_urls) ? row.photo_urls : [],
    };

    next.billing_codes = Array.from(new Set(
      next.billing_codes.map((code) => String(code || "").trim()).filter(Boolean)
    ));

    const goodPhotoUrls = [];
    next.photo_urls.forEach((url) => {
      const normalized = String(url || "").trim();
      if (!normalized) return;
      if (!/^https?:\/\//i.test(normalized)){
        warnings.push({ row: rowId, reason: `Ignored non-URL photo value: ${normalized}` });
        return;
      }
      goodPhotoUrls.push(normalized);
    });
    next.photo_urls = Array.from(new Set(goodPhotoUrls));

    if (!next.items.length && !next.billing_codes.length){
      warnings.push({ row: rowId, reason: "No items or billing codes found." });
    }
    validRows.push(next);
  });
  return { errors, warnings, validRows };
}

