function getKmzLeafletStyle(row, geometryType){
  const layerType = row?.__layer_type || "networkPoints";
  const palette = {
    networkPoints: "#2563eb",
    connectivityPoints: "#16a34a",
    drops: "#f97316",
    cable: "#0ea5e9",
  };
  const fallbackColor = palette[layerType] || "#2563eb";
  const kmlStyle = row?.__kml_style || null;
  if (geometryType === "Point"){
    const icon = kmlStyle?.icon || {};
    return {
      radius: icon.scale ? Math.max(4, Math.round(6 * icon.scale)) : 6,
      color: icon.color || fallbackColor,
      fillColor: icon.color || fallbackColor,
      fillOpacity: Number.isFinite(icon.opacity) ? Math.max(0.5, icon.opacity) : 0.88,
      weight: 2,
      pane: MAP_PANES.kmz,
      bubblingMouseEvents: false,
    };
  }
  if (geometryType === "Polygon"){
    const poly = kmlStyle?.poly || {};
    const line = kmlStyle?.line || {};
    return {
      color: line.color || poly.color || fallbackColor,
      weight: line.width || 2,
      fillColor: poly.color || fallbackColor,
      fillOpacity: poly.fill === false ? 0 : (Number.isFinite(poly.opacity) ? poly.opacity : 0.14),
      opacity: poly.outline === false ? 0 : (Number.isFinite(line.opacity) ? line.opacity : 1),
      pane: MAP_PANES.kmz,
      bubblingMouseEvents: false,
    };
  }
  const line = kmlStyle?.line || {};
  return {
    color: line.color || fallbackColor,
    weight: line.width || 2,
    opacity: Number.isFinite(line.opacity) ? line.opacity : 0.7,
    pane: MAP_PANES.kmz,
    bubblingMouseEvents: false,
  };
}

function createKmzLeafletLayer(feature, row){
  if (!window.L || !feature?.geometry) return null;
  const geom = feature.geometry;
  if (HIDE_KMZ_NETWORK_VISUALS && (geom.type === "Point" || geom.type === "LineString" || geom.type === "MultiLineString")){
    return null;
  }
  if (geom.type === "Point"){
    const lat = Number(geom.coordinates?.[1]);
    const lng = Number(geom.coordinates?.[0]);
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
    return window.L.circleMarker([lat, lng], getKmzLeafletStyle(row, "Point"));
  }
  if (geom.type === "LineString"){
    const latLngs = (geom.coordinates || [])
      .map((coord) => [Number(coord?.[1]), Number(coord?.[0])])
      .filter((coord) => Number.isFinite(coord[0]) && Number.isFinite(coord[1]));
    if (!latLngs.length) return null;
    return window.L.polyline(latLngs, getKmzLeafletStyle(row, "LineString"));
  }
  if (geom.type === "MultiLineString"){
    const lineSets = (geom.coordinates || [])
      .map((line) => (Array.isArray(line) ? line : []))
      .map((line) => line
        .map((coord) => [Number(coord?.[1]), Number(coord?.[0])])
        .filter((coord) => Number.isFinite(coord[0]) && Number.isFinite(coord[1])))
      .filter((line) => line.length);
    if (!lineSets.length) return null;
    return window.L.polyline(lineSets, getKmzLeafletStyle(row, "LineString"));
  }
  if (geom.type === "Polygon"){
    const ring = Array.isArray(geom.coordinates?.[0]) ? geom.coordinates[0] : [];
    const latLngs = ring
      .map((coord) => [Number(coord?.[1]), Number(coord?.[0])])
      .filter((coord) => Number.isFinite(coord[0]) && Number.isFinite(coord[1]));
    if (!latLngs.length) return null;
    return window.L.polygon(latLngs, getKmzLeafletStyle(row, "Polygon"));
  }
  return null;
}

function parseKmzDescriptionRows(rawHtml){
  const parseRowsFromHtml = (htmlValue) => {
    const parser = new DOMParser();
    const doc = parser.parseFromString(`<body>${htmlValue}</body>`, "text/html");
    return Array.from(doc.querySelectorAll("tr"));
  };
  const decodeHtmlEntities = (value) => {
    const text = String(value || "");
    if (!text) return "";
    const el = document.createElement("textarea");
    el.innerHTML = text;
    return String(el.value || "");
  };
  const html = String(rawHtml || "").trim();
  if (!html) return [];
  let tableRows = parseRowsFromHtml(html);
  if (!tableRows.length && /&lt;\/?(table|tr|td|th)\b/i.test(html)){
    const decoded = decodeHtmlEntities(html);
    tableRows = parseRowsFromHtml(decoded);
  }
  const rows = [];
  tableRows.forEach((tr) => {
    const cells = Array.from(tr.querySelectorAll("th,td"))
      .map((cell) => cell.textContent.replace(/\s+/g, " ").trim())
      .filter(Boolean);
    if (cells.length < 2) return;
    rows.push({
      key: cells[0],
      value: cells.slice(1).join(" "),
    });
  });
  return rows;
}

function sanitizeKmzDescriptionText(rawHtml){
  const raw = String(rawHtml || "").trim();
  if (!raw) return "";
  const decodeHtmlEntities = (value) => {
    const el = document.createElement("textarea");
    el.innerHTML = String(value || "");
    return String(el.value || "");
  };
  const extractText = (htmlValue) => {
    const parser = new DOMParser();
    const doc = parser.parseFromString(`<body>${htmlValue}</body>`, "text/html");
    return String(doc.body?.textContent || "").replace(/\s+\n/g, "\n").replace(/\n\s+/g, "\n").replace(/[ \t]+/g, " ").trim();
  };
  let text = extractText(raw);
  if (!text && /&lt;\/?(table|tr|td|th|div|span|p)\b/i.test(raw)){
    text = extractText(decodeHtmlEntities(raw));
  }
  return text;
}

function normalizePopupRowKey(value){
  return String(value || "").trim().toLowerCase();
}

function getKmzPreferredLocationName(row){
  const candidates = [
    row?.ruidoso_network_point_name,
    row?.ruidosonetworkpointname,
    row?.ruidosonetworkname,
    row?.ruidoso_network_name,
    row?.networkname,
    row?.network_name,
    row?.placemark_name,
    row?.location_name,
  ];
  for (const candidate of candidates){
    const value = String(candidate || "").trim();
    if (value) return value;
  }
  return "";
}

function getKmzBillingCodes(row){
  if (Array.isArray(row?.billing_codes)){
    return Array.from(new Set(
      row.billing_codes.map((code) => String(code || "").trim()).filter(Boolean)
    ));
  }
  return buildBillingCodesFromRow(row || {});
}

function getKmzPhotoUrls(row){
  const featureId = String(row?.__feature_id || "").trim();
  const base = Array.isArray(row?.photo_urls)
    ? row.photo_urls
    : buildPhotoUrlsFromRow(row || {});
  const override = featureId ? (state.map.kmzPhotoOverrides.get(featureId) || []) : [];
  return Array.from(new Set(
    [...base, ...override]
      .map((url) => String(url || "").trim())
      .filter((url) => /^https?:\/\//i.test(url))
  ));
}

function setKmzFeaturePhotoUrls(featureId, urls){
  const key = String(featureId || "").trim();
  if (!key) return;
  const row = state.map.kmzFeatureRows.get(key) || null;
  const cleanUrls = Array.from(new Set(
    (Array.isArray(urls) ? urls : [])
      .map((url) => String(url || "").trim())
      .filter((url) => /^https?:\/\//i.test(url))
  ));
  if (row){
    row.photo_urls = cleanUrls.slice();
  }
  if (cleanUrls.length){
    state.map.kmzPhotoOverrides.set(key, cleanUrls.slice());
  } else {
    state.map.kmzPhotoOverrides.delete(key);
  }
  saveKmzPhotoOverridesForActiveProject();
  queueSaveKmzSnapshotForActiveProject();
}

function addKmzFeaturePhotoUrl(featureId, url){
  const key = String(featureId || "").trim();
  const clean = String(url || "").trim();
  if (!key || !/^https?:\/\//i.test(clean)) return false;
  const row = state.map.kmzFeatureRows.get(key) || null;
  const next = getKmzPhotoUrls(row || { __feature_id: key, photo_urls: [] });
  if (!next.includes(clean)) next.push(clean);
  setKmzFeaturePhotoUrls(key, next);
  return true;
}

function removeKmzFeaturePhotoUrl(featureId, url){
  const key = String(featureId || "").trim();
  if (!key) return;
  const row = state.map.kmzFeatureRows.get(key) || null;
  const next = getKmzPhotoUrls(row || { __feature_id: key, photo_urls: [] })
    .filter((entry) => entry !== String(url || "").trim());
  setKmzFeaturePhotoUrls(key, next);
}

function buildKmzPhotoSectionHtml(row){
  const featureId = String(row?.__feature_id || "").trim();
  const urls = getKmzPhotoUrls(row);
  return `
    <section class="kmz-photo-section" data-kmz-photo-feature="${escapeHtml(featureId)}">
      <div class="kmz-material-heading">Photos</div>
      ${urls.length ? `
        <div class="kmz-photo-grid">
          ${urls.map((url) => `
            <div class="kmz-photo-card">
              <a href="${escapeHtml(url)}" target="_blank" rel="noopener noreferrer">
                <img src="${escapeHtml(url)}" alt="Feature photo" loading="lazy" />
              </a>
              <button type="button" class="btn ghost small" data-photo-remove-url="${escapeHtml(url)}" data-photo-feature-id="${escapeHtml(featureId)}">Remove</button>
            </div>
          `).join("")}
        </div>
      ` : `<div class="muted small">No photos linked yet.</div>`}
      <div class="kmz-photo-add-row">
        <input class="input compact" type="url" placeholder="Paste photo URL" data-photo-url-input="${escapeHtml(featureId)}" />
        <button type="button" class="btn secondary small" data-photo-add-url data-photo-feature-id="${escapeHtml(featureId)}">Add Photo URL</button>
      </div>
    </section>
  `;
}

function appendKmzSupplementalRows(rows, row){
  const list = Array.isArray(rows) ? rows.slice() : [];
  const existingKeys = new Set(list.map((entry) => normalizePopupRowKey(entry?.key)));
  const billingCodes = getKmzBillingCodes(row);
  if (billingCodes.length && !existingKeys.has("billing codes")){
    list.push({ key: "Billing Codes", value: billingCodes.join(", ") });
  }
  const photoUrls = getKmzPhotoUrls(row);
  if (photoUrls.length && !existingKeys.has("photo urls")){
    list.push({ key: "Photo URLs", value: photoUrls.join(" | ") });
  }
  return list;
}

function applyKmzPopupLocationOverride(rows, locationName){
  const list = Array.isArray(rows) ? rows.slice() : [];
  const preferred = String(locationName || "").trim();
  if (!preferred || !list.length) return list;
  const locationIndex = list.findIndex((entry) => {
    const key = normalizePopupRowKey(entry?.key);
    return key === "location" || key === "location / name" || key === "location/name";
  });
  if (locationIndex >= 0){
    const existing = list[locationIndex] || {};
    list[locationIndex] = { ...existing, value: preferred };
    return list;
  }
  return [{ key: "Location", value: preferred }, ...list];
}

function isKmzPathFeatureRow(row){
  const name = String(row?.placemark_name || row?.location_name || "").trim();
  if (/^ruidosopath/i.test(name)) return true;
  const folderPath = String(
    row?.folder_path
    || row?.folder_name
    || row?.__kml_layer_raw
    || row?.__kml_layer
    || ""
  );
  return /\bpaths?\b/i.test(folderPath);
}

function trimRowsUntilKey(rows, keyName){
  const list = Array.isArray(rows) ? rows : [];
  if (!list.length) return [];
  const target = normalizePopupRowKey(keyName);
  const idx = list.findIndex((entry) => normalizePopupRowKey(entry?.key) === target);
  if (idx <= 0) return list;
  return list.slice(idx);
}

function buildKmzFallbackAttributeRows(row){
  const center = getGeometryCenter(row?.geometry || null);
  const preferredLocation = getKmzPreferredLocationName(row);
  const fallback = [
    ["Location / Name", preferredLocation],
    ["Feature ID", row?.__feature_id || row?.id || row?.__rowNumber || ""],
    ["Coordinates", center ? `${center.lat.toFixed(6)}, ${center.lng.toFixed(6)}` : ""],
    ["Folder", row?.folder_path || row?.folder_name || row?.__kml_layer || ""],
  ];
  const skip = new Set([
    "id",
    "location_name",
    "placemark_name",
    "folder_name",
    "folder_path",
    "latitude",
    "longitude",
    "geometry",
    "raw_description_html",
    "notes",
    "__kml_layer",
    "__kml_layer_raw",
    "__layer_type",
    "__feature_id",
    "__rowNumber",
  ]);
  Object.entries(row || {}).forEach(([key, value]) => {
    if (skip.has(key) || key.startsWith("__")) return;
    if (value == null || value === "") return;
    fallback.push([getFeatureFieldLabel(key), formatFeatureFieldValue(value)]);
  });
  if (row?.notes){
    fallback.push(["Notes", row.notes]);
  }
  return fallback
    .filter((entry) => String(entry[1] || "").trim())
    .map(([key, value]) => ({ key, value: String(value) }));
}

function getKmzPopupContentModel(row){
  const preferredLocation = getKmzPreferredLocationName(row);
  const descRows = appendKmzSupplementalRows(applyKmzPopupLocationOverride(
    parseKmzDescriptionRows(row?.raw_description_html || ""),
    preferredLocation
  ), row);
  if (descRows.length){
    const trimmedRows = appendKmzSupplementalRows(
      isKmzPathFeatureRow(row) ? trimRowsUntilKey(descRows, "Path Name") : descRows,
      row
    );
    if (trimmedRows.length){
      return { kind: "table", rows: trimmedRows };
    }
  }
  const plainText = sanitizeKmzDescriptionText(row?.raw_description_html || "");
  if (plainText){
    return { kind: "text", text: plainText };
  }
  return { kind: "table", rows: buildKmzFallbackAttributeRows(row) };
}

function buildKmzMaterialSectionHtml(featureId, {
  featureTotals = [],
  loading = false,
  errorText = "",
} = {}){
  const featureKey = String(featureId || "").trim();
  const byKey = new Map();
  (Array.isArray(featureTotals) ? featureTotals : []).forEach((row) => {
    const itemKey = normalizeMaterialItemKey(row?.item_key || "");
    if (!itemKey) return;
    byKey.set(itemKey, {
      item_key: itemKey,
      item_name: getMaterialItemLabel(itemKey, row?.item_name || ""),
      expected_qty: coerceMaterialInt(row?.expected_qty, 0),
      used_qty: coerceMaterialInt(row?.used_qty, 0),
    });
  });
  const keys = [
    ...MATERIAL_ITEM_KEYS,
    ...Array.from(byKey.keys()).filter((itemKey) => !MATERIAL_ITEM_KEYS.includes(itemKey)),
  ];
  const rows = keys.map((itemKey) => {
    const match = byKey.get(itemKey);
    return {
      item_key: itemKey,
      item_name: getMaterialItemLabel(itemKey, match?.item_name || ""),
      expected_qty: match?.expected_qty || 0,
      used_qty: match?.used_qty || 0,
    };
  });
  const canWrite = Boolean(
    state.activeProject?.id
    && state.client
    && state.user
    && !isDemo
    && !isDemoUser()
  );
  const disabledAttr = canWrite && !loading ? "" : " disabled";
  const statusHtml = errorText
    ? `<div class="muted small" style="color:#b91c1c;">${escapeHtml(errorText)}</div>`
    : (loading
      ? `<div class="muted small">Loading materials...</div>`
      : "");
  return `
    <section class="kmz-material-section" data-kmz-material-feature="${escapeHtml(featureKey)}">
      <div class="kmz-material-heading">Materials</div>
      ${statusHtml}
      <table class="kmz-popup-table">
        <tbody>
          ${rows.map((row) => `
            <tr>
              <th>${escapeHtml(row.item_name)}</th>
              <td>Expected ${row.expected_qty} | Used ${row.used_qty}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
      <div class="kmz-material-actions">
        ${MATERIAL_ITEM_KEYS.map((itemKey) => `
          <button
            type="button"
            class="btn secondary small"
            data-material-add="${escapeHtml(itemKey)}"
            data-material-feature-id="${escapeHtml(featureKey)}"${disabledAttr}
          >${escapeHtml(MATERIAL_ITEM_DEFS[itemKey]?.addLabel || `+ ${getMaterialItemLabel(itemKey)}`)}</button>
        `).join("")}
      </div>
      <div class="muted small">Planned vs used is company-scoped and updates alerts automatically.</div>
    </section>
  `;
}

function buildMapDetailsDrawerBodyHtml(row, {
  featureTotals = [],
  loadingMaterials = false,
  materialError = "",
} = {}){
  const model = getKmzPopupContentModel(row);
  const detailsHtml = model.kind === "table"
    ? `
      <table class="kmz-popup-table">
        <tbody>
          ${(model.rows || []).map((entry) => `
            <tr>
              <th>${escapeHtml(entry.key || "Field")}</th>
              <td>${escapeHtml(entry.value || "-")}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    `
    : `<div class="kmz-popup-text">${escapeHtml(model.text || "No description available.")}</div>`;
  return `
    ${detailsHtml}
    ${buildKmzMaterialSectionHtml(row?.__feature_id || "", {
      featureTotals,
      loading: loadingMaterials,
      errorText: materialError,
    })}
    ${buildKmzPhotoSectionHtml(row)}
  `;
}

function buildKmzFeaturePopupHtml(featureId){
  const row = state.map.kmzFeatureRows.get(String(featureId || "").trim()) || null;
  if (!row){
    return `<div class="kmz-popup"><div class="muted small">Feature unavailable.</div></div>`;
  }
  const title = getKmzPreferredLocationName(row) || "Placemark";
  const model = getKmzPopupContentModel(row);
  const tableHtml = model.kind === "table"
    ? `
      <table class="kmz-popup-table">
        <tbody>
          ${(model.rows || []).map((entry) => `
            <tr>
              <th>${escapeHtml(entry.key || "Field")}</th>
              <td>${escapeHtml(entry.value || "-")}</td>
            </tr>
          `).join("")}
        </tbody>
      </table>
    `
    : `<div class="kmz-popup-text">${escapeHtml(model.text || "No description available.")}</div>`;
  return `
    <div class="kmz-popup" data-kmz-feature-id="${escapeHtml(row.__feature_id || featureId)}">
      <h3 class="kmz-popup-title">${escapeHtml(title)}</h3>
      ${tableHtml}
      <div class="kmz-popup-actions">
        <button type="button" class="btn secondary small" data-kmz-action="view-details" data-kmz-feature-id="${escapeHtml(row.__feature_id || featureId)}">View Details</button>
      </div>
    </div>
  `;
}

async function openMapDetailsDrawerForKmzFeature(featureId){
  const key = String(featureId || "").trim();
  if (!key) return;
  const row = state.map.kmzFeatureRows.get(key) || null;
  if (!row) return;
  const drawer = $("mapDetailsDrawer");
  const titleEl = $("mapDetailsTitle");
  const bodyEl = $("mapDetailsBody");
  if (!drawer || !titleEl || !bodyEl) return;
  state.map.kmzSelectedFeatureId = key;
  state.map.materialFeatureId = key;
  handleRedlineContextChange();
  titleEl.textContent = getKmzPreferredLocationName(row) || "Feature details";
  bodyEl.innerHTML = buildMapDetailsDrawerBodyHtml(row, {
    featureTotals: [],
    loadingMaterials: true,
  });
  drawer.classList.add("is-open");
  let featureTotals = [];
  let materialError = "";
  try{
    featureTotals = await refreshMaterialFeatureTotals(key, { silent: true });
  } catch (error){
    materialError = getDetailedErrorMessage(error);
  }
  if (state.map.materialFeatureId !== key) return;
  bodyEl.innerHTML = buildMapDetailsDrawerBodyHtml(row, {
    featureTotals,
    loadingMaterials: false,
    materialError,
  });
}

function closeMapDetailsDrawer(){
  const drawer = $("mapDetailsDrawer");
  if (!drawer) return;
  drawer.classList.remove("is-open");
  state.map.materialFeatureId = "";
  handleRedlineContextChange();
}

async function handleMapDetailsMaterialAdd(featureId, itemKey){
  const featureKey = String(featureId || "").trim();
  const normalizedItemKey = normalizeMaterialItemKey(itemKey);
  const projectId = state.activeProject?.id || null;
  if (!featureKey || !normalizedItemKey || !projectId){
    toast("Materials unavailable", "Select a project and feature before logging usage.", "error");
    return;
  }
  if (!state.client || !state.user || isDemo || isDemoUser()){
    toast("Materials unavailable", "Sign in with a live account to log material usage.", "error");
    return;
  }
  const { data, error } = await state.client.rpc("fn_record_material_usage", {
    p_project_id: projectId,
    p_feature_id: featureKey,
    p_item_key: normalizedItemKey,
    p_qty_used: 1,
  });
  if (error){
    let message = getDetailedErrorMessage(error);
    if (String(error?.code || "") === "42702" && /item_key/i.test(message)){
      message = "Database material functions need migration fix (item_key ambiguity). Apply latest Supabase migrations and retry.";
    }
    toast("Material update failed", message, "error");
    return;
  }
  if (data && typeof data === "object"){
    setMapMaterialStateFromPayload(data);
  }
  const latestFeatureTotals = await refreshMaterialFeatureTotals(featureKey, { projectId, silent: true });
  if (state.map.materialFeatureId === featureKey){
    const row = state.map.kmzFeatureRows.get(featureKey) || null;
    const bodyEl = $("mapDetailsBody");
    if (row && bodyEl){
      bodyEl.innerHTML = buildMapDetailsDrawerBodyHtml(row, {
        featureTotals: latestFeatureTotals,
        loadingMaterials: false,
      });
    }
  }
  await refreshMaterialProjectData({ projectId, silent: true });
  if (data?.alerts){
    await triggerMaterialAlertNotifications(data.alerts, {
      projectId,
      companyId: getActiveCompanyId(),
    });
  }
}

async function openKmzFeaturePopup(featureId, { focusMap = true } = {}){
  const key = String(featureId || "").trim();
  if (!key) return;
  const featureMeta = state.map.kmzFeatureLayers.get(key) || null;
  if (!featureMeta || !state.map.instance) return;
  const row = state.map.kmzFeatureRows.get(key) || null;
  ensureKmzFolderChainVisible(featureMeta.parentNodeId);
  setKmzLeafVisibility(key, true);
  syncKmzOverlayGroups();
  state.map.kmzSelectedFeatureId = key;
  handleRedlineContextChange();
  const layer = featureMeta.layer;
  const map = state.map.instance;
  if (focusMap){
    if (typeof layer.getLatLng === "function"){
      const latLng = layer.getLatLng();
      if (latLng){
        map.setView(latLng, Math.max(map.getZoom(), 17));
      }
    } else if (typeof layer.getBounds === "function"){
      const bounds = layer.getBounds();
      if (bounds?.isValid?.()){
        map.fitBounds(bounds.pad(0.25));
      }
    }
  }
  const mappedSite = resolveSiteForKmzFeatureRow(row);
  if (mappedSite){
    const siteKey = toSiteIdKey(mappedSite?.id);
    if (siteKey){
      state.map.popupSiteKeys = [siteKey];
      state.map.popupSiteIndex = 0;
      state.map.popupMarker = layer || null;
      state.map.popupRequiredCodes = normalizeCodeList(getCodesRequiredForActiveProject());
      await renderMapPopupActiveSite({ syncSelection: false });
      if (isDebug){
        dlog("[kmz->site popup] using SpecCom popup for KMZ feature", {
          featureId: key,
          featureName: getKmzPreferredLocationName(row) || row?.location_name || null,
          siteId: mappedSite?.id || null,
          siteName: getSiteDisplayName(mappedSite || {}),
        });
      }
      renderMapLayerPanel();
      return;
    }
  }
  const popupHtml = buildKmzFeaturePopupHtml(key);
  if (typeof layer.getPopup !== "function" || !layer.getPopup()){
    layer.bindPopup(popupHtml, { className: "sc-site-popup", maxWidth: 440 });
  } else if (typeof layer.setPopupContent === "function"){
    layer.setPopupContent(popupHtml);
  } else {
    layer.bindPopup(popupHtml, { className: "sc-site-popup", maxWidth: 440 });
  }
  if (typeof layer.openPopup === "function"){
    layer.openPopup();
  }
  const feature = row ? buildKmzFeatureFromRow(row, row.__kml_layer || "KMZ") : null;
  if (feature){
    handleMapFeatureSelection(feature, { tab: "data" });
  }
  renderMapLayerPanel();
}

function buildFallbackKmzTree(rows){
  const root = {
    id: "kmz-root",
    type: "folder",
    label: "Project",
    children: [],
    path: [],
  };
  const folderIndex = new Map();
  folderIndex.set("", root);
  let folderSeq = 1;
  (rows || []).forEach((row, idx) => {
    const featureId = String(row?.__feature_id || row?.id || `kmz-feature-${idx + 1}`);
    row.__feature_id = featureId;
    const rawPath = String(row?.folder_path || row?.folder_name || row?.__kml_layer_raw || row?.__kml_layer || "Project");
    const parts = rawPath
      .split("/")
      .map((part) => canonicalKmzLayerName(part))
      .map((part) => String(part || "").trim())
      .filter(Boolean);
    let parent = root;
    let pathKey = "";
    parts.forEach((part) => {
      pathKey += `/${part.toLowerCase()}`;
      if (!folderIndex.has(pathKey)){
        const node = {
          id: `kmz-folder-fallback-${folderSeq}`,
          type: "folder",
          label: part,
          children: [],
          path: (parent.path || []).concat(part),
        };
        folderSeq += 1;
        folderIndex.set(pathKey, node);
        parent.children.push(node);
      }
      parent = folderIndex.get(pathKey);
    });
    parent.children.push({
      id: `kmz-leaf-${featureId}`,
      type: "leaf",
      label: getKmzPreferredLocationName(row) || `Placemark ${idx + 1}`,
      featureId,
    });
  });
  return root;
}

function registerKmzTreeNode(node, parentNodeId, parentGroup){
  if (!node || !window.L) return;
  if (!state.map.kmzNodeIndex) state.map.kmzNodeIndex = new Map();
  if (node.type === "leaf"){
    const row = state.map.kmzFeatureRows.get(node.featureId) || null;
    if (!row) return;
    const feature = buildKmzFeatureFromRow(row, row.__kml_layer || "KMZ");
    if (!feature) return;
    const layer = createKmzLeafletLayer(feature, row);
    if (!layer) return;
    const overlayKey = getKmzOverlayKeyForFeature(row, feature);
    layer.on("click", (event) => {
      const latlng = event?.latlng || (typeof layer.getLatLng === "function" ? layer.getLatLng() : null);
      if (beginRedlineDraftForKmzNode(node.featureId, latlng)){
        if (window.L?.DomEvent?.stop && event?.originalEvent){
          window.L.DomEvent.stop(event.originalEvent);
        }
        return;
      }
      void openKmzFeaturePopup(node.featureId, { focusMap: false });
    });
    // Label point features with their name, like Google Earth.
    const labelText = getKmzPreferredLocationName(row) || row.placemark_name || "";
    if (feature.geometry?.type === "Point" && labelText && typeof layer.bindTooltip === "function"){
      const permanent = state.map.kmzShowPermanentLabels === true;
      layer.bindTooltip(escapeHtml(labelText), {
        permanent,
        direction: "top",
        offset: [0, -6],
        className: "kmz-feature-label",
        opacity: 0.95,
      });
    }
    const visible = state.map.kmzFeatureVisibility.get(node.featureId) !== false;
    const skipParentGroup = overlayKey === "paths" || overlayKey === "boundaries";
    if (visible && !skipParentGroup){
      parentGroup.addLayer(layer);
    }
    state.map.kmzNodeIndex.set(node.id, {
      type: "leaf",
      node,
      parentNodeId,
    });
    state.map.kmzFeatureLayers.set(node.featureId, {
      layer,
      feature,
      nodeId: node.id,
      parentNodeId,
      overlayKey,
    });
    return;
  }
  const folderGroup = window.L.layerGroup();
  if (state.map.kmzFolderVisibility.get(node.id) !== false){
    parentGroup.addLayer(folderGroup);
  }
  state.map.kmzFolderVisibility.set(node.id, state.map.kmzFolderVisibility.get(node.id) !== false);
  state.map.kmzNodeIndex.set(node.id, {
    type: "folder",
    node,
    parentNodeId,
    group: folderGroup,
  });
  (node.children || []).forEach((child) => {
    registerKmzTreeNode(child, node.id, folderGroup);
  });
}

function renderKmzPreviewFeatures(rows, sourceName = "KMZ Import"){
  ensureMap();
  if (!state.map.instance || !window.L) return;
  ensureMapLayerRegistry();
  const map = state.map.instance;
  const kmzLayer = state.map.layers?.kmz;
  const kmzPathsLayer = state.map.layers?.kmzPaths;
  const kmzBoundsLayer = state.map.layers?.kmzBounds;
  const kmzPinsLayer = state.map.layers?.kmzPins;
  if (!kmzLayer) return;
  if (kmzLayer?.clearLayers) kmzLayer.clearLayers();
  [kmzPinsLayer, kmzPathsLayer, kmzBoundsLayer].forEach((layerGroup) => {
    if (!layerGroup) return;
    try{
      if (map.hasLayer(layerGroup)) map.removeLayer(layerGroup);
    } catch {}
    try{
      if (layerGroup.clearLayers) layerGroup.clearLayers();
    } catch {}
  });
  state.map.kmzImportGroups = new Map();
  state.map.kmzGroupVisibility = new Map();
  state.map.kmzFeatureLayers = new Map();
  state.map.kmzFeatureRows = new Map();
  state.map.kmzNodeIndex = new Map();
  state.map.kmzFeatureVisibility = new Map();
  state.map.kmzFolderVisibility = new Map();
  state.map.kmzOverlayGroups = null;
  state.map.kmzSelectedFeatureId = "";
  (rows || []).forEach((row, idx) => {
    const featureId = String(row?.__feature_id || row?.id || `kmz-feature-${idx + 1}`);
    row.__feature_id = featureId;
    row.__kml_layer = canonicalKmzLayerName(row?.__kml_layer || row?.__kml_layer_raw || row?.folder_name || sourceName);
    row.__layer_type = row.__layer_type || inferKmzLayerType(String(row?.folder_path || row?.folder_name || "").split("/"));
    state.map.kmzFeatureRows.set(featureId, row);
    state.map.kmzFeatureVisibility.set(featureId, true);
  });
  // Show permanent name labels (Google Earth style) only when the point count
  // is modest; dense files fall back to hover labels to avoid a wall of text.
  const pointCount = (rows || []).filter((row) => (row?.geometry?.type || "") === "Point").length;
  state.map.kmzShowPermanentLabels = pointCount > 0 && pointCount <= 250;
  rebuildRuidosoEvidenceIndex();
  let rootTree = rows?.__kmlFolderTree && rows.__kmlFolderTree.type === "folder"
    ? rows.__kmlFolderTree
    : buildFallbackKmzTree(rows || []);
  if (Array.isArray(rootTree?.children) && rootTree.children.length === 1 && rootTree.children[0]?.type === "folder"){
    rootTree = rootTree.children[0];
  }
  state.map.kmzFolderTree = rootTree;
  state.map.kmzRootNodeId = rootTree.id || "kmz-root";
  if (!(state.map.kmzTreeExpanded instanceof Set)) state.map.kmzTreeExpanded = new Set();
  state.map.kmzTreeExpanded.add(state.map.kmzRootNodeId);
  registerKmzTreeNode(rootTree, null, kmzLayer);
  state.map.kmzLayerCatalog = getOrderedKmzLayerList([
    ...(rows?.__kmlLayerNames || []),
    ...(rows || []).map((row) => row?.folder_name || row?.__kml_layer || row?.__kml_layer_raw),
  ], { includeCritical: true });
  setMapViewMenuDefaultsOnKmzImport();
  syncKmzOverlayGroups();
  logKmzOverlayLayerCounts();
  renderMapLayerPanel();
  fitMapToKmzRows(rows, { maxZoom: 16 });
  queueSaveKmzSnapshotForActiveProject();
}

function fitMapToKmzRows(rows, { maxZoom = 16 } = {}){
  if (!state.map.instance || !window.L) return;
  const points = [];
  const addPoint = (lat, lng) => {
    const latNum = Number(lat);
    const lngNum = Number(lng);
    if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)) return;
    if (latNum < -90 || latNum > 90) return;
    if (lngNum < -180 || lngNum > 180) return;
    points.push([latNum, lngNum]);
  };
  const walkCoords = (node) => {
    if (!Array.isArray(node)) return;
    if (node.length >= 2 && Number.isFinite(Number(node[0])) && Number.isFinite(Number(node[1]))){
      // GeoJSON coordinates are [lng, lat].
      addPoint(node[1], node[0]);
      return;
    }
    node.forEach((child) => walkCoords(child));
  };
  (rows || []).forEach((row) => {
    addPoint(row?.latitude, row?.longitude);
    if (row?.geometry && typeof row.geometry === "object"){
      walkCoords(row.geometry.coordinates);
    }
  });
  if (!points.length) return;
  if (points.length === 1){
    state.map.instance.setView(points[0], Math.max(state.map.instance.getZoom() || 0, 17));
    return;
  }
  const bounds = window.L.latLngBounds(points);
  if (bounds?.isValid?.()){
    state.map.instance.fitBounds(bounds, { padding: [24, 24], maxZoom });
  }
}

function ensureMapPanes(){
  const map = state.map.instance;
  if (!map || !window.L) return;
  const panes = [
    [MAP_PANES.boundary, 410],
    [MAP_PANES.spans, 420],
    [MAP_PANES.kmz, 430],
    [MAP_PANES.pins, 440],
    [MAP_PANES.photos, 450],
    [MAP_PANES.highlight, 460],
    [MAP_PANES.pending, 470],
  ];
  panes.forEach(([name, zIndex]) => {
    const pane = map.getPane(name) || map.createPane(name);
    pane.style.zIndex = String(zIndex);
  });
}

function exifPartToNumber(value){
  if (typeof value === "number") return value;
  if (!value || typeof value !== "object") return Number(value);
  const numerator = Number(value.numerator);
  const denominator = Number(value.denominator);
  if (!Number.isFinite(numerator) || !Number.isFinite(denominator) || denominator === 0) return NaN;
  return numerator / denominator;
}

function convertExifDmsToDecimal(dms, ref){
  if (!Array.isArray(dms) || dms.length < 3) return NaN;
  const deg = exifPartToNumber(dms[0]);
  const min = exifPartToNumber(dms[1]);
  const sec = exifPartToNumber(dms[2]);
  if (![deg, min, sec].every(Number.isFinite)) return NaN;
  let decimal = deg + (min / 60) + (sec / 3600);
  if (ref === "S" || ref === "W") decimal *= -1;
  return decimal;
}

async function savePhotoToSupabase(file, lat, lon){
  const client = state.client || supabase;
  if (!client){
    console.error("Supabase client not ready.");
    return null;
  }
  const projectId = state.activeProject?.id || null;
  const safeName = String(file?.name || "photo.jpg").trim().replace(/[^a-zA-Z0-9._-]+/g, "_");
  const filePath = `${projectId || "unassigned"}/${Date.now()}_${safeName}`;
  const { error: uploadError } = await client
    .storage
    .from("field-photos")
    .upload(filePath, file, { upsert: false, contentType: file?.type || "image/jpeg" });
  if (uploadError){
    console.error("Upload error:", uploadError);
    return null;
  }
  const { data: urlData } = client.storage.from("field-photos").getPublicUrl(filePath);
  const imageUrl = String(urlData?.publicUrl || "").trim();
  const payload = {
    project_id: projectId,
    file_name: String(file?.name || safeName || "photo"),
    image_url: imageUrl,
    latitude: Number(lat),
    longitude: Number(lon),
  };
  const { data, error: dbError } = await client
    .from("field_photos")
    .insert([payload])
    .select("id, project_id, file_name, image_url, latitude, longitude, created_at")
    .single();
  if (dbError){
    console.error("DB insert error:", dbError);
    return null;
  }
  return data || null;
}

function bindMapPhotoUploadInput(){
  const input = $("photoUpload");
  if (!input || input.dataset.bound === "1") return;
  input.dataset.bound = "1";
  input.addEventListener("change", (e) => {
    const files = Array.from(e?.target?.files || []);
    if (!files.length) return;
    if (!state.map.instance) ensureMap();
    if (!state.map.instance || !window.L) return;
    if (!window.EXIF){
      console.warn("EXIF library not loaded.");
      return;
    }
    files.forEach((file) => {
      const reader = new FileReader();
      reader.onload = (event) => {
        const img = new Image();
        img.onload = () => {
          window.EXIF.getData(img, function (){
            const lat = window.EXIF.getTag(this, "GPSLatitude");
            const lon = window.EXIF.getTag(this, "GPSLongitude");
            const latRef = window.EXIF.getTag(this, "GPSLatitudeRef");
            const lonRef = window.EXIF.getTag(this, "GPSLongitudeRef");
            if (!lat || !lon){
              console.warn("No GPS data found in image:", file.name);
              return;
            }
            const latitude = convertExifDmsToDecimal(lat, latRef);
            const longitude = convertExifDmsToDecimal(lon, lonRef);
            if (!Number.isFinite(latitude) || !Number.isFinite(longitude)){
              console.warn("Invalid GPS data in image:", file.name);
              return;
            }
            void savePhotoToSupabase(file, latitude, longitude)
              .then(async (saved) => {
                if (!saved){
                  toast("Upload failed", `Could not save ${file.name}.`, "error");
                  return;
                }
                if (state.activeProject?.id){
                  await loadProjectFieldPhotos(state.activeProject.id);
                } else {
                  state.map.fieldPhotos = [saved].concat(state.map.fieldPhotos || []);
                }
                renderDerivedMapLayers(getSiteSearchResultSet().rows);
                state.map.instance.setView([latitude, longitude], Math.max(state.map.instance.getZoom() || 0, 17));
                toast("Photo saved", `${file.name} pinned on map.`);
              })
              .catch((error) => {
                console.error("Photo save error:", error);
                toast("Upload failed", `Could not save ${file.name}.`, "error");
              });
          });
        };
        img.src = event?.target?.result || "";
      };
      reader.readAsDataURL(file);
    });
    e.target.value = "";
  });
}

function ensureMap(){
  if (state.map.instance || !window.L) return;
  const mapEl = $("liveMap");
  if (!mapEl) return;
  const map = window.L.map(mapEl).setView([39.5, -98.35], 10);
  const street = window.L.tileLayer(MAP_BASEMAPS.street.url, {
    attribution: MAP_BASEMAPS.street.attribution,
    maxZoom: MAP_BASEMAPS.street.maxZoom,
  });
  const satellite = window.L.tileLayer(MAP_BASEMAPS.satellite.url, {
    attribution: MAP_BASEMAPS.satellite.attribution,
    maxZoom: MAP_BASEMAPS.satellite.maxZoom,
  });
  state.map.basemapLayers = { street, satellite };
  state.map.basemap = getSavedBasemap();
  state.map.basemapLayer = state.map.basemap === "satellite" ? satellite : street;
  state.map.basemapLayer.addTo(map);
  state.map.layerVisibility = getSavedLayerVisibility();
  state.map.mapViewOverlays = getSavedMapViewOverlays();
  window.__speccomMap = map;
  state.map.instance = map;
  ensureMapPanes();
  initMapWorkspaceUi();
  applyDrawerUiState();
  ensureMapLayerRegistry();
  applyMapLayerVisibility();
  registerMapUiBindings();
  renderMapLayerPanel();
  setMapBasemap(state.map.basemap);
  // Prevent Leaflet from absorbing touches on overlay panels (causes multiple-click issue)
  ["mapFieldPanel", "leftControlRail", "mapDetailsDrawer"].forEach((id) => {
    const el = $(id);
    if (el && window.L?.DomEvent) {
      window.L.DomEvent.disableClickPropagation(el);
      window.L.DomEvent.disableScrollPropagation(el);
    }
  });
  renderFeatureDrawer();
  map.on("popupclose", () => {
    // Clear popup context so stale async callbacks don't corrupt the next popup
    state.map.popupSiteKeys = [];
    state.map.popupSiteIndex = 0;
    state.map.popupMarker = null;
    // Refocus the search input so the user can immediately search the next location
    const searchInput = $("kmzTreeSearch");
    if (searchInput){
      searchInput.focus();
      searchInput.select();
    }
  });
  map.on("click", async (event) => {
    const latlng = event?.latlng;
    if (!latlng){
      toast("Pin error", "Invalid map location.");
      return;
    }
    if (state.redline.enabled){
      if (!state.redline.addMode){
        return;
      }
      const backdrop = $("redlineEditorBackdrop");
      if (backdrop && !backdrop.hidden){
        return;
      }
      const point = getRedlinePointFromLatLng(latlng);
      if (!point){
        const source = state.redline.source || resolveRedlineSource();
        if (!source?.project_id){
          toast("Project required", "Select a project first, then add redline markers.", "error");
        } else {
          toast("Redline unavailable", "Map overlay is not ready yet. Try again.", "error");
        }
        return;
      }
      state.redline.addMode = false;
      openRedlineEditor({ point });
      renderRedlineUi();
      return;
    }
    const isPinPlacementMode = Boolean(state.map.dropPinMode || state.map.pinTargetSiteId);
    if (!isPinPlacementMode){
      return;
    }
    state.map.pendingLatLng = { lat: latlng.lat, lng: latlng.lng };
    dlog("[map click]", latlng.lat, latlng.lng);
    showPendingPinMarker(latlng);
    if (!state.map.dropPinMode) return;
    state.map.dropPinMode = false;
    const targetSiteId = state.map.pinTargetSiteId;
    state.map.pinTargetSiteId = null;
    if (targetSiteId){
      await updateSiteLocationFromMapClick(targetSiteId, { lat: latlng.lat, lng: latlng.lng });
    }
  });
  renderMapFieldPanel();
}

async function loadLocationNames(userIds){
  if (!state.client || !userIds.length) return;
  const { data } = await state.client
    .from("profiles")
    .select("id, display_name")
    .in("id", userIds);
  (data || []).forEach((row) => {
    if (row?.id) state.map.userNames.set(row.id, row.display_name || "");
  });
}

function updateMapMarkers(rows){
  if (!state.map.instance) return;
  ensureMapLayerRegistry();
  const pinsLayer = state.map.layers?.pins;
  if (HIDE_MAP_SITE_PINS){
    const markers = state.map.markers;
    markers.forEach((marker) => {
      if (pinsLayer?.removeLayer) pinsLayer.removeLayer(marker);
      else if (state.map.instance?.removeLayer) state.map.instance.removeLayer(marker);
    });
    markers.clear();
    state.map.featureMarkerMeta.clear();
    return;
  }
  const activeSearch = String(state.mapFilters.search || "").trim();
  const renderRows = activeSearch ? getSiteSearchResultSet().rows : (rows || []);
  const requiredCodesRaw = getCodesRequiredForActiveProject();
  const requiredCodes = Array.isArray(requiredCodesRaw) ? requiredCodesRaw : [];
  const markers = state.map.markers;
  const seen = new Set();
  renderRows.forEach((row) => {
    const coords = getSiteCoords(row);
    if (!coords){
      debugLog("[map] missing coordinates", row);
      return;
    }
    const id = toSiteIdKey(row?.id);
    if (!id) return;
    const markerCoords = [coords.lat, coords.lng];
    let marker = markers.get(id);
    const color = getSitePinColor(row);
    if (!marker){
      marker = window.L.circleMarker(markerCoords, {
        radius: 8,
        color,
        fillColor: color,
        fillOpacity: 0.9,
        weight: 2,
        pane: MAP_PANES.pins,
        bubblingMouseEvents: false,
      });
      const resolveSite = () => {
        return getVisibleSites().find((item) => toSiteIdKey(item?.id) === id) || row;
      };
      if (pinsLayer?.addLayer) pinsLayer.addLayer(marker);
      else marker.addTo(state.map.instance);
      marker.on("click", () => {
        openSiteMarkerPopup(marker, id, resolveSite, { syncSelection: true });
      });
      marker.on("mouseover", () => {
        openSiteMarkerPopup(marker, id, resolveSite, { syncSelection: false });
      });
      markers.set(id, marker);
      state.map.featureMarkerMeta.set(id, { kind: "site", siteId: id });
    } else {
      marker.setLatLng(markerCoords);
      if (marker.setStyle){
        marker.setStyle({ color, fillColor: color });
      }
    }
    bindSiteMarkerPopup(marker, row, {
      requiredCodes,
      siteCodes: getCachedSiteCodes(row.id),
      loadingCodes: false,
      sitePhotos: getCachedSitePhotos(row.id),
      loadingPhotos: false,
    });
    try{
      const loc = row.name || row.address || row.label || row.location_name || `Site ${row.id || ""}`.trim();
      const hoverCodes = normalizeCodeList(getCachedSiteCodes(row.id));
      const fallbackCodes = hoverCodes.length ? hoverCodes : requiredCodes;
      const codeText = fallbackCodes.length ? fallbackCodes.slice(0, 8).join(" | ") : "(none)";
      const more = fallbackCodes.length > 8 ? ` | +${fallbackCodes.length - 8} more` : "";
      const tooltipHtml = `
        <div class="scHoverTip">
          <div class="t1">${escapeHtml(loc)}</div>
          <div class="t2">Codes: ${escapeHtml(codeText + more)}</div>
        </div>
      `;
      const existingTooltip = typeof marker.getTooltip === "function" ? marker.getTooltip() : null;
      if (existingTooltip && typeof marker.setTooltipContent === "function"){
        marker.setTooltipContent(tooltipHtml);
      } else if (typeof marker.bindTooltip === "function"){
        marker.bindTooltip(tooltipHtml, {
          direction: "top",
          sticky: true,
          opacity: 0.97,
          className: "sc-hover-tooltip",
          interactive: false,
        });
      }
    } catch (error){
      debugLog("[map] tooltip render failed", error);
    }
    seen.add(id);
  });
  markers.forEach((marker, id) => {
    if (!seen.has(id)){
      if (pinsLayer?.removeLayer) pinsLayer.removeLayer(marker);
      else state.map.instance.removeLayer(marker);
      markers.delete(id);
      state.map.featureMarkerMeta.delete(id);
    }
  });
}

function renderDerivedMapLayers(rows){
  if (!state.map.instance || !window.L) return;
  ensureMapLayerRegistry();
  const boundaryLayer = state.map.layers?.boundary;
  const spansLayer = state.map.layers?.spans;
  const photosLayer = state.map.layers?.photos;
  if (boundaryLayer?.clearLayers) boundaryLayer.clearLayers();
  if (spansLayer?.clearLayers) spansLayer.clearLayers();
  if (photosLayer?.clearLayers) photosLayer.clearLayers();

  const sites = (rows || []).map((site) => ({ site, coords: getSiteCoords(site) })).filter((x) => x.coords);
  if (sites.length >= 2 && boundaryLayer){
    const points = sites.map((x) => [x.coords.lat, x.coords.lng]);
    const bounds = window.L.latLngBounds(points);
    const rectangle = window.L.rectangle(bounds, {
      color: "#0ea5e9",
      weight: 2,
      fillOpacity: 0.05,
      dashArray: "6 4",
      pane: MAP_PANES.boundary,
    });
    rectangle.on("click", () => {
      const feature = {
        type: "Feature",
        geometry: {
          type: "Polygon",
          coordinates: [[
            [bounds.getWest(), bounds.getSouth()],
            [bounds.getEast(), bounds.getSouth()],
            [bounds.getEast(), bounds.getNorth()],
            [bounds.getWest(), bounds.getNorth()],
            [bounds.getWest(), bounds.getSouth()],
          ]],
        },
        properties: {
          id: state.activeProject?.id || "",
          type: "BOUNDARY",
          name: `${state.activeProject?.name || "Project"} Boundary`,
          project_id: state.activeProject?.id || "",
          points: sites.length,
        },
      };
      handleMapFeatureSelection(feature);
    });
    boundaryLayer.addLayer(rectangle);
  }
  if (!HIDE_MAP_SPANS && sites.length >= 2 && spansLayer){
    const ordered = sites.slice().sort((a, b) => String(a.site?.name || "").localeCompare(String(b.site?.name || "")));
    const linePoints = ordered.map((x) => [x.coords.lat, x.coords.lng]);
    const span = window.L.polyline(linePoints, {
      color: "#14b8a6",
      weight: 3,
      opacity: 0.85,
      pane: MAP_PANES.spans,
    });
    span.on("click", () => {
      const feature = {
        type: "Feature",
        geometry: {
          type: "LineString",
          coordinates: ordered.map((x) => [x.coords.lng, x.coords.lat]),
        },
        properties: {
          id: `${state.activeProject?.id || "project"}-span`,
          type: "SPAN",
          name: `${state.activeProject?.name || "Project"} Path`,
          project_id: state.activeProject?.id || "",
          segment_count: Math.max(0, ordered.length - 1),
        },
      };
      handleMapFeatureSelection(feature);
    });
    spansLayer.addLayer(span);
  }
  if (photosLayer){
    (state.siteMedia || []).forEach((row, idx) => {
      const lat = Number(row?.gps_lat);
      const lng = Number(row?.gps_lng);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      const marker = window.L.circleMarker([lat, lng], {
        radius: 5,
        color: "#ef4444",
        fillColor: "#ef4444",
        fillOpacity: 0.85,
        weight: 2,
        pane: MAP_PANES.photos,
        bubblingMouseEvents: false,
      });
      const feature = {
        type: "Feature",
        geometry: { type: "Point", coordinates: [lng, lat] },
        properties: {
          id: row?.id || idx + 1,
          type: "PHOTO",
          name: state.activeSite ? `${getSiteDisplayName(state.activeSite)} Photo` : "Photo Marker",
          created_at: row?.created_at || "",
          gps_lat: lat,
          gps_lng: lng,
        },
      };
      marker.on("click", () => handleMapFeatureSelection(feature));
      photosLayer.addLayer(marker);
    });
    (state.map.fieldPhotos || []).forEach((row, idx) => {
      const lat = Number(row?.latitude);
      const lng = Number(row?.longitude);
      if (!Number.isFinite(lat) || !Number.isFinite(lng)) return;
      const marker = window.L.marker([lat, lng], { pane: MAP_PANES.photos, bubblingMouseEvents: false });
      const imgUrl = String(row?.image_url || "").trim();
      const fileLabel = String(row?.file_name || `Field photo ${idx + 1}`);
      marker.bindPopup(`
        <b>${escapeHtml(fileLabel)}</b><br>
        Lat: ${lat.toFixed(6)}<br>
        Lon: ${lng.toFixed(6)}
        ${imgUrl ? `<br><a href="${escapeHtml(imgUrl)}" target="_blank" rel="noopener noreferrer">Open image</a>` : ""}
      `);
      photosLayer.addLayer(marker);
    });
  }
}

async function refreshLocations(){
  const status = $("mapStatus");
  if (!state.client && !isDemo) return;
  if (!state.user){
    if (status) status.textContent = t("mapStatusSignin");
    renderMapFieldPanel();
    return;
  }
  ensureMap();
  await loadProjectSites(state.activeProject?.id || null);
  const searchResult = getSiteSearchResultSet();
  const rows = searchResult.rows;
  if (state.map.myLocation){
    const nearest = findNearestVisibleSite(state.map.myLocation, getFieldGpsAssociationRadius(state.map.myLocation));
    state.map.nearestSiteId = nearest?.site?.id ? toSiteIdKey(nearest.site.id) : "";
    state.map.nearestSiteDistanceM = nearest?.distanceM ?? null;
  } else {
    state.map.nearestSiteId = "";
    state.map.nearestSiteDistanceM = null;
  }
  updateMapMarkers(rows);
  renderDerivedMapLayers(rows);
  renderMapLayerPanel();
  renderFeatureDrawer();
  updateSiteSearchUiSummary(searchResult);
  renderMapFieldPanel();
  if (status){
    if (!state.activeProject){
      status.textContent = t("mapStatusNoProject");
    } else if (!rows.length){
      status.textContent = searchResult.rawQuery ? "No matching sites." : t("mapStatusNoSites");
    } else {
      status.textContent = searchResult.rawQuery
        ? `${rows.length} match${rows.length === 1 ? "" : "es"}`
        : t("mapStatusSites", { count: rows.length });
    }
  }
}

function showProfileSetupModal(show){
  const modal = $("profileSetupModal");
  if (!modal) return;
  if (show && state.profileSetupDismissed){
    modal.style.display = "none";
    return;
  }
  modal.style.display = show ? "flex" : "none";
}

function hasPreferredLanguageChoice(){
  const allowed = new Set(["en", "es", "pt"]);
  const profileLang = String(state.profile?.preferred_language || window.currentUserProfile?.preferred_language || "").trim().toLowerCase();
  const pendingLang = String(state.pendingPreferredLanguage || "").trim().toLowerCase();
  const storedLang = String(safeLocalStorageGet("preferred_language") || "").trim().toLowerCase();
  return allowed.has(profileLang) || allowed.has(pendingLang) || allowed.has(storedLang);
}

function syncLanguageControls(){
  const lang = getPreferredLanguage();
  const select = $("languageSelect");
  if (select) select.value = lang;
  const topSelect = $("languageSelectTop");
  if (topSelect) topSelect.value = lang;
  const menuSelect = $("languageSelectMenu");
  if (menuSelect) menuSelect.value = lang;
  const profileSelect = $("profileLanguageSelect");
  if (profileSelect) profileSelect.value = lang;
  syncMenuLanguageToggle();
}

function syncMenuLanguageToggle(){
  const lang = getPreferredLanguage();
  document.querySelectorAll("#menuModal .segmented-btn").forEach((btn) => {
    const btnLang = btn.getAttribute("data-lang");
    btn.classList.toggle("active", btnLang === lang);
  });
}

async function savePreferredLanguage(lang, { closeModal = false } = {}){
  const next = normalizeLanguage(lang);
  setPreferredLanguage(next);
  syncLanguageControls();
  if (!state.user || !state.client || isDemo){
    if (closeModal) showProfileSetupModal(false);
    return;
  }
  if (state.profile){
    try{
      const { error } = await state.client
        .from("profiles")
        .update({ preferred_language: next })
        .eq("id", state.user.id);
      if (error){
        const message = String(error.message || "").toLowerCase();
        if (error.status === 400 || message.includes("preferred_language")){
          safeLocalStorageSet("preferred_language", next);
          console.warn("preferred_language missing; using local fallback");
          if (closeModal) showProfileSetupModal(false);
          return;
        }
        toast("Language save failed", error.message);
        return;
      }
    } catch (err){
      console.warn("preferred_language missing; using local fallback", err);
      safeLocalStorageSet("preferred_language", next);
      if (closeModal) showProfileSetupModal(false);
      return;
    }
  } else {
    try{
      const { error } = await state.client
        .from("profiles")
        .insert({
          id: state.user.id,
          display_name: state.user?.email || null,
          preferred_language: next,
        });
      if (error){
        const message = String(error.message || "").toLowerCase();
        if (error.status === 400 || message.includes("preferred_language")){
          safeLocalStorageSet("preferred_language", next);
          console.warn("preferred_language missing; using local fallback");
          if (closeModal) showProfileSetupModal(false);
          return;
        }
        safeLocalStorageSet("preferred_language", next);
        if (closeModal) showProfileSetupModal(false);
        toast("Profile needed", "Ask an authorized team member to create your profile. Language saved locally.");
        return;
      }
    } catch (err){
      console.warn("preferred_language missing; using local fallback", err);
      safeLocalStorageSet("preferred_language", next);
      if (closeModal) showProfileSetupModal(false);
      return;
    }
  }
  await loadProfile(state.client, state.user?.id);
  if (closeModal) showProfileSetupModal(false);
}

