function getLocalDateISO(value = new Date()){
  const now = value instanceof Date ? value : new Date(value || Date.now());
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const day = String(now.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function formatTimeShort(value){
  if (!value) return "-";
  const date = new Date(value);
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function formatDurationMinutes(totalMinutes){
  const minutes = Number(totalMinutes || 0);
  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  return `${hours}h ${String(remainder).padStart(2, "0")}m`;
}

function formatEventLabel(eventType){
  switch (eventType){
    case "START_JOB":
      return t("techStartJob");
    case "PAUSE_JOB":
      return t("techPauseJob");
    case "LUNCH":
      return t("techLunch");
    case "BREAK_15":
      return t("techBreak");
    case "TRUCK_INSPECTION":
      return t("techTruckInspection");
    case "END_JOB":
      return t("techEndJob");
    default:
      return eventType || "";
  }
}

function computeTechnicianSummary(events){
  let paidMinutes = 0;
  let unpaidMinutes = 0;
  let inspections = 0;
  (events || []).forEach((event) => {
    if (!event.started_at || !event.ended_at) return;
    const minutes = Number(event.duration_minutes || 0);
    if (event.event_type === "TRUCK_INSPECTION"){
      paidMinutes += minutes;
      inspections += 1;
      return;
    }
    if (event.event_type === "START_JOB"){
      paidMinutes += minutes;
      return;
    }
    if (event.event_type === "LUNCH" || event.event_type === "BREAK_15" || event.event_type === "PAUSE_JOB"){
      unpaidMinutes += minutes;
    }
  });
  return {
    paidMinutes,
    unpaidMinutes,
    totalMinutes: paidMinutes,
    inspections,
  };
}

