  const sim = ensureTechnicianSimulationState();
  const statusEl = $("techClockStatus");
  const stateEl = $("techJobState");
  const currentWrap = $("techCurrentActivity");
  if (!currentWrap) return;
  const item = getCurrentShiftItem();
  const clockLabel = sim.clockedInAt
    ? `Clocked in at ${formatTimeShort(sim.clockedInAt)}${sim.clockedOutAt ? ` • Clocked out at ${formatTimeShort(sim.clockedOutAt)}` : ""}`
    : "Shift start preloaded for 8:00 AM. Clock in to begin.";
  if (statusEl) statusEl.textContent = clockLabel;
  if (stateEl){
    if (!sim.clockedInAt){
      stateEl.innerHTML = `<span class="dot status-not-started"></span><span>Not Started</span>`;
    } else if (item){
      stateEl.innerHTML = `<span class="dot ${getShiftStatusClass(item)}"></span><span>${escapeHtml(getShiftStatusLabel(item))}</span>`;
    } else {
      stateEl.innerHTML = `<span class="dot status-complete"></span><span>Completed</span>`;
    }
  }
  if (!item){
    const allComplete = sim.items.length > 0 && sim.items.every((entry) => entry.status === "COMPLETED");
    currentWrap.innerHTML = allComplete
      ? `<div class="tech-current-card"><div class="tech-shift-title">Shift complete</div><div class="muted small">All planned activities are complete.</div></div>`
      : `<div class="tech-current-card"><div class="tech-shift-title">No activity selected</div><div class="muted small">Open a task from Today's Shift to load it here.</div></div>`;
    return;
  }
  const elapsed = calcShiftElapsedMinutes(item);
  const notes = Array.isArray(item.notes) ? item.notes : [];
  const photos = Array.isArray(item.photos) ? item.photos : [];
  const complianceSource = getTechItemComplianceSource(item);
  const compliancePill = complianceSource ? renderAppointmentCompliancePill(complianceSource) : "";
  const appointmentWindow = formatTechAppointmentWindow(item);
  currentWrap.innerHTML = `
    <div class="tech-current-card ${item.status === "ACTIVE" ? "is-active" : ""}">
      <div class="tech-shift-head">
        <div>
          <div class="tech-shift-title">${escapeHtml(item.title)}</div>
          <div class="tech-shift-sub">${escapeHtml(item.subtitle || "")}</div>
          ${renderTechWorkflowProgress(item)}
        </div>
        <div class="status-pill ${getShiftStatusClass(item)}">${escapeHtml(getShiftStatusLabel(item))}</div>
      </div>
      <div class="muted small">Elapsed ${formatDurationMinutes(elapsed)} of planned ${formatDurationMinutes(item.plannedMinutes || 0)}</div>
      ${(item.kind === "service" || item.kind === "trouble") ? `
        <div class="muted small">${escapeHtml(item.customer || "")} • ${escapeHtml(item.address || "")}</div>
      ` : ""}
      ${appointmentWindow ? `<div class="muted small">${escapeHtml(appointmentWindow)}</div>` : ""}
      ${compliancePill ? `<div>${compliancePill}</div>` : ""}
      ${item.kind === "inspection" ? `
        <div class="tech-checklist">
          <div class="tech-checklist-title">Pre-Inspection Checklist</div>
          <label class="tech-checklist-item ${item.checklist?.tires ? 'is-checked' : ''}"><input type="checkbox" data-tech-checklist="tires" data-tech-item-id="${item.id}" ${item.checklist?.tires ? "checked" : ""} /> Tires</label>
          <label class="tech-checklist-item ${item.checklist?.lights ? 'is-checked' : ''}"><input type="checkbox" data-tech-checklist="lights" data-tech-item-id="${item.id}" ${item.checklist?.lights ? "checked" : ""} /> Lights</label>
          <label class="tech-checklist-item ${item.checklist?.safety ? 'is-checked' : ''}"><input type="checkbox" data-tech-checklist="safety" data-tech-item-id="${item.id}" ${item.checklist?.safety ? "checked" : ""} /> Safety Equipment</label>
          <label class="tech-checklist-item ${item.checklist?.tools ? 'is-checked' : ''}"><input type="checkbox" data-tech-checklist="tools" data-tech-item-id="${item.id}" ${item.checklist?.tools ? "checked" : ""} /> Tools Loaded</label>
        </div>
      ` : ""}
      <div class="tech-shift-actions">
        <button class="btn small" type="button" data-tech-shift-action="start" data-tech-item-id="${item.id}" ${!sim.clockedInAt || item.status === "COMPLETED" || item.status === "ACTIVE" ? "disabled" : ""}>Start</button>
        <button class="btn secondary small" type="button" data-tech-shift-action="pause" data-tech-item-id="${item.id}" ${item.status !== "ACTIVE" ? "disabled" : ""}>Pause</button>
        <button class="btn secondary small" type="button" data-tech-shift-action="resume" data-tech-item-id="${item.id}" ${item.status !== "PAUSED" ? "disabled" : ""}>Resume</button>
        <button class="btn danger small" type="button" data-tech-shift-action="complete" data-tech-item-id="${item.id}" ${!sim.clockedInAt || item.status === "COMPLETED" ? "disabled" : ""}>Complete</button>
        <button class="btn ghost small" type="button" data-tech-shift-action="addNote" data-tech-item-id="${item.id}">Notes</button>
        <button class="btn ghost small" type="button" data-tech-shift-action="addPhoto" data-tech-item-id="${item.id}">Photo</button>
      </div>
      <input id="techQuickPhotoInput" type="file" accept=".jpg,.jpeg,.png,.webp,image/jpeg,image/png,image/webp" style="display:none;" />
      ${notes.length ? `<div class="tech-note-list">${notes.map((n) => `<div class="tech-note-item">• ${escapeHtml(n)}</div>`).join("")}</div>` : ""}
      ${photos.length ? `<div class="muted small">Photos: ${escapeHtml(photos.join(", "))}</div>` : ""}
    </div>
  `;
