async function loadDispatchTechnicians(){
  const select = $("dispatchAssignUser");
  if (!state.features.dispatch) return;
  if (!canViewDispatch() || !state.activeProject || !state.client || isDemo){
    state.workOrders.technicians = [];
    state.workOrders.workforce = [];
    if (select) select.innerHTML = `<option value="">Unassigned</option>`;
    renderWorkforceStatusBoard("dispatchWorkforceBoard");
    renderWorkforceStatusBoard("supervisorCrewStatus");
    return;
  }
  const { data, error } = await state.client
    .from("project_members")
    .select("user_id")
    .eq("project_id", state.activeProject.id);
  if (error){
    toast("Technicians load error", error.message);
    return;
  }
  const ids = (data || []).map(r => r.user_id);
  let profiles = [];
  if (ids.length){
    let profileRows = [];
    const { data: workerRows, error: workerErr } = await state.client
      .from("profiles")
      .select("id, display_name, worker_id, worker_role")
      .in("id", ids);
    if (workerErr){
      const { data: fallbackRows, error: fallbackErr } = await state.client
        .from("profiles")
        .select("id, display_name")
        .in("id", ids);
      if (fallbackErr){
        toast("Technicians load error", fallbackErr.message);
        return;
      }
      profileRows = fallbackRows || [];
    } else {
      profileRows = workerRows || [];
    }
    profiles = profileRows;
  }
  const profileById = new Map(profiles.map(p => [p.id, p || {}]));
  state.workOrders.technicians = ids.map((id) => {
    const profile = profileById.get(id) || {};
    const displayName = String(profile.display_name || "").trim() || id;
    const workerId = String(profile.worker_id || "").trim() || `WK-${String(id).slice(0, 8).toUpperCase()}`;
    const workerRole = String(profile.worker_role || "").trim() || "Technician";
    return { id, name: displayName, worker_id: workerId, worker_role: workerRole };
  });
  if (select){
    select.innerHTML = `<option value="">Unassigned</option>` + state.workOrders.technicians
      .map(t => `<option value="${t.id}">${escapeHtml(t.name)}</option>`)
      .join("");
  }
  renderWorkforceStatusBoard("dispatchWorkforceBoard");
  renderWorkforceStatusBoard("supervisorCrewStatus");
}

function syncDispatchStatusFilter(){
  const statusSelect = $("dispatchStatusFilter");
  if (!statusSelect) return;
  const current = statusSelect.value;
  statusSelect.innerHTML = `<option value="">${t("dispatchStatusAll")}</option>` + WORK_ORDER_STATUSES
    .map(status => `<option value="${status}">${escapeHtml(formatWorkOrderStatusLabel(status))}</option>`)
    .join("");
  if (current){
    statusSelect.value = current;
  }
}

async function loadDispatchWorkOrders(){
  const wrap = $("dispatchTable");
  if (!wrap) return;
  if (!state.features.dispatch){
    state.workOrders.dispatch = [];
    renderDispatchTable();
    return;
  }
  if (!canViewDispatch()){
    state.workOrders.dispatch = [];
    renderDispatchTable();
    return;
  }
  if (!state.activeProject || !state.client || isDemo){
    state.workOrders.dispatch = [];
    renderDispatchTable();
    return;
  }
  let query = state.client
    .from("work_orders")
    .select("id, project_id, type, status, scheduled_start, scheduled_end, address, customer_label, notes, priority, assigned_to_user_id, external_source, external_id, sla_due_at, contact_phone, lat, lng, created_at, updated_at")
    .eq("project_id", state.activeProject.id);

  const dateValue = $("dispatchDateFilter")?.value || "";
  if (dateValue){
    const target = new Date(`${dateValue}T00:00:00`);
    const start = startOfDay(target).toISOString();
    const end = endOfDay(target).toISOString();
    query = query.gte("scheduled_start", start).lte("scheduled_start", end);
  }
  const statusValue = $("dispatchStatusFilter")?.value || "";
  if (statusValue){
    query = query.eq("status", statusValue);
  }
  const assignValue = $("dispatchAssignFilter")?.value || "all";
  if (assignValue === "assigned"){
    query = query.not("assigned_to_user_id", "is", null);
  } else if (assignValue === "unassigned"){
    query = query.is("assigned_to_user_id", null);
  }

  const { data, error } = await query
    .order("scheduled_start", { ascending: true, nullsFirst: true })
    .order("priority", { ascending: true });
  if (error){
    if (isMissingTable(error)){
      state.features.dispatch = false;
      state.workOrders.dispatch = [];
      renderDispatchTable();
      return;
    }
    toast("Dispatch load error", error.message);
    return;
  }
  state.workOrders.dispatch = data || [];
  renderDispatchTable();
  renderDispatchWarnings();
}

function renderDispatchTable(){
  const wrap = $("dispatchTable");
  if (!wrap){
    renderDispatchWorkspaceSummary();
    renderDispatchAssignmentBoard();
    renderWorkforceStatusBoard("dispatchWorkforceBoard");
    renderSupervisorOverview();
    return;
  }
  if (!state.activeProject){
    wrap.innerHTML = `<div class="muted small">${t("laborNoProject")}</div>`;
    renderDispatchWorkspaceSummary();
    renderDispatchAssignmentBoard();
    renderWorkforceStatusBoard("dispatchWorkforceBoard");
    renderSupervisorOverview();
    return;
  }
  if (!canViewDispatch()){
    wrap.innerHTML = `<div class="muted small">Dispatch is limited to privileged roles.</div>`;
    renderDispatchWorkspaceSummary();
    renderDispatchAssignmentBoard();
    renderWorkforceStatusBoard("dispatchWorkforceBoard");
    renderSupervisorOverview();
    return;
  }
  const rows = state.workOrders.dispatch || [];
  renderDispatchWorkspaceSummary();
  renderDispatchAssignmentBoard();
  renderWorkforceStatusBoard("dispatchWorkforceBoard");
  if (!rows.length){
    wrap.innerHTML = `<div class="muted small">${t("woNoOrders")}</div>`;
    renderSupervisorOverview();
    return;
  }
  const techOptions = state.workOrders.technicians || [];
  wrap.innerHTML = `
    <table class="table">
      <thead>
        <tr>
          <th>Scheduled</th>
          <th>Type</th>
          <th>Status</th>
          <th>Customer</th>
          <th>Address</th>
          <th>Priority</th>
          <th>Assigned</th>
          <th></th>
        </tr>
      </thead>
      <tbody>
        ${rows.map((row) => {
          const scheduled = row.scheduled_start ? new Date(row.scheduled_start).toLocaleString() : "Unscheduled";
          const statusClass = statusPillClass(row.status);
          const compliancePill = renderAppointmentCompliancePill(row);
          const assignedName = techOptions.find(t => t.id === row.assigned_to_user_id)?.name || "";
          return `
            <tr>
              <td>${escapeHtml(scheduled)}</td>
              <td>${escapeHtml(row.type || "")}</td>
              <td>
                <span class="status-pill ${statusClass}">${escapeHtml(formatWorkOrderStatusLabel(row.status))}</span>
                ${compliancePill ? `<div style="margin-top:6px;">${compliancePill}</div>` : ""}
              </td>
              <td>${escapeHtml(row.customer_label || "")}</td>
              <td>${escapeHtml(row.address || "")}</td>
              <td>${escapeHtml(String(row.priority ?? ""))}</td>
              <td>
                <select class="input compact" data-action="assignWorkOrder" data-id="${row.id}">
                  <option value="">Unassigned</option>
                  ${techOptions.map(t => `
                    <option value="${t.id}" ${t.id === row.assigned_to_user_id ? "selected" : ""}>${escapeHtml(t.name)}</option>
                  `).join("")}
                </select>
                ${assignedName ? `<div class="muted small">${escapeHtml(assignedName)}</div>` : ""}
              </td>
              <td><button class="btn ghost" data-action="editWorkOrder" data-id="${row.id}">Edit</button></td>
            </tr>
          `;
        }).join("")}
      </tbody>
    </table>
  `;
}

function renderDispatchWorkspaceSummary(){
  const wrap = $("dispatchWorkspaceSummary");
  if (!wrap) return;
  const rows = state.workOrders.dispatch || [];
  const active = rows.filter((row) => ["NEW", "ASSIGNED", "EN_ROUTE", "ON_SITE", "IN_PROGRESS"].includes(String(row.status || "").toUpperCase())).length;
  const blocked = rows.filter((row) => String(row.status || "").toUpperCase() === "BLOCKED").length;
  const unassigned = rows.filter((row) => !row.assigned_to_user_id).length;
  const complete = rows.filter((row) => String(row.status || "").toUpperCase() === "COMPLETE").length;
  wrap.innerHTML = `
    <div class="note">
      <div style="font-weight:900;">Active Queue</div>
      <div class="muted small">Current work order load by status.</div>
      <div class="row" style="margin-top:8px;">
        <span class="chip"><span class="dot warn"></span><span>Active: ${active}</span></span>
        <span class="chip"><span class="dot bad"></span><span>Blocked: ${blocked}</span></span>
        <span class="chip"><span class="dot ok"></span><span>Complete: ${complete}</span></span>
      </div>
    </div>
    <div class="note">
      <div style="font-weight:900;">Assignment Tools</div>
      <div class="muted small">Create, assign, reassign, and prioritize field jobs.</div>
      <div class="row" style="margin-top:8px;">
        <span class="chip"><span class="dot warn"></span><span>Unassigned: ${unassigned}</span></span>
        <span class="chip"><span class="dot ok"></span><span>Dispatch Ready</span></span>
      </div>
    </div>
    <div class="note" style="grid-column:1 / -1;">
      <div style="font-weight:900;">Live Workforce Map (Coming Soon)</div>
      <div class="muted small">Future dispatch map will show worker code, status, current job, and last updated time.</div>
    </div>
  `;
}

function getDispatchOpenJobs(){
  return (state.workOrders.dispatch || []).filter((row) => {
    const status = String(row?.status || "").toUpperCase();
    return status !== "COMPLETE" && status !== "CANCELED";
  });
}

function isWorkerAvailableForAssignment(worker){
  const status = String(worker?.status || "").toUpperCase();
  return status === "AVAILABLE" || status === "COMPLETE";
}

function formatDispatchJobLabel(job){
  if (!job) return "";
  const core = job.customer_label || job.type || `WO-${String(job.id || "").slice(0, 8)}`;
  const status = formatWorkOrderStatusLabel(job.status || "NEW");
  return `${core} (${status})`;
}

function getDispatchWorkerOptions(){
  const rows = (state.workOrders.workforce || []).slice();
  rows.sort((a, b) => {
    const aAvailable = isWorkerAvailableForAssignment(a) ? 0 : 1;
    const bAvailable = isWorkerAvailableForAssignment(b) ? 0 : 1;
    if (aAvailable !== bAvailable) return aAvailable - bAvailable;
    return String(a.display_name || "").localeCompare(String(b.display_name || ""));
  });
  return rows;
}

function renderDispatchAssignmentBoard(){
  const wrap = $("dispatchAssignmentBoard");
  if (!wrap) return;
  if (!state.activeProject){
    wrap.innerHTML = `<div class="muted small">${t("laborNoProject")}</div>`;
    return;
  }
  if (!canViewDispatch()){
    wrap.innerHTML = `<div class="muted small">Dispatch assignment tools are limited to dispatch visibility.</div>`;
    return;
  }
  const openJobs = getDispatchOpenJobs();
  const workforce = getDispatchWorkerOptions();
  const availableCount = workforce.filter((worker) => isWorkerAvailableForAssignment(worker)).length;
  const selectedJobId = $("dispatchAssignBoardJob")?.value || (openJobs[0]?.id || "");
  const selectedWorkerId = $("dispatchAssignBoardWorker")?.value || (workforce[0]?.user_id || "");
  const selectedJob = openJobs.find((job) => job.id === selectedJobId) || null;
  const selectedWorker = workforce.find((worker) => worker.user_id === selectedWorkerId) || null;
  wrap.innerHTML = `
    <div class="dispatch-assignment-board">
      <div class="dispatch-assignment-head">
        <span class="chip"><span class="dot warn"></span><span>Open Jobs: ${openJobs.length}</span></span>
        <span class="chip"><span class="dot ok"></span><span>Available Workers: ${availableCount}</span></span>
      </div>
      <div class="dispatch-assignment-grid">
        <div class="note">
          <div style="font-weight:900;">Open Jobs</div>
          <select id="dispatchAssignBoardJob" class="input" style="margin-top:8px;">
            ${openJobs.length
              ? openJobs.map((job) => `<option value="${job.id}" ${job.id === selectedJobId ? "selected" : ""}>${escapeHtml(formatDispatchJobLabel(job))}</option>`).join("")
              : `<option value="">No open jobs</option>`}
          </select>
          ${selectedJob ? `
            <div class="dispatch-assignment-detail" style="margin-top:8px;">
              <div class="muted small">${escapeHtml(selectedJob.type || "Work Order")} • ${escapeHtml(formatWorkOrderStatusLabel(selectedJob.status))}</div>
              <div class="muted small">${escapeHtml(selectedJob.address || "No address")}</div>
              ${renderAppointmentCompliancePill(selectedJob)}
            </div>
          ` : `<div class="muted small" style="margin-top:8px;">No job selected.</div>`}
        </div>
        <div class="note">
          <div style="font-weight:900;">Available / Eligible Workers</div>
          <select id="dispatchAssignBoardWorker" class="input" style="margin-top:8px;">
            ${workforce.length
              ? workforce.map((worker) => `
                <option value="${worker.user_id}" ${worker.user_id === selectedWorkerId ? "selected" : ""}>
                  ${escapeHtml(`${worker.worker_id} - ${worker.display_name}`)}
                </option>
              `).join("")
              : `<option value="">No workers</option>`}
          </select>
          ${selectedWorker ? `
            <div class="dispatch-assignment-detail" style="margin-top:8px;">
              <div class="muted small">${escapeHtml(selectedWorker.worker_role || "Worker")}</div>
              <div class="status-pill ${workforceStatusPillClass(selectedWorker.status)}" style="margin-top:4px;">${escapeHtml(formatWorkforceStatusLabel(selectedWorker.status))}</div>
              <div class="muted small" style="margin-top:4px;">${escapeHtml(selectedWorker.current_job || "No active assignment")}</div>
            </div>
          ` : `<div class="muted small" style="margin-top:8px;">No worker selected.</div>`}
        </div>
      </div>
      <div class="row" style="margin-top:10px; gap:8px; flex-wrap:wrap;">
        <button
          class="btn"
          type="button"
          data-action="dispatchAssignBoard"
          ${!selectedJob || !selectedWorker ? "disabled" : ""}
        >
          Assign Job
        </button>
        <button
          class="btn ghost"
          type="button"
          data-action="dispatchAssignmentMapHook"
          ${!selectedJob && !selectedWorker ? "disabled" : ""}
        >
          View on Map
        </button>
      </div>
    </div>
  `;
}

async function assignDispatchBoardSelection(){
  if (!state.client || !state.activeProject) return;
  const jobId = $("dispatchAssignBoardJob")?.value || "";
  const workerUserId = $("dispatchAssignBoardWorker")?.value || "";
  if (!jobId || !workerUserId){
    toast("Assignment required", "Select an open job and a worker.");
    return;
  }
  const job = (state.workOrders.dispatch || []).find((row) => row.id === jobId) || null;
  if (!job){
    toast("Assignment failed", "Selected job is no longer available.");
    return;
  }
  if (isDemoUser()){
    const row = (state.demo.workOrders || []).find((wo) => wo.id === jobId);
    if (row){
      row.assigned_to_user_id = workerUserId;
      if (String(row.status || "").toUpperCase() === "NEW") row.status = "ASSIGNED";
    }
    await loadDispatchWorkOrders();
    await loadDispatchTechnicians();
    toast("Assignment saved", "Demo assignment updated.");
    return;
  }
  const { error: rpcError } = await state.client.rpc("fn_assign_work_order", {
    work_order_id: jobId,
    technician_user_id: workerUserId,
  });
  if (rpcError){
    const { error: updateError } = await state.client
      .from("work_orders")
      .update({ assigned_to_user_id: workerUserId })
      .eq("id", jobId);
    if (updateError){
      toast("Assignment failed", updateError.message);
      return;
    }
  }
  const currentStatus = String(job.status || "").toUpperCase();
  if (currentStatus === "NEW"){
    await state.client
      .from("work_orders")
      .update({ status: "ASSIGNED" })
      .eq("id", jobId);
  }
  await loadDispatchWorkOrders();
  await loadDispatchTechnicians();
  toast("Assignment saved", "Job assigned to worker.");
}

function handleDispatchAssignmentMapHook(){
  const jobId = $("dispatchAssignBoardJob")?.value || "";
  const workerUserId = $("dispatchAssignBoardWorker")?.value || "";
  const job = (state.workOrders.dispatch || []).find((row) => row.id === jobId) || null;
  const worker = (state.workOrders.workforce || []).find((row) => row.user_id === workerUserId) || null;
  const jobLabel = job ? formatDispatchJobLabel(job) : "No job selected";
  const workerLabel = worker ? `${worker.worker_id} ${worker.display_name}` : "No worker selected";
  toast("Dispatch map hook", `${workerLabel} • ${jobLabel}. Live map routing hook coming next.`);
}

function normalizeWorkforceStatus(status){
  const value = String(status || "").toUpperCase();
  if (value === "NEW") return "ASSIGNED";
  if (value === "CANCELED") return "AVAILABLE";
  if (["ASSIGNED", "EN_ROUTE", "ON_SITE", "IN_PROGRESS", "BLOCKED", "COMPLETE", "AVAILABLE"].includes(value)) return value;
  return "AVAILABLE";
}

function workforceStatusPriority(status){
  const value = normalizeWorkforceStatus(status);
  if (value === "BLOCKED") return 1;
  if (value === "IN_PROGRESS") return 2;
  if (value === "ON_SITE") return 3;
  if (value === "EN_ROUTE") return 4;
  if (value === "ASSIGNED") return 5;
  if (value === "COMPLETE") return 6;
  return 7;
}

function workforceStatusPillClass(status){
  const value = normalizeWorkforceStatus(status);
  if (value === "BLOCKED") return "bad";
  if (value === "AVAILABLE" || value === "COMPLETE") return "ok";
  return "warn";
}

function formatWorkforceStatusLabel(status){
  const value = normalizeWorkforceStatus(status);
  if (value === "AVAILABLE") return "Available";
  return formatWorkOrderStatusLabel(value);
}

function buildWorkforceStatusRows(){
  const technicians = state.workOrders.technicians || [];
  const workOrders = state.workOrders.dispatch || [];
  const rows = technicians.map((tech) => {
    const assignedOrders = workOrders
      .filter((order) => order.assigned_to_user_id === tech.id)
      .slice()
      .sort((a, b) => {
        const rankDiff = workforceStatusPriority(a.status) - workforceStatusPriority(b.status);
        if (rankDiff !== 0) return rankDiff;
        const aTime = Date.parse(a.updated_at || a.scheduled_start || a.created_at || 0) || 0;
        const bTime = Date.parse(b.updated_at || b.scheduled_start || b.created_at || 0) || 0;
        return bTime - aTime;
      });
    const current = assignedOrders[0] || null;
    const status = current ? normalizeWorkforceStatus(current.status) : "AVAILABLE";
    const currentJob = current
      ? (current.customer_label || current.type || `WO-${String(current.id || "").slice(0, 8)}`)
      : "No active assignment";
    const compliance = current ? getAppointmentCompliance(current) : null;
    return {
      user_id: tech.id,
      worker_id: tech.worker_id || `WK-${String(tech.id || "").slice(0, 8).toUpperCase()}`,
      display_name: tech.name || "Worker",
      worker_role: tech.worker_role || "Technician",
      status,
      current_job: currentJob,
      compliance,
      project_name: state.activeProject?.name || "",
      work_order_id: current?.id || "",
      updated_at: current?.updated_at || current?.created_at || "",
    };
  });
  state.workOrders.workforce = rows;
  return rows;
}

function renderWorkforceStatusBoard(targetId){
  const el = $(targetId);
  if (!el) return;
  if (!state.activeProject){
    el.innerHTML = `<div class="muted small">${t("laborNoProject")}</div>`;
    return;
  }
  if (!canViewDispatch()){
    el.innerHTML = `<div class="muted small">Workforce status is limited to dispatch visibility.</div>`;
    return;
  }
  const rows = buildWorkforceStatusRows();
  if (!rows.length){
    el.innerHTML = `<div class="muted small">No workers assigned to this project yet.</div>`;
    return;
  }
  const counts = {
    ASSIGNED: 0,
    EN_ROUTE: 0,
    ON_SITE: 0,
    IN_PROGRESS: 0,
    BLOCKED: 0,
    COMPLETE: 0,
    AVAILABLE: 0,
  };
  rows.forEach((row) => {
    const key = normalizeWorkforceStatus(row.status);
    counts[key] = (counts[key] || 0) + 1;
  });
  el.innerHTML = `
    <div class="workforce-board">
      <div class="workforce-board-chips">
        <span class="chip"><span class="dot warn"></span><span>Assigned: ${counts.ASSIGNED}</span></span>
        <span class="chip"><span class="dot warn"></span><span>En Route: ${counts.EN_ROUTE}</span></span>
        <span class="chip"><span class="dot warn"></span><span>On Site: ${counts.ON_SITE}</span></span>
        <span class="chip"><span class="dot warn"></span><span>In Progress: ${counts.IN_PROGRESS}</span></span>
        <span class="chip"><span class="dot bad"></span><span>Blocked: ${counts.BLOCKED}</span></span>
        <span class="chip"><span class="dot ok"></span><span>Complete: ${counts.COMPLETE}</span></span>
        <span class="chip"><span class="dot ok"></span><span>Available: ${counts.AVAILABLE}</span></span>
      </div>
      <div class="workforce-board-list">
        ${rows.map((row) => `
          <article class="workforce-row">
            <div>
              <div class="workforce-row-id">${escapeHtml(row.worker_id)}</div>
              <div style="font-weight:800;">${escapeHtml(row.display_name)}</div>
              <div class="muted small">${escapeHtml(row.worker_role || "Worker")}</div>
            </div>
            <div>
              <div class="status-pill ${workforceStatusPillClass(row.status)}">${escapeHtml(formatWorkforceStatusLabel(row.status))}</div>
              <div class="muted small" style="margin-top:6px;">${escapeHtml(row.current_job || "No active assignment")}</div>
              ${row.compliance ? `<div style="margin-top:6px;"><span class="appointment-pill ${row.compliance.tone}">${escapeHtml(row.compliance.label)}</span></div>` : ""}
            </div>
            <div class="workforce-row-actions">
              <button
                class="btn ghost small"
                type="button"
                data-action="openWorkerMapHook"
                data-worker-id="${escapeHtml(row.worker_id)}"
                data-worker-name="${escapeHtml(row.display_name)}"
              >
                Map Hook
              </button>
            </div>
          </article>
        `).join("")}
      </div>
    </div>
  `;
}

function handleWorkforceMapHook(workerId, workerName){
  const name = String(workerName || "").trim() || String(workerId || "").trim() || "Worker";
  toast("Workforce map hook", `${name} selected. Live map zoom/highlight will be connected next.`);
}

function renderDispatchWarnings(){
  const wrap = $("dispatchImportWarnings");
  if (!wrap) return;
  const warnings = state.workOrders.importWarnings || [];
  if (!warnings.length){
    wrap.style.display = "none";
    wrap.innerHTML = "";
    return;
  }
  wrap.style.display = "";
  wrap.innerHTML = `
    <div style="font-weight:900;">Import warnings</div>
    <ul class="muted small" style="margin-top:6px;">
      ${warnings.map(w => `<li>${escapeHtml(w)}</li>`).join("")}
    </ul>
  `;
}

function openDispatchModal(order = null){
  const modal = $("dispatchModal");
  if (!modal) return;
  state.workOrders.editing = order ? order.id : null;
  $("dispatchType").value = order?.type || "INSTALL";
  $("dispatchStatus").value = order?.status || "NEW";
  $("dispatchScheduledStart").value = order?.scheduled_start ? order.scheduled_start.slice(0, 16) : "";
  $("dispatchScheduledEnd").value = order?.scheduled_end ? order.scheduled_end.slice(0, 16) : "";
  $("dispatchCustomerLabel").value = order?.customer_label || "";
  $("dispatchAddress").value = order?.address || "";
  $("dispatchLat").value = Number.isFinite(order?.lat) ? String(order.lat) : "";
  $("dispatchLng").value = Number.isFinite(order?.lng) ? String(order.lng) : "";
  $("dispatchContactPhone").value = order?.contact_phone || "";
  $("dispatchPriority").value = Number.isFinite(order?.priority) ? String(order.priority) : "3";
  $("dispatchSlaDueAt").value = order?.sla_due_at ? order.sla_due_at.slice(0, 16) : "";
  $("dispatchNotes").value = order?.notes || "";
  $("dispatchAssignUser").value = order?.assigned_to_user_id || "";
  modal.style.display = "flex";
}

function closeDispatchModal(){
  const modal = $("dispatchModal");
  if (modal) modal.style.display = "none";
  state.workOrders.editing = null;
}

async function saveDispatchWorkOrder(){
  if (!state.client || !state.user || !state.activeProject) return;
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  showSaveStatus("saving");
  const payload = {
    project_id: state.activeProject.id,
    type: $("dispatchType").value,
    status: $("dispatchStatus").value,
    scheduled_start: $("dispatchScheduledStart").value ? new Date($("dispatchScheduledStart").value).toISOString() : null,
    scheduled_end: $("dispatchScheduledEnd").value ? new Date($("dispatchScheduledEnd").value).toISOString() : null,
    customer_label: $("dispatchCustomerLabel").value.trim() || null,
    address: $("dispatchAddress").value.trim() || null,
    lat: Number.isFinite(Number($("dispatchLat").value)) ? Number($("dispatchLat").value) : null,
    lng: Number.isFinite(Number($("dispatchLng").value)) ? Number($("dispatchLng").value) : null,
    contact_phone: $("dispatchContactPhone").value.trim() || null,
    priority: Number.isFinite(Number($("dispatchPriority").value)) ? Number($("dispatchPriority").value) : 3,
    sla_due_at: $("dispatchSlaDueAt").value ? new Date($("dispatchSlaDueAt").value).toISOString() : null,
    notes: $("dispatchNotes").value.trim() || null,
    updated_at: new Date().toISOString(),
  };
  const assignedUserId = $("dispatchAssignUser").value || null;
  const previous = state.workOrders.dispatch.find(r => r.id === state.workOrders.editing);
  const previousAssigned = previous?.assigned_to_user_id || null;
  let workOrderId = state.workOrders.editing;
  if (!workOrderId){
    payload.created_by = state.user.id;
    const { data, error } = await state.client
      .from("work_orders")
      .insert(payload)
      .select("id")
      .maybeSingle();
    if (error){
      showSaveStatus("error");
      toast("Create failed", error.message);
      return;
    }
    workOrderId = data?.id || null;
    if (workOrderId){
      await insertWorkOrderEvent(workOrderId, "CREATED", payload);
    }
  } else {
    const { error } = await state.client
      .from("work_orders")
      .update(payload)
      .eq("id", workOrderId);
    if (error){
      showSaveStatus("error");
      toast("Update failed", error.message);
      return;
    }
    await insertWorkOrderEvent(workOrderId, "UPDATED", payload);
  }

  if (workOrderId && assignedUserId && assignedUserId !== previousAssigned){
    const { error } = await state.client.rpc("fn_assign_work_order", {
      work_order_id: workOrderId,
      technician_user_id: assignedUserId,
    });
    if (error){
      toast("Assign failed", error.message);
    }
  } else if (workOrderId && !assignedUserId && previousAssigned){
    await state.client
      .from("work_orders")
      .update({ assigned_to_user_id: null })
      .eq("id", workOrderId);
  }

  showSaveStatus("saved");
  closeDispatchModal();
  await loadDispatchWorkOrders();
}

function parseCsv(text){
  const rows = [];
  let row = [];
  let value = "";
  let inQuotes = false;
  for (let i = 0; i < text.length; i += 1){
    const char = text[i];
    const next = text[i + 1];
    if (char === "\""){
      if (inQuotes && next === "\""){
        value += "\"";
        i += 1;
      } else {
        inQuotes = !inQuotes;
      }
      continue;
    }
    if (char === "," && !inQuotes){
      row.push(value);
      value = "";
      continue;
    }
    if ((char === "\n" || char === "\r") && !inQuotes){
      if (value.length || row.length){
        row.push(value);
        rows.push(row);
        row = [];
        value = "";
      }
      continue;
    }
    value += char;
  }
  if (value.length || row.length){
    row.push(value);
    rows.push(row);
  }
  return rows;
}

function normalizeRuidosoToken(value){
  return String(value || "")
    .trim()
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "");
}

function hasNode54AliasSignal(value){
  const text = String(value || "").trim();
  if (!text) return false;
  if (/\b1635\s*CA\b/i.test(text)) return true;
  if (/\bNODE\s*54\b/i.test(text)) return true;
  const normalized = normalizeRuidosoToken(text);
  return normalized === "54"
    || normalized === "NODE54"
    || normalized.includes("NODE54")
    || normalized.includes("1635CA");
}

function expandRuidosoJobMapTokens(value){
  const text = String(value || "").trim();
  const out = new Set();
  if (!text) return [];
  const normalized = normalizeRuidosoToken(text);
  if (normalized) out.add(normalized);
  if (hasNode54AliasSignal(text)){
    out.add("1635CA");
  }
  const nodeMatch = text.match(/NODE\d+_[A-Z0-9]+(?:_[A-Z0-9]+)?/i);
  if (nodeMatch?.[0]){
    const normalizedNode = normalizeRuidosoToken(nodeMatch[0]);
    if (normalizedNode) out.add(normalizedNode);
    if (hasNode54AliasSignal(nodeMatch[0])){
      out.add("1635CA");
    }
  }
  return Array.from(out);
}

function normalizeRuidosoEnclosure(value){
  const clean = String(value || "")
    .trim()
    .toUpperCase()
    .replace(/-REENTRY$/i, "")
    .replace(/\s+/g, "");
  if (!clean) return "";
  return clean.replace(/^0+(?=\d)/, "");
}

function parseRuidosoPhotoLoc(value){
  const raw = String(value || "").trim();
  if (!raw) return { jobMap: "", enclosure: "" };
  const cleaned = raw.replace(/-REENTRY$/i, "");
  const lastDash = cleaned.lastIndexOf("-");
  if (lastDash > 0){
    const left = cleaned.slice(0, lastDash).trim();
    const leftTokens = expandRuidosoJobMapTokens(left);
    return {
      jobMap: leftTokens.find((token) => token === "1635CA") || left,
      enclosure: cleaned.slice(lastDash + 1).trim(),
    };
  }
  const tokens = expandRuidosoJobMapTokens(cleaned);
  return {
    jobMap: tokens.find((token) => token === "1635CA") || "",
    enclosure: extractEnclosureToken(cleaned),
  };
}

function parseRuidosoCodesRaw(value){
  const src = String(value || "").trim();
  if (!src) return [];
  const out = new Set();
  const pattern = /([^,\n]+?)\s*\[(\d+(?:\.\d+)?)\]/g;
  let match;
  while ((match = pattern.exec(src))){
    const code = String(match[1] || "").trim().replace(/\s+/g, " ");
    if (code) out.add(code);
  }
  if (!out.size){
    src.split(",").forEach((part) => {
      const cleaned = String(part || "").replace(/\s*-\s*$/, "").trim();
      if (cleaned) out.add(cleaned);
    });
  }
  return Array.from(out);
}

function parseOptionalNumber(value){
  const raw = String(value ?? "").trim();
  if (!raw) return null;
  const cleaned = raw.replace(/,/g, "");
  const parsed = Number(cleaned);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatImportNumber(value){
  const num = Number(value);
  if (!Number.isFinite(num)) return "0";
  if (Number.isInteger(num)) return String(num);
  return String(num);
}

function normalizeBillingCsvHeaderKey(value){
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/\s+/g, " ")
    .replace(/[\s-]+/g, "_");
}

function normalizeCsvHeaders(headers){
  const aliasMap = new Map([
    ["loc", "loc"],
    ["location", "loc"],
    ["place", "loc"],
    ["place_name", "loc"],
    ["site", "loc"],
    ["site_name", "loc"],
    ["name", "loc"],
    ["job__map/enclosure/codes", "codes_payload"],
    ["codes", "codes_payload"],
    ["billing_codes", "codes_payload"],
    ["enclosure_codes", "codes_payload"],
    ["code_payload", "codes_payload"],
    ["codes_payload", "codes_payload"],
    ["units_allowed", "units_allowed"],
    ["allowed_units", "units_allowed"],
    ["allowed_total", "units_allowed"],
    ["total_allowed", "units_allowed"],
    ["units_billed", "units_billed"],
    ["billed_units", "units_billed"],
    ["billed_total", "units_billed"],
    ["total_billed", "units_billed"],
    ["code", "code"],
    ["billing_code", "code"],
    ["item_code", "code"],
    ["allowed", "allowed"],
    ["qty_allowed", "allowed"],
    ["units_allowed_code", "allowed"],
    ["billed", "billed"],
    ["qty_billed", "billed"],
    ["units_billed_code", "billed"],
    ["photo_url", "photo_url"],
    ["image_url", "photo_url"],
    ["photo", "photo_url"],
    ["image", "photo_url"],
    ["url", "photo_url"],
    ["link", "photo_url"],
  ]);

  const indexes = {
    loc: -1,
    codes_payload: -1,
    units_allowed: -1,
    units_billed: -1,
    code: -1,
    allowed: -1,
    billed: -1,
    photo_url: -1,
  };
  const canonicalByIndex = [];

  (Array.isArray(headers) ? headers : []).forEach((rawHeader, idx) => {
    const raw = String(rawHeader || "").trim();
    const direct = raw.toLowerCase();
    const normalized = normalizeBillingCsvHeaderKey(raw);
    const canonical = aliasMap.get(direct) || aliasMap.get(normalized) || "";
    canonicalByIndex[idx] = canonical || normalized;
    if (canonical && indexes[canonical] < 0){
      indexes[canonical] = idx;
    }
  });

  const canonicalFields = Object.entries(indexes)
    .filter(([, idx]) => idx >= 0)
    .map(([key]) => key);
  const hasLongCodeRows = indexes.loc >= 0
    && indexes.code >= 0
    && (indexes.allowed >= 0 || indexes.billed >= 0 || indexes.units_allowed >= 0 || indexes.units_billed >= 0);
  if (hasLongCodeRows){
    canonicalFields.push("code_rows[]");
  }

  return {
    indexes,
    canonicalByIndex,
    canonicalFields,
    hasLongCodeRows,
  };
}

function parseBillingCodesPayload(value){
  const source = String(value || "").trim();
  if (!source) return [];
  const out = [];
  source
    .split(/[;\n]+/)
    .map((part) => String(part || "").trim())
    .filter(Boolean)
    .forEach((segment) => {
      const bits = segment.split("|").map((part) => String(part || "").trim()).filter(Boolean);
      if (!bits.length) return;
      const code = bits[0];
      if (!code) return;
      let allowed = null;
      let billed = null;
      bits.slice(1).forEach((token) => {
        const match = token.match(/^([a-z_]+)\s*=\s*([-\d.,]+)$/i);
        if (!match) return;
        const key = normalizeBillingCsvHeaderKey(match[1]);
        const valueNum = parseOptionalNumber(match[2]);
        if (!Number.isFinite(valueNum)) return;
        if (["allowed", "qty_allowed", "units_allowed", "units_allowed_code"].includes(key)){
          allowed = valueNum;
        } else if (["billed", "qty_billed", "units_billed", "units_billed_code"].includes(key)){
          billed = valueNum;
        }
      });
      out.push({
        code,
        allowed: Number.isFinite(allowed) ? allowed : 0,
        billed: Number.isFinite(billed) ? billed : 0,
      });
    });
  return out;
}

function buildBillingCodesPayload(codeRows){
  const list = Array.isArray(codeRows) ? codeRows : [];
  return list
    .filter((row) => String(row?.code || "").trim())
    .map((row) => {
      const code = String(row.code || "").trim();
      const allowed = formatImportNumber(row.allowed);
      const billed = formatImportNumber(row.billed);
      return `${code}|allowed=${allowed}|billed=${billed}`;
    })
    .join(";");
}

function isImportDryRunEnabled(){
  return Boolean($("importLocationsDryRun")?.checked);
}

function normalizeNodeKey(raw){
  const text = String(raw || "").trim();
  if (!text) return "";
  if (/^(?:node\s*)?54$/i.test(text)) return "1635CA";
  if (/node\s*54/i.test(text)) return "1635CA";
  if (/1635\s*ca/i.test(text)) return "1635CA";
  return normalizeRuidosoToken(text);
}

function normalizeSegmentKey(raw){
  const text = String(raw || "").trim();
  if (!text) return null;
  const upper = text.toUpperCase();
  const segmentMatch = upper.match(/1635\s*CA[_\s-]*0?(\d{1,2})/i);
  if (segmentMatch?.[1]){
    const num = Number.parseInt(segmentMatch[1], 10);
    if (Number.isFinite(num)){
      return { type: "segment", key: `1635CA_${String(num).padStart(2, "0")}` };
    }
  }
  const pointMatch = upper.match(/RUIDOSONETWORKPOINT[-_\s]*0*(\d+)/i);
  if (pointMatch?.[1]){
    const n = String(Number.parseInt(pointMatch[1], 10));
    if (n !== "NaN") return { type: "sublocation", key: n };
  }
  if (/^\d{3,}$/.test(upper)){
    return { type: "sublocation", key: String(Number.parseInt(upper, 10)) };
  }
  const node = normalizeNodeKey(text);
  if (node === "1635CA"){
    return { type: "node", key: "1635CA" };
  }
  return null;
}

function makeSiteSearchTokens(site){
  const name = String(site?.name || "").trim();
  const notes = String(site?.notes || "").trim();
  const drop = String(site?.drop_number || "").trim();
  const display = String(getSiteDisplayName(site) || "").trim();
  return [name, notes, drop, display].filter(Boolean);
}

function resolveEvidenceTargets(projectId, normalized){
  const projectKey = String(projectId || "").trim();
  const sites = (state.projectSites || [])
    .filter((site) => String(site?.project_id || "").trim() === projectKey);
  if (!normalized || !sites.length) return [];
  const findById = (id) => sites.find((row) => String(row?.id || "") === String(id || ""));
  if (normalized.type === "sublocation"){
    const key = String(normalized.key || "").trim();
    if (!key) return [];
    const exactRegex = new RegExp(`(^|\\D)${key}(\\D|$)`, "i");
    const pointRegex = new RegExp(`RUIDOSONETWORKPOINT[-_\\s]*${key}`, "i");
    const matches = sites.filter((site) => {
      if (key === "2054"){
        const name = String(site?.name || "");
        return name === "2054" || pointRegex.test(name);
      }
      return makeSiteSearchTokens(site).some((value) => exactRegex.test(value));
    });
    return Array.from(new Set(matches.map((row) => String(row.id || "")).filter(Boolean)))
      .map(findById)
      .filter(Boolean);
  }
  if (normalized.type === "segment"){
    const key = String(normalized.key || "").toUpperCase().trim();
    if (!key) return [];
    const matches = sites.filter((site) => {
      const name = String(site?.name || "").toUpperCase().trim();
      return name === key;
    });
    return Array.from(new Set(matches.map((row) => String(row.id || "")).filter(Boolean)))
      .map(findById)
      .filter(Boolean);
  }
  if (normalized.type === "node" && normalized.key === "1635CA"){
    const segments = sites.filter((site) => /^1635CA_\d{2}$/i.test(String(site?.name || "").trim()));
    if (!segments.length) return [];
    const preferred = segments.find((site) => /^1635CA_01$/i.test(String(site?.name || "").trim()));
    if (preferred) return [preferred];
    const sorted = segments.slice().sort((a, b) => {
      const aAt = new Date(a?.created_at || 0).getTime() || 0;
      const bAt = new Date(b?.created_at || 0).getTime() || 0;
      return aAt - bAt;
    });
    return sorted.length ? [sorted[0]] : [];
  }
  return [];
}

function buildEvidenceItem({
  rawSegment = "",
  rawNode = "",
  rawEnclosure = "",
  photoUrls = [],
  codesUsed = [],
  source = "import",
  meta = {},
} = {}){
  const normalized = normalizeSegmentKey(rawSegment)
    || normalizeSegmentKey(rawEnclosure)
    || normalizeSegmentKey(rawNode)
    || null;
  const nodeKey = normalizeNodeKey(rawNode || rawSegment || "");
  const urls = Array.from(new Set((Array.isArray(photoUrls) ? photoUrls : [])
    .map((url) => String(url || "").trim())
    .filter((url) => /^https?:\/\//i.test(url))));
  const codes = Array.from(new Set((Array.isArray(codesUsed) ? codesUsed : [])
    .map((code) => String(code || "").trim())
    .filter(Boolean)));
  if (!normalized && !nodeKey) return null;
  if (!urls.length && !codes.length) return null;
  return {
    normalized: normalized || (nodeKey === "1635CA" ? { type: "node", key: "1635CA" } : null),
    nodeKey,
    photoUrls: urls,
    codesUsed: codes,
    source: String(source || "import"),
    meta: {
      rawSegment: String(rawSegment || ""),
      rawNode: String(rawNode || ""),
      rawEnclosure: String(rawEnclosure || ""),
      ...(meta && typeof meta === "object" ? meta : {}),
    },
  };
}

function getRuidosoRowCandidateJobMaps(row){
  const candidates = [
    row?.job_map,
    row?.node,
    row?.node_id,
    row?.node_name,
    row?.ruidoso_network_name,
    row?.ruidosonetworkname,
    row?.ruidoso_network_point_name,
    row?.ruidosonetworkpointname,
    row?.placemark_name,
    row?.location_name,
    row?.name,
  ];
  const out = new Set();
  candidates.forEach((raw) => {
    const text = String(raw || "").trim();
    if (!text) return;
    expandRuidosoJobMapTokens(text).forEach((token) => out.add(token));
  });
  return Array.from(out);
}

function getRuidosoRowCandidateEnclosures(row){
  const candidates = [
    row?.enclosure,
    row?.drop_number,
    row?.terminal_port,
    row?.location_name,
    row?.placemark_name,
    row?.ruidoso_network_point_name,
    row?.ruidosonetworkpointname,
  ];
  const out = new Set();
  candidates.forEach((raw) => {
    const normalized = normalizeRuidosoEnclosure(raw);
    if (normalized) out.add(normalized);
    const token = normalizeRuidosoEnclosure(extractEnclosureToken(raw));
    if (token) out.add(token);
  });
  return Array.from(out);
}

function normalizeRuidosoNameKey(value){
  return normalizeRuidosoToken(value);
}

function makeRuidosoCoordKey(lat, lng, precision = 5){
  const latNum = Number(lat);
  const lngNum = Number(lng);
  if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)) return "";
  return `${latNum.toFixed(precision)}|${lngNum.toFixed(precision)}`;
}

function getRuidosoRowCandidateNameKeys(row){
  const fields = [
    row?.ruidoso_network_point_name,
    row?.ruidosonetworkpointname,
    row?.ruidoso_network_name,
    row?.ruidosonetworkname,
    row?.placemark_name,
    row?.location_name,
    row?.name,
    row?.drop_number,
    row?.enclosure,
  ];
  const out = new Set();
  fields.forEach((value) => {
    const normalized = normalizeRuidosoNameKey(value);
    if (normalized) out.add(normalized);
  });
  return Array.from(out);
}

function getRuidosoRowCoordinate(row){
  const lat = Number(row?.latitude ?? row?.lat ?? row?.gps_lat);
  const lng = Number(row?.longitude ?? row?.lng ?? row?.gps_lng);
  if (Number.isFinite(lat) && Number.isFinite(lng)){
    return { lat, lng };
  }
  return getGeometryCenter(row?.geometry || null);
}

function rebuildRuidosoEvidenceIndex(rows = null){
  const byName = new Map();
  const byEnclosure = new Map();
  const byCoord = new Map();
  const enclosureCounts = new Map();
  const list = Array.isArray(rows)
    ? rows
    : Array.from(state.map.kmzFeatureRows?.values?.() || []);

  const mergeEvidence = (target, row) => {
    if (!target) return;
    const codes = getKmzBillingCodes(row);
    const photos = getKmzPhotoUrls(row);
    if (codes.length){
      const nextCodes = new Set(target.codes || []);
      codes.forEach((code) => nextCodes.add(code));
      target.codes = Array.from(nextCodes);
    }
    if (photos.length){
      const nextPhotos = new Set(target.photos || []);
      photos.forEach((url) => nextPhotos.add(url));
      target.photos = Array.from(nextPhotos);
    }
  };

  const attachEvidence = (map, key, row) => {
    if (!key) return;
    const current = map.get(key) || { codes: [], photos: [] };
    mergeEvidence(current, row);
    map.set(key, current);
  };

  list.forEach((row) => {
    if (!row || typeof row !== "object") return;
    const hasSignals = getKmzBillingCodes(row).length || getKmzPhotoUrls(row).length;
    if (!hasSignals) return;
    getRuidosoRowCandidateNameKeys(row).forEach((key) => attachEvidence(byName, key, row));
    getRuidosoRowCandidateEnclosures(row).forEach((key) => {
      if (!key) return;
      enclosureCounts.set(key, (enclosureCounts.get(key) || 0) + 1);
      attachEvidence(byEnclosure, key, row);
    });
    const coord = getRuidosoRowCoordinate(row);
    const coordKey = makeRuidosoCoordKey(coord?.lat, coord?.lng);
    attachEvidence(byCoord, coordKey, row);
  });

  state.map.ruidosoEvidenceByName = byName;
  state.map.ruidosoEvidenceByEnclosure = byEnclosure;
  state.map.ruidosoEvidenceByCoord = byCoord;
  state.map.ruidosoEvidenceEnclosureCounts = enclosureCounts;
}

function getRuidosoSiteEvidence(site){
  if (!site) return null;
  const byName = state.map.ruidosoEvidenceByName || new Map();
  const byEnclosure = state.map.ruidosoEvidenceByEnclosure || new Map();
  const byCoord = state.map.ruidosoEvidenceByCoord || new Map();
  const enclosureCounts = state.map.ruidosoEvidenceEnclosureCounts || new Map();

  const nameKeys = [
    site?.name,
    getSiteDisplayName(site),
    extractEnclosureToken(site?.name),
  ].map(normalizeRuidosoNameKey).filter(Boolean);
  for (const key of nameKeys){
    if (byName.has(key)) return byName.get(key);
  }

  const enclosure = normalizeRuidosoEnclosure(extractEnclosureToken(site?.name));
  if (enclosure && (enclosureCounts.get(enclosure) || 0) === 1 && byEnclosure.has(enclosure)){
    return byEnclosure.get(enclosure);
  }

  const coords = getSiteCoords(site);
  const coordKey = makeRuidosoCoordKey(coords?.lat, coords?.lng);
  if (coordKey && byCoord.has(coordKey)) return byCoord.get(coordKey);
  return null;
}

function isRuidoso1635PhotoArchiveCandidate(site){
  if (!site) return false;
  const projectText = [
    state.activeProject?.name,
    state.activeProject?.title,
    state.activeProject?.job_number,
  ].join(" ");
  const siteText = [
    site?.name,
    getSiteDisplayName(site),
    site?.notes,
    site?.location_label,
    site?.label,
  ].join(" ");
  return /ruidoso|1635\s*ca|ruidosonetworkpoint/i.test(`${projectText} ${siteText}`);
}

function getRuidosoArchiveSiteEnclosures(site){
  const out = new Set();
  [
    site?.name,
    getSiteDisplayName(site),
    site?.notes,
    site?.location_label,
    site?.label,
    site?.drop_number,
  ].forEach((value) => {
    const text = String(value || "").trim();
    if (!text) return;
    const pointMatch = text.match(/RuidosoNetworkPoint[-_\s]*(\d+)/i);
    if (pointMatch?.[1]){
      out.add(normalizeRuidosoEnclosure(pointMatch[1]));
    }
    // Extract "1635CA_XX" node designator (e.g. from site name "1635CA_02" → key "1635CA_02")
    const nodeKeyMatch = text.match(/1635\s*CA[_]?(\w+)/i);
    if (nodeKeyMatch?.[1]){
      out.add(normalizeRuidosoEnclosure(`1635CA_${nodeKeyMatch[1]}`));
    }
    const enclosure = normalizeRuidosoEnclosure(extractEnclosureToken(text));
    if (enclosure) out.add(enclosure);
  });
  return Array.from(out).filter(Boolean);
}

function getRuidosoArchiveCreatedAt(value){
  const parsed = new Date(value || "");
  if (Number.isFinite(parsed.getTime())) return parsed.toISOString();
  return "2026-01-01T00:00:00.000Z";
}

function makeRuidosoArchivePhotoRow({
  url,
  loc,
  date,
  source = "RUIDOSO archive",
  tech = "",
  photoIndex = "",
  rowIndex = 0,
} = {}){
  const cleanUrl = String(url || "").trim();
  if (!/^https?:\/\//i.test(cleanUrl)) return null;
  const parsed = parseRuidosoPhotoLoc(loc || "");
  // Key by the node designator (e.g. "1635CA_02") extracted from the left part of the loc
  // (e.g. "NODE54_1635CA_02-1704" → "1635CA_02"), not the numeric drop suffix.
  const locLeft = String(loc || "").split("-").slice(0, -1).join("-");
  const nodeKeyMatch = locLeft.match(/1635\s*CA[_]?(\w+)/i);
  const enclosure = nodeKeyMatch
    ? normalizeRuidosoEnclosure(`1635CA_${nodeKeyMatch[1]}`)
    : normalizeRuidosoEnclosure(parsed.enclosure || extractEnclosureToken(loc));
  return {
    id: `ruidoso-archive-${fnv1aHash(`${loc}|${photoIndex}|${cleanUrl}|${rowIndex}`)}`,
    site_id: "",
    media_path: cleanUrl,
    previewUrl: cleanUrl,
    created_by: "",
    gps_lat: null,
    gps_lng: null,
    gps_accuracy_m: null,
    created_at: getRuidosoArchiveCreatedAt(date),
    source: "ruidoso_archive",
    proof_type: "archive_photo",
    is_live_proof: false,
    backfilled: true,
    device_user_agent: "",
    captured_at_locked: true,
    gps_locked: false,
    readonly: true,
    ruidoso_loc: String(loc || "").trim(),
    ruidoso_enclosure: enclosure,
    ruidoso_source: String(source || "").trim(),
    ruidoso_tech: String(tech || "").trim(),
    ruidoso_photo_index: String(photoIndex || "").trim(),
  };
}

async function loadRuidoso1635PhotoArchive(){
  if (state.map.ruidosoPhotoArchive) return state.map.ruidosoPhotoArchive;
  if (state.map.ruidosoPhotoArchivePromise) return state.map.ruidosoPhotoArchivePromise;
  state.map.ruidosoPhotoArchivePromise = (async () => {
    const empty = { byEnclosure: new Map(), all: [] };
    try{
      const resp = await fetch(RUIDOSO_1635CA_PHOTO_ARCHIVE_URL, { cache: "force-cache" });
      if (!resp.ok) throw new Error(`HTTP ${resp.status}`);
      const rows = parseCsv(await resp.text());
      if (!rows.length) return empty;
      const headers = (rows[0] || []).map(SpecCom.helpers.normalizeImportHeader);
      const locIdx = findHeaderIndex(headers, ["loc", "location", "location_name"]);
      const urlIdx = findHeaderIndex(headers, ["photo_url", "url"]);
      const dateIdx = findHeaderIndex(headers, ["date", "taken_at", "created_at"]);
      const sourceIdx = findHeaderIndex(headers, ["source"]);
      const techIdx = findHeaderIndex(headers, ["tech", "technician"]);
      const photoIdx = findHeaderIndex(headers, ["photo_index", "index"]);
      if (locIdx < 0 || urlIdx < 0) return empty;

      const byEnclosure = new Map();
      const all = [];
      rows.slice(1).forEach((row, rowIndex) => {
        const item = makeRuidosoArchivePhotoRow({
          loc: row[locIdx] || "",
          url: row[urlIdx] || "",
          date: dateIdx >= 0 ? row[dateIdx] : "",
          source: sourceIdx >= 0 ? row[sourceIdx] : "",
          tech: techIdx >= 0 ? row[techIdx] : "",
          photoIndex: photoIdx >= 0 ? row[photoIdx] : "",
          rowIndex,
        });
        if (!item?.ruidoso_enclosure) return;
        all.push(item);
        if (!byEnclosure.has(item.ruidoso_enclosure)) byEnclosure.set(item.ruidoso_enclosure, []);
        byEnclosure.get(item.ruidoso_enclosure).push(item);
      });

      const archive = { byEnclosure, all };
      state.map.ruidosoPhotoArchive = archive;
      return archive;
    } catch (error){
      debugLog("[ruidoso archive] photo archive load failed", error);
      return empty;
    } finally {
      state.map.ruidosoPhotoArchivePromise = null;
    }
  })();
  return state.map.ruidosoPhotoArchivePromise;
}

async function getRuidosoArchivePhotosForSite(site){
  if (!isRuidoso1635PhotoArchiveCandidate(site)) return [];
  const enclosures = getRuidosoArchiveSiteEnclosures(site);
  if (!enclosures.length) return [];
  const archive = await loadRuidoso1635PhotoArchive();
  const seen = new Set();
  const out = [];
  enclosures.forEach((enclosure) => {
    (archive.byEnclosure.get(enclosure) || []).forEach((item) => {
      const key = String(item?.media_path || item?.previewUrl || "").trim();
      if (!key || seen.has(key)) return;
      seen.add(key);
      out.push({ ...item, site_id: site?.id || "" });
    });
  });
  return out.sort((a, b) => {
    const at = new Date(a.created_at || 0).getTime() || 0;
    const bt = new Date(b.created_at || 0).getTime() || 0;
    if (at !== bt) return at - bt;
    return String(a.ruidoso_photo_index || "").localeCompare(String(b.ruidoso_photo_index || ""), undefined, { numeric: true });
  });
}

function primeSitePopupCachesFromRuidosoEvidence(rows = null){
  const sites = Array.isArray(rows) ? rows : getVisibleSites();
  let seededCodes = 0;
  let seededPhotos = 0;
  sites.forEach((site) => {
    const siteId = toSiteIdKey(site?.id);
    if (!siteId) return;
    const evidence = getRuidosoSiteEvidence(site);
    if (!evidence) return;
    const cachedCodes = getCachedSiteCodes(siteId);
    if (!cachedCodes.length && Array.isArray(evidence.codes) && evidence.codes.length){
      setCachedSiteCodes(siteId, evidence.codes);
      seededCodes += 1;
    }
    const cachedPhotos = getCachedSitePhotos(siteId);
    if (!cachedPhotos.length && Array.isArray(evidence.photos) && evidence.photos.length){
      setCachedSitePhotos(siteId, evidence.photos.map((url) => ({ url })));
      seededPhotos += 1;
    }
  });
  if (seededCodes || seededPhotos){
    debugLog("[map] seeded popup cache from evidence", { seededCodes, seededPhotos });
  }
}

async function upsertImportedCodesToSitesNotes(codesBySiteId){
  const updates = [];
  const dateLabel = new Date().toISOString().slice(0, 10);
  codesBySiteId.forEach((codes, siteId) => {
    const site = (state.projectSites || []).find((row) => String(row?.id || "") === String(siteId || ""));
    if (!site || !codes?.size) return;
    const codeList = Array.from(codes).sort();
    const block = `CODES USED (imported ${dateLabel}): ${codeList.join(", ")}`;
    const current = String(site?.notes || "");
    if (current.includes(block)) return;
    const nextNotes = current.trim() ? `${current.trim()}\n${block}` : block;
    updates.push({ siteId, notes: nextNotes });
  });
  for (const item of updates){
    const { error } = await state.client
      .from("sites")
      .update({ notes: item.notes })
      .eq("id", item.siteId);
    if (error) throw error;
    const local = (state.projectSites || []).find((row) => String(row?.id || "") === String(item.siteId || ""));
    if (local) local.notes = item.notes;
  }
  return updates.length;
}

async function upsertImportedBillingToSites(billingBySiteId){
  if (!state.client || !billingBySiteId?.size){
    return { updatedSites: 0, firstSiteIds: [], firstSample: null };
  }
  const firstSiteIds = [];
  let firstSample = null;
  let updatedSites = 0;
  const dateLabel = new Date().toISOString().slice(0, 10);

  for (const [siteId, billing] of billingBySiteId.entries()){
    const unitsAllowed = Number(billing?.units_allowed);
    const unitsBilled = Number(billing?.units_billed);
    const hasUnitsAllowed = Number.isFinite(unitsAllowed);
    const hasUnitsBilled = Number.isFinite(unitsBilled);
    const codeRows = Array.isArray(billing?.code_rows) ? billing.code_rows : [];
    const codesPayload = String(billing?.codes_payload || "").trim() || buildBillingCodesPayload(codeRows);

    if (!firstSample){
      firstSample = {
        siteId: String(siteId || ""),
        units_allowed: hasUnitsAllowed ? unitsAllowed : null,
        units_billed: hasUnitsBilled ? unitsBilled : null,
      };
    }

    let wroteUnits = false;
    if (hasUnitsAllowed || hasUnitsBilled){
      const unitPayloads = [
        { units_allowed: unitsAllowed, units_billed: unitsBilled },
      ].map((payload) => Object.fromEntries(
        Object.entries(payload).filter(([, val]) => Number.isFinite(val))
      )).filter((payload) => Object.keys(payload).length > 0);

      for (const payload of unitPayloads){
        const { error } = await state.client
          .from("sites")
          .update(payload)
          .eq("id", siteId);
        if (!error){
          wroteUnits = true;
          break;
        }
        const missingCols = Object.keys(payload).filter((col) => isMissingColumnError(error, col));
        if (missingCols.length === Object.keys(payload).length){
          continue;
        }
        throw error;
      }
    }

    let wrotePayloadNote = false;
    if (codesPayload){
      const site = (state.projectSites || []).find((row) => String(row?.id || "") === String(siteId || ""));
      const current = String(site?.notes || "");
      const payloadBlock = `BILLING CODES PAYLOAD (imported ${dateLabel}): ${codesPayload}`;
      if (!current.includes(payloadBlock)){
        const nextNotes = current.trim() ? `${current.trim()}\n${payloadBlock}` : payloadBlock;
        const { error } = await state.client
          .from("sites")
          .update({ notes: nextNotes })
          .eq("id", siteId);
        if (error) throw error;
        if (site) site.notes = nextNotes;
        wrotePayloadNote = true;
      }
    }

    const local = (state.projectSites || []).find((row) => String(row?.id || "") === String(siteId || ""));
    if (local){
      if (hasUnitsAllowed){
        local.units_allowed = unitsAllowed;
      }
      if (hasUnitsBilled){
        local.units_billed = unitsBilled;
      }
    }
    if (wroteUnits || wrotePayloadNote){
      updatedSites += 1;
      if (firstSiteIds.length < 2){
        firstSiteIds.push(String(siteId || ""));
      }
    }
  }
  return { updatedSites, firstSiteIds, firstSample };
}

function buildDryRunBillingSummaryBySite({
  projectId = state.activeProject?.id || null,
  evidenceItems = [],
} = {}){
  const projectKey = String(projectId || "").trim();
  const items = Array.isArray(evidenceItems) ? evidenceItems : [];
  const matchedSiteIds = new Set();
  const unresolved = new Set();
  const billingBySiteId = new Map();

  const mergeBillingForSite = (siteId, incoming) => {
    if (!siteId || !incoming) return;
    const bucket = billingBySiteId.get(siteId) || {
      units_allowed: 0,
      units_billed: 0,
      code_rows: new Map(),
      codes_payload: "",
    };
    const allowed = Number(incoming.units_allowed);
    const billed = Number(incoming.units_billed);
    if (Number.isFinite(allowed)) bucket.units_allowed += allowed;
    if (Number.isFinite(billed)) bucket.units_billed += billed;
    const rows = Array.isArray(incoming.code_rows) ? incoming.code_rows : [];
    rows.forEach((row) => {
      const code = String(row?.code || "").trim();
      if (!code) return;
      const prev = bucket.code_rows.get(code) || { code, allowed: 0, billed: 0 };
      const rAllowed = Number(row?.allowed);
      const rBilled = Number(row?.billed);
      if (Number.isFinite(rAllowed)) prev.allowed += rAllowed;
      if (Number.isFinite(rBilled)) prev.billed += rBilled;
      bucket.code_rows.set(code, prev);
    });
    if (incoming.codes_payload){
      bucket.codes_payload = String(incoming.codes_payload);
    }
    billingBySiteId.set(siteId, bucket);
  };

  items.forEach((item) => {
    const normalized = item?.normalized || null;
    if (!normalized || !projectKey) return;
    const targets = resolveEvidenceTargets(projectKey, normalized);
    if (!targets.length){
      const rawLoc = String(item?.meta?.rawSegment || item?.meta?.rawEnclosure || item?.meta?.rawNode || "").trim();
      if (rawLoc) unresolved.add(rawLoc);
      return;
    }
    targets.forEach((site) => {
      const siteId = String(site?.id || "").trim();
      if (!siteId) return;
      matchedSiteIds.add(siteId);
      if (item?.billing && typeof item.billing === "object"){
        mergeBillingForSite(siteId, item.billing);
      }
    });
  });

  const sampleUpdates = Array.from(billingBySiteId.entries()).slice(0, 3).map(([siteId, bucket]) => {
    const site = (state.projectSites || []).find((row) => String(row?.id || "") === String(siteId || ""));
    const codeRows = Array.from(bucket.code_rows?.values?.() || []);
    const payload = String(bucket.codes_payload || "").trim() || buildBillingCodesPayload(codeRows);
    return {
      site_id: siteId,
      loc: getSiteDisplayName(site || { name: siteId }),
      units_allowed: bucket.units_allowed,
      units_billed: bucket.units_billed,
      codes_payload_preview: payload.slice(0, 140),
    };
  });

  return {
    matchedLocCount: matchedSiteIds.size,
    notFoundLocs: Array.from(unresolved),
    sampleUpdates,
  };
}

async function syncImportedEvidenceToDb({
  projectId = state.activeProject?.id || null,
  evidenceItems = [],
  silent = true,
  token = null,
} = {}){
  const projectKey = String(projectId || "").trim();
  if (!projectKey || !state.client || isDemo){
    return {
      matchedSites: 0,
      insertedPhotos: 0,
      skippedPhotoDuplicates: 0,
      insertedCodes: 0,
      noteUpdates: 0,
      billingUpdatedSites: 0,
      failures: 0,
      sampleResolvedSiteIds: [],
      firstBillingSample: null,
    };
  }
  if (String(state.activeProject?.id || "") !== projectKey){
    return {
      matchedSites: 0,
      insertedPhotos: 0,
      skippedPhotoDuplicates: 0,
      insertedCodes: 0,
      noteUpdates: 0,
      billingUpdatedSites: 0,
      failures: 0,
      sampleResolvedSiteIds: [],
      firstBillingSample: null,
    };
  }
  if (token != null && token !== state.map.evidenceSyncToken){
    return {
      matchedSites: 0,
      insertedPhotos: 0,
      skippedPhotoDuplicates: 0,
      insertedCodes: 0,
      noteUpdates: 0,
      billingUpdatedSites: 0,
      failures: 0,
      sampleResolvedSiteIds: [],
      firstBillingSample: null,
    };
  }
  if (!Array.isArray(state.projectSites) || !state.projectSites.length){
    await loadProjectSites(projectKey);
  }
  const photoWanted = [];
  const codesBySiteId = new Map();
  const billingBySiteId = new Map();
  let failures = 0;
  const unresolvedSamples = [];
  const matchedSites = new Set();
  const sampleResolvedSiteIds = [];

  const mergeBillingForSite = (siteId, incoming) => {
    if (!siteId || !incoming) return;
    const bucket = billingBySiteId.get(siteId) || {
      units_allowed: 0,
      units_billed: 0,
      code_rows: new Map(),
    };
    const allowed = Number(incoming.units_allowed);
    const billed = Number(incoming.units_billed);
    if (Number.isFinite(allowed)) bucket.units_allowed += allowed;
    if (Number.isFinite(billed)) bucket.units_billed += billed;
    const rows = Array.isArray(incoming.code_rows) ? incoming.code_rows : [];
    rows.forEach((row) => {
      const code = String(row?.code || "").trim();
      if (!code) return;
      const prev = bucket.code_rows.get(code) || { code, allowed: 0, billed: 0 };
      const rAllowed = Number(row?.allowed);
      const rBilled = Number(row?.billed);
      if (Number.isFinite(rAllowed)) prev.allowed += rAllowed;
      if (Number.isFinite(rBilled)) prev.billed += rBilled;
      bucket.code_rows.set(code, prev);
    });
    if (incoming.codes_payload){
      bucket.codes_payload = String(incoming.codes_payload);
    }
    billingBySiteId.set(siteId, bucket);
  };

  for (const item of (Array.isArray(evidenceItems) ? evidenceItems : [])){
    const normalized = item?.normalized || null;
    if (!normalized) continue;
    const targets = resolveEvidenceTargets(projectKey, normalized);
    if (!targets.length){
      failures += 1;
      if (unresolvedSamples.length < 5){
        unresolvedSamples.push({
          normalized,
          source: item?.source || "",
          meta: item?.meta || {},
        });
      }
      continue;
    }
    targets.forEach((site) => matchedSites.add(String(site?.id || "")));
    targets.forEach((site) => {
      const id = String(site?.id || "");
      if (id && sampleResolvedSiteIds.length < 2 && !sampleResolvedSiteIds.includes(id)){
        sampleResolvedSiteIds.push(id);
      }
    });
    const urls = Array.isArray(item?.photoUrls) ? item.photoUrls : [];
    const codes = Array.isArray(item?.codesUsed) ? item.codesUsed : [];
    targets.forEach((site) => {
      const siteId = String(site?.id || "").trim();
      if (!siteId) return;
      urls.forEach((url) => {
        const cleanUrl = String(url || "").trim();
        if (!/^https?:\/\//i.test(cleanUrl)) return;
        photoWanted.push({ site_id: siteId, media_path: cleanUrl });
      });
      if (!codesBySiteId.has(siteId)) codesBySiteId.set(siteId, new Set());
      const bucket = codesBySiteId.get(siteId);
      codes.forEach((code) => {
        const clean = String(code || "").trim();
        if (clean) bucket.add(clean);
      });
      if (item?.billing && typeof item.billing === "object"){
        mergeBillingForSite(siteId, item.billing);
      }
    });
  }
  const touchedSiteIds = Array.from(new Set(
    photoWanted.map((row) => row.site_id)
      .concat(Array.from(codesBySiteId.keys()))
      .concat(Array.from(billingBySiteId.keys()))
  ));
  if (failures){
    dlog("[evidence sync] unresolved mappings", { count: failures, samples: unresolvedSamples });
  }
  if (!touchedSiteIds.length){
    const summary = {
      matchedSites: matchedSites.size,
      insertedPhotos: 0,
      skippedPhotoDuplicates: 0,
      insertedCodes: 0,
      noteUpdates: 0,
      billingUpdatedSites: 0,
      failures,
      sampleResolvedSiteIds,
      firstBillingSample: null,
    };
    if (!silent){
      toast("Evidence sync complete", `Matched ${summary.matchedSites} sites. Inserted 0 photos, 0 codes. Unmapped rows skipped ${summary.failures}.`);
    }
    return summary;
  }

  const { data: mediaRows, error: mediaReadError } = await state.client
    .from("site_media")
    .select("site_id, media_path")
    .in("site_id", touchedSiteIds);
  if (mediaReadError) throw mediaReadError;
  const existingMedia = new Set((mediaRows || []).map((row) => `${row.site_id}|${String(row.media_path || "").trim()}`));
  const uniquePhotoWanted = Array.from(new Map(photoWanted.map((row) => [`${row.site_id}|${row.media_path}`, row])).values());
  const photoInserts = uniquePhotoWanted
    .filter((row) => !existingMedia.has(`${row.site_id}|${row.media_path}`))
    .map((row) => ({
      ...row,
      created_by: state.user?.id || null,
      created_at: new Date().toISOString(),
    }));
  const skippedPhotoDuplicates = Math.max(0, uniquePhotoWanted.length - photoInserts.length);
  let insertedPhotos = 0;
  const insertByChunks = async (table, rows) => {
    if (!rows.length) return 0;
    const chunkSize = 200;
    let inserted = 0;
    for (let i = 0; i < rows.length; i += chunkSize){
      const chunk = rows.slice(i, i + chunkSize);
      let { error } = await state.client.from(table).insert(chunk);
      if (error && isMissingColumnError(error, "created_by")){
        ({ error } = await state.client.from(table).insert(chunk.map(({ created_by, ...rest }) => rest)));
      }
      if (error) throw error;
      inserted += chunk.length;
    }
    return inserted;
  };
  insertedPhotos = await insertByChunks("site_media", photoInserts);

  let insertedCodes = 0;
  let noteUpdates = 0;
  let codesTableAvailable = true;
  let existingCodeRows = [];
  if (codesBySiteId.size){
    const codeRead = await state.client
      .from("site_codes")
      .select("site_id, code")
      .in("site_id", touchedSiteIds);
    if (codeRead.error){
      if (isMissingTable(codeRead.error)){
        codesTableAvailable = false;
      } else {
        throw codeRead.error;
      }
    } else {
      existingCodeRows = codeRead.data || [];
    }
  }

  let billingUpdatedSites = 0;
  let firstBillingSample = null;
  if (billingBySiteId.size){
    const normalizedBilling = new Map();
    billingBySiteId.forEach((bucket, siteId) => {
      normalizedBilling.set(siteId, {
        units_allowed: bucket.units_allowed,
        units_billed: bucket.units_billed,
        code_rows: Array.from(bucket.code_rows?.values?.() || []),
        codes_payload: bucket.codes_payload || buildBillingCodesPayload(Array.from(bucket.code_rows?.values?.() || [])),
      });
    });
    const billingSummary = await upsertImportedBillingToSites(normalizedBilling);
    billingUpdatedSites = billingSummary.updatedSites || 0;
    firstBillingSample = billingSummary.firstSample || null;
  }
  if (codesBySiteId.size){
    if (codesTableAvailable){
      const existingCodes = new Set(existingCodeRows.map((row) => `${row.site_id}|${String(row.code || "").trim().toUpperCase()}`));
      const codeInserts = [];
      codesBySiteId.forEach((codes, siteId) => {
        codes.forEach((code) => {
          const key = `${siteId}|${String(code || "").trim().toUpperCase()}`;
          if (existingCodes.has(key)) return;
          codeInserts.push({
            site_id: siteId,
            code,
            created_by: state.user?.id || null,
            created_at: new Date().toISOString(),
          });
        });
      });
      insertedCodes = await insertByChunks("site_codes", codeInserts);
    } else {
      noteUpdates = await upsertImportedCodesToSitesNotes(codesBySiteId);
    }
  }

  const touchedKeys = new Set(touchedSiteIds.map((id) => toSiteIdKey(id)).filter(Boolean));
  touchedKeys.forEach((key) => {
    state.map.sitePhotosBySiteId.delete(key);
    state.map.siteCodesBySiteId.delete(key);
  });
  const activeSiteKey = toSiteIdKey(state.activeSite?.id);
  if (activeSiteKey && touchedKeys.has(activeSiteKey)){
    await loadSiteMedia(state.activeSite.id);
    await loadSiteCodes(state.activeSite.id);
    renderSitePanel();
  }
  const summary = {
    matchedSites: matchedSites.size,
    insertedPhotos,
    skippedPhotoDuplicates,
    insertedCodes,
    noteUpdates,
    billingUpdatedSites,
    failures,
    sampleResolvedSiteIds,
    firstBillingSample,
  };
  if (!silent){
    toast(
      "Evidence sync complete",
      `Matched ${summary.matchedSites} sites. Photos +${summary.insertedPhotos} (${summary.skippedPhotoDuplicates} dupes). Codes +${summary.insertedCodes}${summary.noteUpdates ? `, notes +${summary.noteUpdates}` : ""}. Unmapped rows skipped ${summary.failures}.`
    );
  }
  return summary;
}

function applyRuidosoPackageDataToRows(rows, {
  codeByKey,
  photosByKey,
  enclosureKeyCounts,
  codeByNameKey = new Map(),
  photosByNameKey = new Map(),
}){
  const list = Array.isArray(rows) ? rows : [];
  let matchedRows = 0;
  let rowsWithCodes = 0;
  let rowsWithPhotos = 0;
  list.forEach((row) => {
    const nameKeys = getRuidosoRowCandidateNameKeys(row);
    const jobMaps = getRuidosoRowCandidateJobMaps(row);
    const enclosures = getRuidosoRowCandidateEnclosures(row);
    const codeSet = new Set((Array.isArray(row.billing_codes) ? row.billing_codes : [])
      .map((value) => String(value || "").trim()).filter(Boolean));
    const photoSet = new Set((Array.isArray(row.photo_urls) ? row.photo_urls : [])
      .map((value) => String(value || "").trim()).filter((url) => /^https?:\/\//i.test(url)));
    let matchedAny = false;

    nameKeys.forEach((key) => {
      if (!key) return;
      const nameCodes = codeByNameKey.get(key) || [];
      const namePhotos = photosByNameKey.get(key) || [];
      if (nameCodes.length || namePhotos.length){
        matchedAny = true;
      }
      nameCodes.forEach((code) => codeSet.add(String(code || "").trim()));
      namePhotos.forEach((url) => {
        const clean = String(url || "").trim();
        if (/^https?:\/\//i.test(clean)) photoSet.add(clean);
      });
    });

    if (!enclosures.length && !matchedAny) return;
    let matchedKey = "";
    for (const enclosure of enclosures){
      for (const jobMap of jobMaps){
        const key = `${jobMap}|${enclosure}`;
        if (codeByKey.has(key) || photosByKey.has(key)){
          matchedKey = key;
          break;
        }
      }
      if (matchedKey) break;
      const fallbackKey = `*|${enclosure}`;
      const count = enclosureKeyCounts.get(fallbackKey) || 0;
      if (count === 1 && (codeByKey.has(fallbackKey) || photosByKey.has(fallbackKey))){
        matchedKey = fallbackKey;
        break;
      }
    }
    if (matchedKey){
      matchedAny = true;
      (codeByKey.get(matchedKey) || []).forEach((code) => {
        codeSet.add(String(code || "").trim());
      });
      (photosByKey.get(matchedKey) || []).forEach((url) => {
        const clean = String(url || "").trim();
        if (/^https?:\/\//i.test(clean)) photoSet.add(clean);
      });
    }
    if (!matchedAny) return;
    matchedRows += 1;
    const nextCodes = Array.from(codeSet).filter(Boolean);
    const nextPhotos = Array.from(photoSet).filter((url) => /^https?:\/\//i.test(url));
    if (nextCodes.length){
      row.billing_codes = nextCodes;
      rowsWithCodes += 1;
    }
    if (nextPhotos.length){
      row.photo_urls = nextPhotos;
      rowsWithPhotos += 1;
    }
  });
  return { matchedRows, rowsWithCodes, rowsWithPhotos };
}

async function importRuidosoPackageZip(file){
  const JSZip = await loadJsZip();
  const zip = await JSZip.loadAsync(file);
  const entries = Object.values(zip.files || {}).filter((entry) => !entry.dir);
  const productionEntry = entries.find((entry) => /ruidoso_production_codes\.csv$/i.test(String(entry.name || "")));
  const photoEntry = entries.find((entry) => /ruidoso_photo_links\.csv$/i.test(String(entry.name || "")));
  if (!productionEntry && !photoEntry){
    throw new Error("ZIP does not contain ruidoso_production_codes.csv or ruidoso_photo_links.csv.");
  }

  const codeByKey = new Map();
  const photosByKey = new Map();
  const evidenceItems = [];
  const enclosureKeyCounts = new Map();
  const upsertMapSet = (map, key, values) => {
    if (!key || !values?.length) return;
    const next = new Set(map.get(key) || []);
    values.forEach((value) => {
      const cleaned = String(value || "").trim();
      if (cleaned) next.add(cleaned);
    });
    if (next.size) map.set(key, Array.from(next));
  };
  const bumpEnclosureCount = (key) => {
    if (!key) return;
    enclosureKeyCounts.set(key, (enclosureKeyCounts.get(key) || 0) + 1);
  };

  if (productionEntry){
    const text = await productionEntry.async("string");
    const rows = parseCsv(text);
    const headers = (rows[0] || []).map(SpecCom.helpers.normalizeImportHeader);
    const jobIdx = findHeaderIndex(headers, ["job_map", "jobmap"]);
    const enclosureIdx = findHeaderIndex(headers, ["enclosure"]);
    const codesIdx = findHeaderIndex(headers, ["codes_raw", "codes"]);
    rows.slice(1).forEach((row) => {
      const jobMapKeys = expandRuidosoJobMapTokens(row[jobIdx] || "");
      const enclosure = normalizeRuidosoEnclosure(row[enclosureIdx] || "");
      const codes = parseRuidosoCodesRaw(row[codesIdx] || "");
      if (!enclosure) return;
      if (jobMapKeys.length){
        jobMapKeys.forEach((jobMap) => upsertMapSet(codeByKey, `${jobMap}|${enclosure}`, codes));
        bumpEnclosureCount(`*|${enclosure}`);
      }
      upsertMapSet(codeByKey, `*|${enclosure}`, codes);
      const evidence = buildEvidenceItem({
        rawSegment: row[enclosureIdx] || "",
        rawNode: row[jobIdx] || "",
        rawEnclosure: enclosure,
        codesUsed: codes,
        source: "zip",
        meta: { entry: "ruidoso_production_codes.csv" },
      });
      if (evidence) evidenceItems.push(evidence);
    });
  }

  if (photoEntry){
    const text = await photoEntry.async("string");
    const rows = parseCsv(text);
    const headers = (rows[0] || []).map(SpecCom.helpers.normalizeImportHeader);
    const locIdx = findHeaderIndex(headers, ["loc", "location", "location_name"]);
    const urlIdx = findHeaderIndex(headers, ["photo_url", "url"]);
    rows.slice(1).forEach((row) => {
      const parsed = parseRuidosoPhotoLoc(row[locIdx] || "");
      const jobMapKeys = expandRuidosoJobMapTokens(parsed.jobMap || row[locIdx] || "");
      const enclosure = normalizeRuidosoEnclosure(parsed.enclosure);
      const url = String(row[urlIdx] || "").trim();
      if (!enclosure || !/^https?:\/\//i.test(url)) return;
      if (jobMapKeys.length){
        jobMapKeys.forEach((jobMap) => upsertMapSet(photosByKey, `${jobMap}|${enclosure}`, [url]));
        bumpEnclosureCount(`*|${enclosure}`);
      }
      upsertMapSet(photosByKey, `*|${enclosure}`, [url]);
      const evidence = buildEvidenceItem({
        rawSegment: row[locIdx] || parsed.enclosure || "",
        rawNode: parsed.jobMap || "",
        rawEnclosure: enclosure,
        photoUrls: [url],
        source: "zip",
        meta: { entry: "ruidoso_photo_links.csv" },
      });
      if (evidence) evidenceItems.push(evidence);
    });
  }

  const kmzRows = Array.from(state.map.kmzFeatureRows?.values?.() || []);
  if (!kmzRows.length){
    throw new Error("Import a KMZ first, then apply this ZIP package.");
  }
  const result = applyRuidosoPackageDataToRows(kmzRows, { codeByKey, photosByKey, enclosureKeyCounts });
  rebuildRuidosoEvidenceIndex(kmzRows);
  primeSitePopupCachesFromRuidosoEvidence(state.projectSites || []);

  const previewRows = state.importPreview?.rawRows;
  if (Array.isArray(previewRows) && previewRows.length){
    const byFeatureId = new Map(kmzRows.map((row) => [String(row.__feature_id || ""), row]));
    previewRows.forEach((row) => {
      const key = String(row?.__feature_id || "");
      const match = byFeatureId.get(key);
      if (!match) return;
      row.billing_codes = Array.isArray(match.billing_codes) ? match.billing_codes.slice() : [];
      row.photo_urls = Array.isArray(match.photo_urls) ? match.photo_urls.slice() : [];
    });
  }
  renderMapLayerPanel();
  const selectedId = String(state.map.kmzSelectedFeatureId || "").trim();
  if (selectedId && state.map.kmzFeatureRows.has(selectedId)){
    void openKmzFeaturePopup(selectedId, { focusMap: false });
  }
  queueSaveKmzSnapshotForActiveProject({ immediate: true });
  return { ...result, evidenceItems };
}

async function importRuidosoPackageCsv(file){
  const text = await file.text();
  const rows = parseCsv(text);
  if (!rows.length){
    throw new Error("CSV is empty.");
  }
  const rawHeaders = rows[0] || [];
  const headers = rawHeaders.map(SpecCom.helpers.normalizeImportHeader);
  const canonical = normalizeCsvHeaders(rawHeaders);
  const canonicalIdx = canonical.indexes;
  const findHeaderContains = (tokens = []) => headers.findIndex((header) => (
    tokens.some((token) => header.includes(token))
  ));
  const jobIdx = (() => {
    const direct = findHeaderIndex(headers, ["job_map", "jobmap", "node", "node_id"]);
    if (direct >= 0) return direct;
    return findHeaderContains(["job_map", "jobmap", "node", "network_node"]);
  })();
  const enclosureIdx = (() => {
    const direct = findHeaderIndex(headers, [
      "enclosure",
      "segment",
      "location_segment",
      "drop_number",
      "network_point",
      "network_point_name",
      "ruidoso_network_point_name",
    ]);
    if (direct >= 0) return direct;
    return findHeaderContains(["enclosure", "segment", "drop", "network_point", "point_name", "site_name"]);
  })();
  const codesIdx = (() => {
    if (canonicalIdx.codes_payload >= 0) return canonicalIdx.codes_payload;
    const direct = findHeaderIndex(headers, ["codes_raw", "codes", "billing_codes", "billing_code", "work_codes"]);
    if (direct >= 0) return direct;
    return findHeaderContains(["codes", "billing_code", "work_code"]);
  })();
  const locIdx = (() => {
    if (canonicalIdx.loc >= 0) return canonicalIdx.loc;
    const direct = findHeaderIndex(headers, [
      "loc",
      "segment",
      "location_segment",
      "location",
      "location_name",
      "site_name",
      "name",
      "network_point_name",
      "ruidoso_network_point_name",
    ]);
    if (direct >= 0) return direct;
    return findHeaderContains(["loc", "segment", "location", "site_name", "point_name", "network_point", "name"]);
  })();
  const unitsAllowedIdx = canonicalIdx.units_allowed;
  const unitsBilledIdx = canonicalIdx.units_billed;
  const longCodeIdx = canonicalIdx.code;
  const longAllowedIdx = canonicalIdx.allowed >= 0 ? canonicalIdx.allowed : (longCodeIdx >= 0 ? canonicalIdx.units_allowed : -1);
  const longBilledIdx = canonicalIdx.billed >= 0 ? canonicalIdx.billed : (longCodeIdx >= 0 ? canonicalIdx.units_billed : -1);
  const urlIdx = (() => {
    if (canonicalIdx.photo_url >= 0) return canonicalIdx.photo_url;
    const direct = findHeaderIndex(headers, [
      "photo_url",
      "url",
      "image_url",
      "photo",
      "photo_link",
      "image_link",
      "link",
    ]);
    if (direct >= 0) return direct;
    return findHeaderContains(["photo_url", "image_url", "photo", "image", "url", "link"]);
  })();

  const hasLongFormat = locIdx >= 0 && longCodeIdx >= 0 && (longAllowedIdx >= 0 || longBilledIdx >= 0);
  const hasLegacyCodesColumns = codesIdx >= 0 && (jobIdx >= 0 || enclosureIdx >= 0 || locIdx >= 0);
  const hasCodesColumns = hasLegacyCodesColumns || hasLongFormat;
  const hasPhotoColumns = urlIdx >= 0 && (locIdx >= 0 || enclosureIdx >= 0 || jobIdx >= 0);
  if (!hasCodesColumns && !hasPhotoColumns){
    const found = (rawHeaders || []).map((h) => String(h || "").trim()).filter(Boolean);
    throw new Error(`CSV headers not recognized. Required one of: (1) loc + job__map/enclosure/codes, (2) loc + code + allowed/billed, or (3) photo columns. Detected: ${found.join(", ") || "(none)"}`);
  }
  const detectedFormat = hasLongFormat
    ? "C"
    : ((unitsAllowedIdx >= 0 || unitsBilledIdx >= 0) ? "B" : "A");
  const detectedType = hasCodesColumns && hasPhotoColumns
    ? "combined"
    : (hasPhotoColumns ? "photos" : "codes");

  const codeByKey = new Map();
  const photosByKey = new Map();
  const codeByNameKey = new Map();
  const photosByNameKey = new Map();
  const enclosureKeyCounts = new Map();
  const billingByLoc = new Map();
  let processedRows = 0;
  let codeRows = 0;
  let photoRows = 0;
  const evidenceItems = [];
  const upsertMapSet = (map, key, values) => {
    if (!key || !values?.length) return;
    const next = new Set(map.get(key) || []);
    values.forEach((value) => {
      const cleaned = String(value || "").trim();
      if (cleaned) next.add(cleaned);
    });
    if (next.size) map.set(key, Array.from(next));
  };
  const upsertNameSet = (map, rawKey, values) => {
    const key = normalizeRuidosoNameKey(rawKey);
    if (!key || !values?.length) return;
    const next = new Set(map.get(key) || []);
    values.forEach((value) => {
      const cleaned = String(value || "").trim();
      if (cleaned) next.add(cleaned);
    });
    if (next.size) map.set(key, Array.from(next));
  };
  const bumpEnclosureCount = (key) => {
    if (!key) return;
    enclosureKeyCounts.set(key, (enclosureKeyCounts.get(key) || 0) + 1);
  };
  const getBillingBucket = (rawLoc) => {
    const locText = String(rawLoc || "").trim();
    if (!locText) return null;
    const key = normalizeRuidosoNameKey(locText) || locText.toLowerCase();
    const existing = billingByLoc.get(key);
    if (existing) return existing;
    const created = {
      loc: locText,
      codeRows: new Map(),
      explicitAllowedTotal: 0,
      explicitBilledTotal: 0,
      hasExplicitAllowed: false,
      hasExplicitBilled: false,
    };
    billingByLoc.set(key, created);
    return created;
  };
  const addBillingCodeRow = (bucket, code, allowed, billed) => {
    if (!bucket) return;
    const cleanCode = String(code || "").trim();
    if (!cleanCode) return;
    const prev = bucket.codeRows.get(cleanCode) || { code: cleanCode, allowed: 0, billed: 0 };
    const allowedNum = Number(allowed);
    const billedNum = Number(billed);
    if (Number.isFinite(allowedNum)) prev.allowed += allowedNum;
    if (Number.isFinite(billedNum)) prev.billed += billedNum;
    bucket.codeRows.set(cleanCode, prev);
  };

  rows.slice(1).forEach((row) => {
    processedRows += 1;
    const rawLoc = locIdx >= 0 ? row[locIdx] : "";
    const parsedLoc = parseRuidosoPhotoLoc(rawLoc || "");
    const jobMapKeys = Array.from(new Set([
      ...expandRuidosoJobMapTokens(jobIdx >= 0 ? row[jobIdx] : ""),
      ...expandRuidosoJobMapTokens(parsedLoc.jobMap || rawLoc || ""),
    ]));
    const enclosure = normalizeRuidosoEnclosure(
      (enclosureIdx >= 0 ? row[enclosureIdx] : "") || parsedLoc.enclosure || ""
    );
    const locText = String(
      (locIdx >= 0 ? row[locIdx] : "")
      || (enclosureIdx >= 0 ? row[enclosureIdx] : "")
      || ""
    ).trim();
    if (!enclosure && !locText) return;

    if (hasLongFormat && locIdx >= 0 && longCodeIdx >= 0){
      const codeValue = String(row[longCodeIdx] || "").trim();
      const allowedValue = parseOptionalNumber(longAllowedIdx >= 0 ? row[longAllowedIdx] : null);
      const billedValue = parseOptionalNumber(longBilledIdx >= 0 ? row[longBilledIdx] : null);
      const allowedNum = Number.isFinite(allowedValue) ? allowedValue : 0;
      const billedNum = Number.isFinite(billedValue) ? billedValue : 0;
      if (codeValue){
        codeRows += 1;
        const bucket = getBillingBucket(locText);
        addBillingCodeRow(bucket, codeValue, allowedNum, billedNum);
        upsertNameSet(codeByNameKey, locText, [codeValue]);
        if (jobMapKeys.length && enclosure){
          jobMapKeys.forEach((jobMap) => upsertMapSet(codeByKey, `${jobMap}|${enclosure}`, [codeValue]));
          bumpEnclosureCount(`*|${enclosure}`);
        }
        if (enclosure){
          upsertMapSet(codeByKey, `*|${enclosure}`, [codeValue]);
        }
        const evidence = buildEvidenceItem({
          rawSegment: locText || row[enclosureIdx] || "",
          rawNode: row[jobIdx] || parsedLoc.jobMap || "",
          rawEnclosure: enclosure,
          codesUsed: [codeValue],
          source: "csv",
          meta: { type: "codes_long" },
        });
        if (evidence) evidenceItems.push(evidence);
      }
    }

    if (hasLegacyCodesColumns && codesIdx >= 0){
      const codesPayloadRaw = String(row[codesIdx] || "").trim();
      const parsedPayloadRows = parseBillingCodesPayload(codesPayloadRaw);
      const codes = parsedPayloadRows.length
        ? parsedPayloadRows.map((entry) => entry.code)
        : parseRuidosoCodesRaw(codesPayloadRaw);
      if (codes.length) codeRows += 1;
      if (locText) upsertNameSet(codeByNameKey, locText, codes);
      if (jobMapKeys.length && enclosure){
        jobMapKeys.forEach((jobMap) => upsertMapSet(codeByKey, `${jobMap}|${enclosure}`, codes));
        bumpEnclosureCount(`*|${enclosure}`);
      }
      if (enclosure){
        upsertMapSet(codeByKey, `*|${enclosure}`, codes);
      }
      if (locText){
        const bucket = getBillingBucket(locText);
        parsedPayloadRows.forEach((entry) => addBillingCodeRow(bucket, entry.code, entry.allowed, entry.billed));
        const explicitAllowed = parseOptionalNumber(unitsAllowedIdx >= 0 ? row[unitsAllowedIdx] : null);
        const explicitBilled = parseOptionalNumber(unitsBilledIdx >= 0 ? row[unitsBilledIdx] : null);
        if (Number.isFinite(explicitAllowed)){
          bucket.explicitAllowedTotal += explicitAllowed;
          bucket.hasExplicitAllowed = true;
        }
        if (Number.isFinite(explicitBilled)){
          bucket.explicitBilledTotal += explicitBilled;
          bucket.hasExplicitBilled = true;
        }
      }
      const evidence = buildEvidenceItem({
        rawSegment: locText || row[enclosureIdx] || "",
        rawNode: row[jobIdx] || parsedLoc.jobMap || "",
        rawEnclosure: enclosure,
        codesUsed: codes,
        source: "csv",
        meta: { type: "codes" },
      });
      if (evidence) evidenceItems.push(evidence);
    }

    if (hasPhotoColumns && urlIdx >= 0){
      const url = String(row[urlIdx] || "").trim();
      if (!/^https?:\/\//i.test(url)) return;
      photoRows += 1;
      if (locText) upsertNameSet(photosByNameKey, locText, [url]);
      if (jobMapKeys.length && enclosure){
        jobMapKeys.forEach((jobMap) => upsertMapSet(photosByKey, `${jobMap}|${enclosure}`, [url]));
        bumpEnclosureCount(`*|${enclosure}`);
      }
      if (enclosure){
        upsertMapSet(photosByKey, `*|${enclosure}`, [url]);
      }
      const evidence = buildEvidenceItem({
        rawSegment: locText || row[enclosureIdx] || "",
        rawNode: row[jobIdx] || parsedLoc.jobMap || "",
        rawEnclosure: enclosure,
        photoUrls: [url],
        source: "csv",
        meta: { type: "photo_url" },
      });
      if (evidence) evidenceItems.push(evidence);
    }
  });

  billingByLoc.forEach((bucket) => {
    const codeRowsList = Array.from(bucket.codeRows.values());
    const sumAllowed = codeRowsList.reduce((total, row) => total + (Number(row.allowed) || 0), 0);
    const sumBilled = codeRowsList.reduce((total, row) => total + (Number(row.billed) || 0), 0);
    const unitsAllowed = bucket.hasExplicitAllowed ? bucket.explicitAllowedTotal : sumAllowed;
    const unitsBilled = bucket.hasExplicitBilled ? bucket.explicitBilledTotal : sumBilled;
    const codesPayload = buildBillingCodesPayload(codeRowsList);
    const codesUsed = codeRowsList.map((row) => row.code).filter(Boolean);
    const evidence = buildEvidenceItem({
      rawSegment: bucket.loc,
      rawNode: bucket.loc,
      rawEnclosure: bucket.loc,
      codesUsed,
      source: "csv",
      meta: { type: "billing_totals", format: detectedFormat },
    });
    if (!evidence) return;
    evidence.billing = {
      units_allowed: unitsAllowed,
      units_billed: unitsBilled,
      codes_payload: codesPayload,
      code_rows: codeRowsList,
    };
    evidenceItems.push(evidence);
  });

  const kmzRows = Array.from(state.map.kmzFeatureRows?.values?.() || []);
  if (!kmzRows.length){
    throw new Error("Import a KMZ first, then apply this CSV package.");
  }
  const result = applyRuidosoPackageDataToRows(kmzRows, {
    codeByKey,
    photosByKey,
    enclosureKeyCounts,
    codeByNameKey,
    photosByNameKey,
  });
  rebuildRuidosoEvidenceIndex(kmzRows);
  primeSitePopupCachesFromRuidosoEvidence(state.projectSites || []);

  const previewRows = state.importPreview?.rawRows;
  if (Array.isArray(previewRows) && previewRows.length){
    const byFeatureId = new Map(kmzRows.map((row) => [String(row.__feature_id || ""), row]));
    previewRows.forEach((row) => {
      const key = String(row?.__feature_id || "");
      const match = byFeatureId.get(key);
      if (!match) return;
      row.billing_codes = Array.isArray(match.billing_codes) ? match.billing_codes.slice() : [];
      row.photo_urls = Array.isArray(match.photo_urls) ? match.photo_urls.slice() : [];
    });
  }
  renderMapLayerPanel();
  const selectedId = String(state.map.kmzSelectedFeatureId || "").trim();
  if (selectedId && state.map.kmzFeatureRows.has(selectedId)){
    void openKmzFeaturePopup(selectedId, { focusMap: false });
  }
  queueSaveKmzSnapshotForActiveProject({ immediate: true });
  dlog("[csv import] billing detection", {
    detectedFormat,
    canonicalFields: canonical.canonicalFields,
    codeRows,
    photoRows,
    billingLocs: billingByLoc.size,
  });
  return {
    ...result,
    detectedType,
    detectedFormat,
    canonicalFields: canonical.canonicalFields,
    billingLocCount: billingByLoc.size,
    processedRows,
    codeRows,
    photoRows,
    evidenceItems,
  };
}

function findHeaderIndex(headers, names){
  for (const name of names){
    const idx = headers.indexOf(name);
    if (idx >= 0) return idx;
  }
  return -1;
}

function decodePdfLiteralString(value){
  const src = String(value || "");
  let out = "";
  for (let i = 0; i < src.length; i += 1){
    const ch = src[i];
    if (ch !== "\\"){
      out += ch;
      continue;
    }
    i += 1;
    if (i >= src.length) break;
    const next = src[i];
    if (next === "n") out += "\n";
    else if (next === "r") out += "\r";
    else if (next === "t") out += "\t";
    else if (next === "b") out += "\b";
    else if (next === "f") out += "\f";
    else if (next === "(") out += "(";
    else if (next === ")") out += ")";
    else if (next === "\\") out += "\\";
    else if (/[0-7]/.test(next)){
      let octal = next;
      for (let j = 0; j < 2; j += 1){
        const peek = src[i + 1];
        if (!peek || !/[0-7]/.test(peek)) break;
        octal += peek;
        i += 1;
      }
      out += String.fromCharCode(parseInt(octal, 8));
    } else {
      out += next;
    }
  }
  return out;
}

function decodePdfHexString(hexValue){
  const clean = String(hexValue || "").replace(/\s+/g, "");
  if (!clean) return "";
  const padded = clean.length % 2 === 1 ? `${clean}0` : clean;
  let out = "";
  for (let i = 0; i < padded.length; i += 2){
    const pair = padded.slice(i, i + 2);
    const code = Number.parseInt(pair, 16);
    if (!Number.isFinite(code)) continue;
    out += String.fromCharCode(code);
  }
  return out;
}

function extractPhotoLinksFromPdfBuffer(buffer){
  const text = new TextDecoder("latin1").decode(new Uint8Array(buffer));
  const links = [];
  const literalRegex = /\/URI\s*\(((?:\\.|[^\\)])*)\)/g;
  const hexRegex = /\/URI\s*<([0-9A-Fa-f\s]+)>/g;
  let match;
  while ((match = literalRegex.exec(text))){
    const url = decodePdfLiteralString(match[1] || "").trim();
    if (!/^https?:\/\//i.test(url)) continue;
    const start = Math.max(0, match.index - 420);
    const context = text.slice(start, match.index);
    links.push({ url, context });
  }
  while ((match = hexRegex.exec(text))){
    const url = decodePdfHexString(match[1] || "").trim();
    if (!/^https?:\/\//i.test(url)) continue;
    const start = Math.max(0, match.index - 420);
    const context = text.slice(start, match.index);
    links.push({ url, context });
  }
  return links;
}

async function extractPhotoLinksFromPdfAnnotations(buffer){
  const pdfjsLib = await loadPdfJs();
  const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
  const rows = [];
  const seen = new Set();
  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1){
    const page = await pdf.getPage(pageNumber);
    const annots = await page.getAnnotations({ intent: "display" });
    const textContent = await page.getTextContent();
    const pageText = String((textContent?.items || []).map((item) => item?.str || "").join(" ")).slice(0, 800);
    (annots || []).forEach((annot) => {
      const url = String(
        annot?.url
        || annot?.unsafeUrl
        || annot?.a?.uri
        || annot?.action
        || ""
      ).trim();
      if (!/^https?:\/\//i.test(url)) return;
      const key = `${pageNumber}|${url}`;
      if (seen.has(key)) return;
      seen.add(key);
      rows.push({
        url,
        context: pageText,
        page: pageNumber,
      });
    });
  }
  return rows;
}

function extractLocationHintsFromText(text){
  const src = String(text || "");
  const out = new Set();
  const pointRegex = /\bRUIDOSONETWORKPOINT[-_\s]?\d+\b/ig;
  const nodeRegex = /\bNODE\d+_[A-Z0-9]+(?:_[A-Z0-9]+)?\b/ig;
  let match;
  while ((match = pointRegex.exec(src))){
    const raw = String(match[0] || "").trim();
    if (raw) out.add(raw);
  }
  while ((match = nodeRegex.exec(src))){
    const raw = String(match[0] || "").trim();
    if (raw) out.add(raw);
  }
  return Array.from(out);
}

function extractNameHintsFromUrl(url){
  const src = String(url || "").trim();
  if (!src) return [];
  const out = new Set();
  const noQuery = src.split("?")[0] || src;
  const fileName = noQuery.split("/").pop() || "";
  [src, fileName].forEach((segment) => {
    extractLocationHintsFromText(segment).forEach((token) => out.add(token));
    String(segment || "")
      .split(/[\/?&=_\-.]+/)
      .map((part) => part.trim())
      .filter(Boolean)
      .forEach((part) => {
        if (/^ruidosonetworkpoint\d+$/i.test(part)){
          const normalized = part.replace(/(ruidosonetworkpoint)(\d+)/i, "$1-$2");
          out.add(normalized);
        }
      });
  });
  return Array.from(out);
}

async function importRuidosoPhotoReportPdf(file){
  const buffer = await file.arrayBuffer();
  let links = await extractPhotoLinksFromPdfAnnotations(buffer);
  if (!links.length){
    links = extractPhotoLinksFromPdfBuffer(buffer);
  }
  if (!links.length){
    throw new Error("No http(s) photo links found in PDF.");
  }
  const kmzRows = Array.from(state.map.kmzFeatureRows?.values?.() || []);
  if (!kmzRows.length){
    throw new Error("Import a KMZ first, then apply this PDF report.");
  }

  const photosByKey = new Map();
  const photosByNameKey = new Map();
  const enclosureKeyCounts = new Map();
  const upsertMapSet = (map, key, values) => {
    if (!key || !values?.length) return;
    const next = new Set(map.get(key) || []);
    values.forEach((value) => {
      const cleaned = String(value || "").trim();
      if (cleaned) next.add(cleaned);
    });
    if (next.size) map.set(key, Array.from(next));
  };
  const upsertNameSet = (map, rawKey, values) => {
    const key = normalizeRuidosoNameKey(rawKey);
    if (!key || !values?.length) return;
    const next = new Set(map.get(key) || []);
    values.forEach((value) => {
      const cleaned = String(value || "").trim();
      if (cleaned) next.add(cleaned);
    });
    if (next.size) map.set(key, Array.from(next));
  };
  const bumpEnclosureCount = (key) => {
    if (!key) return;
    enclosureKeyCounts.set(key, (enclosureKeyCounts.get(key) || 0) + 1);
  };

  let mappedByName = 0;
  let mappedByEnclosure = 0;
  const evidenceItems = [];
  links.forEach((entry) => {
    const url = String(entry?.url || "").trim();
    if (!/^https?:\/\//i.test(url)) return;
    const contextHints = extractLocationHintsFromText(entry?.context || "");
    const urlHints = extractNameHintsFromUrl(url);
    const allHints = Array.from(new Set([...contextHints, ...urlHints]));
    if (allHints.length){
      mappedByName += 1;
      allHints.forEach((hint) => upsertNameSet(photosByNameKey, hint, [url]));
    }
    const enclosureRaw = extractEnclosureToken(`${entry?.context || ""} ${url}`);
    const enclosure = normalizeRuidosoEnclosure(enclosureRaw);
    if (enclosure){
      mappedByEnclosure += 1;
      upsertMapSet(photosByKey, `*|${enclosure}`, [url]);
      bumpEnclosureCount(`*|${enclosure}`);
      const nodeHint = allHints.find((hint) => /NODE\d+_/i.test(hint)) || "";
      const jobMapKeys = expandRuidosoJobMapTokens(nodeHint);
      jobMapKeys.forEach((jobMap) => {
        upsertMapSet(photosByKey, `${jobMap}|${enclosure}`, [url]);
      });
    }
    const evidence = buildEvidenceItem({
      rawSegment: `${allHints.join(" ")} ${entry?.context || ""}`,
      rawNode: allHints.find((hint) => /NODE\s*54|1635CA/i.test(String(hint || ""))) || "",
      rawEnclosure: enclosure || enclosureRaw,
      photoUrls: [url],
      source: "pdf",
      meta: { page: entry?.page || null },
    });
    if (evidence) evidenceItems.push(evidence);
  });

  const result = applyRuidosoPackageDataToRows(kmzRows, {
    codeByKey: new Map(),
    photosByKey,
    enclosureKeyCounts,
    codeByNameKey: new Map(),
    photosByNameKey,
  });
  rebuildRuidosoEvidenceIndex(kmzRows);
  primeSitePopupCachesFromRuidosoEvidence(state.projectSites || []);

  const previewRows = state.importPreview?.rawRows;
  if (Array.isArray(previewRows) && previewRows.length){
    const byFeatureId = new Map(kmzRows.map((row) => [String(row.__feature_id || ""), row]));
    previewRows.forEach((row) => {
      const key = String(row?.__feature_id || "");
      const match = byFeatureId.get(key);
      if (!match) return;
      row.photo_urls = Array.isArray(match.photo_urls) ? match.photo_urls.slice() : [];
    });
  }
  renderMapLayerPanel();
  const selectedId = String(state.map.kmzSelectedFeatureId || "").trim();
  if (selectedId && state.map.kmzFeatureRows.has(selectedId)){
    void openKmzFeaturePopup(selectedId, { focusMap: false });
  }
  queueSaveKmzSnapshotForActiveProject({ immediate: true });
  return {
    ...result,
    linkCount: links.length,
    mappedByName,
    mappedByEnclosure,
    evidenceItems,
  };
}

async function readLocationImportRows(file){
  const name = String(file?.name || "").toLowerCase();
  if (name.endsWith(".kmz")){
    const parsed = await parseKmzFile(file);
    if (!parsed.length) return [];
    const headers = ["location_name", "latitude", "longitude", "notes", "billing_codes", "photo_urls", "progress_notes", "finish_date", "map_url", "gps_status"];
    const gridRows = parsed.map((row) => [
      row.location_name || "",
      row.latitude ?? "",
      row.longitude ?? "",
      row.notes || "",
      Array.isArray(row.billing_codes) ? row.billing_codes.join("|") : (row.billing_codes || row.billing_code || ""),
      Array.isArray(row.photo_urls) ? row.photo_urls.join("|") : (row.photo_urls || ""),
      row.progress_notes || "",
      row.finish_date || "",
      row.map_url || "",
      row.gps_status || "",
    ]);
    return [headers, ...gridRows];
  }
  throw new Error("Unsupported file type. Upload .kmz.");
}

async function resolveUserIdByIdentifier(identifier){
  if (!identifier || !state.client) return null;
  const { data, error } = await state.client.rpc("fn_resolve_user_id", { identifier });
  if (error) return null;
  return data || null;
}

async function importDispatchCsv(file){
  if (!file || !state.client || !state.activeProject) return;
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  state.workOrders.importWarnings = [];
  renderDispatchWarnings();
  const text = await file.text();
  const rows = parseCsv(text);
  if (!rows.length) return;
  const headers = rows[0].map((h, idx) => {
    const trimmed = String(h || "").trim();
    return idx === 0 ? trimmed.replace(/^\uFEFF/, "") : trimmed;
  });
  const index = (name) => headers.indexOf(name);
  const required = ["external_id", "type"];
  const missing = required.filter(name => index(name) === -1);
  if (missing.length){
    toast("CSV error", `Missing headers: ${missing.join(", ")}`);
    return;
  }
  const dataRows = rows.slice(1).filter(r => r.length && r.some(cell => String(cell || "").trim().length));
  const payloads = [];
  const assignments = [];
  dataRows.forEach((row, rowIndex) => {
    const externalId = String(row[index("external_id")] || "").trim();
    if (!externalId) return;
    const typeValue = String(row[index("type")] || "").trim().toUpperCase();
    const type = WORK_ORDER_TYPES.includes(typeValue) ? typeValue : "INSTALL";
    const scheduledStart = row[index("scheduled_start")] ? new Date(row[index("scheduled_start")]).toISOString() : null;
    const scheduledEnd = row[index("scheduled_end")] ? new Date(row[index("scheduled_end")]).toISOString() : null;
    const priority = Number(row[index("priority")] || 3);
    const payload = {
      project_id: state.activeProject.id,
      external_source: "CSV",
      external_id: externalId,
      type,
      status: "NEW",
      scheduled_start: scheduledStart,
      scheduled_end: scheduledEnd,
      address: String(row[index("address")] || "").trim() || null,
      lat: Number.isFinite(Number(row[index("lat")])) ? Number(row[index("lat")]) : null,
      lng: Number.isFinite(Number(row[index("lng")])) ? Number(row[index("lng")]) : null,
      customer_label: String(row[index("customer_label")] || "").trim() || null,
      notes: String(row[index("notes")] || "").trim() || null,
      priority: Number.isFinite(priority) ? priority : 3,
      sla_due_at: row[index("sla_due_at")] ? new Date(row[index("sla_due_at")]).toISOString() : null,
      created_by: state.user?.id || null,
      updated_at: new Date().toISOString(),
    };
    payloads.push(payload);
    const assignEmail = String(row[index("assigned_to_email")] || "").trim();
    const assignEmployeeId = String(row[index("assigned_to_employee_id")] || "").trim();
    if (assignEmail || assignEmployeeId){
      assignments.push({
        external_id: externalId,
        email: assignEmail,
        employee_id: assignEmployeeId,
        row_number: rowIndex + 2,
      });
    }
  });
  if (!payloads.length){
    toast("CSV error", "No valid rows.");
    return;
  }

  const externalIds = payloads.map(p => p.external_id);
  const { data: existingRows } = await state.client
    .from("work_orders")
    .select("id, external_id")
    .eq("project_id", state.activeProject.id)
    .eq("external_source", "CSV")
    .in("external_id", externalIds);
  const existingMap = new Map((existingRows || []).map(r => [r.external_id, r.id]));

  const { error } = await state.client
    .from("work_orders")
    .upsert(payloads, { onConflict: "project_id,external_source,external_id" });
  if (error){
    toast("Import failed", error.message);
    return;
  }

  const { data: allRows } = await state.client
    .from("work_orders")
    .select("id, external_id")
    .eq("project_id", state.activeProject.id)
    .eq("external_source", "CSV")
    .in("external_id", externalIds);
  const idMap = new Map((allRows || []).map(r => [r.external_id, r.id]));

  for (const payload of payloads){
    const workOrderId = idMap.get(payload.external_id);
    if (!workOrderId) continue;
    const wasExisting = existingMap.has(payload.external_id);
    await insertWorkOrderEvent(workOrderId, wasExisting ? "UPDATED" : "CREATED", payload);
  }

  const warnings = [];
  for (const assignment of assignments){
    const workOrderId = idMap.get(assignment.external_id);
    if (!workOrderId) continue;
    const identifier = assignment.employee_id || assignment.email;
    const userId = await resolveUserIdByIdentifier(identifier);
    if (!userId){
      warnings.push(`Row ${assignment.row_number}: no match for ${identifier}`);
      continue;
    }
    await state.client.rpc("fn_assign_work_order", {
      work_order_id: workOrderId,
      technician_user_id: userId,
    });
  }

  await loadDispatchWorkOrders();
  state.workOrders.importWarnings = warnings;
  renderDispatchWarnings();
  if (warnings.length){
    toast("Import complete", `Imported ${payloads.length} work orders. ${warnings.length} warnings.`);
  } else {
    toast("Import complete", `Imported ${payloads.length} work orders.`);
  }
}

async function handleLocationImport(file){
  if (!file){
    const input = $("importLocationsInput");
    if (input){
      input.value = "";
      input.click();
    }
    return;
  }
  const activeProjectId = state.activeProject?.id || null;
  dlog("Import handler reached, file selected:", file.name);
  const name = file.name.toLowerCase();
  const isKmzFile = name.endsWith(".kmz") || name.endsWith(".kml");
  if (!activeProjectId && !isKmzFile){
    toast("Project required", "Select a project before importing ZIP, CSV, or PDF packages.");
    return;
  }
  const syncToken = (state.map.evidenceSyncToken || 0) + 1;
  state.map.evidenceSyncToken = syncToken;
  let rows = [];
  try{
    if (name.endsWith(".kmz")){
      rows = await parseKmzFile(file);
    } else if (name.endsWith(".kml")){
      rows = await parseKmlFile(file);
    } else if (name.endsWith(".zip")){
      const result = await importRuidosoPackageZip(file);
      const sync = await syncImportedEvidenceToDb({
        projectId: activeProjectId,
        evidenceItems: result.evidenceItems || [],
        silent: true,
        token: syncToken,
      });
      toast(
        "Package applied",
        `Matched ${result.matchedRows} points. DB sync: ${sync.matchedSites} sites, +${sync.insertedPhotos} photos (${sync.skippedPhotoDuplicates} dupes), +${sync.insertedCodes} codes${sync.noteUpdates ? `, +${sync.noteUpdates} notes` : ""}, unmapped rows skipped ${sync.failures}.`
      );
      return;
    } else if (name.endsWith(".csv")){
      const result = await importRuidosoPackageCsv(file);
      if (isImportDryRunEnabled()){
        const dryRun = buildDryRunBillingSummaryBySite({
          projectId: activeProjectId,
          evidenceItems: result.evidenceItems || [],
        });
        const missingPreview = dryRun.notFoundLocs.slice(0, 10);
        const samplePreview = dryRun.sampleUpdates.slice(0, 3);
        toast(
          "CSV dry run",
          `Format ${result.detectedFormat || "?"}. Matched ${dryRun.matchedLocCount} locs. Not found ${dryRun.notFoundLocs.length}.`
        );
        dlog("[csv import] dry run summary", {
          detectedFormat: result.detectedFormat || null,
          canonicalFields: result.canonicalFields || [],
          matchedLocCount: dryRun.matchedLocCount,
          notFoundLocs: missingPreview,
          sampleUpdates: samplePreview,
        });
        console.log("[CSV dry run]", {
          format_detected: result.detectedFormat || null,
          canonical_fields: result.canonicalFields || [],
          matched_locs: dryRun.matchedLocCount,
          not_found_locs_first_10: missingPreview,
          sample_updates_first_3: samplePreview,
        });
        return;
      }
      const sync = await syncImportedEvidenceToDb({
        projectId: activeProjectId,
        evidenceItems: result.evidenceItems || [],
        silent: true,
        token: syncToken,
      });
      const typeLabel = result.detectedType === "photos"
        ? "Photo CSV"
        : (result.detectedType === "codes" ? "Codes CSV" : "Combined CSV");
      toast(
        `${typeLabel} applied`,
        `Rows ${result.processedRows}. Matched ${result.matchedRows} points. DB sync: ${sync.matchedSites} sites, +${sync.insertedPhotos} photos (${sync.skippedPhotoDuplicates} dupes), +${sync.insertedCodes} codes${sync.noteUpdates ? `, +${sync.noteUpdates} notes` : ""}${sync.billingUpdatedSites ? `, +${sync.billingUpdatedSites} billing updates` : ""}, unmapped rows skipped ${sync.failures}.`
      );
      if (isDebug){
        const first = sync.firstBillingSample || {};
        toast(
          "CSV debug",
          `Format ${result.detectedFormat || "?"} | fields: ${(result.canonicalFields || []).join(", ") || "(none)"} | locs updated: ${sync.billingUpdatedSites || 0} | ids: ${(sync.sampleResolvedSiteIds || []).slice(0, 2).join(", ") || "(none)"} | first units: ${first.units_allowed ?? "-"} / ${first.units_billed ?? "-"}`
        );
      }
      dlog("[csv import] debug summary", {
        detectedFormat: result.detectedFormat || null,
        canonicalFields: result.canonicalFields || [],
        billingLocCount: result.billingLocCount || 0,
        billingUpdatedSites: sync.billingUpdatedSites || 0,
        sampleResolvedSiteIds: (sync.sampleResolvedSiteIds || []).slice(0, 2),
        firstBillingSample: sync.firstBillingSample || null,
      });
      return;
    } else if (name.endsWith(".pdf")){
      const result = await importRuidosoPhotoReportPdf(file);
      const sync = await syncImportedEvidenceToDb({
        projectId: activeProjectId,
        evidenceItems: result.evidenceItems || [],
        silent: true,
        token: syncToken,
      });
      toast(
        "Photo PDF applied",
        `Links ${result.linkCount}. Matched ${result.matchedRows} points. DB sync: ${sync.matchedSites} sites, +${sync.insertedPhotos} photos (${sync.skippedPhotoDuplicates} dupes), +${sync.insertedCodes} codes${sync.noteUpdates ? `, +${sync.noteUpdates} notes` : ""}, unmapped rows skipped ${sync.failures}.`
      );
      return;
    } else {
      toast("Import error", "Unsupported file type. Upload KMZ, KML, ZIP, CSV, or PDF.");
      return;
    }
  } catch (error){
    reportErrorToast("Import failed", error);
    return;
  }
  if (!rows.length){
    toast("Import error", "No data rows found.");
    return;
  }
  dlog("Parsed rows:", rows);
  const coordResolution = await resolveImportRowCoordinates(rows);
  if (coordResolution.matched || coordResolution.geocoded || coordResolution.unresolved){
    const parts = [];
    if (coordResolution.matched) parts.push(`${coordResolution.matched} matched to existing locations`);
    if (coordResolution.geocoded) parts.push(`${coordResolution.geocoded} geocoded from address`);
    if (coordResolution.unresolved) parts.push(`${coordResolution.unresolved} still missing coordinates`);
    toast("Coordinates resolved", `${parts.join(", ")}.`);
  }
  const kmzAllRows = Array.isArray(rows.__allKmzRows) ? rows.__allKmzRows : rows;
  const kmzLayerNames = getOrderedKmzLayerList(rows.__kmlLayerNames || kmzAllRows.map((row) => row?.__kml_layer || row?.__kml_layer_raw));
  state.map.kmzLayerCatalog = kmzLayerNames;

  const normalized = rows.map((row) => ({
    location_name: String(row.location_name).trim(),
    placemark_name: row.placemark_name ? String(row.placemark_name).trim() : String(row.location_name || "").trim(),
    folder_name: row.folder_name ? String(row.folder_name).trim() : null,
    folder_path: row.folder_path ? String(row.folder_path).trim() : null,
    latitude: Number.parseFloat(row.latitude),
    longitude: Number.parseFloat(row.longitude),
    geometry: row.geometry && typeof row.geometry === "object" ? row.geometry : null,
    raw_description_html: row.raw_description_html ? String(row.raw_description_html) : "",
    notes: row.progress_notes
      ? String(row.progress_notes).trim()
      : (row.notes ? String(row.notes).trim() : null),
    finish_date: row.finish_date ? String(row.finish_date).trim() : null,
    map_url: row.map_url ? String(row.map_url).trim() : null,
    gps_status: row.gps_status ? String(row.gps_status).trim() : null,
    items: Array.isArray(row.items) ? row.items : buildItemsFromRow(row),
    billing_codes: buildBillingCodesFromRow(row),
    photo_urls: buildPhotoUrlsFromRow(row),
    testing_wavelength: parseImportNumberOrNull(row.testing_wavelength),
    test_result_low: parseImportNumberOrNull(row.test_results_low ?? row.test_result_low),
    test_result_high: parseImportNumberOrNull(row.test_results_high ?? row.test_result_high),
    __kml_layer: canonicalKmzLayerName(row.__kml_layer || row.__kml_layer_raw || ""),
    __kml_layer_raw: String(row.__kml_layer_raw || row.__kml_layer || "").trim() || null,
    __layer_type: row.__layer_type || inferKmzLayerType(String(row.folder_path || row.folder_name || row.__kml_layer || "").split("/")),
    __has_line_geometry: row.__has_line_geometry === true,
    __has_polygon_geometry: row.__has_polygon_geometry === true,
    __feature_id: row.__feature_id || "",
    __rowNumber: row.__rowNumber,
  }));

  const validation = validateLocationImportRows(normalized);

  state.importPreview.projectId = activeProjectId;
  state.importPreview.rawRows = normalized;
  state.importPreview.rows = validation.validRows;
  state.importPreview.validation = validation;
  state.importPreview.preview = renderImportPreviewMarkers(validation.validRows);
  renderKmzPreviewFeatures(kmzAllRows, file.name || "KMZ Import");

  if (!activeProjectId){
    const featureCount = kmzAllRows.length || rows.length || 0;
    toast("KMZ loaded", `Loaded ${featureCount} map feature${featureCount === 1 ? "" : "s"}. Select a project to save or import locations.`);
    return;
  }

  await syncMaterialRequirementsFromKmzRows(kmzAllRows, {
    projectId: activeProjectId,
    replaceExisting: true,
    silent: true,
  });
  await refreshMaterialProjectData({ projectId: activeProjectId, silent: true });

  openImportLocationsModal(validation.validRows, state.activeProject);
}

async function importLocationsFile(file){
  if (!file) return;
  if (!state.activeProject){
    toast("Project required", "Select a project before importing.");
    return;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  if (!state.client || !state.user){
    toast("Import unavailable", "Sign in to import locations.");
    return;
  }
  let rows = [];
  try{
    rows = await readLocationImportRows(file);
  } catch (error){
    reportErrorToast("Import failed", error);
    return;
  }
  if (!rows.length){
    toast("Import error", "No rows found.");
    return;
  }
  const headers = rows[0].map(SpecCom.helpers.normalizeImportHeader);
  const nameIdx = findHeaderIndex(headers, ["location_name", "name"]);
  const latIdx = findHeaderIndex(headers, ["lat", "latitude"]);
  const lngIdx = findHeaderIndex(headers, ["lng", "longitude"]);
  const dropIdx = findHeaderIndex(headers, ["drop_number"]);
  const workTypeIdx = findHeaderIndex(headers, ["work_type"]);
  const notesIdx = findHeaderIndex(headers, ["notes"]);
  const billingIdx = findHeaderIndex(headers, ["billing_code_default"]);

  const missingHeaders = [];
  if (latIdx < 0) missingHeaders.push("lat/latitude");
  if (lngIdx < 0) missingHeaders.push("lng/longitude");
  if (missingHeaders.length){
    toast("Import error", `Missing headers: ${missingHeaders.join(", ")}`);
    return;
  }

  const dataRows = rows.slice(1).filter((row) => row?.length && row.some(cell => String(cell || "").trim().length));
  if (!dataRows.length){
    toast("Import error", "No data rows found.");
    return;
  }

  let skipped = 0;
  const skippedRows = [];
  const payloads = [];
  dataRows.forEach((row, idx) => {
    const rowNumber = idx + 2;
    const lat = Number(String(row[latIdx] ?? "").trim());
    const lng = Number(String(row[lngIdx] ?? "").trim());
    if (!Number.isFinite(lat) || !Number.isFinite(lng)){
      skipped += 1;
      skippedRows.push(rowNumber);
      return;
    }
    const rawName = nameIdx >= 0 ? String(row[nameIdx] ?? "").trim() : "";
    const name = rawName || `Location ${rowNumber - 1}`;
    const payload = {
      project_id: state.activeProject.id,
      name,
      gps_lat: lat,
      gps_lng: lng,
      created_by: state.user?.id || null,
    };
    const dropNumber = dropIdx >= 0 ? String(row[dropIdx] ?? "").trim() : "";
    const workType = workTypeIdx >= 0 ? String(row[workTypeIdx] ?? "").trim() : "";
    const notes = notesIdx >= 0 ? String(row[notesIdx] ?? "").trim() : "";
    const billingCode = billingIdx >= 0 ? String(row[billingIdx] ?? "").trim() : "";
    if (dropNumber) payload.drop_number = dropNumber;
    if (workType) payload.work_type = workType;
    if (notes) payload.notes = notes;
    if (billingCode) payload.billing_code_default = billingCode;
    payloads.push(payload);
  });

  if (!payloads.length){
    toast("Import error", "No rows with valid coordinates.");
    return;
  }

  const { error } = await state.client
    .from("sites")
    .insert(payloads);
  if (error){
    reportErrorToast("Import failed", error);
    return;
  }
  await loadProjectSites(state.activeProject?.id || null);
  if (skippedRows.length){
    console.warn("Import skipped rows with missing/invalid coordinates:", skippedRows);
  }
  toast("Import complete", `Imported ${payloads.length} locations, skipped ${skipped} rows.`);
}

async function importLocationsSpreadsheetForProject(file, projectId){
  if (!file) return { inserted: 0, updated: 0, skipped: 0 };
  if (!projectId){
    toast("Project required", "Select a project before importing.");
    return null;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return null;
  }
  if (!state.client || !state.user){
    toast("Import unavailable", "Sign in to import locations.");
    return null;
  }
  let rows = [];
  try{
    rows = await readLocationImportRows(file);
  } catch (error){
    reportErrorToast("Import failed", error);
    return null;
  }
  if (!rows.length){
    toast("Import error", "No rows found.");
    return null;
  }
  const headers = rows[0].map(SpecCom.helpers.normalizeImportHeader);
  const nameIdx = findHeaderIndex(headers, ["location_name", "name"]);
  const latIdx = findHeaderIndex(headers, ["lat", "latitude"]);
  const lngIdx = findHeaderIndex(headers, ["lng", "longitude"]);
  const dropIdx = findHeaderIndex(headers, ["drop_number"]);
  const workTypeIdx = findHeaderIndex(headers, ["work_type"]);
  const notesIdx = findHeaderIndex(headers, ["notes"]);
  const billingIdx = findHeaderIndex(headers, ["billing_code_default"]);

  const missingHeaders = [];
  if (latIdx < 0) missingHeaders.push("lat/latitude");
  if (lngIdx < 0) missingHeaders.push("lng/longitude");
  if (missingHeaders.length){
    toast("Import error", `Missing headers: ${missingHeaders.join(", ")}`);
    return null;
  }

  const dataRows = rows.slice(1).filter((row) => row?.length && row.some(cell => String(cell || "").trim().length));
  if (!dataRows.length){
    toast("Import error", "No data rows found.");
    return null;
  }

  const { data: existingSites, error: existingError } = await state.client
    .from("sites")
    .select("id, name")
    .eq("project_id", projectId);
  if (existingError){
    reportErrorToast("Import failed", existingError);
    return null;
  }
  const byName = new Map((existingSites || []).map((s) => [String(s.name || "").trim().toLowerCase(), s]));

  let skipped = 0;
  const skippedRows = [];
  const inserts = [];
  const updates = [];

  dataRows.forEach((row, idx) => {
    const rowNumber = idx + 2;
    const lat = Number(String(row[latIdx] ?? "").trim());
    const lng = Number(String(row[lngIdx] ?? "").trim());
    if (!Number.isFinite(lat) || !Number.isFinite(lng)){
      skipped += 1;
      skippedRows.push(rowNumber);
      return;
    }
    const rawName = nameIdx >= 0 ? String(row[nameIdx] ?? "").trim() : "";
    const name = rawName || `Location ${rowNumber - 1}`;
    const dropNumber = dropIdx >= 0 ? String(row[dropIdx] ?? "").trim() : "";
    const workType = workTypeIdx >= 0 ? String(row[workTypeIdx] ?? "").trim() : "";
    const notes = notesIdx >= 0 ? String(row[notesIdx] ?? "").trim() : "";
    const billingCode = billingIdx >= 0 ? String(row[billingIdx] ?? "").trim() : "";

    const existing = byName.get(String(name).trim().toLowerCase()) || null;
    if (existing){
      const update = {
        id: existing.id,
        data: {
          gps_lat: lat,
          gps_lng: lng,
        },
      };
      if (dropNumber) update.data.drop_number = dropNumber;
      if (workType) update.data.work_type = workType;
      if (notes) update.data.notes = notes;
      if (billingCode) update.data.billing_code_default = billingCode;
      updates.push(update);
    } else {
      const payload = {
        project_id: projectId,
        name,
        gps_lat: lat,
        gps_lng: lng,
        created_by: state.user?.id || null,
      };
      if (dropNumber) payload.drop_number = dropNumber;
      if (workType) payload.work_type = workType;
      if (notes) payload.notes = notes;
      if (billingCode) payload.billing_code_default = billingCode;
      inserts.push(payload);
    }
  });

  if (!inserts.length && !updates.length){
    toast("Import error", "No rows with valid coordinates.");
    return null;
  }

  let inserted = 0;
  let updated = 0;
  if (updates.length){
    for (const update of updates){
      const { error } = await state.client
        .from("sites")
        .update(update.data)
        .eq("id", update.id);
      if (error){
        reportErrorToast("Import failed", error);
        return null;
      }
      updated += 1;
    }
  }
  if (inserts.length){
    const { error } = await state.client
      .from("sites")
      .insert(inserts);
    if (error){
      reportErrorToast("Import failed", error);
      return null;
    }
    inserted = inserts.length;
  }

  if (skippedRows.length){
    console.warn("Import skipped rows with missing/invalid coordinates:", skippedRows);
  }
  toast("Import complete", `Added ${inserted} new locations, updated ${updated}, skipped ${skipped}.`);
  return { inserted, updated, skipped };
}

async function loadTechnicianTimesheet(){
  if (!state.features.labor) return;
  if (useTechnicianDaySimulation()){
    ensureTechnicianSimulationState();
    renderTechnicianDashboard();
    await loadAssignedWorkOrders();
    return;
  }
  if (!isTechnician()){
    state.technician.timesheet = null;
    state.technician.events = [];
    state.technician.activeEvent = null;
    renderTechnicianDashboard();
    return;
  }
  if (isDemo){
    const workDate = getSpecComDateKey();
    const userId = state.user?.id || "demo-bootstrap-user";
    const rows = Array.isArray(state.demo.timesheets) ? state.demo.timesheets : [];
    const match = rows
      .filter((row) => row.user_id === userId && row.work_date === workDate)
      .sort((a, b) => String(b.created_at || "").localeCompare(String(a.created_at || "")))[0] || null;
    state.technician.timesheet = match;
    await loadTechnicianEvents();
    await loadAssignedWorkOrders();
    return;
  }
  if (!state.client || !state.user || isDemo){
    state.technician.timesheet = null;
    state.technician.events = [];
    state.technician.activeEvent = null;
    renderTechnicianDashboard();
    return;
  }
  const workDate = getSpecComDateKey();
  const { data, error } = await state.client
    .from("technician_timesheets")
    .select("id, user_id, project_id, work_date, clock_in_at, clock_out_at, total_minutes_worked, created_at")
    .eq("user_id", state.user.id)
    .eq("work_date", workDate)
    .order("created_at", { ascending: false })
    .limit(1);
  if (error){
    if (isMissingTable(error)){
      state.features.labor = false;
      state.technician.timesheet = null;
      state.technician.events = [];
      state.technician.activeEvent = null;
      renderTechnicianDashboard();
      return;
    }
    toast("Timesheet load error", error.message);
    return;
  }
  state.technician.timesheet = data?.[0] || null;
  await loadTechnicianEvents();
  await loadAssignedWorkOrders();
}

async function loadTechnicianEvents(){
  if (useTechnicianDaySimulation()){
    renderTechnicianDashboard();
    return;
  }
  if (isDemo){
    if (!state.technician.timesheet){
      state.technician.events = [];
      state.technician.activeEvent = null;
      renderTechnicianDashboard();
      return;
    }
    const tsId = state.technician.timesheet.id;
    state.technician.events = (state.demo.timeEvents || [])
      .filter((row) => row.timesheet_id === tsId)
      .sort((a, b) => String(a.created_at || "").localeCompare(String(b.created_at || "")));
    state.technician.activeEvent = state.technician.events.find(e => e.started_at && !e.ended_at) || null;
    renderTechnicianDashboard();
    return;
  }
  if (!state.client || !state.user || isDemo || !state.technician.timesheet){
    state.technician.events = [];
    state.technician.activeEvent = null;
    renderTechnicianDashboard();
    return;
  }
  const { data, error } = await state.client
    .from("technician_time_events")
    .select("id, event_type, started_at, ended_at, duration_minutes, created_at")
    .eq("timesheet_id", state.technician.timesheet.id)
    .order("created_at", { ascending: true });
  if (error){
    toast("Event load error", error.message);
    return;
  }
  state.technician.events = data || [];
  state.technician.activeEvent = state.technician.events.find(e => e.started_at && !e.ended_at) || null;
  renderTechnicianDashboard();
}

async function startTechnicianTimesheet(){
  if (useTechnicianDaySimulation()){
    const sim = ensureTechnicianSimulationState();
    if (sim.clockedInAt && !sim.clockedOutAt){
      toast("Clock in", "Shift already active.");
      renderTechnicianDashboard();
      return;
    }
    const allCompleted = sim.items.length && sim.items.every((item) => item.status === "COMPLETED");
    if (sim.clockedOutAt || allCompleted){
      sim.items = createTechnicianShiftItems();
      sim.activeItemId = null;
    }
    sim.clockedInAt = nowISO();
    sim.clockedOutAt = null;
    const next = getCurrentShiftItem();
    sim.activeItemId = next?.id || null;
    persistTechnicianSimulation();
    setTechnicianShiftTicking();
    renderTechnicianDashboard();
    toast("Clock in", "Technician shift started.");
    return;
  }
  if (!state.activeProject){
    toast("Project required", "Select a project before clocking in.");
    return;
  }
  if (isDemo){
    const now = nowISO();
    const workDate = getSpecComDateKey();
    const userId = state.user?.id || "demo-bootstrap-user";
    state.demo.timesheets = Array.isArray(state.demo.timesheets) ? state.demo.timesheets : [];
    const existing = state.demo.timesheets.find((row) => row.user_id === userId && row.work_date === workDate && !row.clock_out_at);
    if (existing){
      state.technician.timesheet = existing;
      await loadTechnicianEvents();
      toast("Clock in", "Already clocked in (demo).");
      return;
    }
    const row = {
      id: `demo-timesheet-${Date.now()}`,
      user_id: userId,
      project_id: state.activeProject.id,
      work_date: workDate,
      clock_in_at: now,
      clock_out_at: null,
      total_minutes_worked: 0,
      created_at: now,
    };
    state.demo.timesheets.unshift(row);
    state.technician.timesheet = row;
    await loadTechnicianEvents();
    toast("Clock in", "Clocked in (demo).");
    return;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  if (!state.client || !state.user) return;
  const { data, error } = await state.client.rpc("fn_start_timesheet", {
    user_id: state.user.id,
    project_id: state.activeProject.id,
  });
  if (error){
    toast("Clock in failed", error.message);
    return;
  }
  state.technician.timesheet = data || null;
  await loadTechnicianEvents();
  renderTechnicianDashboard();
}

async function logTechnicianEvent(eventType){
  if (useTechnicianDaySimulation()){
    const sim = ensureTechnicianSimulationState();
    if (!sim.clockedInAt || sim.clockedOutAt){
      toast("Clock in required", "Clock in to manage shift activities.");
      return;
    }
    if (eventType === "START_JOB"){
      handleTechnicianShiftAction("quickStart");
      return;
    }
    if (eventType === "PAUSE_JOB"){
      handleTechnicianShiftAction("quickPause");
      return;
    }
    if (eventType === "LUNCH"){
      handleTechnicianShiftAction("quickLunch");
      return;
    }
    if (eventType === "BREAK_15"){
      handleTechnicianShiftAction("quickBreak");
      return;
    }
    if (eventType === "TRUCK_INSPECTION"){
      handleTechnicianShiftAction("quickInspect");
      return;
    }
    if (eventType === "END_JOB"){
      handleTechnicianShiftAction("quickComplete");
      return;
    }
    return;
  }
  if (!state.technician.timesheet){
    toast("Clock in required", t("techNoTimesheet"));
    return;
  }
  if (state.technician.timesheet.clock_out_at){
    toast("Clocked out", "Clock back in before logging events.");
    return;
  }
  if (isDemo){
    state.demo.timeEvents = Array.isArray(state.demo.timeEvents) ? state.demo.timeEvents : [];
    const now = nowISO();
    state.demo.timeEvents.push({
      id: `demo-time-event-${Date.now()}`,
      timesheet_id: state.technician.timesheet.id,
      event_type: eventType,
      started_at: now,
      ended_at: now,
      duration_minutes: 0,
      created_at: now,
    });
    await loadTechnicianEvents();
    return;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const { error } = await state.client.rpc("fn_log_time_event", {
    timesheet_id: state.technician.timesheet.id,
    event_type: eventType,
  });
  if (error){
    toast("Event failed", error.message);
    return;
  }
  await loadTechnicianEvents();
}

async function endTechnicianTimesheet(){
  if (useTechnicianDaySimulation()){
    const sim = ensureTechnicianSimulationState();
    if (!sim.clockedInAt || sim.clockedOutAt){
      toast("Clock out", "No active shift.");
      return;
    }
    const active = sim.items.find((item) => item.status === "ACTIVE") || null;
    if (active){
      completeShiftActivity(active.id, { skipForm: active.kind !== "service" && active.kind !== "trouble" });
      if (active.kind === "service" || active.kind === "trouble"){
        return;
      }
    }
    const eos = sim.items.find((item) => item.kind === "eos") || null;
    if (eos && eos.status !== "COMPLETED"){
      completeShiftActivity(eos.id, { skipForm: true });
    }
    sim.clockedOutAt = nowISO();
    persistTechnicianSimulation();
    renderTechnicianDashboard();
    toast("Clock out", "Technician shift ended.");
    return;
  }
  if (!state.technician.timesheet) return;
  if (isDemo){
    const now = nowISO();
    const ts = state.technician.timesheet;
    const startMs = ts.clock_in_at ? new Date(ts.clock_in_at).getTime() : Date.now();
    const endMs = new Date(now).getTime();
    const worked = Math.max(0, Math.round((endMs - startMs) / 60000));
    state.demo.timesheets = (state.demo.timesheets || []).map((row) => (
      row.id === ts.id
        ? { ...row, clock_out_at: now, total_minutes_worked: worked }
        : row
    ));
    state.technician.timesheet = state.demo.timesheets.find((row) => row.id === ts.id) || null;
    await loadTechnicianEvents();
    toast("Clock out", "Clocked out (demo).");
    return;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const activeEvent = state.technician.activeEvent;
  if (activeEvent && activeEvent.event_type === "START_JOB"){
    toast("Active job", "End the job before clocking out.");
    return;
  }
  const { data, error } = await state.client.rpc("fn_end_timesheet", {
    timesheet_id: state.technician.timesheet.id,
  });
  if (error){
    toast("Clock out failed", error.message);
    return;
  }
  state.technician.timesheet = data || state.technician.timesheet;
  await loadTechnicianEvents();
  renderTechnicianDashboard();
  await autoSaveDailyProgressReport({
    projectId: state.technician.timesheet?.project_id || data?.project_id || state.activeProject?.id || null,
    reportDate: state.technician.timesheet?.work_date || data?.work_date || getSpecComDateKey(),
    silent: false,
  });
}

async function loadLaborRows(){
  const wrap = $("laborTable");
  if (!wrap) return;
  if (!state.features.labor){
    state.labor.rows = [];
    renderLaborTable();
    return;
  }
  if (!canViewLabor()){
    state.labor.rows = [];
    renderLaborTable();
    return;
  }
  if (!state.activeProject){
    state.labor.rows = [];
    renderLaborTable();
    return;
  }
  if (isDemo){
    state.labor.rows = [];
    renderLaborTable();
    return;
  }
  const { data, error } = await state.client
    .from("technician_timesheets")
    .select("id, user_id, work_date, total_minutes_worked, clock_in_at, clock_out_at, created_at")
    .eq("project_id", state.activeProject.id)
    .order("work_date", { ascending: false })
    .order("created_at", { ascending: false });
  if (error){
    if (isMissingTable(error)){
      state.features.labor = false;
      state.labor.rows = [];
      renderLaborTable();
      return;
    }
    toast("Labor load error", error.message);
    return;
  }
  const rows = data || [];
  const userIds = [...new Set(rows.map(r => r.user_id).filter(Boolean))];
  let nameById = new Map();
  if (userIds.length){
    const { data: profiles, error: profileError } = await state.client
      .from("profiles")
      .select("id, display_name")
      .in("id", userIds);
    if (!profileError){
      nameById = new Map((profiles || []).map(p => [p.id, p.display_name || p.id]));
    }
  }

  const pendingIds = rows.filter(r => r.total_minutes_worked == null).map(r => r.id);
  const paidByTimesheet = new Map();
  if (pendingIds.length){
    const { data: events } = await state.client
      .from("technician_time_events")
      .select("timesheet_id, event_type, duration_minutes, started_at, ended_at")
      .in("timesheet_id", pendingIds);
    const bySheet = new Map();
    (events || []).forEach((event) => {
      if (!bySheet.has(event.timesheet_id)) bySheet.set(event.timesheet_id, []);
      bySheet.get(event.timesheet_id).push(event);
    });
    bySheet.forEach((evs, id) => {
      const summary = computeTechnicianSummary(evs);
      paidByTimesheet.set(id, summary.paidMinutes);
    });
  }

  state.labor.rows = rows.map((row) => {
    const paidMinutes = Number(row.total_minutes_worked ?? paidByTimesheet.get(row.id) ?? 0);
    return {
      id: row.id,
      user_id: row.user_id,
      name: nameById.get(row.user_id) || row.user_id,
      work_date: row.work_date,
      paid_minutes: paidMinutes,
      clock_in_at: row.clock_in_at,
      clock_out_at: row.clock_out_at,
    };
  });
  renderLaborTable();
}

async function loadLaborSnapshotForDashboard(){
  if (!state.features.labor){
    state.labor.snapshot = null;
    renderAlerts();
    return;
  }
  if (!canViewLabor() || !state.activeProject || !state.client || isDemo){
    state.labor.snapshot = null;
    renderAlerts();
    return;
  }

  const workDate = getSpecComDateKey();
  const { data, error } = await state.client
    .from("technician_timesheets")
    .select("id, user_id, work_date, total_minutes_worked, clock_in_at, clock_out_at, created_at")
    .eq("project_id", state.activeProject.id)
    .eq("work_date", workDate)
    .order("created_at", { ascending: false });
  if (error){
    if (isMissingTable(error)){
      state.features.labor = false;
      state.labor.snapshot = null;
      renderAlerts();
      return;
    }
    toast("Timesheet snapshot error", error.message);
    return;
  }

  const rows = data || [];
  const userIds = [...new Set(rows.map((row) => row.user_id).filter(Boolean))];
  let nameById = new Map();
  if (userIds.length){
    const { data: profiles, error: profileError } = await state.client
      .from("profiles")
      .select("id, display_name")
      .in("id", userIds);
    if (!profileError){
      nameById = new Map((profiles || []).map((row) => [row.id, row.display_name || row.id]));
    }
  }

  const pendingIds = rows.filter((row) => row.total_minutes_worked == null).map((row) => row.id);
  const paidByTimesheet = new Map();
  if (pendingIds.length){
    const { data: events } = await state.client
      .from("technician_time_events")
      .select("timesheet_id, event_type, duration_minutes, started_at, ended_at")
      .in("timesheet_id", pendingIds);
    const bySheet = new Map();
    (events || []).forEach((event) => {
      if (!bySheet.has(event.timesheet_id)) bySheet.set(event.timesheet_id, []);
      bySheet.get(event.timesheet_id).push(event);
    });
    bySheet.forEach((eventsForSheet, timesheetId) => {
      const summary = computeTechnicianSummary(eventsForSheet);
      paidByTimesheet.set(timesheetId, summary.paidMinutes);
    });
  }

  state.labor.snapshot = {
    project_id: state.activeProject.id,
    work_date: workDate,
    rows: rows.map((row) => ({
      id: row.id,
      user_id: row.user_id,
      name: nameById.get(row.user_id) || row.user_id,
      clock_in_at: row.clock_in_at,
      clock_out_at: row.clock_out_at,
      paid_minutes: Number(row.total_minutes_worked ?? paidByTimesheet.get(row.id) ?? 0),
    })),
  };
  renderAlerts();
}

function renderLaborTable(){
  const wrap = $("laborTable");
  if (!wrap) return;
  if (!state.activeProject){
    wrap.innerHTML = `<div class="muted small">${t("laborNoProject")}</div>`;
    return;
  }
  const rows = state.labor.rows || [];
  if (!rows.length){
    wrap.innerHTML = `<div class="muted small">${t("laborNoRows")}</div>`;
    return;
  }
  wrap.innerHTML = `
    <table class="table">
      <thead>
        <tr>
          <th>${t("laborTechLabel")}</th>
          <th>${t("laborDateLabel")}</th>
          <th>${t("laborPaidHoursLabel")}</th>
        </tr>
      </thead>
      <tbody>
        ${rows.map((row) => {
          const hours = (Number(row.paid_minutes || 0) / 60).toFixed(2);
          return `
            <tr>
              <td>${escapeHtml(row.name || "")}</td>
              <td>${escapeHtml(row.work_date || "")}</td>
              <td>${hours}</td>
            </tr>
          `;
        }).join("")}
      </tbody>
    </table>
  `;
}

function exportLaborCsv(){
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const rows = state.labor.rows || [];
  if (!rows.length) return;
  const header = [t("laborTechLabel"), t("laborDateLabel"), t("laborPaidHoursLabel")];
  const csvRows = rows.map((row) => ([
    row.name || "",
    row.work_date || "",
    (Number(row.paid_minutes || 0) / 60).toFixed(2),
  ]));
  const csv = [header.map(escapeCsv).join(",")]
    .concat(csvRows.map(r => r.map(escapeCsv).join(",")))
    .join("\n");
  const projectLabel = state.activeProject?.job_number || state.activeProject?.name || "project";
  downloadFile(`labor-${projectLabel}.csv`, csv, "text/csv");
}

function showAuth(show){
  if (CONTROL_CENTER_DEV_MODE && !show){
    $("viewAuth").style.display = "none";
    $("viewApp").style.display = "";
    console.info("[auth] app UI shown", { reason: "control-center-dev-mode" });
    return;
  }
  $("viewAuth").style.display = show ? "" : "none";
  $("viewApp").style.display = show ? "none" : "";
  console.info(show ? "[auth] auth UI shown" : "[auth] app UI shown", { source: "showAuth" });
}

function showPendingAccountMessage(){
  // Show a holding screen for users whose account hasn't been assigned to a company yet
  const el = document.getElementById("viewApp");
  if (!el) return;
  el.style.display = "";
  // Hide nav and sidebar so they don't see broken empty state
  ["viewNav", "navBar", "sideBar", "mainNav"].forEach((id) => {
    const node = document.getElementById(id);
    if (node) node.style.display = "none";
  });
  // Find the main content area and render a pending card
  const main = document.getElementById("mainContent") || document.getElementById("appContent") || el;
  const existing = document.getElementById("pendingAccountCard");
  if (existing) return;
  const card = document.createElement("div");
  card.id = "pendingAccountCard";
  card.className = "card";
  card.style.cssText = "max-width:480px;margin:80px auto;text-align:center;padding:32px 24px;";
  card.innerHTML = `
    <div style="font-size:2rem;margin-bottom:12px;">⏳</div>
    <h2 style="margin:0 0 8px;">Account Pending Setup</h2>
    <p class="muted" style="margin:0 0 20px;">Your account has been created but hasn't been assigned to a company yet. A SpecCom administrator will activate your account shortly.</p>
    <p class="muted small">If you believe this is an error, contact your administrator.</p>
    <button class="btn ghost small" style="margin-top:16px;" onclick="SpecCom.helpers.handleSignOut()">Sign out</button>
  `;
  main.prepend(card);
}

