async function saveProfilePhotoFromFile(file){
  if (!file) return;
  const userId = String(state.user?.id || "").trim();
  if (!userId){
    toast("Not signed in", "Sign in first to save profile photo.", "error");
    return false;
  }
  const ext = getAvatarFileExtension(file);
  if (!ext){
    toast("Invalid file", "Choose JPG, PNG, or WEBP.", "error");
    return false;
  }
  if (!state.client){
    toast("Upload failed", "Client not ready.", "error");
    return false;
  }
  const objectPath = `${userId}/avatar.${ext}`;
  const storage = state.client.storage.from("profile-images");
  const { error: uploadError } = await storage.upload(objectPath, file, {
    upsert: true,
    contentType: file.type || undefined,
    cacheControl: "3600",
  });
  if (uploadError){
    toast("Upload failed", uploadError.message || "Could not upload profile photo.", "error");
    return false;
  }
  const { data: publicUrlData } = storage.getPublicUrl(objectPath);
  const avatarUrl = String(publicUrlData?.publicUrl || objectPath).trim();
  const { error: updateError } = await state.client
    .from("profiles")
    .update({ avatar_url: avatarUrl })
    .eq("id", userId);
  if (updateError){
    toast("Save failed", updateError.message || "Could not save profile avatar URL.", "error");
    return false;
  }
  state.profile = state.profile || {};
  state.profile.avatar_url = avatarUrl;
  window.currentUserProfile = state.profile;
  updateCommandHeaderAvatar(avatarUrl);
  renderProfileHomeCard();
  toast("Profile photo saved", "Your profile photo was updated.");
  return true;
}

async function initProfilePhotoUpload(user) {
  const contexts = [
    {
      wrap: document.getElementById("prof-avatar-wrap"),
      input: document.getElementById("prof-photo-input"),
      display: document.getElementById("prof-avatar-display"),
      hint: document.querySelector(".prof-photo-hint"),
      uploading: document.querySelector(".prof-photo-uploading"),
    },
    {
      wrap: document.getElementById("profile-page-avatar-wrap"),
      input: document.getElementById("profile-page-photo-input"),
      display: document.getElementById("profile-page-avatar-display"),
      hint: document.getElementById("profile-page-photo-hint"),
      uploading: document.getElementById("profile-page-photo-uploading"),
    },
  ];

  for (const ctx of contexts){
    const { wrap, input, display, hint, uploading } = ctx;
    if (!wrap || !input || !display) continue;
    if (user?.photoUrl) display.innerHTML = `<img src="${user.photoUrl}" alt="Profile photo"/>`;
    else if (user?.name) display.textContent = user.name.slice(0, 2).toUpperCase();
    if (!wrap.dataset.uploadBound){
      wrap.addEventListener("click", () => input.click());
      wrap.dataset.uploadBound = "1";
    }
    if (input.dataset.uploadBound) continue;
    input.dataset.uploadBound = "1";
    input.addEventListener("change", async (e) => {
      const target = e.target;
      const file = target?.files?.[0] || null;
      if (!file) return;
      if (file.size > 2 * 1024 * 1024) {
        toast("Photo must be under 2MB", "Choose a JPG, PNG, or WEBP file under 2MB.", "error");
        input.value = "";
        return;
      }
      const localUrl = URL.createObjectURL(file);
      display.innerHTML = `<img src="${localUrl}" alt="Profile photo"/>`;
      if (hint) hint.style.display = "none";
      if (uploading) {
        uploading.textContent = "Uploading...";
        uploading.style.display = "block";
      }
      try {
        const saved = await saveProfilePhotoFromFile(file);
        if (!saved){
          if (hint) hint.style.display = "block";
          if (uploading) uploading.style.display = "none";
          URL.revokeObjectURL(localUrl);
          input.value = "";
          return;
        }
        if (uploading) uploading.textContent = "Photo updated!";
        setTimeout(() => {
          if (hint) hint.style.display = "block";
          if (uploading) uploading.style.display = "none";
        }, 2500);
      } catch (err) {
        console.error("Photo upload failed:", err);
        toast("Upload failed", "Please try again.", "error");
        if (hint) hint.style.display = "block";
        if (uploading) uploading.style.display = "none";
      }
      URL.revokeObjectURL(localUrl);
      input.value = "";
    });
  }
}

async function clearProfilePhoto(){
  const userId = String(state.user?.id || "").trim();
  if (!userId || !state.client) return;
  const objectPrefix = `${userId}/`;
  try{
    const storage = state.client.storage.from("profile-images");
    const { data: listData } = await storage.list(objectPrefix, { limit: 20 });
    const paths = (listData || [])
      .map((row) => `${objectPrefix}${row.name}`)
      .filter((path) => /\/avatar\.(jpg|jpeg|png|webp)$/i.test(path));
    if (paths.length){
      await storage.remove(paths);
    }
  } catch {}
  await state.client
    .from("profiles")
    .update({ avatar_url: null })
    .eq("id", userId);
  if (state.profile){
    state.profile.avatar_url = null;
    window.currentUserProfile = state.profile;
  }
  renderProfileHomeCard();
  toast("Profile photo removed", "Photo removed.");
}

