function renderMapFieldPanel(){
  const panel = $("mapFieldPanel");
  const panelHeader = $("mapFieldPanelHeader");
  const showBtn = $("btnMapFieldShow");
  const gpsState = $("mapFieldGpsState");
  const actionsWrap = $("mapFieldNearbyActions");
  const createWrap = $("mapFieldCreateWrap");
  const card = $("mapFieldLocationCard");
  const tailActions = $("mapFieldDayTailActions");
  if (!panel || !gpsState || !actionsWrap || !createWrap || !card || !tailActions) return;
  const isRoot = bypassesFieldDayWorkflow();
  const createOpen = Boolean(state.map.fieldCreateOpen);
  if (state.node54Diagnostics.enabled){
    panel.hidden = false;
    panel.style.display = "grid";
    panel.classList.remove("is-root-admin", "is-create-open");
    panel.classList.add("is-node54-diagnostic");
    document.body.classList.add("node54-diagnostic-mode");
    if (showBtn) showBtn.style.display = "none";
    if (panelHeader){ panelHeader.hidden = true; panelHeader.style.display = "none"; }
    gpsState.hidden = true;
    gpsState.style.display = "none";
    createWrap.hidden = true;
    createWrap.style.display = "none";
    actionsWrap.hidden = false;
    actionsWrap.innerHTML = renderNode54DiagnosticPanel();
    card.hidden = true;
    card.innerHTML = "";
    tailActions.hidden = true;
    tailActions.innerHTML = "";
    return;
  }
  panel.classList.remove("is-node54-diagnostic");
  document.body.classList.remove("node54-diagnostic-mode");
  if (isRoot){
    panel.hidden = false;
    panel.style.display = "grid";
    panel.classList.toggle("is-create-open", createOpen);
    panel.classList.add("is-root-admin");
    document.body.classList.toggle("map-create-open", createOpen);
    if (showBtn) showBtn.style.display = "none";
    if (panelHeader){
      panelHeader.hidden = true;
      panelHeader.style.display = "none";
    }
    gpsState.hidden = true;
    gpsState.style.display = "none";
    createWrap.hidden = !createOpen;
    createWrap.style.display = createOpen ? "grid" : "none";
    actionsWrap.hidden = createOpen;
    actionsWrap.innerHTML = createOpen ? "" : renderRootMapAdminControls();
    card.hidden = true;
    card.innerHTML = "";
    tailActions.hidden = true;
    tailActions.innerHTML = "";
    return;
  }
  panel.classList.remove("is-root-admin");
  if (panelHeader){
    panelHeader.hidden = false;
    panelHeader.style.display = "";
  }
  gpsState.hidden = false;
  gpsState.style.display = "";
  const panelVisible = state.map.fieldPanelVisible !== false;
  panel.hidden = !panelVisible;
  panel.style.display = panelVisible ? "grid" : "none";
  if (showBtn){
    showBtn.style.display = panelVisible ? "none" : "";
  }
  if (panelVisible && isMobileViewport()){
    setLayersPanelOpen(false, { persist: true });
    setMapViewDropdownOpen(false);
  }
  if (!panelVisible) return;
  createWrap.hidden = !createOpen;
  createWrap.style.display = createOpen ? "grid" : "none";
  if (panel){
    panel.classList.toggle("is-create-open", createOpen);
  }
  document.body.classList.toggle("map-create-open", createOpen);
  actionsWrap.hidden = createOpen;
  tailActions.hidden = createOpen;

  const gps = state.map.myLocation;
  const nearestId = toSiteIdKey(state.map.nearestSiteId);
  const nearest = nearestId
    ? getVisibleSites().find((site) => toSiteIdKey(site?.id) === nearestId) || null
    : null;
  const selected = createOpen ? null : (getMapFieldSelectedSite() || nearest || null);

  if (!gps){
    gpsState.textContent = "GPS not captured yet.";
  } else {
    const lat = Number(gps.lat).toFixed(6);
    const lng = Number(gps.lng).toFixed(6);
    const accuracyText = Number.isFinite(gps.accuracy_m) ? ` (+/-${Math.round(gps.accuracy_m)}m)` : "";
    gpsState.textContent = `${lat}, ${lng}${accuracyText}`;
  }

  actionsWrap.innerHTML = `
    ${renderNode54EntryAction()}
    ${renderFieldDayControls(gps, nearest, selected)}
    ${!selected ? `
      <section class="map-field-guide-card">
        <div class="map-field-card-kicker">Select Saved Location</div>
        <label for="mapFieldVisitSearch">Search saved location</label>
        <div class="map-field-search-row">
          <input id="mapFieldVisitSearch" class="input compact" type="search" placeholder="1704, 1748, 2123" />
          <button class="btn secondary small" type="button" data-map-field-action="searchVisitLocation">Search</button>
        </div>
        <div class="muted tiny">No saved location is selected yet.</div>
        ${state.activeProject ? `<button id="btnMapShowCreateLocation" class="btn ghost small" type="button">Create New Location Here</button>` : ""}
        ${state.activeProject ? `<button id="btnMapFieldImportLocations" class="btn ghost small" type="button">Import Locations (KMZ / KML / ZIP / CSV / PDF)</button>` : ""}
      </section>
    ` : ""}
  `;
  tailActions.innerHTML = "";

  if (!selected){
    card.hidden = true;
    card.innerHTML = "";
    tailActions.innerHTML = `
      ${renderFieldBreakLunchCard()}
      ${renderFieldDayEndCard()}
      ${renderMapFieldGpsAwareness(gps, nearest)}
      ${renderTodayWorklistCard(selected)}
    `;
    return;
  }
  card.hidden = false;
  const status = getSiteWorkflowStatus(selected);
  const statusClass = getMapFieldStatusClass(status);
  const statusLabel = getMapFieldStatusLabel(status);
  const coords = getSiteCoords(selected);
  const coordText = coords ? `${coords.lat.toFixed(6)}, ${coords.lng.toFixed(6)}` : "No GPS";
  card.innerHTML = `
    <div class="row" style="justify-content:space-between; align-items:center; gap:8px;">
      <div style="font-weight:800;">${escapeHtml(getSiteDisplayName(selected))}</div>
      <span class="map-field-status-chip ${statusClass}">${escapeHtml(statusLabel)}</span>
    </div>
    <div class="map-field-location-meta">${escapeHtml(coordText)}</div>
    ${renderSiteTestResultChip(selected)}
    ${renderFieldDayLocationControls(selected)}
    <div class="map-field-utility-row">
      <button class="btn ghost small" type="button" data-map-field-action="open" data-site-id="${selected.id}">Open Full Location Details</button>
      <button class="btn ghost small" type="button" data-map-field-action="complete" data-site-id="${selected.id}">Mark Base Complete</button>
    </div>
    <div class="map-field-status-control">
      <label class="small" for="mapFieldStatusSelect">Base location status</label>
      <select id="mapFieldStatusSelect" class="input compact" data-site-id="${selected.id}">
        <option value="${MAP_FIELD_STATUS.NOT_STARTED}" ${status === MAP_FIELD_STATUS.NOT_STARTED ? "selected" : ""}>Not Started</option>
        <option value="${MAP_FIELD_STATUS.IN_PROGRESS}" ${status === MAP_FIELD_STATUS.IN_PROGRESS ? "selected" : ""}>In Progress</option>
        <option value="${MAP_FIELD_STATUS.COMPLETE}" ${status === MAP_FIELD_STATUS.COMPLETE ? "selected" : ""}>Complete</option>
      </select>
    </div>
    ${renderMapFieldWorkLogForm(selected, status)}
  `;
  tailActions.innerHTML = `
    ${renderFieldBreakLunchCard()}
    ${renderFieldDayEndCard()}
    ${renderMapFieldGpsAwareness(gps, nearest)}
    ${renderTodayWorklistCard(selected)}
  `;
  void hydrateMapFieldSiteActivity(selected.id);
}

function setMapFieldPanelVisible(visible){
  const next = Boolean(visible);
  state.map.fieldPanelVisible = next;
  if (next && isMobileViewport()){
    setLayersPanelOpen(false, { persist: true });
    setMapViewDropdownOpen(false);
  }
  if (!next && state.map.fieldCreateOpen){
    state.map.fieldCreateOpen = false;
    document.body.classList.remove("map-create-open");
  }
  renderMapFieldPanel();
}

function setMapFloatPanelHidden(hidden){
  const next = Boolean(hidden);
  if (typeof window.__setMapFloatPanelHidden === "function"){
    window.__setMapFloatPanelHidden(next);
  } else {
    const panel = $("map-float-panel");
    const body = $("map-float-body");
    const minBtn = $("map-float-minimize");
    document.body.classList.toggle("map-float-panel-hidden", next);
    if (panel){
      panel.classList.toggle("is-hidden-for-map", next);
      panel.setAttribute("aria-hidden", next ? "true" : "false");
    }
    if (!next && body) body.style.display = "";
    if (!next && minBtn) minBtn.textContent = "−";
  }
  queueMapInvalidate([80, 180]);
}

function hideMapFloatPanelForMapAction(){
  if (!isMobileViewport()) return;
  setMapFloatPanelHidden(true);
}

function setMapFieldCreateOpen(open){
  const wrap = $("mapFieldCreateWrap");
  const panel = $("mapFieldPanel");
  const panelHeader = $("mapFieldPanelHeader");
  const gpsState = $("mapFieldGpsState");
  const actionsWrap = $("mapFieldNearbyActions");
  const locationCard = $("mapFieldLocationCard");
  state.map.fieldCreateOpen = Boolean(open);
  if (open){
    state.map.fieldPanelVisible = true;
    if (isMobileViewport()){
      setLayersPanelOpen(false);
    }
  }
  if (!open){
    state.map.fieldCreateRecentlyClosedUntil = Date.now() + 450;
  }
  document.body.classList.toggle("map-create-open", Boolean(open));
  if (panel){
    panel.classList.toggle("is-create-open", Boolean(open));
  }
  [panelHeader, gpsState, actionsWrap, locationCard].forEach((el) => {
    if (!(el instanceof HTMLElement)) return;
    el.style.display = open ? "none" : "";
  });
  if (!wrap) return;
  wrap.hidden = !open;
  wrap.style.display = open ? "grid" : "none";
  if (open){
    state.map.dropPinMode = false;
    state.map.pendingLatLng = null;
    clearPendingPinMarker();
  }
  if (open){
    $("mapFieldLocationName")?.focus();
  } else {
    state.map._pendingProofPhotos = [];
    state.map._pendingPhotoCapture = null;
    const preview = $("mapFieldPhotoPreview");
    if (preview) preview.innerHTML = "";
    const photoInput = $("mapFieldPhotoInput");
    if (photoInput) photoInput.value = "";
  }
  renderMapFieldPanel();
}

async function openSitePopupForSiteId(siteId, { center = true, syncSelection = true } = {}){
  const siteKey = toSiteIdKey(siteId);
  if (!siteKey) return false;
  const site = getVisibleSiteByIdKey(siteKey);
  if (!site) return false;
  if (center){
    focusSiteOnMap(siteKey);
  }
  const marker = state.map.markers.get(siteKey) || null;
  if (!marker) return false;
  setMapPopupSiteContext(marker, site);
  await renderMapPopupActiveSite({ syncSelection });
  return true;
}

async function openLocationForField(siteId, { center = true, forAdd = false } = {}){
  if (!siteId) return;
  await setActiveSite(siteId, { openOverview: false });
  setMapFieldSelectedSite(siteId);
  const popupOpened = await openSitePopupForSiteId(siteId, { center, syncSelection: true });
  if (center){
    hideMapFloatPanelForMapAction();
  }
  if (forAdd && !popupOpened){
    // Stay on map — navigating to viewNodes hides the map container and causes tile reload
    // artifacts ("Map data not yet available") when the user returns to the map view.
    renderMapFieldPanel();
  }
}

async function requestMapCurrentLocation({ center = false, silent = false } = {}){
  ensureMap();
  // Set the timestamp immediately so concurrent setActiveView calls don't spawn duplicate GPS requests
  state.map.lastFieldGpsCheckAt = Date.now();
  const gps = await getCurrentGps({ enableHighAccuracy: true, timeout: 12000, maximumAge: 12000 });
  if (!gps){
    if (!silent){
      toast("GPS unavailable", "Unable to capture your current location.");
    }
    return null;
  }
  const enriched = {
    lat: gps.lat,
    lng: gps.lng,
    accuracy_m: Number.isFinite(gps.accuracy) ? gps.accuracy : null,
    captured_at: nowISO(),
  };
  state.lastGPS = { lat: enriched.lat, lng: enriched.lng, accuracy_m: enriched.accuracy_m };
  state.map.myLocation = enriched;
  state.map.lastFieldGpsCheckAt = Date.now();
  ensureMyLocationMarker(enriched);
  const nearest = findNearestVisibleSite(enriched, getFieldGpsAssociationRadius(enriched));
  state.map.nearestSiteId = nearest?.site?.id ? toSiteIdKey(nearest.site.id) : "";
  state.map.nearestSiteDistanceM = nearest?.distanceM ?? null;
  void recordFieldLocationPingFromGps(enriched, { nearest, source: "field_location_button" });
  if (center && state.map.instance){
    state.map.instance.setView([enriched.lat, enriched.lng], Math.max(state.map.instance.getZoom() || 0, 18));
    if (!silent){
      hideMapFloatPanelForMapAction();
    }
  }
  renderMapFieldPanel();
  return enriched;
}

async function openOrCreateSpliceAtCurrentLocation({ center = true, hidePanel = true } = {}){
  const gps = await requestMapCurrentLocation({ center, silent: false });
  if (!gps) return null;
  const nearest = findNearestVisibleSite(gps, getFieldGpsAssociationRadius(gps));
  let siteId = nearest?.site?.id || null;
  if (!siteId){
    siteId = await createSiteFromMapClick(
      { lat: gps.lat, lng: gps.lng },
      "",
      {
        locationType: "Splice Point",
        openedFromFieldCapture: true,
        createdAt: gps.captured_at || nowISO(),
        suppressAccessDeniedToast: true,
      }
    );
  }
  if (!siteId){
    toast("Location captured", "No nearby assigned splice location, and this account cannot create new pins for this project.");
    return null;
  }
  // A concurrent loadProjectSites (from background polling or initial setActiveView call)
  // may have overwritten state.projectSites with server data fetched before this site was
  // created, evicting it from state. If that happened, reload now so openLocationForField
  // can find the site.
  const siteKey = toSiteIdKey(siteId);
  if (!getVisibleSites().find((s) => toSiteIdKey(s?.id) === siteKey)){
    await loadProjectSites(state.activeProject?.id || null);
  }
  // Restore GPS view in case something moved the map during the async site operations
  if (center && state.map.instance){
    state.map.instance.setView([gps.lat, gps.lng], Math.max(state.map.instance.getZoom() || 0, 17));
  }
  await openLocationForField(siteId, { center: true, forAdd: true });
  focusSiteOnMap(siteId);
  if (hidePanel){
    setMapFieldPanelVisible(false);
  }
  return siteId;
}

function setSiteWorkflowStatus(siteId, status){
  const key = toSiteIdKey(siteId);
  if (!key) return;
  const normalized = normalizeMapFieldStatus(status);
  state.map.siteWorkflowById.set(key, normalized);
  const resultSet = getSiteSearchResultSet();
  if (state.map.instance){
    updateMapMarkers(resultSet.rows);
  }
  renderMapFieldPanel();
}

function formatMapFieldPendingDocSize(bytes){
  const size = Number(bytes);
  if (!Number.isFinite(size) || size < 0) return "";
  if (size < 1024) return `${Math.round(size)} B`;
  const units = ["KB", "MB", "GB", "TB"];
  let value = size;
  let unitIndex = -1;
  while (value >= 1024 && unitIndex < units.length - 1){
    value /= 1024;
    unitIndex += 1;
  }
  const digits = value >= 10 ? 1 : 2;
  return `${value.toFixed(digits)} ${units[Math.max(0, unitIndex)]}`;
}

function renderMapFieldPendingDocs(){
  const preview = $("mapFieldDocPreview");
  if (!preview) return;
  preview.replaceChildren();
  const pendingDocs = Array.isArray(state.map._pendingDocs) ? state.map._pendingDocs : [];
  pendingDocs.forEach((file, index) => {
    const row = document.createElement("div");
    row.style.display = "flex";
    row.style.alignItems = "center";
    row.style.justifyContent = "space-between";
    row.style.gap = "8px";
    row.style.padding = "6px 8px";
    row.style.border = "1px solid rgba(255,255,255,0.12)";
    row.style.borderRadius = "8px";

    const details = document.createElement("div");
    details.style.minWidth = "0";
    details.style.display = "flex";
    details.style.flexDirection = "column";
    details.style.gap = "2px";

    const nameEl = document.createElement("div");
    nameEl.className = "small";
    nameEl.style.wordBreak = "break-word";
    nameEl.textContent = String(file?.name || `Attachment ${index + 1}`);

    const metaEl = document.createElement("div");
    metaEl.className = "muted small";
    metaEl.textContent = formatMapFieldPendingDocSize(file?.size);

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.className = "btn ghost small";
    removeBtn.dataset.mapFieldDocRemove = String(index);
    removeBtn.setAttribute("aria-label", `Remove ${nameEl.textContent}`);
    removeBtn.textContent = "x";

    details.appendChild(nameEl);
    if (metaEl.textContent){
      details.appendChild(metaEl);
    }
    row.append(details, removeBtn);
    preview.appendChild(row);
  });
}

function parseMapFieldBillingCodeLines(raw){
  return String(raw || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      let billingCode = line;
      let quantity = 1;
      const match = line.match(/^(.*\S)\s+(-?\d+(?:\.\d+)?)$/);
      if (match){
        billingCode = match[1].trim();
        const parsedQty = Number(match[2]);
        if (Number.isFinite(parsedQty) && parsedQty > 0){
          quantity = parsedQty;
        }
      }
      return {
        billing_code: billingCode,
        quantity,
      };
    })
    .filter((row) => row.billing_code);
}

function applyMapFieldSiteNotes(siteId, nextNotes){
  const siteKey = toSiteIdKey(siteId);
  if (!siteKey) return;
  const liveMatch = (state.projectSites || []).find((row) => toSiteIdKey(row.id) === siteKey);
  if (liveMatch){
    liveMatch.notes = nextNotes;
  }
  if (toSiteIdKey(state.activeSite?.id) === siteKey && state.activeSite){
    state.activeSite.notes = nextNotes;
    if (state.pinOverview.open){
      SpecCom.helpers.renderPinOverview();
    } else {
      renderSitePanel();
    }
  }
  if (Array.isArray(state.pendingSites) && state.pendingSites.length){
    state.pendingSites = state.pendingSites.map((row) => (
      toSiteIdKey(row.id) === siteKey ? { ...row, notes: nextNotes } : row
    ));
    savePendingSitesToStorage(state.pendingSites);
  }
}

async function appendMapFieldBillingCodesToSiteNotes(site, billingRows){
  if (!site?.id || !billingRows.length) return false;
  const billingLine = `Billing: ${billingRows.map((row) => `${row.billing_code} x${row.quantity}`).join(", ")}`;
  const existing = String(site.notes || "").trim();
  const nextNotes = existing ? `${existing}\n${billingLine}` : billingLine;
  if (state.client && !site.is_pending){
    const { error } = await state.client
      .from("sites")
      .update({ notes: nextNotes })
      .eq("id", site.id);
    if (error){
      return false;
    }
  }
  site.notes = nextNotes;
  applyMapFieldSiteNotes(site.id, nextNotes);
  return true;
}

function parseMapFieldWorkCodes(raw){
  return Array.from(new Set(String(raw || "")
    .split(/[\n,]+/)
    .map((code) => code.trim())
    .filter(Boolean)));
}

function parseMapFieldMaterialLines(raw){
  return String(raw || "")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter(Boolean)
    .map((line) => {
      const match = line.match(/^(.*\S)\s+(-?\d+(?:\.\d+)?)$/);
      const item = match ? match[1].trim() : line;
      const qty = match ? Number(match[2]) : 1;
      return {
        item_key: item,
        qty_used: Number.isFinite(qty) && qty > 0 ? qty : 1,
      };
    })
    .filter((row) => row.item_key);
}

function normalizeMapFieldYesNo(value, fallback = ""){
  const text = String(value || "").trim().toLowerCase();
  if (["yes", "no", "unknown"].includes(text)) return text;
  return fallback;
}

function normalizeFieldVisitType(value){
  const text = String(value || "").trim();
  return FIELD_VISIT_TYPES.includes(text) ? text : "QC/Audit";
}

function normalizeFieldVisitFinalStatus(value, fallback = ""){
  const text = String(value || "").trim();
  return FIELD_VISIT_FINAL_STATUSES.includes(text) ? text : fallback;
}

function getDefaultVisitLabel(site){
  return String(getSiteDisplayName(site) || "field-visit").trim();
}

function getFieldVisitSource(label){
  const clean = String(label || "").trim();
  return clean ? `${FIELD_VISIT_SOURCE_PREFIX}${clean}` : "";
}

function isFieldVisitPhotoForLabel(photo, label){
  const source = String(photo?.source || "").trim();
  return Boolean(label) && source === getFieldVisitSource(label);
}

function getFieldVisitPhotoCount(siteId, label, proofType = ""){
  const photos = getCachedSitePhotos(siteId);
  const normalizedProof = String(proofType || "").trim();
  return photos.filter((photo) => (
    isFieldVisitPhotoForLabel(photo, label)
    && (!normalizedProof || String(photo?.proofType || "").trim() === normalizedProof)
  )).length;
}

function createFieldVisitDraft(site, existing = {}){
  const baseLabel = getDefaultVisitLabel(site);
  return {
    siteId: toSiteIdKey(site?.id),
    visitLabel: String(existing.visitLabel || existing.visit_label || baseLabel).trim() || baseLabel,
    visitType: normalizeFieldVisitType(existing.visitType || existing.visit_type),
    previousComplete: normalizeMapFieldYesNo(existing.previousComplete || existing.previous_complete, "unknown"),
    workWrong: normalizeMapFieldYesNo(existing.workWrong || existing.work_wrong, "no"),
    badReading: normalizeMapFieldYesNo(existing.badReading || existing.bad_reading, "no"),
    beforeReading: String(existing.beforeReading || existing.before_reading || "").trim(),
    afterReading: String(existing.afterReading || existing.after_reading || "").trim(),
    readingImproved: normalizeMapFieldYesNo(existing.readingImproved || existing.reading_improved, "unknown"),
    passFail: normalizeMapFieldYesNo(existing.passFail || existing.pass_fail, "unknown"),
    customerTransferBlocker: normalizeMapFieldYesNo(existing.customerTransferBlocker || existing.customer_transfer_blocker, "unknown"),
    fixedEnoughForTurnup: normalizeMapFieldYesNo(existing.fixedEnoughForTurnup || existing.fixed_enough_for_turnup, "unknown"),
    needsPatrickReview: normalizeMapFieldYesNo(existing.needsPatrickReview || existing.needs_patrick_review, "no"),
    needsReturn: Boolean(existing.needsReturn || existing.needs_return),
    escalate: Boolean(existing.escalate),
    auditNotes: String(existing.auditNotes || existing.audit_notes || "").trim(),
    finalNotes: String(existing.finalNotes || existing.final_notes || existing.work_completed || "").trim(),
    finalStatus: normalizeFieldVisitFinalStatus(existing.finalStatus || existing.final_status),
    materialItem: "",
    materialQty: "",
    materialUnit: "each",
    materialNotes: "",
    materials: Array.isArray(existing.materials) ? existing.materials : [],
    codeValue: "",
    codeRef: "",
    codeNotes: "",
    codes: Array.isArray(existing.codes) ? existing.codes : [],
  };
}

function getMapFieldVisitDraft(site){
  const siteId = toSiteIdKey(site?.id);
  const active = state.fieldDay.activeEvent || null;
  const activeLabel = active?.event_type === FIELD_DAY_EVENT_TYPES.LOCATION_WORK && toSiteIdKey(active.site_id) === siteId
    ? String(active.label || "").trim()
    : "";
  const current = state.map.fieldVisitDraft;
  if (!current || current.siteId !== siteId){
    state.map.fieldVisitDraft = createFieldVisitDraft(site, activeLabel ? { visitLabel: activeLabel } : {});
  } else if (activeLabel && current.visitLabel !== activeLabel){
    state.map.fieldVisitDraft.visitLabel = activeLabel;
  }
  return state.map.fieldVisitDraft;
}

function updateMapFieldVisitDraftFromInputs(siteId){
  const siteKey = toSiteIdKey(siteId);
  const site = getVisibleSiteByIdKey(siteKey) || getMapFieldSelectedSite();
  if (!site) return null;
  const draft = getMapFieldVisitDraft(site);
  if (!draft || draft.siteId !== siteKey) return draft;
  const value = (id) => String($(id)?.value || "").trim();
  const checked = (id) => Boolean($(id)?.checked);
  draft.visitLabel = value("mapFieldVisitLabel") || getDefaultVisitLabel(site);
  draft.visitType = normalizeFieldVisitType(value("mapFieldVisitType"));
  draft.previousComplete = normalizeMapFieldYesNo(value("mapFieldPreviousComplete"), draft.previousComplete || "unknown");
  draft.workWrong = normalizeMapFieldYesNo(value("mapFieldWorkWrong"), draft.workWrong || "no");
  draft.badReading = normalizeMapFieldYesNo(value("mapFieldBadReading"), draft.badReading || "no");
  draft.beforeReading = value("mapFieldBeforeReading");
  draft.afterReading = value("mapFieldAfterReading");
  draft.readingImproved = normalizeMapFieldYesNo(value("mapFieldReadingImproved"), draft.readingImproved || "unknown");
  draft.passFail = normalizeMapFieldYesNo(value("mapFieldPassFail"), draft.passFail || "unknown");
  draft.customerTransferBlocker = normalizeMapFieldYesNo(value("mapFieldCustomerTransferBlocker"), draft.customerTransferBlocker || "unknown");
  draft.fixedEnoughForTurnup = normalizeMapFieldYesNo(value("mapFieldFixedEnoughForTurnup"), draft.fixedEnoughForTurnup || "unknown");
  draft.needsPatrickReview = normalizeMapFieldYesNo(value("mapFieldNeedsPatrickReview"), draft.needsPatrickReview || "no");
  draft.needsReturn = checked("mapFieldNeedsReturn");
  draft.escalate = checked("mapFieldEscalate");
  draft.auditNotes = value("mapFieldAuditNotes");
  draft.finalNotes = value("mapFieldWorkCompleted");
  draft.finalStatus = normalizeFieldVisitFinalStatus(value("mapFieldFinalStatus"));
  draft.materialItem = value("mapFieldMaterialItem");
  draft.materialQty = value("mapFieldMaterialQty");
  draft.materialUnit = value("mapFieldMaterialUnit") || "each";
  draft.materialNotes = value("mapFieldMaterialNotes");
  draft.codeValue = value("mapFieldSpliceCode");
  draft.codeRef = value("mapFieldSpliceCodeRef");
  draft.codeNotes = value("mapFieldSpliceCodeNotes");
  return draft;
}

function renderFieldVisitOptions(options, selected){
  return options.map((option) => (
    `<option value="${escapeHtml(option)}" ${option === selected ? "selected" : ""}>${escapeHtml(option)}</option>`
  )).join("");
}

function addMapFieldDraftMaterial(siteId){
  const draft = updateMapFieldVisitDraftFromInputs(siteId);
  if (!draft) return false;
  const item = String(draft.materialItem || "").trim();
  if (!item){
    toast("Material needed", "Enter the material used before adding it.");
    return false;
  }
  const qty = Number(draft.materialQty || 1);
  draft.materials.push({
    item_key: item,
    qty_used: Number.isFinite(qty) && qty > 0 ? qty : 1,
    unit: draft.materialUnit || "each",
    notes: draft.materialNotes || "",
  });
  draft.materialItem = "";
  draft.materialQty = "";
  draft.materialUnit = "each";
  draft.materialNotes = "";
  renderMapFieldPanel();
  return true;
}

function addMapFieldDraftCode(siteId){
  const draft = updateMapFieldVisitDraftFromInputs(siteId);
  if (!draft) return false;
  const code = String(draft.codeValue || "").trim();
  if (!code){
    toast("Code needed", "Enter a billing code before adding it.");
    return false;
  }
  draft.codes.push({
    code,
    ref: draft.codeRef || "",
    notes: draft.codeNotes || "",
  });
  draft.codeValue = "";
  draft.codeRef = "";
  draft.codeNotes = "";
  renderMapFieldPanel();
  return true;
}

function removeMapFieldDraftListItem(siteId, listName, index){
  const draft = updateMapFieldVisitDraftFromInputs(siteId) || state.map.fieldVisitDraft;
  const list = draft?.[listName];
  const idx = Number(index);
  if (!Array.isArray(list) || !Number.isInteger(idx) || idx < 0 || idx >= list.length) return;
  list.splice(idx, 1);
  renderMapFieldPanel();
}

function getMapFieldVisitCodes(siteId){
  const draft = updateMapFieldVisitDraftFromInputs(siteId) || state.map.fieldVisitDraft;
  const codes = collectBillingCodes(draft?.codes, { code: draft?.codeValue, ref: draft?.codeRef, notes: draft?.codeNotes });
  if (codes.length) return codes;
  return parseMapFieldWorkCodes($("mapFieldWorkCodes")?.value || "");
}

function getMapFieldVisitMaterials(siteId){
  const draft = updateMapFieldVisitDraftFromInputs(siteId) || state.map.fieldVisitDraft;
  const materials = collectMaterials(draft?.materials, {
    item_key: draft?.materialItem,
    qty_used: Number(draft?.materialQty || 1) || 1,
    unit: draft?.materialUnit || "each",
    notes: draft?.materialNotes || "",
  });
  if (materials.length) return materials;
  return parseMapFieldMaterialLines($("mapFieldMaterialsUsed")?.value || "");
}

function composeFieldVisitWorkNotes(siteId){
  const draft = updateMapFieldVisitDraftFromInputs(siteId) || state.map.fieldVisitDraft || {};
  const lines = [
    `Visit label: ${draft.visitLabel || ""}`,
    `Visit type: ${draft.visitType || ""}`,
    `Previous work complete: ${draft.previousComplete || "unknown"}`,
    `Work wrong: ${draft.workWrong || "no"}`,
    `Bad reading: ${draft.badReading || "no"}`,
    `Before reading: ${draft.beforeReading || ""}`,
    `After reading: ${draft.afterReading || ""}`,
    `Reading improved: ${draft.readingImproved || "unknown"}`,
    `Pass/fail: ${draft.passFail || "unknown"}`,
    `Customer transfer blocker: ${draft.customerTransferBlocker || "unknown"}`,
    `Fixed enough for turn-up: ${draft.fixedEnoughForTurnup || "unknown"}`,
    `Needs Patrick review: ${draft.needsPatrickReview || "no"}`,
    `Needs return: ${draft.needsReturn ? "yes" : "no"}`,
    `Escalate: ${draft.escalate ? "yes" : "no"}`,
    `Status: ${draft.finalStatus || ""}`,
  ];
  if (draft.auditNotes) lines.push(`Audit notes: ${draft.auditNotes}`);
  if (draft.finalNotes) lines.push(`Final notes: ${draft.finalNotes}`);
  return lines.filter((line) => !line.endsWith(": ")).join("\n");
}

function parseFieldVisitWorkNotes(notes){
  const text = String(notes || "");
  const out = {};
  text.split(/\r?\n/).forEach((line) => {
    const match = line.match(/^([^:]+):\s*(.*)$/);
    if (!match) return;
    const key = match[1].trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_|_$/g, "");
    out[key] = match[2].trim();
  });
  return out;
}

function isFieldVisitStillBad(draft){
  if (!draft) return false;
  return draft.passFail === "no"
    || draft.fixedEnoughForTurnup === "no"
    || draft.customerTransferBlocker === "yes"
    || draft.needsReturn
    || draft.escalate;
}

function isFieldVisitTestResultStillBad(draft){
  if (!draft) return false;
  return draft.badReading === "yes"
    || draft.passFail === "no"
    || draft.fixedEnoughForTurnup === "no";
}

function normalizeCloseoutAnswer(value){
  const text = String(value || "").trim().toLowerCase();
  return FIELD_CLOSEOUT_ANSWER_VALUES.includes(text) ? text : "";
}

function createDefaultCloseoutAnswers(visitDraft, site){
  const photoCount = getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "");
  const billingCodeCount = collectBillingCodes(visitDraft?.codes, {
    code: visitDraft?.codeValue,
    ref: visitDraft?.codeRef,
    notes: visitDraft?.codeNotes,
  }).length;
  const materialCount = collectMaterials(visitDraft?.materials, {
    item_key: visitDraft?.materialItem,
    qty_used: visitDraft?.materialQty,
    unit: visitDraft?.materialUnit,
    notes: visitDraft?.materialNotes,
  }).length;
  return {
    before_reading_entered: visitDraft?.beforeReading ? "yes" : "no",
    after_reading_entered: visitDraft?.afterReading ? "yes" : "no",
    test_result_improved: visitDraft?.readingImproved === "yes" ? "yes" : (visitDraft?.readingImproved === "no" ? "no" : "na"),
    test_result_acceptable: visitDraft?.passFail === "yes" ? "yes" : (visitDraft?.passFail === "no" ? "no" : "na"),
    test_result_still_bad: isFieldVisitTestResultStillBad(visitDraft) ? "yes" : "no",
    needs_patrick_review: visitDraft?.needsPatrickReview === "yes" ? "yes" : "no",
    customer_transfer_blocker_remains: visitDraft?.customerTransferBlocker === "yes" ? "yes" : "no",
    ports_cleaned: "",
    ports_inspected: "",
    fiber_splice_points_inspected: "",
    splice_tray_inspected: "",
    connections_reseated_checked: "",
    damaged_hardware_found: "",
    weather_water_dirt_issue_found: "",
    previous_work_audited: visitDraft?.previousComplete === "yes" ? "yes" : (visitDraft?.previousComplete === "no" ? "no" : ""),
    issue_found: visitDraft?.workWrong === "yes" || visitDraft?.badReading === "yes" ? "yes" : "na",
    issue_repaired: visitDraft?.finalStatus === "Fixed" ? "yes" : "",
    material_used_recorded: materialCount ? "yes" : "na",
    splicing_code_recorded: billingCodeCount ? "yes" : "na",
    site_left_clean: "",
    location_safe_secured: "",
    before_photo_uploaded: getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "", "visit_before") ? "yes" : "no",
    issue_photo_uploaded: getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "", "visit_issue") ? "yes" : "no",
    after_photo_uploaded: getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "", "visit_after") ? "yes" : "no",
    description_notes_completed: visitDraft?.finalNotes ? "yes" : "no",
    gps_time_captured: state.map.myLocation ? "yes" : "",
    status_selected: visitDraft?.finalStatus ? "yes" : "no",
    any_photo_uploaded: photoCount ? "yes" : "no",
  };
}

function syncCloseoutEvidenceAnswers(closeoutDraft, visitDraft, site){
  if (!closeoutDraft) return closeoutDraft;
  const latest = createDefaultCloseoutAnswers(visitDraft, site);
  closeoutDraft.answers = closeoutDraft.answers || {};
  FIELD_CLOSEOUT_EVIDENCE_ANSWER_KEYS.forEach((key) => {
    const answer = normalizeCloseoutAnswer(latest[key]);
    if (answer) closeoutDraft.answers[key] = answer;
  });
  return closeoutDraft;
}

function getMapFieldCloseoutDraft(site){
  const siteId = toSiteIdKey(site?.id);
  const visitDraft = getMapFieldVisitDraft(site);
  if (!state.map.fieldCloseoutDraft || state.map.fieldCloseoutDraft.siteId !== siteId){
    state.map.fieldCloseoutDraft = {
      siteId,
      answers: createDefaultCloseoutAnswers(visitDraft, site),
      notes: {},
      noPhotoPossible: false,
      noPhotoReason: "",
      stillBadNote: "",
      blockerNote: "",
      nextStepNotes: "",
    };
  }
  syncCloseoutEvidenceAnswers(state.map.fieldCloseoutDraft, visitDraft, site);
  return state.map.fieldCloseoutDraft;
}

function updateMapFieldCloseoutDraftFromInputs(siteId){
  const site = getVisibleSiteByIdKey(siteId) || getMapFieldSelectedSite();
  if (!site) return null;
  const draft = getMapFieldCloseoutDraft(site);
  draft.noPhotoPossible = Boolean($("mapFieldNoPhotoPossible")?.checked);
  draft.noPhotoReason = String($("mapFieldNoPhotoReason")?.value || "").trim();
  draft.stillBadNote = String($("mapFieldStillBadNote")?.value || "").trim();
  draft.blockerNote = String($("mapFieldBlockerNote")?.value || "").trim();
  draft.nextStepNotes = String($("mapFieldNextStepNotes")?.value || "").trim();
  FIELD_CLOSEOUT_SECTIONS.forEach((section) => {
    section.items.forEach(([key]) => {
      const noteEl = $(`mapFieldCloseoutNote_${key}`);
      if (noteEl) draft.notes[key] = String(noteEl.value || "").trim();
    });
  });
  return draft;
}

function setMapFieldCloseoutAnswer(siteId, key, value){
  const site = getVisibleSiteByIdKey(siteId) || getMapFieldSelectedSite();
  if (!site) return;
  const draft = getMapFieldCloseoutDraft(site);
  draft.answers[key] = normalizeCloseoutAnswer(value);
  renderMapFieldPanel();
}

function getCloseoutUnansweredItems(closeoutDraft){
  const answers = closeoutDraft?.answers || {};
  return FIELD_CLOSEOUT_SECTIONS.flatMap((section) => (
    section.items
      .filter(([key]) => !normalizeCloseoutAnswer(answers[key]))
      .map(([key, label]) => label || FIELD_CLOSEOUT_ITEM_LABELS.get(key) || key)
  ));
}

function getCloseoutMissingRequirements(site, visitDraft, closeoutDraft){
  const missing = [];
  const photoCount = getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "");
  const finalStatus = normalizeFieldVisitFinalStatus(visitDraft?.finalStatus);
  const unanswered = getCloseoutUnansweredItems(closeoutDraft);
  if (unanswered.length){
    const visible = unanswered.slice(0, 4).join(", ");
    missing.push(`Answer all closeout checklist items Yes, No, or N/A before finalizing: ${visible}${unanswered.length > 4 ? `, +${unanswered.length - 4} more` : ""}.`);
  }
  if (!FIELD_VISIT_FINAL_STATUSES.includes(finalStatus)) missing.push("Select final status.");
  missing.push(...getRequiredFieldEvidenceMissing({
    notes: visitDraft?.finalNotes,
    photoCount,
    noPhotoPossible: closeoutDraft?.noPhotoPossible,
    noPhotoReason: closeoutDraft?.noPhotoReason,
    billingCodes: getMapFieldVisitCodes(site?.id),
    materials: getMapFieldVisitMaterials(site?.id),
  }));
  if (closeoutDraft?.answers?.test_result_still_bad === "yes" && !closeoutDraft.stillBadNote){
    missing.push("Still bad reading requires explanation.");
  }
  if (closeoutDraft?.answers?.customer_transfer_blocker_remains === "yes" && !closeoutDraft.blockerNote){
    missing.push("Customer transfer blocker requires explanation.");
  }
  if (["Needs Return", "Escalate"].includes(finalStatus) && !closeoutDraft?.nextStepNotes){
    missing.push("Needs Return or Escalate requires next-step notes.");
  }
  return missing;
}

function refreshMapFieldCloseoutAnswerUi(closeoutDraft){
  if (!closeoutDraft) return;
  const answers = closeoutDraft.answers || {};
  document.querySelectorAll("[data-closeout-key]").forEach((btn) => {
    const key = btn.dataset.closeoutKey || "";
    const value = btn.dataset.closeoutValue || "";
    btn.classList.toggle("is-active", normalizeCloseoutAnswer(answers[key]) === value);
  });
  document.querySelectorAll("[data-closeout-row-key]").forEach((row) => {
    const key = row.dataset.closeoutRowKey || "";
    row.classList.toggle("is-unanswered", !normalizeCloseoutAnswer(answers[key]));
  });
}

function refreshMapFieldCloseoutValidationState(siteId){
  if (!state.map.fieldCloseoutOpen) return;
  const site = getVisibleSiteByIdKey(siteId) || getMapFieldSelectedSite();
  if (!site) return;
  const visitDraft = updateMapFieldVisitDraftFromInputs(site.id) || state.map.fieldVisitDraft || {};
  const closeoutDraft = updateMapFieldCloseoutDraftFromInputs(site.id) || getMapFieldCloseoutDraft(site);
  syncCloseoutEvidenceAnswers(closeoutDraft, visitDraft, site);
  refreshMapFieldCloseoutAnswerUi(closeoutDraft);
  const missing = getCloseoutMissingRequirements(site, visitDraft, closeoutDraft);
  const validation = $("mapFieldCloseoutValidation");
  if (validation){
    validation.className = missing.length ? "map-field-missing-list" : "map-field-ready-list";
    validation.innerHTML = missing.length
      ? missing.map((item) => `<div>${escapeHtml(item)}</div>`).join("")
      : "Closeout requirements complete.";
  }
  const finalizeBtn = $("btnMapFieldFinalizeCloseout");
  if (finalizeBtn) finalizeBtn.disabled = Boolean(missing.length);
}

function buildFieldCloseoutPayload(site, visitDraft, activeEvent){
  const closeout = updateMapFieldCloseoutDraftFromInputs(site?.id) || getMapFieldCloseoutDraft(site);
  syncCloseoutEvidenceAnswers(closeout, visitDraft, site);
  const gps = state.map.myLocation || {};
  const photoCount = getFieldVisitPhotoCount(site?.id, visitDraft?.visitLabel || "");
  return {
    project_day_id: state.fieldDay.session?.id || "",
    location_visit_id: activeEvent?.id || "",
    project_id: state.activeProject?.id || "",
    user_id: state.user?.id || "",
    base_location_id: site?.id || "",
    base_location_label: getSiteDisplayName(site),
    visit_label: visitDraft?.visitLabel || "",
    visit_type: visitDraft?.visitType || "",
    before_reading: visitDraft?.beforeReading || "",
    after_reading: visitDraft?.afterReading || "",
    final_status: visitDraft?.finalStatus || "",
    audit_notes: visitDraft?.auditNotes || "",
    description_notes: visitDraft?.finalNotes || "",
    work_codes: getMapFieldVisitCodes(site?.id),
    materials_used: getMapFieldVisitMaterials(site?.id),
    timestamp: nowISO(),
    gps_lat: gps.lat ?? null,
    gps_lng: gps.lng ?? null,
    gps_accuracy_m: gps.accuracy_m ?? gps.accuracy ?? null,
    answers: closeout.answers || {},
    notes: closeout.notes || {},
    no_photo_possible: Boolean(closeout.noPhotoPossible),
    no_photo_reason: closeout.noPhotoReason || "",
    still_bad_note: closeout.stillBadNote || "",
    blocker_note: closeout.blockerNote || "",
    next_step_notes: closeout.nextStepNotes || "",
    photo_count: photoCount,
  };
}

function renderFieldCloseoutText(payload){
  if (!payload) return "";
  return [
    `Closeout checklist: ${JSON.stringify(payload)}`,
    `Closeout photos: ${payload.photo_count || 0}`,
    payload.no_photo_reason ? `No photo reason: ${payload.no_photo_reason}` : "",
    payload.still_bad_note ? `Still bad note: ${payload.still_bad_note}` : "",
    payload.blocker_note ? `Transfer blocker note: ${payload.blocker_note}` : "",
    payload.next_step_notes ? `Next step notes: ${payload.next_step_notes}` : "",
  ].filter(Boolean).join("\n");
}

async function saveFieldCloseoutChecklistRecord(payload){
  if (!payload || isDemo || !state.client || !state.user) return null;
  const row = {
    project_day_id: payload.project_day_id || null,
    location_visit_id: payload.location_visit_id || null,
    project_id: payload.project_id || null,
    user_id: payload.user_id || state.user.id,
    base_location_id: payload.base_location_id || null,
    visit_label: payload.visit_label || "",
    submitted_at: payload.timestamp || nowISO(),
    gps_lat: payload.gps_lat ?? null,
    gps_lng: payload.gps_lng ?? null,
    gps_accuracy_m: payload.gps_accuracy_m ?? null,
    checklist: payload,
  };
  try {
    let existingId = null;
    if (row.location_visit_id){
      const { data: existing, error: lookupError } = await state.client
        .from("splicer_location_closeout_checklists")
        .select("id")
        .eq("location_visit_id", row.location_visit_id)
        .order("submitted_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (lookupError && !isMissingTable(lookupError)){
        console.warn("[field closeout] existing checklist lookup failed", lookupError);
        return null;
      }
      existingId = existing?.id || null;
    }
    const query = existingId
      ? state.client.from("splicer_location_closeout_checklists").update(row).eq("id", existingId)
      : state.client.from("splicer_location_closeout_checklists").insert(row);
    const { data, error } = await query.select("id").maybeSingle();
    if (error){
      if (!isMissingTable(error)){
        console.warn("[field closeout] checklist save failed", error);
      }
      return null;
    }
    return data?.id || existingId || null;
  } catch (error) {
    console.warn("[field closeout] checklist save failed", error);
    return null;
  }
}

function parseFieldCloseoutFromNotes(notes){
  const text = String(notes || "");
  const match = text.match(/^Closeout checklist:\s*(\{.*\})$/m);
  if (!match) return null;
  try {
    return JSON.parse(match[1]);
  } catch {
    return null;
  }
}

function normalizeFieldWorkLogRow(row){
  if (!row || typeof row !== "object") return null;
  return {
    id: row.id || "",
    user_id: row.user_id || row.userId || "",
    project_id: row.project_id || row.projectId || "",
    site_id: row.site_id || row.siteId || "",
    work_date: row.work_date || row.workDate || "",
    arrived_at: row.arrived_at || row.arrivedAt || "",
    completed_at: row.completed_at || row.completedAt || row.created_at || "",
    gps_lat: row.gps_lat ?? row.gpsLat ?? null,
    gps_lng: row.gps_lng ?? row.gpsLng ?? null,
    gps_accuracy_m: row.gps_accuracy_m ?? row.gpsAccuracyM ?? null,
    nearest_distance_m: row.nearest_distance_m ?? row.nearestDistanceM ?? null,
    status_before: row.status_before || "",
    status_after: row.status_after || "",
    work_completed: row.work_completed || row.workCompleted || "",
    work_codes: Array.isArray(row.work_codes) ? row.work_codes : [],
    materials_used: Array.isArray(row.materials_used) ? row.materials_used : [],
  };
}

function getCachedFieldWorkLogs(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const cached = state.map.fieldWorkLogsBySiteId.get(key);
  return Array.isArray(cached) ? cached : [];
}

function hasCachedFieldWorkLogs(siteId){
  const key = toSiteIdKey(siteId);
  return Boolean(key) && state.map.fieldWorkLogsBySiteId.has(key);
}

function setCachedFieldWorkLogs(siteId, logs){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  const normalized = (Array.isArray(logs) ? logs : [])
    .map(normalizeFieldWorkLogRow)
    .filter(Boolean);
  state.map.fieldWorkLogsBySiteId.set(key, normalized);
  return normalized;
}

async function fetchFieldWorkLogsForSite(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return [];
  if (hasCachedFieldWorkLogs(key)) return getCachedFieldWorkLogs(key);
  if (isDemo || !state.client){
    return setCachedFieldWorkLogs(key, []);
  }
  const { data, error } = await state.client
    .from("field_work_logs")
    .select("id, user_id, project_id, site_id, work_date, arrived_at, completed_at, gps_lat, gps_lng, gps_accuracy_m, nearest_distance_m, status_before, status_after, work_completed, work_codes, materials_used, created_at")
    .eq("site_id", siteId)
    .order("completed_at", { ascending: false })
    .limit(8);
  if (error){
    if (!isMissingTable(error)){
      console.warn("[field work] log fetch failed", error);
    }
    return setCachedFieldWorkLogs(key, []);
  }
  return setCachedFieldWorkLogs(key, data || []);
}

async function hydrateMapFieldSiteActivity(siteId){
  const key = toSiteIdKey(siteId);
  if (!key) return;
  const needsCodes = !hasCachedSiteCodes(key);
  const needsPhotos = !hasCachedSitePhotos(key);
  const needsLogs = !hasCachedFieldWorkLogs(key);
  if (!needsCodes && !needsPhotos && !needsLogs) return;
  await Promise.all([
    needsCodes ? fetchSiteCodesForMapPopup(key) : Promise.resolve(getCachedSiteCodes(key)),
    needsPhotos ? fetchSitePhotosForMapPopup(key) : Promise.resolve(getCachedSitePhotos(key)),
    needsLogs ? fetchFieldWorkLogsForSite(key) : Promise.resolve(getCachedFieldWorkLogs(key)),
  ]);
  if (toSiteIdKey(getMapFieldSelectedSite()?.id || state.map.nearestSiteId) === key){
    renderMapFieldPanel();
  }
}

function renderMapFieldExistingWorkNotice(site, status){
  const codes = getCachedSiteCodes(site?.id);
  const photos = getCachedSitePhotos(site?.id);
  const logs = getCachedFieldWorkLogs(site?.id);
  const parts = [];
  if (status === MAP_FIELD_STATUS.COMPLETE) parts.push("marked complete");
  if (photos.length) parts.push(`${photos.length} photo${photos.length === 1 ? "" : "s"}`);
  if (codes.length) parts.push(`codes: ${codes.slice(0, 5).join(", ")}${codes.length > 5 ? "..." : ""}`);
  if (logs.length) parts.push(`${logs.length} work log${logs.length === 1 ? "" : "s"}`);
  if (!parts.length) return "";
  return `
    <div class="map-field-existing-work">
      Existing work found here: ${escapeHtml(parts.join(" | "))}. Use the log below for repair/correction work.
    </div>
  `;
}

function renderMapFieldWorkLogForm(site, status){
  if (!site?.id) return "";
  const existingNotice = renderMapFieldExistingWorkNotice(site, status);
  const lastLog = getCachedFieldWorkLogs(site.id)[0] || null;
  const photos = getCachedSitePhotos(site.id);
  const visitLabel = state.map.fieldVisitDraft?.siteId === toSiteIdKey(site.id) ? state.map.fieldVisitDraft.visitLabel : "";
  const previousPhotos = photos.filter((photo) => !isFieldVisitPhotoForLabel(photo, visitLabel));
  const lastLogText = lastLog
    ? `<div class="muted tiny">Last log: ${escapeHtml(formatDprDateTime(lastLog.completed_at))}${lastLog.work_completed ? ` - ${escapeHtml(lastLog.work_completed).slice(0, 160)}` : ""}</div>`
    : "";
  return `
    <section class="map-field-guide-card map-field-history-card">
      <div class="map-field-card-kicker">Previous Location History</div>
      <div class="map-field-work-title">Previous work history for ${escapeHtml(getSiteDisplayName(site))}</div>
      ${existingNotice}
      ${lastLogText}
      <div class="map-field-photo-counts">Previous photos: ${previousPhotos.length}</div>
      ${previousPhotos.length ? `
        <div class="map-field-history-photos">
          ${previousPhotos.slice(0, 4).map((photo) => `
            <a href="${escapeHtml(photo.url)}" target="_blank" rel="noopener">Photo ${escapeHtml(formatDprDateTime(photo.createdAt) || "")}</a>
          `).join("")}
        </div>
      ` : `<div class="muted tiny">No previous photos loaded for this saved location.</div>`}
    </section>
  `;
}

function getFieldGpsAssociationRadius(gps){
  const baseRadius = Math.max(Number(state.map.nearbyRadiusM || 30), 45);
  const accuracy = Number(gps?.accuracy_m ?? gps?.accuracy ?? 0);
  return Math.max(baseRadius, Number.isFinite(accuracy) && accuracy > 0 ? accuracy + 20 : baseRadius);
}

async function recordFieldLocationPingFromGps(gps, { nearest = null, source = "truck_gps" } = {}){
  if (bypassesFieldDayWorkflow()) return null;
  if (isDemo || isDemoUser() || !state.client || !state.user || !gps) return null;
  if (!getOpenFieldDaySession()) return null;
  const projectId = state.activeProject?.id || state.technician.timesheet?.project_id || null;
  if (!projectId) return null;
  const lat = Number(gps.lat);
  const lng = Number(gps.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  const resolvedNearest = nearest || findNearestVisibleSite({ lat, lng }, getFieldGpsAssociationRadius(gps));
  const siteId = resolvedNearest?.site?.id || null;
  const pingKey = `${projectId}|${siteId || "no-site"}`;
  const nowMs = Date.now();
  const lastMs = Number(state.map.fieldLastPingByKey.get(pingKey) || 0);
  if (nowMs - lastMs < 60000) return null;
  state.map.fieldLastPingByKey.set(pingKey, nowMs);
  const capturedAt = gps.captured_at || gps.updated_at || nowISO();
  const payload = {
    user_id: state.user.id,
    project_id: projectId,
    site_id: siteId,
    work_date: getSpecComDateKey(capturedAt),
    captured_at: capturedAt,
    gps_lat: lat,
    gps_lng: lng,
    gps_accuracy_m: gps.accuracy_m ?? gps.accuracy ?? null,
    nearest_distance_m: resolvedNearest?.distanceM ?? null,
    source,
  };
  const { data, error } = await state.client
    .from("field_location_pings")
    .insert(payload)
    .select("id")
    .maybeSingle();
  if (error){
    if (!isMissingTable(error)){
      console.warn("[field work] GPS ping save failed", error);
    }
    state.map.fieldLastPingByKey.delete(pingKey);
    return null;
  }
  return data?.id || null;
}

async function uploadMapFieldVisitPhotos(siteId, proofType = "visit_issue"){
  if (bypassesFieldDayWorkflow()) return;
  const site = getVisibleSiteByIdKey(siteId);
  if (!site){
    toast("Location missing", "Select a saved location before uploading photos.");
    return;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const active = state.fieldDay.activeEvent || null;
  if (!active || active.event_type !== FIELD_DAY_EVENT_TYPES.LOCATION_WORK || toSiteIdKey(active.site_id) !== toSiteIdKey(site.id)){
    toast("Start location first", "Start this location visit before adding visit photos.");
    return;
  }
  const draft = updateMapFieldVisitDraftFromInputs(site.id) || getMapFieldVisitDraft(site);
  const input = document.createElement("input");
  input.type = "file";
  input.accept = "image/*";
  input.multiple = true;
  input.capture = "environment";
  input.style.position = "fixed";
  input.style.left = "-9999px";
  document.body.appendChild(input);
  input.addEventListener("change", async () => {
    const files = Array.from(input.files || []);
    input.remove();
    if (!files.length) return;
    const capturedAt = nowISO();
    const siteCoords = getSiteCoords(site);
    const gps = state.map.myLocation
      || await requestMapCurrentLocation({ center: false, silent: true })
      || (siteCoords ? { lat: siteCoords.lat, lng: siteCoords.lng, accuracy_m: null } : null);
    let savedCount = 0;
    for (const file of files){
      const uploaded = await uploadSiteMediaForSite(file, site, gps, capturedAt, {
        source: getFieldVisitSource(draft.visitLabel),
        proofType,
        isLiveProof: true,
        backfilled: false,
        deviceUserAgent: navigator.userAgent || "",
        gpsLocked: Boolean(gps),
        capturedAtLocked: true,
      });
      if (uploaded) savedCount += 1;
    }
    state.map.sitePhotosBySiteId.delete(toSiteIdKey(site.id));
    await fetchSitePhotosForMapPopup(site.id);
    renderMapFieldPanel();
    if (savedCount){
      toast("Photos uploaded", `${savedCount} photo${savedCount === 1 ? "" : "s"} saved to ${draft.visitLabel}.`);
    }
  }, { once: true });
  input.click();
}

async function saveMapFieldWorkLog(siteId, { allowEmpty = false, startedAt = null, completedAt = null, silent = false, notesOverride = null, codesOverride = null, materialsOverride = null } = {}){
  if (bypassesFieldDayWorkflow()) return null;
  const site = getVisibleSiteByIdKey(siteId);
  if (!site){
    toast("Location missing", "This location is not available.", "error");
    return null;
  }
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return null;
  }
  if (!getOpenFieldDaySession()){
    toast("Start project day", "Start Recorded Project Day before saving field work.");
    return null;
  }
  const projectId = site.project_id || state.activeProject?.id || null;
  if (!projectId){
    toast("Project required", "Select a project before saving field work.");
    return null;
  }
  const notes = notesOverride !== null ? String(notesOverride || "").trim() : composeFieldVisitWorkNotes(site.id);
  const codes = Array.isArray(codesOverride) ? codesOverride : getMapFieldVisitCodes(site.id);
  const materials = Array.isArray(materialsOverride) ? materialsOverride : getMapFieldVisitMaterials(site.id);
  if (!allowEmpty && !notes && !codes.length && !materials.length){
    toast("Work log needed", "Add notes, codes, or material before saving.");
    return null;
  }
  const gps = state.map.myLocation || await requestMapCurrentLocation({ center: false, silent: Boolean(silent) });
  const nearest = gps ? findNearestVisibleSite(gps, getFieldGpsAssociationRadius(gps)) : null;
  const statusBefore = getSiteWorkflowStatus(site);
  const draft = state.map.fieldVisitDraft || {};
  const statusAfter = normalizeMapFieldStatus(
    $("mapFieldStatusSelect")?.value
    || (draft.finalStatus === "Fixed" || draft.finalStatus === "Audit Complete" ? MAP_FIELD_STATUS.COMPLETE : MAP_FIELD_STATUS.IN_PROGRESS)
    || statusBefore
  );
  const completed = completedAt || nowISO();
  const row = {
    user_id: state.user?.id || null,
    project_id: projectId,
    site_id: site.id,
    work_date: getSpecComDateKey(completed),
    arrived_at: startedAt || gps?.captured_at || completed,
    completed_at: completed,
    gps_lat: gps?.lat ?? null,
    gps_lng: gps?.lng ?? null,
    gps_accuracy_m: gps?.accuracy_m ?? gps?.accuracy ?? null,
    nearest_distance_m: nearest?.distanceM ?? state.map.nearestSiteDistanceM ?? null,
    status_before: statusBefore,
    status_after: statusAfter,
    work_completed: notes || null,
    work_codes: codes,
    materials_used: materials,
  };
  let savedRow = null;
  if (isDemo){
    const saved = { id: `demo-field-work-${Date.now()}`, ...row };
    setCachedFieldWorkLogs(site.id, [saved, ...getCachedFieldWorkLogs(site.id)]);
    savedRow = saved;
  } else {
    if (!state.client || !state.user){
      toast("Sign in required", "Sign in before saving field work.");
      return null;
    }
    let existingId = null;
    if (startedAt){
      const { data: existing, error: lookupError } = await state.client
        .from("field_work_logs")
        .select("id")
        .eq("user_id", state.user.id)
        .eq("site_id", site.id)
        .eq("arrived_at", startedAt)
        .order("completed_at", { ascending: false })
        .limit(1)
        .maybeSingle();
      if (lookupError && !isMissingTable(lookupError)){
        toast("Work log save failed", lookupError.message || "Could not verify the existing work log.", "error");
        return null;
      }
      existingId = existing?.id || null;
    }
    const query = existingId
      ? state.client.from("field_work_logs").update(row).eq("id", existingId)
      : state.client.from("field_work_logs").insert(row);
    const { data, error } = await query
      .select("id, user_id, project_id, site_id, work_date, arrived_at, completed_at, gps_lat, gps_lng, gps_accuracy_m, nearest_distance_m, status_before, status_after, work_completed, work_codes, materials_used, created_at")
      .maybeSingle();
    if (error){
      toast("Work log save failed", isMissingTable(error) ? "Database migration for field work logs has not been applied yet." : error.message, "error");
      return null;
    }
    setCachedFieldWorkLogs(site.id, [data, ...getCachedFieldWorkLogs(site.id).filter((row) => row.id !== data?.id)]);
    savedRow = data;
  }
  setSiteWorkflowStatus(site.id, statusAfter);
  const shouldResetDraft = Boolean(completedAt || allowEmpty);
  if (shouldResetDraft){
    $("mapFieldWorkCompleted") && ($("mapFieldWorkCompleted").value = "");
    $("mapFieldWorkCodes") && ($("mapFieldWorkCodes").value = "");
    $("mapFieldMaterialsUsed") && ($("mapFieldMaterialsUsed").value = "");
  }
  if (shouldResetDraft && state.map.fieldVisitDraft?.siteId === toSiteIdKey(site.id)){
    state.map.fieldVisitDraft = createFieldVisitDraft(site, {
      visitLabel: state.map.fieldVisitDraft.visitLabel,
      visitType: state.map.fieldVisitDraft.visitType,
    });
  }
  await recordFieldLocationPingFromGps(gps || {
    lat: row.gps_lat,
    lng: row.gps_lng,
    accuracy_m: row.gps_accuracy_m,
    captured_at: completed,
  }, { nearest, source: "work_log" });
  await autoSaveDailyProgressReport({
    projectId,
    reportDate: row.work_date,
    silent: true,
  });
  renderMapFieldPanel();
  if (!silent){
    toast("Work log saved", "Location, time, GPS, notes, codes, and material were saved.");
  }
  return savedRow || row;
}

function renderMapFieldPendingProofs(){
  const preview = $("mapFieldPhotoPreview");
  if (!preview) return;
  preview.replaceChildren();
  const pending = Array.isArray(state.map._pendingProofPhotos) ? state.map._pendingProofPhotos : [];
  pending.forEach((entry, index) => {
    const thumb = document.createElement("div");
    thumb.style.cssText = "width:68px;min-height:86px;border-radius:10px;overflow:hidden;position:relative;border:1px solid rgba(55,138,221,0.22);flex-shrink:0;background:rgba(255,255,255,0.03);display:flex;flex-direction:column;";
    const img = document.createElement("img");
    img.style.cssText = "width:100%;height:56px;object-fit:cover;";
    img.src = entry.previewUrl;
    thumb.appendChild(img);

    const meta = document.createElement("div");
    meta.style.cssText = "padding:6px;font-size:10px;line-height:1.3;color:rgba(255,255,255,0.78);";
    const gpsText = formatPhotoGpsMeta(entry.gps);
    meta.innerHTML = `<div style="font-weight:800;">VERIFIED LIVE</div><div>${escapeHtml(gpsText)}</div>`;
    thumb.appendChild(meta);

    const removeBtn = document.createElement("button");
    removeBtn.type = "button";
    removeBtn.style.cssText = "position:absolute;top:4px;right:4px;width:20px;height:20px;border-radius:50%;background:rgba(0,0,0,0.72);border:none;color:#fff;font-size:12px;cursor:pointer;display:flex;align-items:center;justify-content:center;line-height:1;";
    removeBtn.textContent = "\u00d7";
    removeBtn.addEventListener("click", () => {
      const rows = Array.isArray(state.map._pendingProofPhotos) ? state.map._pendingProofPhotos.slice() : [];
      rows.splice(index, 1);
      state.map._pendingProofPhotos = rows;
      renderMapFieldPendingProofs();
    });
    thumb.appendChild(removeBtn);
    preview.appendChild(thumb);
  });
}

async function handleMapFieldTakePhotoClick(){
  const input = $("mapFieldPhotoInput");
  if (!(input instanceof HTMLInputElement)) return false;
  const gps = state.map.myLocation || await requestMapCurrentLocation({ center: false, silent: false });
  if (!gps){
    toast("GPS required", "A GPS lock is required before taking a live proof photo.");
    return false;
  }
  state.map._pendingPhotoCapture = {
    gps: {
      lat: gps.lat,
      lng: gps.lng,
      accuracy_m: gps.accuracy_m ?? gps.accuracy ?? null,
    },
    captured_at: gps.captured_at || nowISO(),
    source: "camera",
    proof_type: "live_field_proof",
    device_user_agent: navigator.userAgent || "",
  };
  input.click();
  return true;
}

async function createFieldLocationFromCurrentGps(){
  const gps = state.map.myLocation || await requestMapCurrentLocation({ center: false, silent: false });
  if (!gps){
    return;
  }
  const name = String($("mapFieldLocationName")?.value || "").trim() || "";
  const locationType = String($("mapFieldLocationType")?.value || "Other").trim();
  const notes = String($("mapFieldLocationNotes")?.value || "").trim();
  const newSiteId = await createSiteFromMapClick(
    { lat: gps.lat, lng: gps.lng },
    name,
    {
      locationType,
      notes,
      openedFromFieldCapture: true,
      createdAt: gps.captured_at || nowISO(),
    }
  );
  const createdSiteId = toSiteIdKey(newSiteId || state.activeSite?.id);
  let createdSite = createdSiteId && toSiteIdKey(state.activeSite?.id) === createdSiteId
    ? state.activeSite
    : (state.projectSites || []).find((row) => toSiteIdKey(row.id) === createdSiteId) || null;
  if (!createdSite && createdSiteId && state.client){
    const siteRes = await fetchSiteById(createdSiteId);
    if (!siteRes.error && siteRes.data){
      createdSite = siteRes.data;
    }
  }
  if (createdSiteId){
    setSiteWorkflowStatus(createdSiteId, MAP_FIELD_STATUS.NOT_STARTED);
    setMapFieldSelectedSite(createdSiteId);
  }
  // Upload any queued photos to the newly created site
  const pendingPhotos = state.map._pendingProofPhotos || [];
  if (pendingPhotos.length > 0 && createdSite){
    const site = createdSite;
    let uploaded = 0;
    for (const pending of pendingPhotos){
      const result = await uploadSiteMediaForSite(
        pending.file,
        site,
        pending.gps,
        pending.captured_at,
        {
          source: "camera",
          proofType: pending.proof_type || "live_field_proof",
          isLiveProof: true,
          backfilled: false,
          deviceUserAgent: pending.device_user_agent || navigator.userAgent || "",
        }
      );
      if (!result){
        logPhotoFlowError("map field proof upload failed", new Error("site media insert returned null"), {
          siteId: site.id,
          fileName: pending.file?.name || "",
        });
      }
      if (result) uploaded++;
    }
    if (uploaded > 0){
      toast("Photos uploaded", `${uploaded} photo${uploaded > 1 ? "s" : ""} attached to ${name || "location"}.`);
    }
  }
  state.map._pendingProofPhotos = [];
  state.map._pendingPhotoCapture = null;
  const preview = $("mapFieldPhotoPreview");
  if (preview) preview.innerHTML = "";
  const capturedAt = gps.captured_at || nowISO();

  const billingInput = $("mapFieldBillingCodes");
  const billingRows = parseMapFieldBillingCodeLines(billingInput?.value || "");
  if (createdSite && billingRows.length){
    const rows = billingRows.map((row) => ({
      site_id: createdSite.id,
      project_id: createdSite.project_id || state.activeProject?.id || null,
      billing_code: row.billing_code,
      quantity: row.quantity,
      created_by: state.user?.id || null,
      created_at: capturedAt,
    }));
    let billingSaved = false;
    let billingInsertError = null;
    if (state.client && !createdSite.is_pending){
      const { error } = await state.client.from("site_billing_codes").insert(rows);
      if (!error){
        billingSaved = true;
        toast("Billing saved", `${billingRows.length} billing code${billingRows.length === 1 ? "" : "s"} saved.`, "success");
      } else {
        billingInsertError = error;
      }
    }
    if (!billingSaved){
      const appended = await appendMapFieldBillingCodesToSiteNotes(createdSite, billingRows);
      if (appended){
        toast("Billing saved", "Billing codes were added to site notes.", "success");
      } else {
        toast("Billing save error", billingInsertError?.message || "Could not save billing codes for this location.", "error");
      }
    }
  }
  setMapFieldCreateOpen(false);
  if ($("mapFieldLocationName")) $("mapFieldLocationName").value = "";
  if ($("mapFieldLocationType")) $("mapFieldLocationType").value = "Node";
  if ($("mapFieldLocationNotes")) $("mapFieldLocationNotes").value = "";
  if (billingInput) billingInput.value = "";
  renderMapFieldPanel();
  if (createdSiteId){
    await openLocationForField(createdSiteId, { center: true, forAdd: true });
  }
}

function getSiteSearchResultSet(){
  const all = getVisibleSites();
  const rawQuery = String(state.mapFilters.search || "").trim();
  if (!rawQuery){
    return {
      rawQuery,
      normalizedQuery: "",
      coordQuery: null,
      rows: all,
      nearest: [],
    };
  }
  const coordQuery = parseLocationCoordinateQuery(rawQuery);
  if (coordQuery){
    const nearest = getNearestSitesToCoordinate(all, coordQuery, 5);
    return {
      rawQuery,
      normalizedQuery: "",
      coordQuery,
      rows: nearest.map((x) => x.site),
      nearest,
    };
  }
  const normalizedQuery = normalizeLocationSearchText(rawQuery);
  const rows = all.filter((site) => getSiteSearchBlob(site).includes(normalizedQuery));
  return {
    rawQuery,
    normalizedQuery,
    coordQuery: null,
    rows,
    nearest: [],
  };
}

function highlightLocationMatch(text, query){
  const value = String(text || "");
  const q = String(query || "").trim();
  if (!value || !q || parseLocationCoordinateQuery(q)) return escapeHtml(value);
  const lower = value.toLowerCase();
  const qLower = q.toLowerCase();
  const idx = lower.indexOf(qLower);
  if (idx < 0) return escapeHtml(value);
  const start = escapeHtml(value.slice(0, idx));
  const hit = escapeHtml(value.slice(idx, idx + q.length));
  const end = escapeHtml(value.slice(idx + q.length));
  return `${start}<mark>${hit}</mark>${end}`;
}

function setSiteSearchBanner(message = ""){
  const banner = $("siteSearchBanner");
  if (!banner) return;
  banner.textContent = message || "";
  banner.style.display = message ? "" : "none";
}

function updateSiteSearchUiSummary(resultSet){
  dlog("[search] location search results", {
    query: resultSet.rawQuery || null,
    resultCount: (resultSet.rows || []).length,
    totalVisible: getVisibleSites().length,
    projectId: state.activeProject?.id || null,
    contextType: state.activeProject ? "project" : "company",
  });
  const clearBtn = $("btnClearMapSearch");
  if (clearBtn){
    clearBtn.style.display = resultSet.rawQuery ? "" : "none";
  }
  const meta = $("siteSearchMeta");
  if (!meta) return;
  if (!state.activeProject){
    meta.textContent = "";
    return;
  }
  const total = getVisibleSites().length;
  if (!resultSet.rawQuery){
    meta.textContent = `${total} site${total === 1 ? "" : "s"}`;
    return;
  }
  meta.textContent = `${resultSet.rows.length} match${resultSet.rows.length === 1 ? "" : "es"}`;
}

function syncMapToSearchResults(resultSet){
  if (!state.map.instance || !window.L) return;
  const rows = resultSet.rows || [];
  if (resultSet.coordQuery){
    const key = `${resultSet.coordQuery.lat.toFixed(6)},${resultSet.coordQuery.lng.toFixed(6)}`;
    if (state.map.searchJumpKey !== key){
      state.map.searchJumpKey = key;
      state.map.instance.setView([resultSet.coordQuery.lat, resultSet.coordQuery.lng], 18);
    }
    hideMapFloatPanelForMapAction();
    if (resultSet.nearest[0]){
      const nearest = resultSet.nearest[0];
      const siteName = getSiteDisplayName(nearest.site);
      const meters = Math.round(nearest.distanceM);
      setSiteSearchBanner(`Jumped to coordinate - nearest site: ${siteName} (${meters}m)`);
      setActiveSite(nearest.site.id, { openOverview: false }).then(() => focusSiteOnMap(nearest.site.id));
    } else {
      setSiteSearchBanner("Jumped to coordinate - no nearby site found.");
    }
    return;
  }
  state.map.searchJumpKey = "";
  setSiteSearchBanner("");
  if (!rows.length) return;
  const bounds = [];
  rows.forEach((site) => {
    const coords = getSiteCoords(site);
    if (coords) bounds.push([coords.lat, coords.lng]);
  });
  if (!bounds.length) return;
  if (bounds.length === 1){
    state.map.instance.setView(bounds[0], Math.max(state.map.instance.getZoom() || 0, 17));
    hideMapFloatPanelForMapAction();
    setActiveSite(rows[0].id, { openOverview: false }).then(() => focusSiteOnMap(rows[0].id));
    return;
  }
  state.map.instance.fitBounds(window.L.latLngBounds(bounds), { padding: [24, 24], maxZoom: 16 });
  hideMapFloatPanelForMapAction();
}

async function loadProjectFieldPhotos(projectId){
  if (isDemo || !state.client || !projectId){
    if (!projectId || isProjectContextCurrent(projectId, state.activeProject?.id)) state.map.fieldPhotos = [];
    return;
  }
  const { data, error } = await state.client
    .from("field_photos")
    .select("id, project_id, file_name, image_url, latitude, longitude, created_at")
    .eq("project_id", projectId)
    .order("created_at", { ascending: false });
  if (error){
    console.error("field_photos load error:", error);
    if (isProjectContextCurrent(projectId, state.activeProject?.id)) state.map.fieldPhotos = [];
    return;
  }
  if (!isProjectContextCurrent(projectId, state.activeProject?.id)) return;
  state.map.fieldPhotos = Array.isArray(data) ? data : [];
}

async function loadProjectSites(projectId){
  if (isDemo){
    state.projectSites = (state.demo.sites || []).filter(s => !projectId || s.project_id === projectId);
    state.pendingSites = loadPendingSitesFromStorage();
    state.map.siteSearchIndex.clear();
    state.map.siteCodesBySiteId.clear();
    state.map.sitePhotosBySiteId.clear();
    state.map.fieldWorkLogsBySiteId.clear();
    state.map.fieldPhotos = [];
    renderSiteList();
    return;
  }
  if (!projectId){
    state.projectSites = [];
    state.pendingSites = loadPendingSitesFromStorage();
    state.map.siteSearchIndex.clear();
    state.map.siteCodesBySiteId.clear();
    state.map.sitePhotosBySiteId.clear();
    state.map.fieldWorkLogsBySiteId.clear();
    state.map.fieldPhotos = [];
    renderSiteList();
    return;
  }
  const { data, error } = await fetchSitesByProject(projectId);
  if (!isProjectContextCurrent(projectId, state.activeProject?.id)) return;
  if (error){
    toast("Sites load error", error.message);
    return;
  }
  state.projectSites = data || [];
  state.pendingSites = loadPendingSitesFromStorage();
  state.map.siteSearchIndex.clear();
  state.map.siteCodesBySiteId.clear();
  state.map.sitePhotosBySiteId.clear();
  state.map.fieldWorkLogsBySiteId.clear();
  await loadProjectFieldPhotos(projectId);
  if (!isProjectContextCurrent(projectId, state.activeProject?.id)) return;
  dlog("[data] loadProjectSites complete", {
    projectId,
    siteCount: state.projectSites.length,
    photoCount: (state.map.fieldPhotos || []).length,
    pendingCount: (state.pendingSites || []).length,
  });
  primeSitePopupCachesFromRuidosoEvidence(state.projectSites);
  const visibleIds = new Set(getVisibleSites().map((site) => toSiteIdKey(site?.id)));
  if (state.activeSite && !visibleIds.has(toSiteIdKey(state.activeSite.id))){
    closeSitePanel();
  }
  renderSiteList();
  if (state.map.instance){
    const resultSet = getSiteSearchResultSet();
    updateMapMarkers(resultSet.rows);
    renderDerivedMapLayers(resultSet.rows);
    if (state.node54Diagnostics.enabled) renderNode54MapOverlay();
    if (state.rootCommandCenter.xrayEnabled) renderRootXrayLayer();
    // Do NOT call syncMapToSearchResults here — that runs fitBounds across all
    // project sites and zooms the map way out on every background refresh.
    // syncMapToSearchResults is for explicit user searches only.
  }
  if (isEffectiveRootRole()) void loadRootCommandCenterData({ silent: true, force: true });
}

function getNextSiteName(){
  const sites = getVisibleSites();
  const numbers = sites
    .map((site) => {
      const match = String(site.name || "").match(/site\s+(\d+)/i);
      return match ? Number(match[1]) : null;
    })
    .filter((val) => Number.isFinite(val));
  const next = numbers.length ? Math.max(...numbers) + 1 : 1;
  if (!Number.isFinite(next)) return `Site ${new Date().toISOString().slice(0, 16).replace("T", " ")}`;
  return `Site ${next}`;
}

function renderSiteList(){
  const wrap = $("siteList");
  if (!wrap) return;
  const resultSet = getSiteSearchResultSet();
  updateSiteSearchUiSummary(resultSet);
  if (!state.activeProject){
    wrap.innerHTML = `<div class="muted small">${t("mapStatusNoProject")}</div>`;
    return;
  }
  const rows = resultSet.rows;
  if (!rows.length){
    wrap.innerHTML = `<div class="muted small">${resultSet.rawQuery ? "No matching sites." : t("mapStatusNoSites")}</div>`;
    return;
  }
  const rawSearch = String(state.mapFilters.search || "").trim();
  wrap.innerHTML = rows.map((site) => {
    const isActive = toSiteIdKey(state.activeSite?.id) === toSiteIdKey(site?.id);
    const status = site.is_pending ? ` <span class="muted small">(${t("siteStatusPending")})</span>` : "";
    const label = getSiteDisplayName(site);
    return `
      <button class="site-row${isActive ? " is-selected" : ""}" data-site-id="${site.id}">
        <span>${highlightLocationMatch(label, rawSearch)}${status}</span>
      </button>
    `;
  }).join("");
}

function scheduleLocationSearchRefresh({ syncMap = true } = {}){
  if (state.map.searchDebounceId){
    clearTimeout(state.map.searchDebounceId);
  }
  state.map.searchDebounceId = setTimeout(async () => {
    state.map.searchDebounceId = null;
    renderSiteList();
    const resultSet = getSiteSearchResultSet();
    if (state.map.instance){
      updateMapMarkers(resultSet.rows);
      renderDerivedMapLayers(resultSet.rows);
      if (syncMap){
        syncMapToSearchResults(resultSet);
      }
    }
  }, 300);
}

function clearLocationSearch(){
  state.mapFilters.search = "";
  const input = $("mapSearch");
  if (input) input.value = "";
  setSiteSearchBanner("");
  state.map.searchJumpKey = "";
  renderSiteList();
  if (state.map.instance){
    updateMapMarkers(getVisibleSites());
    renderDerivedMapLayers(getVisibleSites());
  }
}

function focusFirstSearchResult(){
  const resultSet = getSiteSearchResultSet();
  if (!resultSet.rows.length) return;
  const first = resultSet.rows[0];
  setActiveSite(first.id, { openOverview: false }).then(() => {
    focusSiteOnMap(first.id);
    hideMapFloatPanelForMapAction();
  });
}

async function setActiveSite(siteId, { openOverview = false, autoDrawerTab = true } = {}){
  const siteKey = toSiteIdKey(siteId);
  const site = getVisibleSites().find((row) => toSiteIdKey(row?.id) === siteKey) || null;
  state.activeSite = site;
  state.map.fieldSelectedSiteId = site ? siteKey : "";
  if (site){
    if (autoDrawerTab){
      switchSidebarTab("site");
    }
    const feature = buildSiteFeature(site);
    const coords = getSiteCoords(site);
    if (coords){
      const set = getFeatureSetByPoint(coords.lat, coords.lng);
      state.map.selectedSet = set.length ? set : [feature];
      state.map.selectedIndex = Math.max(0, state.map.selectedSet.findIndex((f) => toSiteIdKey(f?.properties?.id) === siteKey));
      if (state.map.selectedIndex < 0) state.map.selectedIndex = 0;
      state.map.selectedFeature = state.map.selectedSet[state.map.selectedIndex] || feature;
      drawFeatureHighlight(state.map.selectedFeature);
    } else {
      state.map.selectedSet = [feature];
      state.map.selectedIndex = 0;
      state.map.selectedFeature = feature;
      drawFeatureHighlight(feature);
    }
  } else {
    closeFeatureDrawer();
  }
  state.siteMedia = [];
  state.siteCodes = [];
  state.siteEntries = [];
  renderSiteList();
  renderSitePanel();
  renderFeatureDrawer();
  renderMapFieldPanel();
  if (openOverview){
    SpecCom.helpers.openPinOverview();
    SpecCom.helpers.renderPinOverview();
  } else if (typeof SpecCom.helpers.closePinOverview === "function"){
    SpecCom.helpers.closePinOverview();
  }
  if (!site || site.is_pending) return;
  await Promise.all([
    loadSiteMedia(site.id),
    loadSiteCodes(site.id),
    loadSiteEntries(site.id),
  ]);
  renderSitePanel();
  renderFeatureDrawer();
  if (openOverview){
    SpecCom.helpers.renderPinOverview();
  } else if (typeof SpecCom.helpers.closePinOverview === "function"){
    SpecCom.helpers.closePinOverview();
  }
}

function closeSitePanel(){
  state.activeSite = null;
  state.map.fieldSelectedSiteId = "";
  state.siteMedia = [];
  state.siteCodes = [];
  state.siteEntries = [];
  SpecCom.helpers.closePinOverview();
  renderSiteList();
  renderSitePanel();
  renderFeatureDrawer();
  renderMapFieldPanel();
}

SpecCom.helpers.ensurePinOverviewModal = function(){
  let modal = document.getElementById("pinOverviewModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "pinOverviewModal";
  modal.className = "modal pin-overview-modal";
  modal.style.display = "none";
  modal.innerHTML = `
    <div class="card modal-card pin-overview-card">
      <div class="pin-overview-top">
        <div class="pin-overview-title">Task Overview</div>
      </div>
      <div class="pin-overview-head">
        <div>
          <div id="pinOverviewTaskNumber" class="pin-overview-task-number">-</div>
          <div id="pinOverviewTaskRef" class="pin-overview-task-ref muted small">Task @ -</div>
        </div>
        <div id="pinOverviewStatus" class="pin-overview-status">PENDING</div>
      </div>
      <div class="pin-overview-meta">
        <div>
          <div class="muted tiny">DATE CREATED</div>
          <div id="pinOverviewDateCreated">-</div>
        </div>
        <div>
          <div class="muted tiny">LAST UPDATED</div>
          <div id="pinOverviewDateUpdated">-</div>
        </div>
      </div>
      <div class="pin-overview-section">
        <div class="muted tiny">WORK TYPE</div>
        <div id="pinOverviewWorkType" class="pin-overview-work-list"></div>
      </div>
      <div class="pin-overview-section">
        <div class="muted tiny">GPS COORDINATES</div>
        <div id="pinOverviewGps" class="pin-overview-inline-value">-</div>
      </div>
      <div class="pin-overview-section">
        <div class="muted tiny">PROGRESS REPORT NOTES</div>
        <div id="pinOverviewNotes" class="pin-overview-notes">-</div>
      </div>
      <div id="pinOverviewManualEditor" class="pin-overview-manual-editor" style="display:none;">
        <div class="muted tiny">MANUAL ENTRY (AUTHORIZED ONLY)</div>
        <div class="row" style="margin-top:8px;">
          <input id="pinOverviewGpsLatInput" class="input compact" type="number" step="any" placeholder="GPS Lat" />
          <input id="pinOverviewGpsLngInput" class="input compact" type="number" step="any" placeholder="GPS Lng" />
        </div>
        <textarea id="pinOverviewNotesInput" class="input" rows="3" placeholder="Progress report notes"></textarea>
        <div class="row" style="justify-content:flex-end; margin-top:8px;">
          <button id="btnPinOverviewSaveManual" class="btn secondary" type="button">Save details</button>
        </div>
      </div>
      <div id="pinOverviewPhotos" class="pin-overview-photo-grid"></div>
      <div class="row" style="justify-content:center; gap:8px; flex-wrap:wrap;">
        <button id="btnPinOverviewNoAccess" class="btn secondary" type="button">Report No Access</button>
        <button id="btnPinOverviewClose" class="btn ghost" type="button">Close Overview</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  const closeBtn = modal.querySelector("#btnPinOverviewClose");
  if (closeBtn){
    closeBtn.addEventListener("click", () => SpecCom.helpers.closePinOverview());
  }
  const saveManualBtn = modal.querySelector("#btnPinOverviewSaveManual");
  if (saveManualBtn){
    saveManualBtn.addEventListener("click", async () => {
      await SpecCom.helpers.savePinOverviewManualDetails();
    });
  }
  const noAccessBtn = modal.querySelector("#btnPinOverviewNoAccess");
  if (noAccessBtn){
    noAccessBtn.addEventListener("click", async () => {
      await SpecCom.helpers.reportNoAccessFromPinOverview();
    });
  }
  modal.addEventListener("click", (e) => {
    if (e.target === modal) SpecCom.helpers.closePinOverview();
  });
  if (!SpecCom.helpers._pinOverviewKeyListener){
    SpecCom.helpers._pinOverviewKeyListener = true;
    document.addEventListener("keydown", (e) => {
      if (!state.pinOverview.open) return;
      if (e.key === "Escape") SpecCom.helpers.closePinOverview();
    });
  }
  return modal;
};

SpecCom.helpers.openPinOverview = function(){
  const modal = SpecCom.helpers.ensurePinOverviewModal();
  modal.style.display = "";
  state.pinOverview.open = true;
};

SpecCom.helpers.closePinOverview = function(){
  const modal = document.getElementById("pinOverviewModal");
  if (modal) modal.style.display = "none";
  state.pinOverview.open = false;
};

SpecCom.helpers.renderPinOverview = function(){
  const modal = SpecCom.helpers.ensurePinOverviewModal();
  const taskNumber = modal.querySelector("#pinOverviewTaskNumber");
  const taskRef = modal.querySelector("#pinOverviewTaskRef");
  const statusEl = modal.querySelector("#pinOverviewStatus");
  const dateCreatedEl = modal.querySelector("#pinOverviewDateCreated");
  const dateUpdatedEl = modal.querySelector("#pinOverviewDateUpdated");
  const workTypeEl = modal.querySelector("#pinOverviewWorkType");
  const gpsEl = modal.querySelector("#pinOverviewGps");
  const notesEl = modal.querySelector("#pinOverviewNotes");
  const manualEditor = modal.querySelector("#pinOverviewManualEditor");
  const manualLatInput = modal.querySelector("#pinOverviewGpsLatInput");
  const manualLngInput = modal.querySelector("#pinOverviewGpsLngInput");
  const manualNotesInput = modal.querySelector("#pinOverviewNotesInput");
  const saveManualBtn = modal.querySelector("#btnPinOverviewSaveManual");
  const noAccessBtn = modal.querySelector("#btnPinOverviewNoAccess");
  const photosEl = modal.querySelector("#pinOverviewPhotos");
  const canManualProofEdit = SpecCom.helpers.isRoot() || isOwner();
  const site = state.activeSite || null;
  if (manualEditor){
    manualEditor.style.display = canManualProofEdit ? "" : "none";
  }
  if (!site){
    if (taskNumber) taskNumber.textContent = "-";
    if (taskRef) taskRef.textContent = "Task @ -";
    if (statusEl){
      statusEl.textContent = "PENDING";
      statusEl.classList.remove("is-complete");
    }
    if (dateCreatedEl) dateCreatedEl.textContent = "-";
    if (dateUpdatedEl) dateUpdatedEl.textContent = "-";
    if (workTypeEl) workTypeEl.innerHTML = `<div class="muted small">-</div>`;
    if (gpsEl) gpsEl.textContent = "-";
    if (notesEl) notesEl.textContent = "-";
    if (manualLatInput) manualLatInput.value = "";
    if (manualLngInput) manualLngInput.value = "";
    if (manualNotesInput) manualNotesInput.value = "";
    if (saveManualBtn) saveManualBtn.disabled = true;
    if (noAccessBtn) noAccessBtn.disabled = true;
    if (photosEl) photosEl.innerHTML = "";
    return;
  }

  const idLabel = String(site.id || "").slice(0, 4).toUpperCase();
  const nameLabel = String(getSiteDisplayName(site) || "").trim();
  const numericMatch = nameLabel.match(/\d+/);
  const primaryTask = numericMatch ? numericMatch[0] : (idLabel || "0000");
  if (taskNumber) taskNumber.textContent = primaryTask;
  if (taskRef) taskRef.textContent = `Task @ ${idLabel || primaryTask}`;

  const isComplete = SpecCom.helpers.getSiteCompletionState(site) && !site.is_pending;
  if (statusEl){
    statusEl.textContent = isComplete ? "COMPLETED" : "PENDING";
    statusEl.classList.toggle("is-complete", isComplete);
  }

  const createdAt = site.created_at ? new Date(site.created_at) : null;
  const updatedAt = site.updated_at ? new Date(site.updated_at) : createdAt;
  if (dateCreatedEl){
    dateCreatedEl.textContent = createdAt && Number.isFinite(createdAt.getTime())
      ? createdAt.toLocaleDateString()
      : "-";
  }
  if (dateUpdatedEl){
    dateUpdatedEl.textContent = updatedAt && Number.isFinite(updatedAt.getTime())
      ? updatedAt.toLocaleDateString()
      : "-";
  }

  if (workTypeEl){
    const fromEntries = (state.siteEntries || []).map((row) => ({
      label: String(row.description || "").trim(),
      qty: Number.isFinite(Number(row.quantity)) ? Number(row.quantity) : 1,
    })).filter((row) => row.label);
    const fromCodes = (state.siteCodes || []).map((row) => ({
      label: String(row.code || "").trim(),
      qty: 1,
    })).filter((row) => row.label);
    const items = fromEntries.length ? fromEntries : fromCodes;
    if (!items.length){
      workTypeEl.innerHTML = `<div class="muted small">-</div>`;
    } else {
      workTypeEl.innerHTML = items.map((row) => (
        `<div class="pin-overview-work-item"><span>${escapeHtml(row.label)}</span><span>x${escapeHtml(row.qty)}</span></div>`
      )).join("");
    }
  }

  if (gpsEl){
    const coords = getSiteCoords(site);
    gpsEl.textContent = coords ? `${coords.lat.toFixed(6)}, ${coords.lng.toFixed(6)}` : "-";
  }

  if (notesEl){
    const notes = String(site.notes || "").trim();
    notesEl.textContent = notes || "-";
  }
  if (manualLatInput || manualLngInput){
    const coords = getSiteCoords(site);
    if (manualLatInput){
      manualLatInput.value = coords ? String(coords.lat) : "";
      manualLatInput.disabled = !canManualProofEdit || site.is_pending;
    }
    if (manualLngInput){
      manualLngInput.value = coords ? String(coords.lng) : "";
      manualLngInput.disabled = !canManualProofEdit || site.is_pending;
    }
  }
  if (manualNotesInput){
    manualNotesInput.value = String(site.notes || "");
    manualNotesInput.disabled = !canManualProofEdit || site.is_pending;
  }
  if (saveManualBtn){
    saveManualBtn.disabled = !canManualProofEdit || site.is_pending;
  }
  if (noAccessBtn){
    noAccessBtn.disabled = site.is_pending || !state.activeProject?.id;
  }

  if (photosEl){
    const items = state.siteMedia || [];
    if (!items.length){
      photosEl.innerHTML = `<div class="muted small">No photos yet.</div>`;
    } else {
      photosEl.innerHTML = items.map((item, idx) => (
        `<button class="pin-overview-photo-card" type="button" data-action="openOverviewMedia" data-index="${idx}">
          ${item.previewUrl ? `<img src="${item.previewUrl}" alt="task photo ${idx + 1}" />` : ""}
        </button>`
      )).join("");
    }
    if (!photosEl.dataset.bound){
      photosEl.dataset.bound = "1";
      photosEl.addEventListener("click", (e) => {
        const btn = e.target.closest("[data-action='openOverviewMedia']");
        if (!btn) return;
        const idx = Number(btn.dataset.index);
        if (!Number.isFinite(idx)) return;
        SpecCom.helpers.openMediaViewer(idx);
      });
    }
  }
};

SpecCom.helpers.savePinOverviewManualDetails = async function(){
  const site = state.activeSite;
  if (!site || site.is_pending) return;
  if (!(SpecCom.helpers.isRoot() || isOwner())){
    toast("Permission denied", "Only authorized team members can manually edit GPS and progress notes.", "error");
    return;
  }
  const latRaw = String($("pinOverviewGpsLatInput")?.value || "").trim();
  const lngRaw = String($("pinOverviewGpsLngInput")?.value || "").trim();
  const notes = String($("pinOverviewNotesInput")?.value || "").trim();
  const hasLat = latRaw !== "";
  const hasLng = lngRaw !== "";
  if (hasLat !== hasLng){
    toast("GPS invalid", "Enter both latitude and longitude, or leave both empty.", "error");
    return;
  }
  const hasGps = hasLat && hasLng;
  const latNum = hasGps ? Number(latRaw) : null;
  const lngNum = hasGps ? Number(lngRaw) : null;
  if (hasGps && (!Number.isFinite(latNum) || !Number.isFinite(lngNum))){
    toast("GPS invalid", "Enter valid numeric latitude/longitude.", "error");
    return;
  }

  if (isDemo){
    state.demo.sites = (state.demo.sites || []).map((row) => {
      if (row.id !== site.id) return row;
      const next = { ...row, notes };
      if (hasGps){
        next.gps_lat = latNum;
        next.gps_lng = lngNum;
      }
      return next;
    });
    state.projectSites = (state.projectSites || []).map((row) => {
      if (row.id !== site.id) return row;
      const next = { ...row, notes };
      if (hasGps){
        next.gps_lat = latNum;
        next.gps_lng = lngNum;
      }
      return next;
    });
    state.activeSite = (state.projectSites || []).find((row) => row.id === site.id) || state.activeSite;
    updateMapMarkers(getVisibleSites());
    renderSitePanel();
    toast("Saved", "Manual details updated.");
    return;
  }

  if (!state.client){
    toast("Update failed", "Client not ready.", "error");
    return;
  }

  const payload = { notes };
  if (hasGps){
    payload.gps_lat = latNum;
    payload.gps_lng = lngNum;
  }

  let res = await state.client
    .from("sites")
    .update(payload)
    .eq("id", site.id)
    .select("id")
    .single();
  if (res.error && hasGps && isMissingGpsColumnError(res.error)){
    const legacyPayload = { ...payload, lat: latNum, lng: lngNum };
    delete legacyPayload.gps_lat;
    delete legacyPayload.gps_lng;
    res = await state.client
      .from("sites")
      .update(legacyPayload)
      .eq("id", site.id)
      .select("id")
      .single();
  }
  if (res.error){
    toast("Update failed", res.error.message, "error");
    return;
  }

  const siteRes = await fetchSiteById(site.id);
  if (siteRes.error){
    toast("Refresh failed", siteRes.error.message, "error");
    return;
  }
  if (siteRes.data){
    state.projectSites = (state.projectSites || []).filter((row) => row.id !== siteRes.data.id).concat(siteRes.data);
    state.activeSite = siteRes.data;
  }
  if (hasGps){
    updateMapMarkers(getVisibleSites());
  }
  renderSitePanel();
  toast("Saved", "Manual details updated.");
};

function renderSitePanel(){
  const subtitle = $("sitePanelSubtitle");
  const mediaGallery = $("siteMediaGallery");
  const codesList = $("siteCodesList");
  const entriesList = $("siteEntriesList");
  const notesInput = $("siteNotesInput");
  const codesInput = $("siteCodesInput");
  const entryDesc = $("siteEntryDescription");
  const entryQty = $("siteEntryQuantity");
  const siteNameInput = $("siteNameInput");
  const saveNameBtn = $("btnSaveSiteName");
  const mediaInput = $("siteMediaInput");
  const saveCodesBtn = $("btnSaveCodes");
  const addEntryBtn = $("btnAddEntry");
  const saveNotesBtn = $("btnSaveNotes");
  const editLocationBtn = $("btnEditSiteLocation");
  const isRoot = SpecCom.helpers.isRoot();
  const canManualProofEdit = isRoot || isOwner();

  const site = state.activeSite;
  const isPending = Boolean(site?.is_pending);
  const disabled = !site || isPending;
  const renderSiteMediaBadges = (item) => {
    const chips = [];
    if (item?.source === "ruidoso_archive"){
      chips.push("RUIDOSO ARCHIVE");
    } else if (item?.is_live_proof){
      chips.push("VERIFIED LIVE");
    } else if (item?.backfilled || item?.source === "backfill_upload"){
      chips.push("BACKFILL UPLOAD");
    } else {
      chips.push("REFERENCE UPLOAD");
    }
    if (item?.gpsLat != null && item?.gpsLng != null){
      chips.push("GPS LOCKED");
    }
    if (item?.created_at){
      chips.push("CAPTURE TIME LOCKED");
    }
    return chips.length
      ? `<div class="row" style="gap:6px; flex-wrap:wrap; margin-top:6px;">${chips.map((chip) => `<span class="chip">${escapeHtml(chip)}</span>`).join("")}</div>`
      : "";
  };
  if (subtitle){
    if (!site){
      subtitle.textContent = t("noSiteSelected");
    } else {
      const when = site.created_at ? new Date(site.created_at).toLocaleString() : "-";
      const pendingLabel = site.is_pending ? ` • ${t("siteStatusPending")}` : "";
      subtitle.textContent = `${getSiteDisplayName(site)} • ${when}${pendingLabel}`;
    }
  }

  if (mediaInput) mediaInput.disabled = disabled;
  if (codesInput) codesInput.disabled = disabled;
  if (entryDesc) entryDesc.disabled = disabled;
  if (entryQty) entryQty.disabled = disabled;
  if (notesInput) notesInput.disabled = disabled || !canManualProofEdit;
  if (siteNameInput) siteNameInput.disabled = disabled;
  if (saveNameBtn) saveNameBtn.disabled = disabled;
  if (saveCodesBtn) saveCodesBtn.disabled = disabled;
  if (addEntryBtn) addEntryBtn.disabled = disabled;
  if (saveNotesBtn) saveNotesBtn.disabled = disabled || !canManualProofEdit;
  if (editLocationBtn) editLocationBtn.disabled = disabled || !canManualProofEdit;

  const nameRow = siteNameInput?.closest(".row");
  if (nameRow && !document.getElementById("btnDeleteSite")){
    const btn = document.createElement("button");
    btn.id = "btnDeleteSite";
    btn.type = "button";
    btn.className = "btn danger";
    btn.textContent = "Delete site";
    nameRow.appendChild(btn);
  }
  const deleteSiteBtn = $("btnDeleteSite");
  if (deleteSiteBtn){
    deleteSiteBtn.style.display = (isRoot && site && !isPending) ? "" : "none";
    deleteSiteBtn.disabled = disabled;
    deleteSiteBtn.onclick = async () => {
      await SpecCom.helpers.deleteSiteFromPanel();
    };
  }

  if (codesInput) codesInput.value = (state.siteCodes || []).map((row) => row.code).join(", ");
  if (notesInput) notesInput.value = site?.notes || "";
  if (siteNameInput) siteNameInput.value = site?.name || "";
  if (editLocationBtn){
    editLocationBtn.style.display = canManualProofEdit ? "" : "none";
    editLocationBtn.onclick = () => {
      if (!site || isPending) return;
      if (!canManualProofEdit){
        toast("Permission denied", "Only authorized team members can manually edit GPS and progress notes.", "error");
        return;
      }
      ensureMap();
      state.map.dropPinMode = true;
      state.map.pinTargetSiteId = site.id;
      toast("Move pin", "Click on the map to update this pin.");
    };
  }

  if (mediaGallery){
    if (!mediaGallery.dataset.viewerBound){
      mediaGallery.dataset.viewerBound = "true";
      mediaGallery.addEventListener("click", (e) => {
        const btn = e.target.closest("[data-action='openMedia']");
        if (!btn) return;
        const idx = Number(btn.dataset.index);
        if (!Number.isFinite(idx)) return;
        SpecCom.helpers.openMediaViewer(idx);
      });
    }
    if (!site){
      mediaGallery.innerHTML = `<div class="muted small">${t("noSiteSelected")}</div>`;
    } else if (!(state.siteMedia || []).length){
      mediaGallery.innerHTML = `<div class="muted small">${t("mediaSubtitle")}</div>`;
    } else {
      mediaGallery.innerHTML = state.siteMedia.map((item, idx) => `
        <button class="media-card" type="button" data-action="openMedia" data-index="${idx}">
          ${item.previewUrl ? `<img src="${item.previewUrl}" alt="media" />` : ""}
          <div class="media-meta">${escapeHtml(new Date(item.created_at).toLocaleString())}</div>
          ${renderSiteMediaBadges(item)}
        </button>
      `).join("");
    }
  }

  if (codesList){
    codesList.innerHTML = (state.siteCodes || []).length
      ? (state.siteCodes || []).map((row) => `<span class="code-chip">${escapeHtml(row.code)}</span>`).join("")
      : `<div class="muted small">${t("codesSubtitle")}</div>`;
  }

  if (entriesList){
    if (!(state.siteEntries || []).length){
      entriesList.innerHTML = `<div class="muted small">${t("entriesSubtitle")}</div>`;
    } else {
      entriesList.innerHTML = (state.siteEntries || []).map((row) => {
        const qty = row.quantity == null ? "-" : row.quantity;
        return `
          <div class="entry-row">
            <div>${escapeHtml(row.description || "")}</div>
            <div class="muted">Qty: ${escapeHtml(qty)}</div>
          </div>
        `;
      }).join("");
    }
  }
  if (state.map.instance){
    renderDerivedMapLayers(getSiteSearchResultSet().rows);
  }
  if (state.pinOverview.open){
    SpecCom.helpers.renderPinOverview();
  }
}

async function saveSiteName(){
  const site = state.activeSite;
  if (!site){
    toast("Site missing", "Site not found.");
    return;
  }
  showSaveStatus("saving");
  const input = $("siteNameInput");
  const nextName = String(input?.value || "").trim() || "Pinned site";

  if (site.is_pending){
    state.pendingSites = loadPendingSitesFromStorage().map((row) => (
      row.id === site.id ? { ...row, name: nextName } : row
    ));
    savePendingSitesToStorage(state.pendingSites);
    state.activeSite = { ...site, name: nextName };
    renderSiteList();
    renderSitePanel();
    showSaveStatus("saved");
    toast("Saved", "Location name updated.");
    return;
  }

  if (!state.client){
    showSaveStatus("error");
    toast("Update failed", "Client not ready.");
    return;
  }
  const { error } = await state.client
    .from("sites")
    .update({ name: nextName })
    .eq("id", site.id);
  if (error){
    showSaveStatus("error");
    toast("Update failed", error.message);
    return;
  }
  state.projectSites = (state.projectSites || []).map((row) => (
    row.id === site.id ? { ...row, name: nextName } : row
  ));
  state.activeSite = { ...site, name: nextName };
  renderSiteList();
  renderSitePanel();
  showSaveStatus("saved");
  toast("Saved", "Location name updated.");
}

async function loadSiteMedia(siteId){
  const siteKey = toSiteIdKey(siteId);
  const archiveSite = (state.projectSites || []).find((row) => toSiteIdKey(row?.id) === siteKey) || null;
  if (isDemo){
    state.siteMedia = (state.demo.siteMedia || []).filter((row) => row.site_id === siteId);
    if (!state.siteMedia.length){
      state.siteMedia = await getRuidosoArchivePhotosForSite(archiveSite);
    }
    setCachedSitePhotos(siteId, state.siteMedia.map((row) => ({
      id: row?.id || "",
      createdBy: row?.created_by || "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
    return;
  }
  let { data, error } = await state.client
    .from("site_media")
    .select("id, site_id, media_path, created_by, gps_lat, gps_lng, gps_accuracy_m, created_at, source, proof_type, is_live_proof, backfilled, device_user_agent, captured_at_locked, gps_locked")
    .eq("site_id", siteId)
    .order("created_at", { ascending: false });
  if (error && isMissingColumnError(error, "created_by")){
    ({ data, error } = await state.client
      .from("site_media")
      .select("id, site_id, media_path, gps_lat, gps_lng, gps_accuracy_m, created_at, source, proof_type, is_live_proof, backfilled, device_user_agent, captured_at_locked, gps_locked")
      .eq("site_id", siteId)
      .order("created_at", { ascending: false }));
  }
  if (error && ["source", "proof_type", "is_live_proof", "backfilled", "device_user_agent", "captured_at_locked", "gps_locked"].some((col) => isMissingColumnError(error, col))){
    ({ data, error } = await state.client
      .from("site_media")
      .select("id, site_id, media_path, created_by, gps_lat, gps_lng, gps_accuracy_m, created_at")
      .eq("site_id", siteId)
      .order("created_at", { ascending: false }));
  }
  if (error){
    logPhotoFlowError("site media load failed", error, { siteId });
    const archivePhotos = await getRuidosoArchivePhotosForSite(archiveSite);
    if (archivePhotos.length){
      state.siteMedia = archivePhotos;
      setCachedSitePhotos(siteId, archivePhotos.map((row) => ({
        id: row?.id || "",
        createdBy: row?.created_by || "",
        url: String(row?.previewUrl || row?.media_path || "").trim(),
        createdAt: row?.created_at || "",
        source: row?.source || "",
        proofType: row?.proof_type || "",
        readonly: Boolean(row?.readonly),
      })).filter((row) => row.url));
      return;
    }
    toast("Media load error", error.message);
    state.siteMedia = [];
    setCachedSitePhotos(siteId, []);
    return;
  }
  const rows = data || [];
  const withUrls = [];
  for (const row of rows){
    const previewUrl = row.media_path
      ? (/^https?:\/\//i.test(String(row.media_path)) ? String(row.media_path) : await getPublicOrSignedUrl("proof-photos", row.media_path))
      : "";
    withUrls.push({
      ...row,
      previewUrl,
      gpsLat: row?.gps_lat ?? null,
      gpsLng: row?.gps_lng ?? null,
      gpsAccuracyM: row?.gps_accuracy_m ?? null,
      source: row?.source || "reference_upload",
      proof_type: row?.proof_type || "",
      is_live_proof: Boolean(row?.is_live_proof),
      backfilled: Boolean(row?.backfilled),
      device_user_agent: row?.device_user_agent || "",
      captured_at_locked: row?.captured_at_locked !== false,
      gps_locked: row?.gps_locked !== false,
    });
  }
  state.siteMedia = withUrls.length ? withUrls : await getRuidosoArchivePhotosForSite(archiveSite);
  setCachedSitePhotos(siteId, withUrls.map((row) => ({
    id: row?.id || "",
    createdBy: row?.created_by || "",
    url: String(row?.previewUrl || "").trim(),
    createdAt: row?.created_at || "",
    source: row?.source || "",
    proofType: row?.proof_type || "",
    readonly: Boolean(row?.readonly),
  })).filter((row) => row.url));
  if (!withUrls.length && state.siteMedia.length){
    setCachedSitePhotos(siteId, state.siteMedia.map((row) => ({
      id: row?.id || "",
      createdBy: row?.created_by || "",
      url: String(row?.previewUrl || row?.media_path || "").trim(),
      createdAt: row?.created_at || "",
      source: row?.source || "",
      proofType: row?.proof_type || "",
      readonly: Boolean(row?.readonly),
    })).filter((row) => row.url));
  }
}

async function loadSiteCodes(siteId){
  if (isDemo){
    state.siteCodes = (state.demo.siteCodes || []).filter((row) => row.site_id === siteId);
    setCachedSiteCodes(siteId, state.siteCodes.map((row) => row.code));
    return;
  }
  const { data, error } = await state.client
    .from("site_codes")
    .select("id, site_id, code, created_at")
    .eq("site_id", siteId)
    .order("created_at", { ascending: true });
  if (error){
    toast("Codes load error", error.message);
    state.siteCodes = [];
    setCachedSiteCodes(siteId, []);
    return;
  }
  state.siteCodes = data || [];
  setCachedSiteCodes(siteId, state.siteCodes.map((row) => row.code));
}

async function loadSiteEntries(siteId){
  if (isDemo){
    state.siteEntries = (state.demo.siteEntries || []).filter((row) => row.site_id === siteId);
    return;
  }
  const { data, error } = await state.client
    .from("site_entries")
    .select("id, site_id, description, quantity, created_at")
    .eq("site_id", siteId)
    .order("created_at", { ascending: false });
  if (error){
    toast("Entries load error", error.message);
    state.siteEntries = [];
    return;
  }
  state.siteEntries = data || [];
}

async function saveSiteNotes(){
  const site = state.activeSite;
  if (!site || site.is_pending) return;
  if (!(SpecCom.helpers.isRoot() || isOwner())){
    toast("Permission denied", "Only authorized team members can manually edit GPS and progress notes.", "error");
    return;
  }
  showSaveStatus("saving");
  const notes = $("siteNotesInput")?.value || "";
  if (isDemo){
    const demoSite = (state.demo.sites || []).find((row) => row.id === site.id);
    if (demoSite) demoSite.notes = notes;
    state.activeSite.notes = notes;
    renderSitePanel();
    showSaveStatus("saved");
    return;
  }
  const { error } = await state.client
    .from("sites")
    .update({ notes })
    .eq("id", site.id);
  if (error){
    showSaveStatus("error");
    toast("Notes save error", error.message);
    return;
  }
  const match = (state.projectSites || []).find((row) => row.id === site.id);
  if (match) match.notes = notes;
  state.activeSite = match || { ...site, notes };
  renderSitePanel();
  showSaveStatus("saved");
}

function parseCodes(raw){
  const list = String(raw || "")
    .split(",")
    .map((code) => code.trim())
    .filter(Boolean);
  return Array.from(new Set(list));
}

async function saveSiteCodes(){
  const site = state.activeSite;
  if (!site || site.is_pending) return;
  showSaveStatus("saving");
  const raw = $("siteCodesInput")?.value || "";
  const codes = parseCodes(raw);
  if (isDemo){
    state.demo.siteCodes = (state.demo.siteCodes || []).filter((row) => row.site_id !== site.id);
    state.demo.siteCodes.push(...codes.map((code) => ({
      id: `demo-code-${Date.now()}-${code}`,
      site_id: site.id,
      code,
      created_at: new Date().toISOString(),
    })));
    state.siteCodes = state.demo.siteCodes.filter((row) => row.site_id === site.id);
    setCachedSiteCodes(site.id, state.siteCodes.map((row) => row.code));
    renderSitePanel();
    showSaveStatus("saved");
    return;
  }
  await state.client.from("site_codes").delete().eq("site_id", site.id);
  if (codes.length){
    const payload = codes.map((code) => ({ site_id: site.id, code }));
    const { error } = await state.client.from("site_codes").insert(payload);
    if (error){
      showSaveStatus("error");
      toast("Codes save error", error.message);
      return;
    }
  }
  await loadSiteCodes(site.id);
  renderSitePanel();
  showSaveStatus("saved");
}

async function addSiteEntry(){
  const site = state.activeSite;
  if (!site || site.is_pending) return;
  const desc = $("siteEntryDescription")?.value.trim();
  const qtyRaw = $("siteEntryQuantity")?.value;
  if (!desc){
    toast("Entry required", "Add a description for the entry.");
    return;
  }
  const quantity = qtyRaw === "" ? null : Number(qtyRaw);
  if (qtyRaw !== "" && !Number.isFinite(quantity)){
    toast("Quantity invalid", "Enter a valid quantity or leave it blank.");
    return;
  }
  showSaveStatus("saving");
  if (isDemo){
    const row = {
      id: `demo-entry-${Date.now()}`,
      site_id: site.id,
      description: desc,
      quantity,
      created_at: new Date().toISOString(),
    };
    state.demo.siteEntries = state.demo.siteEntries || [];
    state.demo.siteEntries.unshift(row);
    state.siteEntries = state.demo.siteEntries.filter((item) => item.site_id === site.id);
    renderSitePanel();
    showSaveStatus("saved");
  } else {
    const { error } = await state.client
      .from("site_entries")
      .insert({ site_id: site.id, description: desc, quantity });
    if (error){
      showSaveStatus("error");
      toast("Entry save error", error.message);
      return;
    }
    await loadSiteEntries(site.id);
    renderSitePanel();
    showSaveStatus("saved");
  }
  const descInput = $("siteEntryDescription");
  const qtyInput = $("siteEntryQuantity");
  if (descInput) descInput.value = "";
  if (qtyInput) qtyInput.value = "";
}

function getCurrentGps({ enableHighAccuracy = true, timeout = 12000, maximumAge = 0 } = {}){
  return new Promise((resolve) => {
    if (!navigator.geolocation){
      resolve(null);
      return;
    }
    navigator.geolocation.getCurrentPosition(
      (pos) => {
        resolve({
          lat: pos.coords.latitude,
          lng: pos.coords.longitude,
          accuracy: Number.isFinite(pos.coords.accuracy) ? pos.coords.accuracy : null,
        });
      },
      () => resolve(null),
      { enableHighAccuracy, timeout, maximumAge }
    );
  });
}

async function addSiteMedia(file){
  const site = state.activeSite;
  if (!site || site.is_pending || !file) return;
  const capturedAt = new Date().toISOString();
  const gps = await getCurrentGps();
  const fallbackGps = (site.gps_lat != null && site.gps_lng != null)
    ? { lat: site.gps_lat, lng: site.gps_lng, accuracy: site.gps_accuracy_m || null }
    : null;
  const finalGps = gps || fallbackGps;

  if (isDemo){
    state.demo.siteMedia = state.demo.siteMedia || [];
    state.demo.siteMedia.unshift({
      id: `demo-media-${Date.now()}`,
      site_id: site.id,
      media_path: "demo-only",
      created_by: state.user?.id || null,
      created_at: capturedAt,
      gps_lat: finalGps?.lat ?? null,
      gps_lng: finalGps?.lng ?? null,
      gps_accuracy_m: finalGps?.accuracy ?? null,
      previewUrl: URL.createObjectURL(file),
    });
    state.siteMedia = state.demo.siteMedia.filter((row) => row.site_id === site.id);
    renderSitePanel();
    return;
  }
  const uploadPath = await uploadSiteMediaForSite(file, site, finalGps, capturedAt, {
    source: "reference_upload",
    proofType: "",
    isLiveProof: false,
    backfilled: false,
    deviceUserAgent: navigator.userAgent || "",
    gpsLocked: Boolean(finalGps),
    capturedAtLocked: true,
  });
  if (!uploadPath){
    return;
  }
  await loadSiteMedia(site.id);
  renderSitePanel();
}

async function dropPin(){
  ensureMap();
  const pendingLatLng = state.map.pendingLatLng;
  if (!pendingLatLng){
    toast("Pin required", "Click the map to choose a location first.");
    return;
  }
  const lat = Number(pendingLatLng.lat);
  const lng = Number(pendingLatLng.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)){
    toast("Pin required", "Click the map to choose a location first.");
    return;
  }
  const siteName = $("dropPinName")?.value.trim() || "";
  await createSiteFromMapClick({ lat, lng }, siteName);
  const nameInput = $("dropPinName");
  if (nameInput) nameInput.value = "";
}

async function createSiteFromMapClick(coords, siteName, options = {}){
  ensureMap();
  const latNum = Number(coords.lat);
  const lngNum = Number(coords.lng);
  if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)){
    toast("Pin error", "Invalid map coordinates.");
    clearPendingPinMarker();
    return null;
  }
  if (state.map.instance){
    state.map.instance.setView([latNum, lngNum], 17);
  }
  const locationType = String(options.locationType || "").trim();
  const userNotes = String(options.notes || "").trim();
  const actor = String(state.profile?.display_name || state.user?.email || state.user?.id || "Unknown").trim();
  const timestamp = String(options.createdAt || nowISO());
  const metadataLines = [
    locationType ? `Type: ${locationType}` : "",
    `Captured: ${timestamp}`,
    `Captured by: ${actor}`,
  ].filter(Boolean);
  const combinedNotes = [userNotes, metadataLines.join(" | ")].filter(Boolean).join("\n");
  const finalName = String(siteName || "").trim() || "Pinned site";
  const payload = {
    project_id: state.activeProject?.id || null,
    name: finalName,
    notes: combinedNotes || null,
    gps_lat: latNum,
    gps_lng: lngNum,
    gps_accuracy_m: null,
    created_at: timestamp,
  };
  try{
    if (isDemo){
      const demoSite = { id: `demo-site-${Date.now()}`, ...payload };
      state.demo.sites = state.demo.sites || [];
      state.demo.sites.push(demoSite);
      state.projectSites = state.demo.sites.filter((row) => row.project_id === payload.project_id);
      renderSiteList();
      updateMapMarkers(getVisibleSites());
      await setActiveSite(demoSite.id);
      toast(t("pinDroppedTitle"), t("pinDroppedBody"));
      return demoSite.id;
    }

    if (!navigator.onLine || !state.client){
      const pending = {
        id: `pending-${Date.now()}-${Math.random().toString(16).slice(2)}`,
        ...payload,
      };
      state.pendingSites = loadPendingSitesFromStorage();
      state.pendingSites.push(pending);
      savePendingSitesToStorage(state.pendingSites);
      renderSiteList();
      updateMapMarkers(getVisibleSites());
      await setActiveSite(pending.id);
      toast(t("pinQueuedTitle"), t("pinQueuedBody"));
      return pending.id;
    }

    let createdSite = null;
    let siteId = null;
    const rpcRes = await state.client
      .rpc("fn_create_site_pin", {
        p_project_id: state.activeProject?.id || null,
        p_lat: latNum,
        p_lng: lngNum,
      });
    if (rpcRes.error){
      debugLog("[dropPin] rpc error", rpcRes.error);
      const errorMessage = String(rpcRes.error.message || "").toLowerCase();
      if (options.suppressAccessDeniedToast && isProjectAccessDeniedError(rpcRes.error)){
        return null;
      }
      if (errorMessage.includes("schema cache")){
        console.error(rpcRes.error);
        toast("Pin save error", "Schema cache is out of date. Refresh and try again.", "error");
        return;
      }
      if (isRpc404(rpcRes.error) || isMissingGpsColumnError(rpcRes.error)){
        const basePayload = { ...payload, created_by: state.user?.id || null };
        let fallback = await state.client
          .from("sites")
          .insert(basePayload)
          .select("id")
          .single();
        if (fallback.error && isMissingGpsColumnError(fallback.error)){
          fallback = await state.client
            .from("sites")
            .insert({ ...stripGpsFields(basePayload), lat: latNum, lng: lngNum })
            .select("id")
            .single();
        }
        if (fallback.error){
          debugLog("[dropPin] fallback error", fallback.error);
          if (options.suppressAccessDeniedToast && isProjectAccessDeniedError(fallback.error)){
            return null;
          }
          reportPinErrorToast("Pin save error", fallback.error);
          return;
        }
        siteId = fallback.data?.id || null;
      } else {
        reportPinErrorToast("Pin save error", rpcRes.error);
        return;
      }
    } else {
      siteId = rpcRes.data || null;
    }

    if (siteId){
      if (finalName || combinedNotes){
        const updatePayload = {};
        if (finalName) updatePayload.name = finalName;
        if (combinedNotes) updatePayload.notes = combinedNotes;
        const nameUpdate = await state.client
          .from("sites")
          .update(updatePayload)
          .eq("id", siteId);
        if (nameUpdate.error){
          reportPinErrorToast("Pin save error", nameUpdate.error);
          return null;
        }
      }
      const siteRes = await fetchSiteById(siteId);
      if (siteRes.error){
        reportPinErrorToast("Pin save error", siteRes.error);
        return null;
      }
      createdSite = siteRes.data || null;
    }

    if (siteId){
      if (createdSite){
        state.projectSites = (state.projectSites || []).filter((row) => row.id !== createdSite.id).concat(createdSite);
        renderSiteList();
        updateMapMarkers(getVisibleSites());
        await setActiveSite(createdSite.id);
      } else {
        await loadProjectSites(state.activeProject?.id || null);
        await setActiveSite(siteId);
      }
    }
    toast(t("pinDroppedTitle"), t("pinDroppedBody"));
    return siteId || createdSite?.id || null;
  } finally {
    clearPendingPinMarker();
  }
}

async function updateSiteLocationFromMapClick(siteId, coords){
  if (!siteId){
    clearPendingPinMarker();
    return;
  }
  if (!(SpecCom.helpers.isRoot() || isOwner())){
    toast("Permission denied", "Only authorized team members can manually edit GPS and progress notes.", "error");
    clearPendingPinMarker();
    return;
  }
  if (!state.client){
    toast("Pin update error", "Client not ready.");
    clearPendingPinMarker();
    return;
  }
  const latNum = Number(coords.lat);
  const lngNum = Number(coords.lng);
  if (!Number.isFinite(latNum) || !Number.isFinite(lngNum)){
    toast("Pin update error", "Invalid coordinates.");
    clearPendingPinMarker();
    return;
  }
  try{
    let res = await state.client
      .from("sites")
      .update({ gps_lat: latNum, gps_lng: lngNum })
      .eq("id", siteId)
      .select("id")
      .single();
    if (res.error && isMissingGpsColumnError(res.error)){
      res = await state.client
        .from("sites")
        .update({ lat: latNum, lng: lngNum })
        .eq("id", siteId)
        .select("id")
        .single();
    }
    if (res.error){
      reportPinErrorToast("Pin update error", res.error);
      return;
    }
    const siteRes = await fetchSiteById(siteId);
    if (siteRes.error){
      reportPinErrorToast("Pin update error", siteRes.error);
      return;
    }
    if (siteRes.data){
      state.projectSites = (state.projectSites || []).filter((row) => row.id !== siteRes.data.id).concat(siteRes.data);
      updateMapMarkers(getVisibleSites());
      await setActiveSite(siteRes.data.id);
    }
    toast("Pin updated", "Location updated.");
  } finally {
    clearPendingPinMarker();
  }
}

async function syncPendingSites(){
  if (isDemo || !state.client || !navigator.onLine || !state.storageAvailable) return;
  const pending = loadPendingSitesFromStorage();
  if (!pending.length) return;
  const remaining = [];
  for (const site of pending){
    const { id, is_pending, ...payload } = site;
    const gpsPayload = { ...payload };
    delete gpsPayload.lat;
    delete gpsPayload.lng;
    delete gpsPayload.latitude;
    delete gpsPayload.longitude;
    let insertRes = await state.client
      .from("sites")
      .insert(gpsPayload)
      .select("id")
      .single();
    if (insertRes.error && isMissingGpsColumnError(insertRes.error)){
      const legacyPayload = {
        ...stripGpsFields(payload),
        lat: payload.gps_lat ?? payload.lat ?? payload.latitude ?? null,
        lng: payload.gps_lng ?? payload.lng ?? payload.longitude ?? null,
      };
      insertRes = await state.client
        .from("sites")
        .insert(legacyPayload)
        .select("id")
        .single();
    }
    if (insertRes.error || !insertRes.data?.id){
      remaining.push(site);
      continue;
    }
    const siteRes = await fetchSiteById(insertRes.data.id);
    if (siteRes.error || !siteRes.data){
      remaining.push(site);
      continue;
    }
    if (state.activeSite?.id === site.id){
      state.activeSite = siteRes.data;
    }
    if (siteRes.data.project_id === state.activeProject?.id){
      state.projectSites = (state.projectSites || []).concat(siteRes.data);
    }
  }
  state.pendingSites = remaining;
  savePendingSitesToStorage(remaining);
  renderSiteList();
  updateMapMarkers(getVisibleSites());
  renderSitePanel();
}

function renderNodeCards(){
  const wrap = $("nodeCards");
  if (!wrap) return;
  if (!state.projectNodes.length){
    wrap.innerHTML = `<div class="muted small">${t("selectProjectNodes")}</div>`;
    return;
  }
  const showBuildControls = SpecCom.helpers.isRoot() || isOwnerOrAdmin();
  const activeNode = state.projectNodes.find(n => n.status === "ACTIVE");
  wrap.innerHTML = state.projectNodes.map((node) => {
    const status = node.status || "NOT_STARTED";
    const isActive = status === "ACTIVE";
    const isComplete = status === "COMPLETE";
    const canStart = !activeNode || activeNode.id === node.id || isComplete;
    const actionLabel = isComplete ? t("completeLabel") : isActive ? t("continueLabel") : t("startLabel");
    const disabled = !canStart && !isActive;
    const completeDisabled = !isActive && !isComplete;
    const deleting = Boolean(node.isDeleting);
    const demoAttrs = isDemoUser() ? `disabled title="${t("availableInProduction")}"` : "";
    const buildButtons = showBuildControls
      ? `
        <button class="btn ghost" data-action="editNode" data-id="${node.id}" ${deleting ? "disabled" : ""}>${t("editLabel")}</button>
        <button class="btn danger" data-action="deleteNode" data-id="${node.id}" ${deleting ? "disabled" : ""} ${demoAttrs}>${deleting ? t("deletingLabel") : t("deleteLabel")}</button>
      `
      : "";
    const descriptionHtml = renderTranslatedText(node.description || t("jobSubtitle"));
    return `
      <div class="node-card">
        <div class="node-meta">
          <div class="node-title">${escapeHtml(node.node_number)}</div>
          ${descriptionHtml}
        </div>
        <div class="node-status ${status.toLowerCase()}">${status.replace("_", " ")}</div>
        <div class="row">
          <button class="btn ${isActive ? "" : "secondary"}" data-action="openNode" data-id="${node.id}" ${disabled ? "disabled" : ""}>${actionLabel}</button>
          <button class="btn ghost" data-action="completeNode" data-id="${node.id}" ${completeDisabled ? "disabled" : ""}>${t("completeAction")}</button>
          ${buildButtons}
        </div>
      </div>
    `;
  }).join("");
  hydrateTranslations(wrap);
}

function getActiveProjectNode(){
  return state.projectNodes.find(n => n.status === "ACTIVE") || null;
}

async function startNode(nodeId){
  const node = state.projectNodes.find(n => n.id === nodeId);
  if (!node){
    toast("Site missing", "Site not found.");
    return;
  }
  const active = getActiveProjectNode();
  if (active && active.id !== nodeId && active.status !== "COMPLETE"){
    toast("Active site in progress", `Finish ${active.node_number} before starting another site.`);
    return;
  }
  if (isDemo){
    node.status = "ACTIVE";
    node.started_at = nowISO();
    state.demo.nodes[node.node_number].status = "ACTIVE";
    state.activeNode = state.demo.nodes[node.node_number];
    renderNodeCards();
    await openNode(node.node_number);
    setActiveView("viewNodes");
    return;
  }
  const { error } = await state.client
    .from("nodes")
    .update({ status: "ACTIVE", started_at: new Date().toISOString() })
    .eq("id", node.id);
  if (error){
    toast("Start failed", error.message);
    return;
  }
  node.status = "ACTIVE";
  await openNode(node.node_number);
  await loadProjectNodes(node.project_id);
  setActiveView("viewNodes");
}

async function completeNode(nodeId){
  const node = state.projectNodes.find(n => n.id === nodeId);
  if (!node){
    toast("Site missing", "Site not found.");
    return;
  }
  const canComplete = Boolean(state.user);
  if (!canComplete){
    toast("Not allowed", "Only authorized team members can complete a site.");
    return;
  }
  if (!state.activeNode || state.activeNode.node_number !== node.node_number){
    toast("Open site", "Open the site before marking it complete.");
    return;
  }
  const photos = computeProofStatus(state.activeNode);
  if (!BUILD_MODE && !photos.photosOk){
    toast("No pay", "Photos missing. Completion is blocked.");
    return;
  }
  if (isDemo){
    node.status = "COMPLETE";
    node.completed_at = nowISO();
    state.demo.nodes[node.node_number].status = "COMPLETE";
    renderNodeCards();
    return;
  }
  const { error } = await state.client
    .from("nodes")
    .update({ status: "COMPLETE", completed_at: new Date().toISOString() })
    .eq("id", node.id);
  if (error){
    toast("Complete failed", error.message);
    return;
  }
  node.status = "COMPLETE";
  await loadProjectNodes(node.project_id);
}

async function editNodeMeta(nodeId){
  if (!SpecCom.helpers.isRoot() && (!BUILD_MODE || !isOwner())){
    toast("Not allowed", "Authorized access required.");
    return;
  }
  const node = state.projectNodes.find(n => n.id === nodeId);
  if (!node){
    toast("Site missing", "Site not found.");
    return;
  }
  const nextNumber = prompt("Edit site number", node.node_number || "");
  if (nextNumber === null) return;
  const nextDesc = prompt("Edit site description", node.description || "");
  if (nextDesc === null) return;
  const trimmedNumber = String(nextNumber).trim() || node.node_number;
  const trimmedDesc = String(nextDesc).trim();
  if (trimmedNumber === node.node_number && trimmedDesc === (node.description || "")) return;

  if (isDemo){
    const demoNode = state.demo.nodes[node.node_number];
    if (demoNode){
      delete state.demo.nodes[node.node_number];
      demoNode.node_number = trimmedNumber;
      demoNode.description = trimmedDesc;
      state.demo.nodes[trimmedNumber] = demoNode;
    }
    node.node_number = trimmedNumber;
    node.description = trimmedDesc;
    state.demo.nodesList = (state.demo.nodesList || []).map((row) => (
      row.id === node.id ? { ...row, node_number: trimmedNumber, description: trimmedDesc } : row
    ));
    renderNodeCards();
    return;
  }

  const { error } = await state.client
    .from("nodes")
    .update({ node_number: trimmedNumber, description: trimmedDesc })
    .eq("id", node.id);
  if (error){
    toast("Update failed", error.message);
    return;
  }
  node.node_number = trimmedNumber;
  node.description = trimmedDesc;
  if (state.activeNode?.id === node.id){
    state.activeNode.node_number = trimmedNumber;
    state.activeNode.description = trimmedDesc;
    updateKPI();
  }
  renderNodeCards();
}

async function deleteNode(nodeId){
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  if (!SpecCom.helpers.isRoot() && (!BUILD_MODE || !isOwner())){
    toast("Not allowed", "Authorized access required.");
    return;
  }
  const node = state.projectNodes.find(n => n.id === nodeId);
  if (!node){
    toast("Site missing", "Site not found.");
    return;
  }
  if (!confirm("Delete site?\nThis will remove the site and all related data. This cannot be undone.")) return;
  const typed = prompt("Type DELETE to confirm.");
  if (typed !== "DELETE"){
    toast("Delete canceled", "Type DELETE to confirm.");
    return;
  }
  node.isDeleting = true;
  renderNodeCards();

  if (isDemo){
    delete state.demo.nodes[node.node_number];
    state.demo.nodesList = (state.demo.nodesList || []).filter(n => n.id !== node.id);
    state.projectNodes = state.projectNodes.filter(n => n.id !== node.id);
    if (state.activeNode?.id === node.id){
      state.activeNode = null;
      clearProof();
    }
    renderNodeCards();
    renderLocations();
    renderInventory();
    renderInvoicePanel();
    renderProofChecklist();
    updateKPI();
    renderBillingDetail();
    toast("Deleted", "Site deleted.");
    return;
  }

  const { error } = await state.client
    .from("nodes")
    .delete()
    .eq("id", node.id);
  if (error){
    toast("Delete failed", error.message);
    node.isDeleting = false;
    renderNodeCards();
    return;
  }
  if (state.activeNode?.id === node.id){
    state.activeNode = null;
    clearProof();
  }
  await loadProjectNodes(node.project_id);
  await loadBillingLocations(state.activeProject?.id || null);
  renderLocations();
  renderInventory();
  renderInvoicePanel();
  renderProofChecklist();
  updateKPI();
  renderBillingDetail();
  toast("Deleted", "Site deleted.");
}

