async function loadBillingLocations(projectId){
  if (!projectId){
    state.billingLocations = [];
    renderBillingLocations();
    return;
  }
  if (isDemo){
    const rows = Object.values(state.demo.nodes || {}).flatMap(node => (node.splice_locations || []).map((loc) => ({
      id: loc.id,
      node_id: node.id,
      label: loc.label ?? null,
      location_label: loc.location_label || loc.name,
      completed: loc.completed,
      terminal_ports: loc.terminal_ports,
      photo_count: getLocationProofUploaded(loc),
      node_number: node.node_number,
      invoice_status: "draft",
    })));
    state.billingLocations = rows;
    state.locationWorkCodes = new Map();
    renderBillingLocations();
    return;
  }
  if (!state.client) return;
  const { data: locs, error: locErr } = await state.client
    .from("splice_locations")
    .select("id, node_id, label, location_label, completed, terminal_ports, sort_order, nodes!inner(project_id,node_number)")
    .eq("nodes.project_id", projectId)
    .order("sort_order", { ascending: true, nullsFirst: false })
    .order("created_at", { ascending: true });
  if (locErr){
    toast("Locations load error", locErr.message);
    return;
  }
  const locationIds = (locs || []).map(l => l.id);
  let counts = new Map();
  let invoiceStatus = new Map();
  let invoiceIdsByLocation = new Map();
  let proofRequiredByLocation = new Map();
  let proofUploadedByLocation = new Map();
  if (locationIds.length){
    const { data: photos, error: photoErr } = await state.client
      .from("splice_location_photos")
      .select("splice_location_id")
      .in("splice_location_id", locationIds);
    if (photoErr){
      toast("Proof load error", photoErr.message);
    } else {
      (photos || []).forEach((row) => {
        counts.set(row.splice_location_id, (counts.get(row.splice_location_id) || 0) + 1);
      });
    }
    const { data: proofRows, error: proofErr } = await state.client
      .from("location_proof_status")
      .select("location_id, proof_required, proof_uploaded")
      .in("location_id", locationIds);
    if (!proofErr){
      (proofRows || []).forEach((row) => {
        proofRequiredByLocation.set(row.location_id, Number(row.proof_required || 0));
        proofUploadedByLocation.set(row.location_id, Number(row.proof_uploaded || 0));
      });
    }
    const { data: invoices } = await state.client
      .from("invoices")
      .select("id, location_id, status")
      .in("location_id", locationIds);
    (invoices || []).forEach((row) => {
      if (row.location_id) invoiceStatus.set(row.location_id, row.status);
      if (row.location_id && row.id) invoiceIdsByLocation.set(row.location_id, row.id);
    });

    const invoiceIds = Array.from(invoiceIdsByLocation.values());
    if (invoiceIds.length){
      const locationByInvoice = new Map();
      invoiceIdsByLocation.forEach((invId, locId) => {
        locationByInvoice.set(invId, locId);
      });
      const { data: items } = await state.client
        .from("invoice_items")
        .select("invoice_id, work_codes(code)")
        .in("invoice_id", invoiceIds);
      const codeMap = new Map();
      (items || []).forEach((row) => {
        const code = row.work_codes?.code;
        if (!code) return;
        const locId = locationByInvoice.get(row.invoice_id);
        if (!locId) return;
        if (!codeMap.has(locId)) codeMap.set(locId, new Set());
        codeMap.get(locId).add(code);
      });
      state.locationWorkCodes = codeMap;
    } else {
      state.locationWorkCodes = new Map();
    }
  }
  state.billingLocations = (locs || []).map((loc) => ({
    id: loc.id,
    node_id: loc.node_id,
    label: loc.label ?? null,
    location_label: loc.location_label,
    completed: loc.completed,
    terminal_ports: normalizeTerminalPorts(loc.terminal_ports ?? DEFAULT_TERMINAL_PORTS),
    photo_count: proofUploadedByLocation.get(loc.id) ?? counts.get(loc.id) ?? 0,
    proof_required: proofRequiredByLocation.get(loc.id),
    node_number: loc.nodes?.node_number || "",
    invoice_status: invoiceStatus.get(loc.id) || "draft",
  }));
  if (state.billingLocation){
    const updated = state.billingLocations.find(l => l.id === state.billingLocation.id);
    if (updated) state.billingLocation = updated;
  }
  renderBillingLocations();
}

function setActiveProjectById(id){
  const next = state.projects.find(p => p.id === id) || null;
  const currentProjectId = String(state.activeProject?.id || "");
  const nextProjectId = String(next?.id || "");
  const openFieldDay = getOpenFieldDaySession();
  const openFieldDayProjectId = openFieldDay ? (openFieldDay.project_id || currentProjectId) : null;
  if (currentProjectId !== nextProjectId && !bypassesFieldDayWorkflow() && !canSwitchFieldProject(openFieldDayProjectId, nextProjectId)){
    toast("End active project day", `End the recorded project day for ${state.activeProject?.name || "the current project"} before switching projects.`, "error");
    return false;
  }
  if (currentProjectId !== nextProjectId && state.node54Diagnostics.enabled){
    deactivateNode54Diagnostics({ render: false });
  }
  if (currentProjectId !== nextProjectId){
    resetRootCommandCenterProject();
  }
  state.activeProject = next;
  if (currentProjectId !== nextProjectId){
    setFieldDayState(null, []);
    state.projectSites = [];
    state.activeSite = null;
    state.map.fieldSelectedSiteId = "";
    state.map.fieldVisitDraft = null;
    state.map.fieldCloseoutOpen = false;
    state.map.fieldCloseoutDraft = null;
    state.map.nearestSiteId = "";
    state.map.nearestSiteDistanceM = null;
    state.map.fieldPhotos = [];
    state.map.siteSearchIndex.clear();
    state.map.siteCodesBySiteId.clear();
    state.map.sitePhotosBySiteId.clear();
    state.map.fieldWorkLogsBySiteId.clear();
    state.map.siteWorkflowById.clear();
  }
  setActiveOrgContext(next?.org_id || state.profile?.org_id || state.activeOrgId || null);
  if (state.activeOrgId && state.ksInvoices?.pendingImportFile && !state.ksInvoices.importing){
    const pending = state.ksInvoices.pendingImportFile;
    state.ksInvoices.pendingImportFile = null;
    state.ksInvoices.missingOrgContext = false;
    queueMicrotask(() => {
      void handleKsInvoiceZipImport(pending);
    });
  }
  clearImportPreviewMarkers();
  loadKmzPhotoOverridesForActiveProject();
  void loadKmzSnapshotForProject(next?.id || null, { silent: true });
  state.map.materialFeatureId = "";
  state.map.materialFeatureTotals.clear();
  state.mapFilters.search = "";
  const mapSearch = $("mapSearch");
  if (mapSearch) mapSearch.value = "";
  state.map.searchJumpKey = "";
  setSiteSearchBanner("");
  state.redline.addMode = false;
  state.redline.source = null;
  state.redline.sourceKey = "";
  state.redline.markers = [];
  saveCurrentProjectPreference(next?.id || null);
  renderProjects();
  loadProjectNodes(state.activeProject?.id || null);
  loadProjectSites(state.activeProject?.id || null);
  void loadFieldDaySession({ silent: true });
  state.activeSite = null;
  renderSitePanel();
  loadRateCards(state.activeProject?.id || null);
  loadLocationProofRequirements(state.activeProject?.id || null);
  loadBillingLocations(state.activeProject?.id || null);
  SpecCom.helpers.loadYourInvoices(state.activeProject?.id || null);
  loadInvoiceFiles(state.activeProject?.id || null);
  loadKsInvoiceWorkspace(state.activeProject?.id || null);
  state.billingLocation = null;
  state.billingInvoice = null;
  state.billingItems = [];
  renderBillingDetail();
  const activeViewId = document.querySelector(".view.active")?.id || null;
  if (state.features.labor && isTechnician()){
    loadTechnicianTimesheet();
  }
  if (activeViewId === "viewLabor" && state.features.labor){
    loadLaborRows();
  }
  if (state.features.labor && canViewLabor()){
    loadLaborSnapshotForDashboard();
  }
  if (activeViewId === "viewDispatch" && state.features.dispatch){
    loadDispatchTechnicians();
    loadDispatchWorkOrders();
  }
  if (activeViewId === "viewSupervisor" && state.features.dispatch){
    loadDispatchTechnicians();
    loadDispatchWorkOrders();
    renderSupervisorOverview();
  }
  if (activeViewId === "viewMap"){
    refreshLocations();
    renderSiteList();
  }
  refreshMaterialProjectData({ silent: true });
  if (activeViewId === "viewAdmin"){
    loadAdminMaterialSettings();
  }
  forcePlainMapRedlineState();

  dlog("[project] setActiveProjectById", {
    projectId: next?.id || null,
    projectName: next?.name || null,
    activeView: activeViewId,
  });
  renderMapFieldPanel();
  return true;
}

async function saveCurrentProjectPreference(projectId){
  setSavedProjectPreference(projectId);
  if (!state.client || !state.user || isDemo) return;
  try{
    const { error } = await state.client
      .from("profiles")
      .update({ current_project_id: projectId })
      .eq("id", state.user.id);
    if (!error && state.profile){
      state.profile.current_project_id = projectId;
      window.currentUserProfile = state.profile;
    }
  } catch {}
}

function canSeedDemo(){
  return Boolean(state.user);
}

async function seedDemoNode(){
  toast("Demo disabled", "Demo mode is disabled in LIVE mode.");
}

function renderLocations(){
  const wrap = $("locations");
  wrap.innerHTML = "";
  syncNodeWorkspaceControls();
  const node = state.activeNode;
  if (!node){
    wrap.innerHTML = `<div class="muted small">${t("openNodePrompt")}</div>`;
    return;
  }

  const rows = getSortedSpliceLocations(node);
  if (!rows.length){
    wrap.innerHTML = `<div class="muted small">${t("noLocationsYet")} ${t("addSpliceLocation")}.</div>`;
    return;
  }

  const list = document.createElement("div");
  list.className = "location-list";
  rows.forEach((r, index) => {
    r.terminal_ports = normalizeTerminalPorts(r.terminal_ports ?? DEFAULT_TERMINAL_PORTS);
    r.photosBySlot = r.photosBySlot || {};
    r.work_codes = Array.isArray(r.work_codes) ? r.work_codes : [];
    r.work_description = r.work_description || "";
    r.isEditingName = Boolean(r.isEditingName);
    r.isEditingPorts = Boolean(r.isEditingPorts);
    r.isEditingCodes = Boolean(r.isEditingCodes);
    r.isDeleting = Boolean(r.isDeleting);
    const activePorts = normalizeTerminalPorts(r.isEditingPorts ? (r.pending_ports ?? r.terminal_ports) : r.terminal_ports);
    const portValue = [2, 4, 6, 8].includes(activePorts) ? String(activePorts) : "custom";
    const customValue = portValue === "custom" ? activePorts : "";
    const customStyle = portValue === "custom" ? "" : 'style="display:none;"';
    const counts = countRequiredSlotUploads(r);
    const missing = SpecCom.helpers.isRoot() ? false : counts.uploaded < counts.required;
    const disableToggle = r.isDeleting || (!r.completed && missing);
    const billingLocked = isLocationBillingLocked(r.id);
    if (billingLocked && r.isEditingName) r.isEditingName = false;
    if (billingLocked && r.isEditingPorts) r.isEditingPorts = false;
    const displayName = getSpliceLocationDisplayName(r, index);
    const inputValue = r.pending_label ?? (r.label ?? "");
    const canDelete = SpecCom.helpers.isRoot() || BUILD_MODE || Boolean(state.user);
    const disableActions = r.isDeleting;
    const nameHtml = r.isEditingName
      ? `
        <div class="field-stack" style="gap:6px;">
          <input class="input compact" data-action="nameInput" data-id="${r.id}" value="${escapeHtml(inputValue)}" ${billingLocked ? "disabled" : ""} data-autofocus="true" />
          <div class="muted small">Optional label (e.g., "MST-3 / East Pedestal").</div>
          <div class="row" style="justify-content:flex-end;">
            <button class="btn ghost small" data-action="cancelName" data-id="${r.id}" ${disableActions ? "disabled" : ""}>Cancel</button>
            <button class="btn secondary small" data-action="saveName" data-id="${r.id}" ${billingLocked || disableActions ? "disabled" : ""}>Save</button>
          </div>
        </div>
      `
      : `<div style="font-weight:900">${escapeHtml(displayName)}</div>`;
    const workCodes = state.locationWorkCodes?.get(r.id);
    const workCodesLabel = workCodes && workCodes.size ? Array.from(workCodes).join(", ") : "None";
    const done = SINGLE_PROOF_PHOTO_MODE
      ? ""
      : (r.completed ? '<span class="pill-ok">COMPLETE</span>' : '<span class="pill-warn">INCOMPLETE</span>');
    const demoAttrs = isDemoUser() ? `disabled title="${t("availableInProduction")}"` : "";
    const editNameBtn = r.isEditingName
      ? ""
      : `<button class="btn ghost small" data-action="editName" data-id="${r.id}" ${billingLocked || disableActions ? "disabled" : ""}>Edit name</button>`;
    const deleteBtn = canDelete && !r.isEditingPorts
      ? `<button class="btn danger small" data-action="deleteLocation" data-id="${r.id}" ${disableActions ? "disabled" : ""} ${demoAttrs}>${r.isDeleting ? "Deleting..." : "Delete location"}</button>`
      : "";

    const card = document.createElement("div");
    card.className = "card location-card";
    card.innerHTML = `
      <div class="row" style="justify-content:space-between;">
        <div>
          ${nameHtml}
          ${r.gps
            ? `<div class="loc-gps-stamp">
                <span class="loc-gps-icon">📍</span>
                <span>${r.gps.lat.toFixed(6)}, ${r.gps.lng.toFixed(6)}</span>
                <span class="loc-gps-acc">±${Math.round(r.gps.accuracy_m || 0)}m</span>
                ${r.created_at ? `<span class="loc-gps-time">· ${new Date(r.created_at).toLocaleString()}</span>` : ""}
              </div>`
            : `<div class="loc-gps-missing">⚠ No arrival GPS — location not verified</div>`
          }
          <div class="muted small">Photos: <b>${counts.uploaded < counts.required ? `<span style="color:#f59e0b">0 captured — required before completion</span>` : `${counts.uploaded} captured`}</b></div>
          <div class="muted small">Work codes: <b>${escapeHtml(workCodesLabel)}</b></div>
        </div>
        <div>
          ${done ? `<div style="display:flex; justify-content:flex-end;">${done}</div>` : ""}
          <div class="row" style="justify-content:flex-end; margin-top:6px;">
            ${editNameBtn}
          </div>
        </div>
      </div>
      <div class="hr"></div>
      ${r.isEditingPorts ? `
        <div class="row" style="align-items:flex-end;">
          <div class="muted small">Terminal ports</div>
          <select class="input" data-action="portsSelect" data-id="${r.id}" style="width:140px; flex:0 0 auto;">
            <option value="2" ${portValue === "2" ? "selected" : ""}>2</option>
            <option value="4" ${portValue === "4" ? "selected" : ""}>4</option>
            <option value="6" ${portValue === "6" ? "selected" : ""}>6</option>
            <option value="8" ${portValue === "8" ? "selected" : ""}>8</option>
            <option value="custom" ${portValue === "custom" ? "selected" : ""}>Custom</option>
          </select>
          <input class="input" type="number" min="1" max="8" step="1" data-action="portsCustom" data-id="${r.id}" value="${customValue}" ${customStyle} style="width:120px; flex:0 0 auto;" />
          ${SINGLE_PROOF_PHOTO_MODE ? "" : `<div class="muted small">Photo slots available: ${FIXED_LOCATION_PHOTO_SLOTS} per location.</div>`}
        </div>
        <div class="row" style="justify-content:flex-end;">
          <button class="btn ghost" data-action="cancelPorts" data-id="${r.id}" ${disableActions ? "disabled" : ""}>Cancel</button>
          <button class="btn secondary" data-action="savePorts" data-id="${r.id}" ${disableActions ? "disabled" : ""}>Save ports</button>
        </div>
        ${SINGLE_PROOF_PHOTO_MODE ? "" : '<div class="muted small">Photo slots stay fixed at 8.</div>'}
      ` : `
        <div class="row" style="align-items:center; justify-content:space-between;">
          <div class="muted small">Ports required: <b>${activePorts}</b></div>
          <div class="row" style="justify-content:flex-end;">
            <button class="btn ghost" data-action="editPorts" data-id="${r.id}" ${billingLocked || disableActions ? "disabled" : ""}>Edit ports</button>
            ${deleteBtn}
          </div>
        </div>
      `}
      <div class="hr"></div>
      ${renderSplicePhotoGrid(r)}
      <div class="hr"></div>
      ${renderCodesSection(r)}
      <div class="hr"></div>
      <div class="row">
        <button class="btn ghost" data-action="toggleComplete" data-id="${r.id}" ${disableToggle ? "disabled" : ""}>${r.completed ? "Undo complete" : "Mark complete"}</button>
      </div>
    `;
    list.appendChild(card);
  });

  list.addEventListener("change", async (e) => {
    const target = e.target;
    if (!target) return;
    if (target.matches('input[type="file"][data-slot-key]')){
      const locId = target.dataset.locationId;
      const slotKey = target.dataset.slotKey;
      const file = target.files?.[0];
      await handleSpliceSlotPhotoUpload(locId, slotKey, file);
      target.value = "";
      return;
    }
    if (target.dataset.action === "nameInput"){
      const loc = node.splice_locations.find(x => x.id === target.dataset.id);
      if (!loc) return;
      loc.pending_label = target.value;
      return;
    }
    if (target.dataset.action === "portsSelect"){
      const loc = node.splice_locations.find(x => x.id === target.dataset.id);
      if (!loc) return;
      if (target.value === "custom"){
        loc.pending_ports = normalizeTerminalPorts(loc.pending_ports ?? loc.terminal_ports ?? DEFAULT_TERMINAL_PORTS);
        renderLocations();
        return;
      }
      loc.pending_ports = normalizeTerminalPorts(target.value);
      renderLocations();
      return;
    }
    if (target.dataset.action === "portsCustom"){
      const loc = node.splice_locations.find(x => x.id === target.dataset.id);
      if (!loc) return;
      const nextPorts = normalizeTerminalPorts(target.value);
      loc.pending_ports = nextPorts;
      target.value = String(nextPorts);
    }
  });

  list.addEventListener("click", async (e) => {
    const openPhoto = e.target.closest("[data-action='openSlotPhoto']");
    if (openPhoto){
      e.preventDefault();
      e.stopPropagation();
      const url = openPhoto.dataset.url;
      if (url) SpecCom.helpers.openStandalonePhotoViewer(url, "Proof photo");
      return;
    }
    const openCameraBtn = e.target.closest("[data-action='openSlotCamera']");
    if (openCameraBtn){
      e.preventDefault();
      e.stopPropagation();
      const inputId = openCameraBtn.dataset.inputId;
      if (inputId){
        await prepareSlotCameraCapture(inputId);
      }
      return;
    }
    const btn = e.target.closest("button");
    const removeBtn = e.target.closest("[data-action='removeSlotPhoto']");
    if (removeBtn){
      e.preventDefault();
      e.stopPropagation();
      const locId = removeBtn.dataset.locationId;
      const slotKey = removeBtn.dataset.slotKey;
      await deleteSpliceSlotPhoto(locId, slotKey);
      return;
    }
    if (!btn) return;
    const action = btn.dataset.action;
    const id = btn.dataset.id;
    if (action === "editName"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      if (isLocationBillingLocked(loc.id)){
        toast("Billing locked", "Location name is locked after billing is ready.");
        return;
      }
      loc.isEditingName = true;
      loc.pending_label = loc.label ?? "";
      renderLocations();
      return;
    }
    if (action === "saveName"){
      const input = list.querySelector(`[data-action="nameInput"][data-id="${id}"]`);
      await saveSpliceLocationName(id, input ? input.value : "");
      return;
    }
    if (action === "cancelName"){
      cancelSpliceLocationNameEdit(id);
      return;
    }
    if (action === "deleteLocation"){
      openDeleteSpliceLocationModal(id);
      return;
    }
    if (action === "editPorts"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      if (isLocationBillingLocked(loc.id)){
        toast("Billing locked", "Terminal ports are locked after billing is ready.");
        return;
      }
      loc.isEditingPorts = true;
      loc.pending_ports = loc.terminal_ports;
      renderLocations();
      return;
    }
    if (action === "cancelPorts"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      loc.isEditingPorts = false;
      loc.pending_ports = null;
      renderLocations();
      return;
    }
    if (action === "savePorts"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      const nextPorts = normalizeTerminalPorts(loc.pending_ports ?? loc.terminal_ports);
      const ok = await updateTerminalPorts(loc.id, nextPorts);
      if (ok){
        loc.isEditingPorts = false;
        loc.pending_ports = null;
        renderLocations();
      }
      return;
    }
    if (action === "editCodes"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      loc.isEditingCodes = true;
      loc.pending_work_codes = Array.isArray(loc.work_codes) ? [...loc.work_codes] : [];
      loc.pending_work_description = loc.work_description || "";
      renderLocations();
      return;
    }
    if (action === "cancelCodes"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      loc.isEditingCodes = false;
      loc.pending_work_codes = null;
      loc.pending_work_description = null;
      renderLocations();
      return;
    }
    if (action === "saveCodes"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      const codesInput = list.querySelector(`[data-action="codesInput"][data-location-id="${id}"]`);
      const descInput = list.querySelector(`[data-action="descInput"][data-location-id="${id}"]`);
      const nextCodes = normalizeWorkCodes(codesInput?.value || "");
      const nextDesc = String(descInput?.value || "").trim();
      const ok = await updateSpliceLocationCodes(id, nextCodes, nextDesc);
      if (ok){
        loc.isEditingCodes = false;
        loc.pending_work_codes = null;
        loc.pending_work_description = null;
        renderLocations();
      }
      return;
    }
    if (action === "toggleComplete"){
      const loc = node.splice_locations.find(x => x.id === id);
      if (!loc) return;
      if (!hasAllRequiredSlotPhotos(loc)){
        toast("Photos required", "All required splice photos are needed before completion.");
        return;
      }
      const next = !loc.completed;
      if (isDemo){
        loc.completed = next;
        renderLocations();
        updateKPI();
        renderProofChecklist();
        return;
      }
      const { error } = await state.client
        .from("splice_locations")
        .update({ completed: next, completed_by: state.user?.id || null })
        .eq("id", loc.id);
      if (error){
        toast("Update failed", error.message);
        return;
      }
      loc.completed = next;
      renderLocations();
      updateKPI();
      renderProofChecklist();
    }
  });

  wrap.appendChild(list);

  const nameInput = wrap.querySelector("[data-autofocus='true']");
  if (nameInput){
    setTimeout(() => {
      nameInput.focus();
      nameInput.select();
    }, 0);
    nameInput.addEventListener("keydown", async (e) => {
      if (e.key === "Enter"){
        e.preventDefault();
        await saveSpliceLocationName(nameInput.dataset.id, nameInput.value);
      }
      if (e.key === "Escape"){
        e.preventDefault();
        cancelSpliceLocationNameEdit(nameInput.dataset.id);
      }
    });
  }
}

function renderSplicePhotoGrid(loc){
  const requiredSlots = getRequiredSlotsForLocation(loc);
  const photos = loc.photosBySlot || {};
  const extraSlots = Object.keys(photos).filter((slot) => !requiredSlots.includes(slot));
  const orderedExtras = extraSlots.sort((a, b) => {
    const aNum = Number.parseInt(String(a).replace("port_", ""), 10);
    const bNum = Number.parseInt(String(b).replace("port_", ""), 10);
    if (Number.isFinite(aNum) && Number.isFinite(bNum)) return aNum - bNum;
    return String(a).localeCompare(String(b));
  });
  const slots = requiredSlots.concat(orderedExtras);
  return `
    <div class="photo-grid">
      ${slots.map((slotKey) => renderSpliceSlotCard(loc, slotKey, requiredSlots.includes(slotKey))).join("")}
    </div>
  `;
}

function getSlotInputId(locId, slotKey){
  return `slot-${String(locId || "").replace(/[^a-zA-Z0-9_-]/g, "_")}-${String(slotKey || "").replace(/[^a-zA-Z0-9_-]/g, "_")}`;
}

function formatPhotoGpsMeta(gps){
  if (!gps || !Number.isFinite(Number(gps.lat)) || !Number.isFinite(Number(gps.lng))){
    return "GPS missing";
  }
  const accuracy = Number.isFinite(Number(gps.accuracy_m))
    ? ` (+/-${Math.round(Number(gps.accuracy_m))}m)`
    : "";
  return `${Number(gps.lat).toFixed(6)}, ${Number(gps.lng).toFixed(6)}${accuracy}`;
}

function getPhotoVerificationChips(photo){
  if (!photo) return [];
  const chips = [];
  if (photo.backfilled || photo.source === "backfill_upload"){
    chips.push("BACKFILL UPLOAD");
  } else {
    chips.push("VERIFIED LIVE");
  }
  if (photo.gps){
    chips.push("GPS LOCKED");
  }
  if (photo.taken_at){
    chips.push("CAPTURE TIME LOCKED");
  }
  return chips;
}

function renderPhotoVerificationChips(photo){
  const chips = getPhotoVerificationChips(photo);
  if (!chips.length) return "";
  return `
    <div class="row" style="gap:6px; flex-wrap:wrap; width:100%; margin-top:8px;">
      ${chips.map((chip) => `<span class="chip">${escapeHtml(chip)}</span>`).join("")}
    </div>
  `;
}

function renderSpliceSlotCard(loc, slotKey, isRequired){
  const photo = loc.photosBySlot?.[slotKey];
  const label = getSlotLabel(slotKey);
  const badge = isRequired ? "" : '<span class="slot-badge">Extra</span>';
  const timestamp = photo?.taken_at ? new Date(photo.taken_at).toLocaleString() : "";
  const locked = isLocationBillingLocked(loc.id);
  const demoLocked = isDemoUser();
  const demoAttrs = demoLocked ? `disabled title="${t("availableInProduction")}"` : "";
  const thumbUrl = photo?.previewUrl || "";
  const thumb = thumbUrl
    ? `<img class="photo-thumb" src="${thumbUrl}" alt="${escapeHtml(label)} photo" data-action="openSlotPhoto" data-url="${thumbUrl}"/>`
    : photo
      ? `<div class="muted small">Photo captured</div>`
      : "";
  const placeholder = `
    <div class="slot-placeholder">
      <div class="camera-icon" aria-hidden="true"></div>
      <div style="font-size:12px;font-weight:700;color:rgba(55,138,221,0.9);margin-top:4px;">Tap to take live proof photo</div>
      <div class="muted small" style="font-size:10px;">GPS is required before camera opens</div>
    </div>
  `;
  const inputId = getSlotInputId(loc.id, slotKey);
  const inputEl = `<input id="${inputId}" class="file-input-hidden" type="file" accept="image/*" capture="environment" data-location-id="${loc.id}" data-slot-key="${slotKey}" data-input-id="${inputId}" />`;
  if (!photo){
    return `
      <div class="photo-slot ${isRequired ? "photo-slot-required" : "extra"}" style="${isRequired ? "border:1.5px solid rgba(55,138,221,0.35);background:rgba(55,138,221,0.04);" : ""}">
        ${inputEl}
        <div class="row" style="justify-content:space-between; width:100%;">
          <div class="slot-title">${escapeHtml(label)}</div>
          ${badge}
        </div>
        ${placeholder}
        <div class="row" style="justify-content:flex-end; width:100%; margin-top:8px;">
          <button type="button" class="btn secondary small" data-action="openSlotCamera" data-input-id="${inputId}" ${demoAttrs}>Take Photo</button>
        </div>
      </div>
    `;
  }
  const gpsMeta = photo?.gps ? formatPhotoGpsMeta(photo.gps) : (photo?.backfilled ? "No in-app GPS lock" : "GPS missing");
  const retakeLabel = photo?.backfilled ? "Replace Backfill Upload" : "Retake Live Proof";
  return `
    <div class="photo-slot ${isRequired ? "" : "extra"}">
      ${inputEl}
      <div class="row" style="justify-content:space-between; width:100%;">
        <div class="slot-title">${escapeHtml(label)}</div>
        ${badge}
      </div>
      ${thumb}
      <div class="slot-meta">${timestamp || "Timestamp pending"}</div>
      <div class="muted small" style="width:100%;">${escapeHtml(gpsMeta)}</div>
      ${renderPhotoVerificationChips(photo)}
      <div class="row" style="justify-content:flex-end; width:100%;">
        ${locked ? "" : `<button type="button" class="btn ghost small" data-action="openSlotCamera" data-input-id="${inputId}" ${demoAttrs}>${escapeHtml(retakeLabel)}</button>`}
        ${locked ? "" : `<button type="button" class="btn ghost small" data-action="removeSlotPhoto" data-location-id="${loc.id}" data-slot-key="${slotKey}" ${demoAttrs}>Remove</button>`}
      </div>
    </div>
  `;
}

async function updateTerminalPorts(locationId, nextPorts){
  const node = state.activeNode;
  if (!node) return false;
  const loc = node.splice_locations.find(x => x.id === locationId);
  if (!loc) return false;
  if (isLocationBillingLocked(loc.id)){
    toast("Billing locked", "Terminal ports are locked after billing is ready.");
    return false;
  }
  const normalized = normalizeTerminalPorts(nextPorts);
  if (normalized === loc.terminal_ports) return true;
  if (isDemo){
    loc.terminal_ports = normalized;
    renderLocations();
    renderProofChecklist();
    toast("Ports saved", `Terminal ports set to ${normalized}.`);
    return true;
  }
  const { error } = await state.client
    .from("splice_locations")
    .update({ terminal_ports: normalized })
    .eq("id", loc.id);
  if (error){
    toast("Update failed", error.message);
    return false;
  }
  loc.terminal_ports = normalized;
  renderLocations();
  renderProofChecklist();
  toast("Ports saved", `Terminal ports set to ${normalized}.`);
  return true;
}

function cancelSpliceLocationNameEdit(locationId){
  const node = state.activeNode;
  if (!node) return;
  const loc = node.splice_locations.find(x => x.id === locationId);
  if (!loc) return;
  loc.isEditingName = false;
  loc.pending_label = null;
  renderLocations();
}

async function saveSpliceLocationName(locationId, nextName){
  const node = state.activeNode;
  if (!node) return;
  const loc = node.splice_locations.find(x => x.id === locationId);
  if (!loc) return;
  if (isLocationBillingLocked(loc.id)){
    toast("Billing locked", "Location name is locked after billing is ready.");
    loc.isEditingName = false;
    loc.pending_label = null;
    renderLocations();
    return;
  }
  const trimmed = String(nextName || "").trim();
  const currentLabel = String(loc.label || "").trim();
  if (trimmed === currentLabel){
    loc.isEditingName = false;
    loc.pending_label = null;
    renderLocations();
    return;
  }
  const ordered = getSortedSpliceLocations(node);
  const index = ordered.findIndex((row) => row.id === loc.id);
  const fallbackName = getSpliceLocationDefaultName(index);
  const nextLabel = trimmed || null;
  const nextLegacyLabel = trimmed || fallbackName;
  if (isDemo){
    loc.label = nextLabel;
    loc.location_label = nextLegacyLabel;
    loc.isEditingName = false;
    loc.pending_label = null;
    renderLocations();
    return;
  }
  const { error } = await state.client
    .from("splice_locations")
    .update({ label: nextLabel, location_label: nextLegacyLabel })
    .eq("id", loc.id);
  if (error){
    toast("Rename failed", error.message);
    return;
  }
  loc.label = nextLabel;
  loc.location_label = nextLegacyLabel;
  loc.isEditingName = false;
  loc.pending_label = null;
  renderLocations();
}

async function updateSpliceLocationCodes(locationId, workCodes, workDescription){
  const node = state.activeNode;
  if (!node) return false;
  const loc = node.splice_locations.find(x => x.id === locationId);
  if (!loc) return false;
  if (isDemo){
    loc.work_codes = Array.isArray(workCodes) ? workCodes : [];
    loc.work_description = workDescription || "";
    toast("Saved", "Codes and description updated.");
    return true;
  }
  const { error } = await state.client
    .from("splice_locations")
    .update({
      work_codes: Array.isArray(workCodes) ? workCodes : [],
      work_description: workDescription || "",
    })
    .eq("id", locationId);
  if (error){
    toast("Save failed", error.message);
    return false;
  }
  loc.work_codes = Array.isArray(workCodes) ? workCodes : [];
  loc.work_description = workDescription || "";
  toast("Saved", "Codes and description updated.");
  return true;
}

let deleteSpliceModalState = { locationId: null };

function ensureDeleteSpliceModal(){
  let modal = document.getElementById("deleteSpliceModal");
  if (modal) return modal;
  modal = document.createElement("div");
  modal.id = "deleteSpliceModal";
  modal.className = "modal-backdrop";
  modal.innerHTML = `
    <div class="modal">
      <div class="modal-title">Delete splice location?</div>
      <div class="modal-body">This removes this location and all photos. This cannot be undone.</div>
      <input id="deleteSpliceConfirmInput" class="input compact" placeholder="Type DELETE to confirm" />
      <div class="modal-actions">
        <button class="btn ghost" data-action="cancel">Cancel</button>
        <button class="btn danger" data-action="confirm" disabled>Delete</button>
      </div>
    </div>
  `;
  document.body.appendChild(modal);
  const input = modal.querySelector("#deleteSpliceConfirmInput");
  const cancelBtn = modal.querySelector("[data-action='cancel']");
  const confirmBtn = modal.querySelector("[data-action='confirm']");

  const updateState = () => {
    confirmBtn.disabled = input.value.trim() !== "DELETE";
  };

  input.addEventListener("input", updateState);
  cancelBtn.addEventListener("click", () => closeDeleteSpliceModal());
  modal.addEventListener("click", (e) => {
    if (e.target === modal) closeDeleteSpliceModal();
  });
  confirmBtn.addEventListener("click", async () => {
    if (confirmBtn.disabled) return;
    confirmBtn.disabled = true;
    const prior = confirmBtn.textContent;
    confirmBtn.textContent = "Deleting...";
    const ok = await deleteSpliceLocation(deleteSpliceModalState.locationId, { skipConfirm: true });
    confirmBtn.textContent = prior;
    updateState();
    if (ok) closeDeleteSpliceModal();
  });
  updateState();
  return modal;
}

function openDeleteSpliceLocationModal(locationId){
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const node = state.activeNode;
  if (!node) return;
  const canDelete = SpecCom.helpers.isRoot() || BUILD_MODE || Boolean(state.user);
  if (!canDelete){
    toast("Not allowed", "Only authorized team members can delete locations.");
    return;
  }
  const modal = ensureDeleteSpliceModal();
  deleteSpliceModalState.locationId = locationId;
  const input = modal.querySelector("#deleteSpliceConfirmInput");
  const confirmBtn = modal.querySelector("[data-action='confirm']");
  input.value = "";
  confirmBtn.disabled = true;
  modal.classList.add("show");
  setTimeout(() => input.focus(), 0);
}

function closeDeleteSpliceModal(){
  const modal = document.getElementById("deleteSpliceModal");
  if (!modal) return;
  modal.classList.remove("show");
  deleteSpliceModalState.locationId = null;
}

async function deleteSpliceLocation(locationId, options = {}){
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return false;
  }
  const node = state.activeNode;
  if (!node) return false;
  const loc = node.splice_locations.find(l => l.id === locationId);
  if (!loc) return false;
  const canDelete = SpecCom.helpers.isRoot() || BUILD_MODE || Boolean(state.user);
  if (!canDelete){
    toast("Not allowed", "Only authorized team members can delete locations.");
    return false;
  }
  if (loc.isDeleting) return false;
  if (!options.skipConfirm){
    const confirmText = "Delete splice location?\nThis will remove the splice location and all its photos. This cannot be undone.";
    if (!confirm(confirmText)) return false;
    const typed = prompt("Type DELETE to confirm.");
    if (typed !== "DELETE"){
      toast("Delete canceled", "Type DELETE to confirm.");
      return false;
    }
  }

  loc.isDeleting = true;
  renderLocations();

  if (isDemo){
    node.splice_locations = (node.splice_locations || []).filter(l => l.id !== loc.id);
    if (state.billingLocation?.id === loc.id){
      state.billingLocation = null;
      renderBillingDetail();
    }
    renderLocations();
    updateKPI();
    renderProofChecklist();
    await loadBillingLocations(state.activeProject?.id || null);
    toast("Deleted", "Splice location deleted.");
    return true;
  }

  const { data: photos, error: photoErr } = await state.client
    .from("splice_location_photos")
    .select("photo_path")
    .eq("splice_location_id", loc.id);
  if (photoErr){
    toast("Delete failed", photoErr.message);
    loc.isDeleting = false;
    renderLocations();
    return false;
  }

  const photoPaths = (photos || []).map(row => row.photo_path).filter(Boolean);
  if (photoPaths.length){
    const { error: storageErr } = await state.client
      .storage
      .from("proof-photos")
      .remove(photoPaths);
    if (storageErr){
      toast("Storage cleanup failed", storageErr.message);
    }
  }

  const { error: deletePhotosErr } = await state.client
    .from("splice_location_photos")
    .delete()
    .eq("splice_location_id", loc.id);
  if (deletePhotosErr){
    toast("Delete failed", deletePhotosErr.message);
    loc.isDeleting = false;
    renderLocations();
    return false;
  }

  const { error: deleteLocErr } = await state.client
    .from("splice_locations")
    .delete()
    .eq("id", loc.id);
  if (deleteLocErr){
    toast("Delete failed", deleteLocErr.message);
    loc.isDeleting = false;
    renderLocations();
    return false;
  }

  node.splice_locations = (node.splice_locations || []).filter(l => l.id !== loc.id);
  if (state.billingLocation?.id === loc.id){
    state.billingLocation = null;
    renderBillingDetail();
  }
  renderLocations();
  updateKPI();
  renderProofChecklist();
  await loadBillingLocations(state.activeProject?.id || null);
  toast("Deleted", "Splice location deleted.");
  return true;
}

async function prepareSlotCameraCapture(inputId){
  const input = document.querySelector(`input[type="file"][data-input-id="${inputId}"]`);
  if (!(input instanceof HTMLInputElement)) return false;
  const gps = await getCurrentGps({ enableHighAccuracy: true, timeout: 12000, maximumAge: 0 });
  if (!gps){
    toast("GPS required", "A live GPS lock is required before taking a proof photo.");
    return false;
  }
  const captureContext = {
    gps: {
      lat: gps.lat,
      lng: gps.lng,
      accuracy_m: Number.isFinite(gps.accuracy) ? gps.accuracy : null,
    },
    captured_at: nowISO(),
    source: "camera",
    device_user_agent: navigator.userAgent || "",
  };
  state.lastGPS = { ...captureContext.gps };
  state.pendingPhotoCaptureContexts[inputId] = captureContext;
  input.click();
  return true;
}

async function handleSpliceSlotPhotoUpload(locationId, slotKey, file){
  const node = state.activeNode;
  if (!node) return;
  if (!file){
    toast("Choose a photo", "Pick a photo file first.");
    return;
  }
  const loc = node.splice_locations.find(l => l.id === locationId);
  if (!loc){
    toast("Location missing", "Splice location not found.");
    return;
  }
  if (isLocationBillingLocked(loc.id)){
    toast("Billing locked", "Photos are locked after billing is ready.");
    return;
  }
  const inputId = getSlotInputId(locationId, slotKey);
  const captureContext = state.pendingPhotoCaptureContexts[inputId] || null;
  delete state.pendingPhotoCaptureContexts[inputId];
  const gps = captureContext?.gps || null;
  const takenAt = captureContext?.captured_at || nowISO();
  if (!gps){
    toast("GPS required", "Live proof photos need a fresh GPS lock before they can be saved.");
    return;
  }
  const previewUrl = URL.createObjectURL(file);
  loc.photosBySlot = loc.photosBySlot || {};
  loc.photosBySlot[slotKey] = {
    previewUrl,
    taken_at: takenAt,
    pending: true,
    gps,
    source: "camera",
    proof_type: slotKey,
    device_user_agent: captureContext?.device_user_agent || navigator.userAgent || "",
  };
  renderLocations();
  renderProofChecklist();

  if (isDemo){
    loc.photosBySlot[slotKey] = { previewUrl, taken_at: takenAt, gps, source: "camera", proof_type: slotKey };
    renderLocations();
    renderProofChecklist();
    return;
  }

  const uploadPath = await uploadProofPhoto(file, node.id, `splice-location/${locationId}`, {
    locationId,
  });
  if (!uploadPath){
    delete loc.photosBySlot[slotKey];
    renderLocations();
    renderProofChecklist();
    return;
  }

  const splicePhotoPayload = {
    splice_location_id: loc.id,
    slot_key: slotKey,
    photo_path: uploadPath,
    taken_at: takenAt,
    gps_lat: gps?.lat ?? null,
    gps_lng: gps?.lng ?? null,
    gps_accuracy_m: gps?.accuracy_m ?? null,
    uploaded_by: state.user?.id || null,
    source: "camera",
    proof_type: slotKey,
    device_user_agent: captureContext?.device_user_agent || navigator.userAgent || "",
  };
  let { data, error } = await state.client
    .from("splice_location_photos")
    .upsert(splicePhotoPayload, { onConflict: "splice_location_id,slot_key" })
    .select("photo_path, taken_at, gps_lat, gps_lng, gps_accuracy_m, source, proof_type, device_user_agent, backfilled")
    .maybeSingle();
  if (error && ["proof_type", "device_user_agent"].some((col) => isMissingColumnError(error, col))){
    const fallbackPayload = { ...splicePhotoPayload };
    delete fallbackPayload.proof_type;
    delete fallbackPayload.device_user_agent;
    ({ data, error } = await state.client
      .from("splice_location_photos")
      .upsert(fallbackPayload, { onConflict: "splice_location_id,slot_key" })
      .select("photo_path, taken_at, gps_lat, gps_lng, gps_accuracy_m, source, backfilled")
      .maybeSingle());
  }

  if (error){
    logPhotoFlowError("splice proof insert failed", error, { locationId: loc.id, slotKey, uploadPath });
    delete loc.photosBySlot[slotKey];
    renderLocations();
    renderProofChecklist();
    toast("Upload failed", error.message);
    return;
  }

  loc.photosBySlot[slotKey] = {
    path: data?.photo_path || uploadPath,
    taken_at: data?.taken_at || takenAt,
    gps: data?.gps_lat != null && data?.gps_lng != null
      ? { lat: data.gps_lat, lng: data.gps_lng, accuracy_m: data.gps_accuracy_m }
      : null,
    previewUrl,
    source: data?.source || "camera",
    proof_type: data?.proof_type || slotKey,
    device_user_agent: data?.device_user_agent || captureContext?.device_user_agent || "",
    backfilled: Boolean(data?.backfilled),
  };
  await loadSplicePhotos(node.id, [loc]);
  renderLocations();
  renderProofChecklist();
}

async function deleteSpliceSlotPhoto(locationId, slotKey){
  if (isDemoUser()){
    toast("Demo restriction", t("availableInProduction"));
    return;
  }
  const node = state.activeNode;
  if (!node) return;
  const loc = node.splice_locations.find(l => l.id === locationId);
  if (!loc) return;
  if (isLocationBillingLocked(loc.id)){
    toast("Billing locked", "Photos are locked after billing is ready.");
    return;
  }
  const existing = loc.photosBySlot?.[slotKey];
  if (!existing){
    toast("No photo", "No photo found for this slot.");
    return;
  }
  if (isDemo){
    delete loc.photosBySlot[slotKey];
    renderLocations();
    renderProofChecklist();
    return;
  }

  const path = existing.path || existing.photo_path;
  if (path){
    const { error: storageErr } = await state.client
      .storage
      .from("proof-photos")
      .remove([path]);
    if (storageErr){
      toast("Remove failed", storageErr.message);
    }
  }

  const { error } = await state.client
    .from("splice_location_photos")
    .delete()
    .eq("splice_location_id", loc.id)
    .eq("slot_key", slotKey);
  if (error){
    toast("Remove failed", error.message);
    return;
  }
  delete loc.photosBySlot[slotKey];
  renderLocations();
  renderProofChecklist();
}

function renderInventory(){
  const wrap = $("inventory");
  wrap.innerHTML = "";
  const node = state.activeNode;
  if (!node){
    wrap.innerHTML = `<div class="muted small">${t("openNodePrompt")}</div>`;
    return;
  }
  const items = node.inventory_checks || [];
  if (!items.length){
    wrap.innerHTML = `<div class="muted small">${t("noInventoryItems")}</div>`;
    return;
  }

  items.forEach((it) => {
    const planned = Number.isFinite(it.planned_qty) ? it.planned_qty : (it.qty_used || 0);
    const remaining = getRemainingForItem(it);
    const usageItemId = getUsageItemId(it);
    const defaultQty = it.qty_used || 1;

    const card = document.createElement("div");
    card.className = "card";
    card.style.marginBottom = "12px";
    card.innerHTML = `
      <div class="row" style="justify-content:space-between;">
        <div>
          <div style="font-weight:900">${escapeHtml(it.item_name)}</div>
          <div class="muted small">${escapeHtml(it.item_code)}</div>
          <div class="muted small">Planned: <b>${planned}</b> | Remaining: <b>${remaining}</b></div>
          <div class="muted small">Default qty: <b>${defaultQty}</b></div>
        </div>
        <div class="row">
          <span class="chip"><span class="dot ${it.completed ? "ok" : "warn"}"></span><span>${it.completed ? "Checked" : "Pending"}</span></span>
          <input class="input" style="width:90px;" type="number" min="1" step="1" value="${defaultQty}" data-qty-for="${usageItemId}"/>
          <button class="btn secondary" data-action="submitUsage" data-id="${usageItemId}">Submit usage</button>
          <button class="btn secondary" data-action="toggleInv" data-id="${it.id}">${it.completed ? "Uncheck" : "Check"}</button>
        </div>
      </div>
      <div style="height:10px"></div>
      <img class="item-photo" src="${it.photo}" alt="item photo"/>
    `;
    card.addEventListener("click", async (e) => {
      const btn = e.target.closest("button");
      if (!btn) return;
      const id = btn.dataset.id;
      const action = btn.dataset.action;
      if (action === "toggleInv"){
        const item = node.inventory_checks.find(x => x.id === id);
        if (!item) return;
        const next = !item.completed;
        if (isDemo){
          item.completed = next;
          renderInventory();
          updateKPI();
        } else {
          const { error } = await state.client
            .from("node_inventory")
            .update({ completed: next, completed_by: state.user?.id || null })
            .eq("id", item.id);
          if (error){
            toast("Update failed", error.message);
            return;
          }
          item.completed = next;
          renderInventory();
          updateKPI();
        }
      } else if (action === "submitUsage"){
        const qtyInput = card.querySelector(`[data-qty-for="${id}"]`);
        const qty = Number.parseInt(qtyInput?.value || "0", 10);
        submitUsage(id, qty);
      }
    });
    wrap.appendChild(card);
  });
}

function setProofStatus(){
  const el = $("photoStatus");
  const mini = $("photoStatusMini");
  if (!state.lastProof){
    if (el) el.textContent = "No photo captured";
    if (mini) mini.textContent = "No photo captured yet.";
    renderProofPreview();
    return;
  }
  const gps = state.lastProof.gps
    ? `${state.lastProof.gps.lat.toFixed(6)}, ${state.lastProof.gps.lng.toFixed(6)}`
    : "GPS missing";
  if (el) el.textContent = `Photo ready: ${state.lastProof.captured_at} (${gps})`;
  if (mini) mini.textContent = `Photo ready: ${state.lastProof.captured_at}`;
  renderProofPreview();
}

function renderProofPreview(){
  const wrap = $("photoPreview");
  if (!wrap) return;
  const items = [
    state.lastProof ? { label: "Usage photo", data: state.lastProof } : null,
  ].filter(Boolean);

  if (!items.length){
    wrap.innerHTML = '<div class="muted small">No photo captured yet.</div>';
    return;
  }

  wrap.innerHTML = items.map((item) => {
    const photoUrl = item.data.previewUrl || "";
    const gps = item.data.gps
      ? `${item.data.gps.lat.toFixed(6)}, ${item.data.gps.lng.toFixed(6)}`
      : "GPS missing";
    return `
      <div class="row" style="gap:16px; align-items:flex-start;">
        ${photoUrl ? `<img src="${photoUrl}" alt="usage photo" />` : ""}
        <div>
          <div style="font-weight:900">${item.label}</div>
          <div class="muted small">${item.data.captured_at}</div>
          <div class="muted small">${gps}</div>
        </div>
      </div>
    `;
  }).join("<div class=\"hr\"></div>");
}

function clearProof(){
  state.lastProof = null;
  state.cameraInvalidated = false;
  setProofStatus();
  renderProofPreview();
}

function syncNodeWorkspaceControls(){
  const closeBtn = $("btnCloseNode");
  if (closeBtn){
    closeBtn.hidden = !state.activeNode;
  }
}

function refreshActiveNodeWorkspace(){
  syncNodeWorkspaceControls();
  renderLocations();
  renderInventory();
  renderInvoicePanel();
  renderAllowedQuantities();
  renderAlerts();
  renderProofChecklist();
  renderBillingDetail();
  updateKPI();
}

function closeActiveNodeWorkspace(){
  if (!state.activeNode) return;
  state.activeNode = null;
  clearProof();
  const input = $("nodeNumber");
  if (input) input.value = "";
  refreshActiveNodeWorkspace();
  toast("Site closed", "Open a site when you are ready to continue.");
}

function clearUsageProof(){
  state.lastProof = null;
  state.cameraInvalidated = false;
  setProofStatus();
  renderProofPreview();
}

async function captureUsageProof(){
  const shot = await captureFrame();
  if (!shot) return;
  state.lastProof = {
    file: makeFileFromBlob(shot.blob),
    captured_at: shot.captured_at,
    gps: shot.gps,
    previewUrl: shot.previewUrl,
    camera: true,
  };
  setProofStatus();
}

async function uploadBackfillPhoto(file, projectId, nodeId, locationId, photoType){
  if (!state.client) return null;
  const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, "_");
  const ts = Date.now();
  const root = projectId || "project";
  const path = `${root}/${nodeId}/${locationId}/${photoType}/${ts}-${safeName}`;
  const { data, error } = await state.client
    .storage
    .from("proof-photos")
    .upload(path, file, { contentType: file.type });
  if (error){
    logPhotoFlowError("backfill storage upload failed", error, { path, nodeId, locationId, photoType });
    toast("Upload failed", error.message);
    return null;
  }
  return data?.path || path;
}

async function handleBackfillPhotoUpload(photoType, file){
  const node = state.activeNode;
  const projectId = state.activeProject?.id || null;
  if (!node){
    toast("Open a site", "Select or open a site first.");
    return;
  }
  if (!isOwner()){
    toast("Not allowed", "Authorized access required.");
    return;
  }
  if (!state.nodeProofStatus?.backfill_allowed){
    toast("Backfill locked", "Backfill is not enabled for this site.");
    return;
  }
  if (!file){
    toast("Choose a photo", "Pick a photo file first.");
    return;
  }
  const locId = $("backfillLocationSelect")?.value;
  if (!locId){
    toast("Location required", "Select a splice location first.");
    return;
  }
  const loc = node.splice_locations.find(l => l.id === locId);
  if (!loc){
    toast("Location missing", "Splice location not found.");
    return;
  }
  const slotKey = getBackfillSlotKey(loc, photoType);
  if (!slotKey){
    toast("Slots full", "All 8 photo slots already have photos. Use the slot grid to retake.");
    return;
  }
  const previewUrl = URL.createObjectURL(file);
  const exifTakenAt = file.lastModified ? new Date(file.lastModified).toISOString() : null;
  const takenAt = exifTakenAt || nowISO();
  loc.photosBySlot = loc.photosBySlot || {};
  loc.photosBySlot[slotKey] = {
    previewUrl,
    taken_at: takenAt,
    pending: true,
    backfilled: true,
    source: "backfill_upload",
    proof_type: photoType,
    device_user_agent: navigator.userAgent || "",
  };
  renderLocations();
  renderProofChecklist();

  if (isDemo){
    loc.photosBySlot[slotKey] = {
      previewUrl,
      taken_at: takenAt,
      backfilled: true,
      source: "backfill_upload",
      proof_type: photoType,
    };
    renderLocations();
    renderProofChecklist();
    return;
  }

  const uploadPath = await uploadBackfillPhoto(file, projectId, node.id, loc.id, photoType);
  if (!uploadPath){
    delete loc.photosBySlot[slotKey];
    renderLocations();
    renderProofChecklist();
    return;
  }

  const backfillPayload = {
    splice_location_id: loc.id,
    slot_key: slotKey,
    photo_path: uploadPath,
    taken_at: takenAt,
    uploaded_by: state.user?.id || null,
    source: "backfill_upload",
    backfilled: true,
    exif_taken_at: exifTakenAt,
    proof_type: photoType,
    device_user_agent: navigator.userAgent || "",
  };
  let { data, error } = await state.client
    .from("splice_location_photos")
    .upsert(backfillPayload, { onConflict: "splice_location_id,slot_key" })
    .select("photo_path, taken_at, source, backfilled, proof_type, device_user_agent")
    .maybeSingle();
  if (error && ["proof_type", "device_user_agent"].some((col) => isMissingColumnError(error, col))){
    const fallbackPayload = { ...backfillPayload };
    delete fallbackPayload.proof_type;
    delete fallbackPayload.device_user_agent;
    ({ data, error } = await state.client
      .from("splice_location_photos")
      .upsert(fallbackPayload, { onConflict: "splice_location_id,slot_key" })
      .select("photo_path, taken_at, source, backfilled")
      .maybeSingle());
  }

  if (error){
    logPhotoFlowError("backfill insert failed", error, { locationId: loc.id, slotKey, uploadPath, photoType });
    delete loc.photosBySlot[slotKey];
    renderLocations();
    renderProofChecklist();
    toast("Upload failed", error.message);
    return;
  }

  loc.photosBySlot[slotKey] = {
    path: data?.photo_path || uploadPath,
    taken_at: data?.taken_at || takenAt,
    previewUrl,
    backfilled: Boolean(data?.backfilled ?? true),
    source: data?.source || "backfill_upload",
    proof_type: data?.proof_type || photoType,
    device_user_agent: data?.device_user_agent || navigator.userAgent || "",
  };
  await loadNodeProofStatus(node.id);
  renderLocations();
  renderProofChecklist();
}

async function uploadProofPhoto(file, nodeId, prefix, ctx = {}){
  if (!state.client) return null;
  const safeName = file.name.replace(/[^a-zA-Z0-9._-]/g, "_");
  const orgSegment = String(ctx?.orgId || state.profile?.org_id || "org-unknown");
  const projectSegment = String(ctx?.projectId || state.activeProject?.id || "project-unknown");
  const locationSegment = String(ctx?.locationId || nodeId || "location-unknown");
  const fileId = (globalThis.crypto && typeof globalThis.crypto.randomUUID === "function")
    ? globalThis.crypto.randomUUID()
    : `${Date.now()}-${Math.random().toString(16).slice(2, 10)}`;
  const folder = `${orgSegment}/${projectSegment}/${locationSegment}/${prefix || "photos"}`;
  const path = `${folder}/${fileId}-${safeName}`;
  const { data, error } = await state.client
    .storage
    .from("proof-photos")
    .upload(path, file, { contentType: file.type });
  if (error){
    logPhotoFlowError("proof storage upload failed", error, { path, nodeId, prefix });
    toast("Upload failed", error.message);
    return null;
  }
  return data?.path || path;
}

async function recordProofUpload(payload){
  if (isDemo) return;
  if (!state.client) return;
  const { error } = await state.client.from("proof_uploads").insert({
    device_info: navigator.userAgent,
    camera: true,
    ...payload,
  });
  if (error){
    toast("Photo log failed", error.message);
  }
}

async function submitUsage(itemId, qty){
  const node = state.activeNode;
  if (!node) return;
  if (!Number.isFinite(qty) || qty <= 0){
    toast("Qty required", "Enter a valid quantity to submit.");
    return;
  }
  if (!state.lastProof?.file || !state.lastProof?.gps || !state.lastProof?.captured_at || state.cameraInvalidated){
    toast("Photos required", "Capture a live photo with GPS before submitting usage.");
    return;
  }
  if (!state.lastProof.camera){
    toast("Camera required", "Camera capture required. Gallery uploads are not allowed.");
    return;
  }
  const jobNumber = state.activeProject?.job_number;
  if (!jobNumber){
    toast("Job required", "Job number required to submit usage photos.");
    return;
  }

  const plannedItem = node.inventory_checks.find(i => getUsageItemId(i) === itemId);
  if (!plannedItem){
    toast("Item missing", "This item is no longer available.");
    return;
  }
  const unitTypeId = resolveUnitTypeIdForItem(plannedItem);
  const remaining = getRemainingForItem(plannedItem);
  const status = qty > remaining ? "needs_approval" : "approved";

  if (isDemo){
    state.demo.usageEvents.push({
      id: `use-${Date.now()}`,
      node_id: node.id,
      item_id: itemId,
      unit_type_id: unitTypeId,
      qty,
      status,
      captured_at: state.lastProof.captured_at,
      captured_at_client: state.lastProof.captured_at,
      gps_lat: state.lastProof.gps.lat,
      gps_lng: state.lastProof.gps.lng,
      gps_accuracy_m: state.lastProof.gps.accuracy_m,
      photo_path: "demo-only",
      proof_required: true,
      camera: true,
    });
    if (status === "needs_approval"){
      toast("Needs approval", "Overage submitted and pending approval.");
    } else {
      toast("Usage submitted", "Approved usage recorded.");
    }
    if (unitTypeId){
      maybeCreateDemoAlert(node.id, unitTypeId);
      state.alerts = state.demo.alerts || [];
      updateAlertsBadge();
      renderAlerts();
    }
    clearUsageProof();
    state.cameraInvalidated = false;
    renderInventory();
    renderAllowedQuantities();
    renderProofChecklist();
    return;
  }

  const uploadPath = await uploadProofPhoto(state.lastProof.file, node.id, "usage");
  if (!uploadPath) return;

  const { data, error } = await state.client
    .from("usage_events")
    .insert({
      node_id: node.id,
      item_id: itemId,
      unit_type_id: unitTypeId,
      qty,
      status,
      photo_path: uploadPath,
      captured_at_client: state.lastProof.captured_at,
      gps_lat: state.lastProof.gps.lat,
      gps_lng: state.lastProof.gps.lng,
      gps_accuracy_m: state.lastProof.gps.accuracy_m,
      proof_required: true,
      camera: true,
    })
    .select("id");

  if (error){
    toast("Usage error", error.message);
    return;
  }
  const usageId = data?.[0]?.id;
  if (usageId){
    await recordProofUpload({
      node_id: node.id,
      usage_event_id: usageId,
      photo_url: uploadPath,
      lat: state.lastProof.gps.lat,
      lng: state.lastProof.gps.lng,
      captured_at_client: state.lastProof.captured_at,
      job_number: jobNumber,
      camera: true,
      captured_by: state.user?.id || null,
    });
  }
  if (status === "needs_approval"){
    toast("Needs approval", "Overage submitted and pending approval.");
  } else {
    toast("Usage submitted", "Approved usage recorded.");
  }
  clearUsageProof();
  state.cameraInvalidated = false;
  await loadUsageEvents(node.id);
  await loadAlerts(node.id);
  renderInventory();
  renderAllowedQuantities();
  renderAlerts();
  renderProofChecklist();
}

async function loadUsageEvents(nodeId){
  if (isDemo) return;
  const { data, error } = await state.client
    .from("usage_events")
    .select("id,node_id,item_id,unit_type_id,qty,status,photo_path,gps_lat,gps_lng,captured_at_server,captured_at_client,proof_required,camera")
    .eq("node_id", nodeId);
  if (error){
    toast("Usage load error", error.message);
    return;
  }
  state.usageEvents = data || [];
}

async function loadInvoices(nodeId){
  if (isDemo) return;
  const [subRes, primeRes] = await Promise.all([
    state.client
      .from("sub_invoices")
      .select("id, invoice_number, status, total, currency")
      .eq("node_id", nodeId),
    state.client
      .from("prime_invoices")
      .select("id, invoice_number, status, total, currency")
      .eq("node_id", nodeId),
  ]);
  if (subRes.error){
    toast("Invoice load error", subRes.error.message);
  }
  if (primeRes.error){
    toast("Invoice load error", primeRes.error.message);
  }
  if (state.activeNode && state.activeNode.id === nodeId){
    state.activeNode.invoices = {
      sub: subRes.data || [],
      prime: primeRes.data || [],
    };
  }
}

function subscribeUsageEvents(nodeId){
  if (isDemo || !state.client) return;
  if (state.realtime.usageChannel){
    state.client.removeChannel(state.realtime.usageChannel);
    state.realtime.usageChannel = null;
  }
  state.realtime.usageChannel = state.client
    .channel(`usage-events-${nodeId}`)
    .on(
      "postgres_changes",
      { event: "*", schema: "public", table: "usage_events", filter: `node_id=eq.${nodeId}` },
      async () => {
        await loadUsageEvents(nodeId);
        await loadAlerts(nodeId);
        renderInventory();
        renderAllowedQuantities();
        renderProofChecklist();
        renderAlerts();
      }
    )
    .subscribe();
}

function toLocalDateISO(value = new Date()){
  const d = value instanceof Date ? new Date(value.getTime()) : new Date(value);
  const year = d.getFullYear();
  const month = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${year}-${month}-${day}`;
}

function getWeekEndingSaturdayISO(reference = new Date()){
  const d = reference instanceof Date ? new Date(reference.getTime()) : new Date(reference);
  const day = d.getDay();
  d.setDate(d.getDate() + (6 - day));
  return toLocalDateISO(d);
}

function parseInvoiceNumberPart(value){
  const n = Number(value);
  return Number.isFinite(n) ? n : 0;
}

function parseInvoiceCurrency(value){
  if (value === null || value === undefined || value === "") return 0;
  const n = Number.parseFloat(String(value).replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(n) ? n : 0;
}

function roundInvoiceCurrency(value){
  return Math.round((Number(value) || 0) * 100) / 100;
}

function getOfficeInvoiceLineTotal(item){
  const qty = parseInvoiceCurrency(item?.qty);
  const unitRate = parseInvoiceCurrency(item?.unit_rate);
  return roundInvoiceCurrency(qty * unitRate);
}

function getNextOfficeInvoiceNumber(){
  const dateKey = toLocalDateISO(new Date()).replace(/-/g, "");
  const prefix = `INV-${dateKey}-`;
  const source = [...(state.officeInvoices.records || [])];
  if (state.officeInvoices.draft?.invoice_number){
    source.push({ invoice_number: state.officeInvoices.draft.invoice_number });
  }
  const used = source
    .map((row) => String(row?.invoice_number || ""))
    .filter((value) => value.startsWith(prefix))
    .map((value) => parseInvoiceNumberPart(value.split("-")[2]))
    .filter((n) => Number.isFinite(n) && n > 0);
  const next = (used.length ? Math.max(...used) : 0) + 1;
  return `${prefix}${String(next).padStart(3, "0")}`;
}

function normalizeOfficeRecentValues(raw){
  const values = Array.isArray(raw) ? raw : [];
  const seen = new Set();
  const out = [];
  values.forEach((value) => {
    const clean = String(value || "").trim();
    if (!clean || seen.has(clean.toLowerCase())) return;
    seen.add(clean.toLowerCase());
    out.push(clean);
  });
  return out.slice(0, 10);
}

function ensureOfficeInvoiceStateLoaded(){
  if (state.officeInvoices.loaded) return;
  const recordsRaw = safeLocalStorageGet(OFFICE_INVOICE_RECORDS_KEY);
  const recentsRaw = safeLocalStorageGet(OFFICE_INVOICE_RECENTS_KEY);
  const draftRaw = safeLocalStorageGet(OFFICE_INVOICE_DRAFT_KEY);
  if (recordsRaw){
    try{
      const parsed = JSON.parse(recordsRaw);
      state.officeInvoices.records = Array.isArray(parsed) ? parsed : [];
    } catch {}
  }
  if (recentsRaw){
    try{
      const parsed = JSON.parse(recentsRaw) || {};
      state.officeInvoices.recents = {
        company: normalizeOfficeRecentValues(parsed.company),
        billTo: normalizeOfficeRecentValues(parsed.billTo),
        jobNumber: normalizeOfficeRecentValues(parsed.jobNumber),
        location: normalizeOfficeRecentValues(parsed.location),
      };
    } catch {}
  }
  if (draftRaw){
    try{
      const parsed = JSON.parse(draftRaw);
      if (parsed && typeof parsed === "object" && parsed.id){
        state.officeInvoices.draft = parsed;
      }
    } catch {}
  }
  state.officeInvoices.loaded = true;
}

function persistOfficeInvoiceState(){
  safeLocalStorageSet(OFFICE_INVOICE_RECORDS_KEY, JSON.stringify(state.officeInvoices.records || []));
  safeLocalStorageSet(OFFICE_INVOICE_RECENTS_KEY, JSON.stringify(state.officeInvoices.recents || {}));
  if (state.officeInvoices.draft){
    safeLocalStorageSet(OFFICE_INVOICE_DRAFT_KEY, JSON.stringify(state.officeInvoices.draft));
  } else {
    safeLocalStorageSet(OFFICE_INVOICE_DRAFT_KEY, "");
  }
}

function normalizeKsInvoiceNumber(value){
  return String(value || "").trim();
}

function buildKsInvoiceKey(invoiceNumber){
  const clean = normalizeKsInvoiceNumber(invoiceNumber);
  if (!clean) return "";
  if (/^speccom_/i.test(clean)) return clean;
  return `SpecCom_${clean}`;
}

function normalizeKsInvoiceLookup(value){
  return normalizeKsInvoiceNumber(value).toLowerCase();
}

function isUuidLike(value){
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(String(value || "").trim());
}

function parseInvoiceNumberFromFilename(fileName){
  const base = String(fileName || "").trim().split(/[\\/]/).pop() || "";
  if (!base) return null;
  const withoutExt = base.replace(/\.[^.]+$/, "");
  const clean = withoutExt.replace(/\s+/g, "_").trim();
  const match = clean.match(/([a-z0-9]+(?:[_-][a-z0-9]+){1,})$/i);
  if (!match?.[1]) return null;
  return match[1].replace(/-/g, "_");
}

function isSkippableZipEntry(entryName){
  const raw = String(entryName || "").replace(/\\/g, "/");
  if (!raw || raw.endsWith("/")) return { skip: true, reason: "directory" };
  const base = raw.split("/").pop() || "";
  if (!base) return { skip: true, reason: "empty-name" };
  if (base.startsWith("~$")) return { skip: true, reason: "temp-file" };
  if (base.startsWith(".")) return { skip: true, reason: "hidden-file" };
  if (/__macosx/i.test(raw)) return { skip: true, reason: "os-metadata" };
  return { skip: false, reason: "" };
}

function parseMoneyNumber(value){
  const num = Number.parseFloat(String(value || "").replace(/[^0-9.\-]/g, ""));
  return Number.isFinite(num) ? num : null;
}

function parseInvoiceDateText(value){
  const raw = String(value || "").trim();
  if (!raw) return "";
  const match = raw.match(/(\d{1,2})[\/\-](\d{1,2})[\/\-](\d{2,4})/);
  if (!match) return raw;
  const mm = String(match[1]).padStart(2, "0");
  const dd = String(match[2]).padStart(2, "0");
  let yyyy = String(match[3]);
  if (yyyy.length === 2){
    yyyy = Number(yyyy) >= 70 ? `19${yyyy}` : `20${yyyy}`;
  }
  return `${mm}/${dd}/${yyyy}`;
}

async function extractPdfLines(buffer){
  const pdfjsLib = await loadPdfJs();
  const pdf = await pdfjsLib.getDocument({ data: buffer }).promise;
  const lines = [];
  for (let pageNumber = 1; pageNumber <= pdf.numPages; pageNumber += 1){
    const page = await pdf.getPage(pageNumber);
    const content = await page.getTextContent();
    const items = (content?.items || [])
      .map((item) => ({
        text: String(item?.str || "").trim(),
        x: Number(item?.transform?.[4] || 0),
        y: Number(item?.transform?.[5] || 0),
      }))
      .filter((item) => item.text);
    items.sort((a, b) => {
      if (Math.abs(a.y - b.y) > 1.5) return b.y - a.y;
      return a.x - b.x;
    });
    let current = null;
    for (const item of items){
      if (!current || Math.abs(current.y - item.y) > 1.5){
        if (current && current.parts.length){
          lines.push(current.parts.join(" ").replace(/\s+/g, " ").trim());
        }
        current = { y: item.y, parts: [item.text] };
      } else {
        current.parts.push(item.text);
      }
    }
    if (current && current.parts.length){
      lines.push(current.parts.join(" ").replace(/\s+/g, " ").trim());
    }
  }
  return lines.filter(Boolean);
}

function parseKsInvoiceLineItems(lines){
  const items = [];
  let inTable = false;
  for (const rawLine of lines){
    const line = String(rawLine || "").replace(/\s+/g, " ").trim();
    if (!line) continue;
    if (!inTable && /billing\s*code|description.*qty.*rate.*total/i.test(line)){
      inTable = true;
      continue;
    }
    if (!inTable) continue;
    if (/grand\s+total|total\s+due|invoice\s+total/i.test(line)){
      break;
    }
    const match = line.match(/^([A-Z0-9][A-Z0-9_\-./]{1,})\s+(.+?)\s+(-?\d+(?:\.\d+)?)\s+\$?(-?\d[\d,]*(?:\.\d{2})?)\s+\$?(-?\d[\d,]*(?:\.\d{2})?)$/i);
    if (!match) continue;
    items.push({
      code: String(match[1] || "").trim(),
      description: String(match[2] || "").trim(),
      qty: Number.parseFloat(String(match[3] || "0")),
      rate: parseMoneyNumber(match[4]),
      total: parseMoneyNumber(match[5]),
    });
  }
  return items;
}

async function parseKsInvoicePdfData(buffer, { sourceFilename = "", fallbackInvoiceNumber = "" } = {}){
  const parseWarnings = [];
  const parseErrors = [];
  let lines = [];
  try {
    lines = await extractPdfLines(buffer);
  } catch (error){
    parseErrors.push(`pdf-text-extract: ${error?.message || "failed"}`);
  }
  const text = lines.join("\n");
  const invoiceMatch = text.match(/\bINVOICE\s*NO\.?\s*[:#-]?\s*([A-Z0-9]+(?:[_-][A-Z0-9]+)*)\b/i);
  let invoiceNumber = normalizeKsInvoiceNumber(invoiceMatch?.[1] || "").replace(/-/g, "_");
  if (!invoiceNumber){
    invoiceNumber = normalizeKsInvoiceNumber(fallbackInvoiceNumber || "").replace(/-/g, "_");
    if (invoiceNumber){
      parseWarnings.push("invoice_number fallback to filename");
    } else {
      invoiceNumber = `UNPARSED_${Date.now()}`;
      parseErrors.push("invoice_number missing in PDF and filename");
    }
  }
  const invoiceKey = buildKsInvoiceKey(invoiceNumber);
  const invoiceDateMatch = text.match(/\bDATE\b\s*[:\-]?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})\b/i);
  const weekEndingMatch = text.match(/\bWEEK\s*ENDING\b\s*[:\-]?\s*(\d{1,2}[\/\-]\d{1,2}[\/\-]\d{2,4})\b/i);
  const projectMatch = text.match(/\bPROJECT\b\s*[:\-]?\s*([^\n\r]+)/i);
  const nodeMatch = text.match(/\bNODE\b\s*[:\-]?\s*([^\n\r]+)/i);
  let billToCompany = "";
  const billToIndex = lines.findIndex((line) => /\bBILL\s*TO\b/i.test(String(line || "")));
  if (billToIndex >= 0){
    for (let idx = billToIndex + 1; idx < Math.min(lines.length, billToIndex + 6); idx += 1){
      const value = String(lines[idx] || "").trim();
      if (!value) continue;
      if (/^(invoice|date|week|project|node)\b/i.test(value)) continue;
      billToCompany = value;
      break;
    }
  }
  const lineItems = parseKsInvoiceLineItems(lines);
  const totals = Array.from(text.matchAll(/\b(?:GRAND\s+TOTAL|TOTAL\s+DUE|INVOICE\s+TOTAL|TOTAL)\b[^\d\-]*(-?\$?\d[\d,]*(?:\.\d{2})?)/ig));
  const grandTotal = totals.length ? parseMoneyNumber(totals[totals.length - 1][1]) : null;
  if (!grandTotal && grandTotal !== 0){
    parseWarnings.push("grand_total not found");
  }
  if (!lineItems.length){
    parseWarnings.push("line_items not parsed");
  }
  const parseStatus = parseErrors.length
    ? "parse_failed"
    : (parseWarnings.length ? "parse_partial" : "parsed");
  const parseError = parseErrors.concat(parseWarnings).join("; ");
  return {
    invoice_number: invoiceNumber,
    invoice_key: invoiceKey,
    invoice_date: parseInvoiceDateText(invoiceDateMatch?.[1] || ""),
    week_ending: parseInvoiceDateText(weekEndingMatch?.[1] || ""),
    project_name: String(projectMatch?.[1] || "").trim(),
    node_name: String(nodeMatch?.[1] || "").trim(),
    bill_to_company: String(billToCompany || "").trim(),
    source_filename: String(sourceFilename || "").trim(),
    line_items: lineItems,
    grand_total: grandTotal,
    parse_status: parseStatus,
    parse_error: parseError,
  };
}

function findKsInvoiceByRouteRef(invoiceRef){
  const raw = normalizeKsInvoiceNumber(invoiceRef);
  if (!raw) return null;
  const needle = normalizeKsInvoiceLookup(raw);
  if (!needle) return null;
  return (state.ksInvoices.records || []).find((row) => {
    const rowId = normalizeKsInvoiceLookup(row?.id);
    const invoiceNo = normalizeKsInvoiceLookup(row?.invoice_number);
    const invoiceKey = normalizeKsInvoiceLookup(row?.invoice_key || buildKsInvoiceKey(row?.invoice_number));
    if (needle === rowId || needle === invoiceNo || needle === invoiceKey) return true;
    const normalizedNeedleNoPrefix = needle.replace(/^speccom_/, "");
    return normalizedNeedleNoPrefix && normalizedNeedleNoPrefix === invoiceNo;
  }) || null;
}

function getInvoiceDeepLinkCandidates(invoiceRef){
  const raw = normalizeKsInvoiceNumber(invoiceRef);
  if (!raw) return [];
  const key = buildKsInvoiceKey(raw);
  const noPrefix = raw.replace(/^speccom_/i, "");
  const set = new Set([
    raw,
    key,
    noPrefix,
    buildKsInvoiceKey(noPrefix),
  ].filter(Boolean).map((v) => normalizeKsInvoiceNumber(v)));
  return Array.from(set);
}

async function resolveKsInvoiceDeepLinkProjectContext(){
  if (!state.client || !state.user) return;
  const routeInvoice = String(getInvoiceIdFromUrl() || state.officeInvoices.routeInvoiceNumber || "").trim();
  if (!routeInvoice) return;
  const orgId = getInvoiceScopeOrgId();
  if (!orgId) return;
  const candidates = getInvoiceDeepLinkCandidates(routeInvoice);
  if (!candidates.length) return;
  let matched = null;
  for (const candidate of candidates){
    if (isUuidLike(candidate)){
      const byId = await state.client
        .from("ks_invoice_records")
        .select("id, project_id, invoice_number, invoice_key")
        .eq("org_id", orgId)
        .eq("id", candidate)
        .limit(1)
        .maybeSingle();
      if (!byId.error && byId.data){
        matched = byId.data;
        break;
      }
    }
    const invoiceNorm = normalizeKsInvoiceLookup(candidate.replace(/^speccom_/i, ""));
    const keyCandidate = buildKsInvoiceKey(candidate);
    const query = await state.client
      .from("ks_invoice_records")
      .select("id, project_id, invoice_number, invoice_key")
      .eq("org_id", orgId)
      .or(`invoice_key.eq.${keyCandidate},invoice_number_norm.eq.${invoiceNorm},invoice_number.eq.${candidate}`)
      .limit(1)
      .maybeSingle();
    if (!query.error && query.data){
      matched = query.data;
      break;
    }
  }
  if (!matched?.project_id) return;
  if (String(state.activeProject?.id || "") === String(matched.project_id)) return;
  const projectMatch = (state.projects || []).find((p) => String(p?.id || "") === String(matched.project_id));
  if (!projectMatch) return;
  console.info("[invoice-deeplink] switching project context", {
    invoice: routeInvoice,
    project_id: matched.project_id,
  });
  setActiveProjectById(projectMatch.id);
}

function persistKsInvoiceLocalFallback(){
  safeLocalStorageSet(KS_INVOICE_RECORDS_KEY, JSON.stringify(state.ksInvoices.records || []));
  safeLocalStorageSet(KS_INVOICE_BATCHES_KEY, JSON.stringify(state.ksInvoices.batches || []));
}

function ensureKsInvoiceLocalStateLoaded(){
  if (state.ksInvoices.loaded) return;
  try {
    const rawRecords = safeLocalStorageGet(KS_INVOICE_RECORDS_KEY);
    if (rawRecords){
      const parsed = JSON.parse(rawRecords);
      state.ksInvoices.records = Array.isArray(parsed) ? parsed : [];
    }
  } catch {
    state.ksInvoices.records = [];
  }
  try {
    const rawBatches = safeLocalStorageGet(KS_INVOICE_BATCHES_KEY);
    if (rawBatches){
      const parsed = JSON.parse(rawBatches);
      state.ksInvoices.batches = Array.isArray(parsed) ? parsed : [];
    }
  } catch {
    state.ksInvoices.batches = [];
  }
  state.ksInvoices.loaded = true;
}

async function loadKsInvoiceWorkspace(projectId = state.activeProject?.id || null){
  ensureKsInvoiceLocalStateLoaded();
  if (!state.client || !state.user){
    renderInvoicePanel();
    return;
  }
  const orgId = getInvoiceScopeOrgId();
  if (!orgId){
    renderInvoicePanel();
    return;
  }
  state.ksInvoices.loading = true;
  try {
    const ksRecordSelect = "id, org_id, project_id, invoice_number, invoice_key, invoice_number_norm, invoice_date, week_ending, project_name, node_name, bill_to_company, customer_name, source_filename, source_file_path, source_mime, import_batch_id, imported_at, status, notes, line_items, grand_total, parse_status, parse_error, warnings, extracted_data, created_by, updated_at";
    let recordsQuery = state.client
      .from("ks_invoice_records")
      .select(ksRecordSelect)
      .eq("org_id", orgId)
      .order("imported_at", { ascending: false })
      .limit(500);
    if (projectId){
      recordsQuery = recordsQuery.eq("project_id", projectId);
    }
    let { data: recordRows, error: recordsError } = await recordsQuery;
    if (recordsError){
      const message = String(recordsError?.message || "").toLowerCase();
      if (message.includes("invoice_key") && message.includes("does not exist")){
        let fallbackQuery = state.client
          .from("ks_invoice_records")
          .select("id, org_id, project_id, invoice_number, invoice_number_norm, customer_name, source_filename, source_file_path, source_mime, import_batch_id, imported_at, status, notes, warnings, extracted_data, created_by, updated_at")
          .eq("org_id", orgId)
          .order("imported_at", { ascending: false })
          .limit(500);
        if (projectId){
          fallbackQuery = fallbackQuery.eq("project_id", projectId);
        }
        ({ data: recordRows, error: recordsError } = await fallbackQuery);
      }
    }
    if (recordsError){
      const message = String(recordsError?.message || "").toLowerCase();
      if (
        (message.includes("ks_invoice_records") && message.includes("does not exist"))
        || (message.includes("ks_invoice_records") && message.includes("could not find the table"))
        || (message.includes("ks_invoice_records") && message.includes("schema cache"))
      ){
        state.ksInvoices.loading = false;
        renderInvoicePanel();
        return;
      }
      toast("K&S invoices load error", recordsError.message, "error");
      state.ksInvoices.loading = false;
      renderInvoicePanel();
      return;
    }
    let batchQuery = state.client
      .from("ks_invoice_import_batches")
      .select("id, org_id, project_id, uploaded_zip_name, total_files, imported_count, skipped_count, failed_count, created_at, created_by, summary")
      .eq("org_id", orgId)
      .order("created_at", { ascending: false })
      .limit(100);
    if (projectId){
      batchQuery = batchQuery.eq("project_id", projectId);
    }
    const { data: batchRows, error: batchError } = await batchQuery;
    if (batchError){
      const message = String(batchError?.message || "").toLowerCase();
      if (!(
        (message.includes("ks_invoice_import_batches") && message.includes("does not exist"))
        || (message.includes("ks_invoice_import_batches") && message.includes("could not find the table"))
        || (message.includes("ks_invoice_import_batches") && message.includes("schema cache"))
      )){
        toast("K&S batches load error", batchError.message, "error");
      }
    }
    const records = await Promise.all((recordRows || []).map(async (row) => {
      const fileUrl = row.source_file_path ? await getPublicOrSignedUrl(INVOICE_FILES_BUCKET, row.source_file_path) : "";
      const extracted = row.extracted_data && typeof row.extracted_data === "object" ? row.extracted_data : {};
      const invoiceNumber = normalizeKsInvoiceNumber(row.invoice_number || extracted.invoice_number || "");
      return {
        ...row,
        invoice_number: invoiceNumber,
        invoice_key: String(row.invoice_key || extracted.invoice_key || buildKsInvoiceKey(invoiceNumber)),
        invoice_date: String(row.invoice_date || extracted.invoice_date || ""),
        week_ending: String(row.week_ending || extracted.week_ending || ""),
        project_name: String(row.project_name || extracted.project_name || ""),
        node_name: String(row.node_name || extracted.node_name || ""),
        bill_to_company: String(row.bill_to_company || extracted.bill_to_company || ""),
        line_items: Array.isArray(row.line_items) ? row.line_items : (Array.isArray(extracted.line_items) ? extracted.line_items : []),
        grand_total: Number.isFinite(Number(row.grand_total)) ? Number(row.grand_total) : (Number.isFinite(Number(extracted.grand_total)) ? Number(extracted.grand_total) : null),
        parse_status: String(row.parse_status || extracted.parse_status || "parsed"),
        parse_error: String(row.parse_error || extracted.parse_error || ""),
        source_file_url: fileUrl,
      };
    }));
    state.ksInvoices.records = records;
    state.ksInvoices.batches = batchRows || [];
    persistKsInvoiceLocalFallback();
  } finally {
    state.ksInvoices.loading = false;
    renderInvoicePanel();
  }
}

function createOfficeInvoiceLineItem(){
  return {
    id: `office-line-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
    code: "",
    description: "",
    qty: "",
    unit_rate: "",
  };
}

function computeOfficeInvoiceTotals(draft){
  const items = Array.isArray(draft?.line_items) ? draft.line_items : [];
  const subtotal = roundInvoiceCurrency(items.reduce((sum, item) => sum + getOfficeInvoiceLineTotal(item), 0));
  return {
    subtotal,
    total: subtotal,
  };
}

function refreshOfficeInvoiceComputedFields(){
  const draft = state.officeInvoices.draft;
  if (!draft) return;
  const items = Array.isArray(draft.line_items) ? draft.line_items : [];
  items.forEach((item) => {
    const totalEl = document.querySelector(`[data-office-line-total-id="${item.id}"]`);
    if (totalEl) totalEl.textContent = formatMoney(getOfficeInvoiceLineTotal(item));
  });
  const totals = computeOfficeInvoiceTotals(draft);
  const subtotalEl = $("officeInvoiceSubtotal");
  const totalEl = $("officeInvoiceTotal");
  if (subtotalEl) subtotalEl.textContent = formatMoney(totals.subtotal);
  if (totalEl) totalEl.textContent = formatMoney(totals.total);
}

function pushOfficeRecentValue(key, value){
  const clean = String(value || "").trim();
  if (!clean) return;
  const list = Array.isArray(state.officeInvoices.recents[key]) ? state.officeInvoices.recents[key] : [];
  const next = [clean, ...list.filter((item) => String(item || "").toLowerCase() !== clean.toLowerCase())].slice(0, 10);
  state.officeInvoices.recents[key] = next;
}

function createOfficeInvoiceDraft(){
  ensureOfficeInvoiceStateLoaded();
  state.officeInvoices.routeInvoiceNumber = "";
  clearInvoiceDeepLinkUrl();
  const recents = state.officeInvoices.recents || {};
  state.officeInvoices.draft = {
    id: `office-invoice-${Date.now()}`,
    company_creating_invoice: recents.company?.[0] || "",
    bill_to: recents.billTo?.[0] || "",
    invoice_number: getNextOfficeInvoiceNumber(),
    invoice_date: toLocalDateISO(new Date()),
    week_ending: getWeekEndingSaturdayISO(new Date()),
    job_number: recents.jobNumber?.[0] || "",
    location: recents.location?.[0] || "",
    notes: "",
    status: "Draft",
    line_items: [createOfficeInvoiceLineItem()],
    created_at: nowISO(),
    updated_at: nowISO(),
  };
  persistOfficeInvoiceState();
  renderInvoicePanel();
}

function openOfficeInvoiceDraft(invoiceId){
  ensureOfficeInvoiceStateLoaded();
  const match = (state.officeInvoices.records || []).find((row) => String(row.id) === String(invoiceId));
  if (!match) return;
  state.officeInvoices.routeInvoiceNumber = "";
  clearInvoiceDeepLinkUrl();
  state.officeInvoices.draft = JSON.parse(JSON.stringify(match));
  if (!Array.isArray(state.officeInvoices.draft.line_items) || !state.officeInvoices.draft.line_items.length){
    state.officeInvoices.draft.line_items = [createOfficeInvoiceLineItem()];
  }
  persistOfficeInvoiceState();
  renderInvoicePanel();
}

function normalizeOfficeInvoiceLookupValue(value){
  return String(value || "").trim().toLowerCase();
}

function findOfficeInvoiceByNumber(invoiceNumber){
  const normalizedNeedle = normalizeOfficeInvoiceLookupValue(invoiceNumber);
  if (!normalizedNeedle) return null;
  return (state.officeInvoices.records || []).find((row) => {
    return normalizeOfficeInvoiceLookupValue(row?.invoice_number) === normalizedNeedle;
  }) || null;
}

function openOfficeInvoiceByNumber(invoiceNumber, { syncUrl = true } = {}){
  ensureOfficeInvoiceStateLoaded();
  const clean = String(invoiceNumber || "").trim();
  if (!clean) return false;
  state.officeInvoices.routeInvoiceNumber = clean;
  state.officeInvoices.draft = null;
  if (state.user && (document.querySelector(".view.active")?.id || "") !== "viewInvoices"){
    setActiveView("viewInvoices");
  }
  if (syncUrl){
    setInvoiceDeepLinkHash(clean);
  }
  renderInvoicePanel();
  return true;
}

function openOfficeInvoiceByRouteRef(invoiceRef, { syncUrl = true } = {}){
  const clean = String(invoiceRef || "").trim();
  if (!clean) return false;
  if (window.__invoiceIntroBypass){
    window.__invoiceIntroBypass = false;
    return openOfficeInvoiceByNumber(clean, { syncUrl });
  }
  if (state.user && (document.querySelector(".view.active")?.id || "") !== "viewInvoices" && isViewAllowed("viewInvoices")){
    setActiveView("viewInvoices");
  }
  return openOfficeBillingIntroThenInvoice(clean, { syncUrl });
}

function closeOfficeInvoiceDeepLink({ syncUrl = true } = {}){
  state.officeInvoices.routeInvoiceNumber = "";
  if (syncUrl){
    clearInvoiceDeepLinkUrl();
  }
  renderInvoicePanel();
}

