function buildKsInvoiceLink(invoiceRef){
  const clean = String(invoiceRef || "").trim();
  if (!clean) return "";
  return `${window.location.origin}${window.location.pathname}#invoice=${encodeURIComponent(clean)}`;
}

function copyKsInvoiceLink(invoiceRef){
  const link = buildKsInvoiceLink(invoiceRef);
  if (!link) return;
  if (navigator.clipboard?.writeText){
    navigator.clipboard.writeText(link)
      .then(() => toast("Link copied", link))
      .catch(() => toast("Copy failed", "Unable to copy link.", "error"));
    return;
  }
  toast("Copy unavailable", link);
}

async function upsertKsInvoiceRecord(record){
  const orgId = getInvoiceScopeOrgId();
  if (!state.client || !state.user || !orgId){
    return { ok: false, reason: "missing-context" };
  }
  const payload = {
    org_id: orgId,
    project_id: state.activeProject?.id || null,
    invoice_number: normalizeKsInvoiceNumber(record.invoice_number),
    invoice_key: buildKsInvoiceKey(record.invoice_key || record.invoice_number),
    invoice_number_norm: normalizeKsInvoiceLookup(record.invoice_number),
    invoice_date: String(record.invoice_date || ""),
    week_ending: String(record.week_ending || ""),
    project_name: String(record.project_name || ""),
    node_name: String(record.node_name || ""),
    bill_to_company: String(record.bill_to_company || ""),
    customer_name: "K & S Electric",
    source_filename: String(record.source_filename || ""),
    source_file_path: String(record.source_file_path || ""),
    source_mime: String(record.source_mime || "application/pdf"),
    import_batch_id: record.import_batch_id || null,
    imported_at: record.imported_at || nowISO(),
    status: String(record.status || "imported"),
    notes: String(record.notes || ""),
    line_items: Array.isArray(record.line_items) ? record.line_items : [],
    grand_total: Number.isFinite(Number(record.grand_total)) ? Number(record.grand_total) : null,
    parse_status: String(record.parse_status || "parsed"),
    parse_error: String(record.parse_error || ""),
    warnings: Array.isArray(record.warnings) ? record.warnings : [],
    extracted_data: record.extracted_data && typeof record.extracted_data === "object" ? record.extracted_data : {},
    created_by: state.user.id,
    updated_at: nowISO(),
  };
  const { error } = await state.client
    .from("ks_invoice_records")
    .upsert(payload, { onConflict: "org_id,invoice_number_norm" });
  if (error){
    const message = String(error?.message || "").toLowerCase();
    if (message.includes("invoice_key") && message.includes("does not exist")){
      const legacyPayload = {
        org_id: payload.org_id,
        project_id: payload.project_id,
        invoice_number: payload.invoice_number,
        invoice_number_norm: payload.invoice_number_norm,
        customer_name: payload.customer_name,
        source_filename: payload.source_filename,
        source_file_path: payload.source_file_path,
        source_mime: payload.source_mime,
        import_batch_id: payload.import_batch_id,
        imported_at: payload.imported_at,
        status: payload.status,
        notes: payload.notes,
        warnings: payload.warnings,
        extracted_data: payload.extracted_data,
        created_by: payload.created_by,
        updated_at: payload.updated_at,
      };
      const { error: legacyError } = await state.client
        .from("ks_invoice_records")
        .upsert(legacyPayload, { onConflict: "org_id,invoice_number_norm" });
      if (!legacyError) return { ok: true };
      return { ok: false, reason: legacyError.message || "upsert-failed" };
    }
    if (
      (message.includes("ks_invoice_records") && message.includes("does not exist"))
      || (message.includes("ks_invoice_records") && message.includes("could not find the table"))
      || (message.includes("ks_invoice_records") && message.includes("schema cache"))
    ){
      return { ok: false, reason: "table-missing" };
    }
    return { ok: false, reason: error.message || "upsert-failed" };
  }
  return { ok: true };
}

async function insertKsInvoiceBatch(batch){
  const orgId = getInvoiceScopeOrgId();
  if (!state.client || !state.user || !orgId){
    return { ok: false, id: `local-batch-${Date.now()}`, reason: "missing-context" };
  }
  const payload = {
    org_id: orgId,
    project_id: state.activeProject?.id || null,
    uploaded_zip_name: String(batch.uploaded_zip_name || "invoices.zip"),
    total_files: Number(batch.total_files || 0),
    imported_count: Number(batch.imported_count || 0),
    skipped_count: Number(batch.skipped_count || 0),
    failed_count: Number(batch.failed_count || 0),
    summary: batch.summary && typeof batch.summary === "object" ? batch.summary : {},
    created_by: state.user.id,
  };
  const { data, error } = await state.client
    .from("ks_invoice_import_batches")
    .insert(payload)
    .select("id")
    .maybeSingle();
  if (error){
    const message = String(error?.message || "").toLowerCase();
    if (
      (message.includes("ks_invoice_import_batches") && message.includes("does not exist"))
      || (message.includes("ks_invoice_import_batches") && message.includes("could not find the table"))
      || (message.includes("ks_invoice_import_batches") && message.includes("schema cache"))
    ){
      return { ok: false, id: `local-batch-${Date.now()}`, reason: "table-missing" };
    }
    return { ok: false, id: `local-batch-${Date.now()}`, reason: error.message || "insert-failed" };
  }
  return { ok: true, id: data?.id || `batch-${Date.now()}` };
}

async function finalizeKsInvoiceBatch(batchId, summary){
  if (!state.client || !batchId || String(batchId).startsWith("local-batch-")) return;
  const { error } = await state.client
    .from("ks_invoice_import_batches")
    .update({
      imported_count: Number(summary.imported || 0),
      skipped_count: Number(summary.skipped || 0),
      failed_count: Number(summary.failed || 0),
      total_files: Number(summary.total || 0),
      summary,
    })
    .eq("id", batchId);
  if (error){
    const message = String(error?.message || "").toLowerCase();
    if (!(
      (message.includes("ks_invoice_import_batches") && message.includes("does not exist"))
      || (message.includes("ks_invoice_import_batches") && message.includes("could not find the table"))
      || (message.includes("ks_invoice_import_batches") && message.includes("schema cache"))
    )){
      toast("Batch update error", error.message, "error");
    }
  }
}

async function uploadKsInvoicePdf({ blob, fileName, invoiceNumber, batchId }){
  const orgId = getInvoiceScopeOrgId();
  const projectId = state.activeProject?.id || "org";
  if (!state.client || !state.user || !orgId){
    return { ok: false, reason: "missing-context", filePath: "", fileUrl: "" };
  }
  const safeName = String(fileName || `${invoiceNumber || "invoice"}.pdf`).replace(/[^\w.\-() ]+/g, "_");
  const path = `${orgId}/${projectId}/ks-electric/${batchId}/${Date.now()}-${safeName}`;
  const uploadBody = new Blob([blob], { type: "application/pdf" });
  const { error: uploadError } = await state.client.storage
    .from(INVOICE_FILES_BUCKET)
    .upload(path, uploadBody, { upsert: true, contentType: "application/pdf" });
  if (uploadError){
    return { ok: false, reason: uploadError.message || "upload-failed", filePath: "", fileUrl: "" };
  }
  const fileUrl = await getPublicOrSignedUrl(INVOICE_FILES_BUCKET, path);
  return { ok: true, filePath: path, fileUrl };
}

async function handleKsInvoiceZipImport(file){
  if (!file){
    toast("File required", "Choose a ZIP file first.", "error");
    return;
  }
  if (!state.client || !state.user || !canViewInvoiceVault()){
    toast("Not allowed", "Sign in with invoice access first.", "error");
    return;
  }
  const session = await ensureValidSessionForAction("ks-invoice-zip-import");
  if (!session) return;
  state.user = session.user;
  if (!state.activeProject?.id){
    state.ksInvoices.missingOrgContext = true;
    state.ksInvoices.pendingImportFile = file || null;
    state.orgContextRequired = true;
    renderInvoicePanel();
    toast("Project required", "Select or create a project before importing invoices.", "error");
    return;
  }
  const orgId = getInvoiceScopeOrgId();
  if (!orgId){
    state.ksInvoices.missingOrgContext = true;
    state.ksInvoices.pendingImportFile = file || null;
    state.orgContextRequired = true;
    renderInvoicePanel();
    toast("Missing org", "No organization context for invoice import. Select/create a project or org to continue.", "error");
    return;
  }
  state.ksInvoices.missingOrgContext = false;
  state.ksInvoices.pendingImportFile = null;
  state.ksInvoices.importing = true;
  state.ksInvoices.lastSummary = null;
  state.ksInvoices.lastWarnings = [];
  renderInvoicePanel();
  try {
    const JSZip = await loadJsZip();
    const zip = await JSZip.loadAsync(file);
    const entries = Object.values(zip.files || {});
    const batchInit = await insertKsInvoiceBatch({
      uploaded_zip_name: file.name,
      total_files: entries.length,
      imported_count: 0,
      skipped_count: 0,
      failed_count: 0,
      summary: { started_at: nowISO() },
    });
    const batchId = batchInit.id || `local-batch-${Date.now()}`;
    const summary = {
      batch_id: batchId,
      uploaded_zip_name: file.name,
      total: 0,
      imported: 0,
      skipped: 0,
      failed: 0,
      duplicates: 0,
      warnings: [],
      errors: [],
      file_results: [],
      started_at: nowISO(),
      finished_at: null,
    };
    const localRecords = Array.isArray(state.ksInvoices.records) ? [...state.ksInvoices.records] : [];
    const existingByNorm = new Map(localRecords.map((row) => [normalizeKsInvoiceLookup(row?.invoice_number), row]));
    for (const entry of entries){
      const entryName = String(entry?.name || "");
      if (!entry) continue;
      summary.total += 1;
      const skip = isSkippableZipEntry(entryName);
      if (skip.skip){
        summary.skipped += 1;
        summary.file_results.push({
          source_filename: entryName,
          result: "skipped",
          stage: "precheck",
          reason: skip.reason,
          extracted_invoice_number: null,
          extracted_node_name: null,
        });
        if (skip.reason !== "directory" && skip.reason !== "os-metadata"){
          summary.warnings.push(`${entryName}: skipped (${skip.reason})`);
        }
        continue;
      }
      const baseName = entryName.split("/").pop() || entryName;
      const filenameInvoiceNumber = parseInvoiceNumberFromFilename(baseName);
      let blob;
      try {
        blob = await entry.async("blob");
      } catch (err){
        summary.failed += 1;
        const reason = err?.message || "read failed";
        summary.errors.push(`${entryName}: ${reason}`);
        summary.file_results.push({
          source_filename: baseName,
          result: "failed",
          stage: "read-zip-entry",
          reason,
          extracted_invoice_number: filenameInvoiceNumber || null,
          extracted_node_name: null,
        });
        console.error("[ks-import] file failed", {
          source_filename: baseName,
          stage: "read-zip-entry",
          reason,
        });
        continue;
      }
      const entryMime = String(blob?.type || "").toLowerCase();
      const isPdfByName = /\.pdf$/i.test(baseName);
      const isPdfByMime = entryMime === "application/pdf";
      const acceptedAsPdf = isPdfByMime || isPdfByName;
      const uploadContentType = acceptedAsPdf ? "application/pdf" : "";
      console.info("[ks-import] file mime check", {
        source_filename: baseName,
        detected_mime_type: entryMime || "",
        extension_based_pdf_acceptance: isPdfByName,
        upload_content_type: uploadContentType,
      });
      if (!acceptedAsPdf){
        summary.skipped += 1;
        const reason = `unsupported-type (mime: ${entryMime || "(empty)"})`;
        summary.warnings.push(`${entryName}: skipped (${reason})`);
        summary.file_results.push({
          source_filename: baseName,
          result: "skipped",
          stage: "precheck",
          reason,
          extracted_invoice_number: filenameInvoiceNumber || null,
          extracted_node_name: null,
        });
        console.info("[ks-import] file skipped", {
          source_filename: baseName,
          stage: "precheck",
          reason,
        });
        continue;
      }
      let parsedPdf = null;
      try {
        const buffer = await blob.arrayBuffer();
        parsedPdf = await parseKsInvoicePdfData(buffer, {
          sourceFilename: baseName,
          fallbackInvoiceNumber: filenameInvoiceNumber || "",
        });
      } catch (err){
        parsedPdf = {
          invoice_number: normalizeKsInvoiceNumber(filenameInvoiceNumber || `UNPARSED_${Date.now()}`),
          invoice_key: buildKsInvoiceKey(filenameInvoiceNumber || `UNPARSED_${Date.now()}`),
          invoice_date: "",
          week_ending: "",
          project_name: "",
          node_name: "",
          bill_to_company: "",
          source_filename: baseName,
          line_items: [],
          grand_total: null,
          parse_status: "parse_failed",
          parse_error: err?.message || "pdf parse failed",
        };
      }
      const parsedInvoiceNumber = normalizeKsInvoiceNumber(parsedPdf.invoice_number || filenameInvoiceNumber || "").replace(/-/g, "_");
      const normalizedInvoice = normalizeKsInvoiceLookup(parsedInvoiceNumber);
      const existing = existingByNorm.get(normalizedInvoice) || null;
      console.info("[ks-import] parsed", {
        source_filename: baseName,
        invoice_number: parsedInvoiceNumber || null,
        node_name: parsedPdf.node_name || null,
        grand_total: parsedPdf.grand_total ?? null,
        parse_status: parsedPdf.parse_status || "unknown",
      });
      if (!parsedInvoiceNumber){
        summary.failed += 1;
        const reason = "invoice number could not be determined";
        summary.errors.push(`${entryName}: ${reason}`);
        summary.file_results.push({
          source_filename: baseName,
          result: "failed",
          stage: "parse-pdf",
          reason,
          extracted_invoice_number: null,
          extracted_node_name: parsedPdf.node_name || null,
        });
        console.error("[ks-import] file failed", {
          source_filename: baseName,
          stage: "parse-pdf",
          reason,
          extracted_node_name: parsedPdf.node_name || null,
        });
        continue;
      }
      const upload = await uploadKsInvoicePdf({
        blob,
        fileName: baseName,
        invoiceNumber: parsedInvoiceNumber,
        batchId,
      });
      if (!upload.ok){
        summary.failed += 1;
        const reason = upload.reason || "upload failed";
        summary.errors.push(`${entryName}: ${reason}`);
        summary.file_results.push({
          source_filename: baseName,
          result: "failed",
          stage: "upload-pdf",
          reason,
          extracted_invoice_number: parsedInvoiceNumber || null,
          extracted_node_name: parsedPdf.node_name || null,
        });
        console.error("[ks-import] file failed", {
          source_filename: baseName,
          stage: "upload-pdf",
          reason,
          extracted_invoice_number: parsedInvoiceNumber || null,
          extracted_node_name: parsedPdf.node_name || null,
        });
        continue;
      }
      const fileMetaPayload = {
        org_id: orgId,
        project_id: state.activeProject?.id || null,
        file_name: baseName,
        file_path: upload.filePath,
        uploaded_by: state.user?.id || null,
      };
      const { error: fileInsertError } = await state.client.from("invoice_files").insert(fileMetaPayload);
      if (fileInsertError){
        const msg = String(fileInsertError?.message || "").toLowerCase();
        if (!(
          (msg.includes("duplicate") && msg.includes("key"))
          || (msg.includes("already exists"))
        )){
          summary.warnings.push(`${entryName}: file metadata insert warning (${fileInsertError.message})`);
        }
      }
      const record = {
        id: existing?.id || `ks-invoice-${Date.now()}-${Math.random().toString(16).slice(2, 8)}`,
        org_id: orgId,
        project_id: state.activeProject?.id || null,
        invoice_number: parsedInvoiceNumber,
        invoice_key: buildKsInvoiceKey(parsedPdf.invoice_key || parsedInvoiceNumber),
        invoice_number_norm: normalizedInvoice,
        invoice_date: parsedPdf.invoice_date || "",
        week_ending: parsedPdf.week_ending || "",
        project_name: parsedPdf.project_name || "",
        node_name: parsedPdf.node_name || "",
        bill_to_company: parsedPdf.bill_to_company || "",
        customer_name: "K & S Electric",
        source_filename: baseName,
        source_file_path: upload.filePath,
        source_file_url: upload.fileUrl,
        source_mime: "application/pdf",
        import_batch_id: batchId,
        imported_at: nowISO(),
        status: existing
          ? (parsedPdf.parse_status === "parsed" ? "updated" : "updated_with_parse_warnings")
          : (parsedPdf.parse_status === "parsed" ? "imported" : "imported_with_parse_warnings"),
        notes: parsedPdf.parse_error || "",
        line_items: Array.isArray(parsedPdf.line_items) ? parsedPdf.line_items : [],
        grand_total: Number.isFinite(Number(parsedPdf.grand_total)) ? Number(parsedPdf.grand_total) : null,
        parse_status: String(parsedPdf.parse_status || "parse_partial"),
        parse_error: String(parsedPdf.parse_error || ""),
        warnings: parsedPdf.parse_error ? [parsedPdf.parse_error] : [],
        extracted_data: {
          invoice_number: parsedInvoiceNumber,
          invoice_key: buildKsInvoiceKey(parsedPdf.invoice_key || parsedInvoiceNumber),
          invoice_date: parsedPdf.invoice_date || "",
          week_ending: parsedPdf.week_ending || "",
          project_name: parsedPdf.project_name || "",
          node_name: parsedPdf.node_name || "",
          bill_to_company: parsedPdf.bill_to_company || "",
          source_filename: baseName,
          line_items: Array.isArray(parsedPdf.line_items) ? parsedPdf.line_items : [],
          grand_total: Number.isFinite(Number(parsedPdf.grand_total)) ? Number(parsedPdf.grand_total) : null,
          parse_status: String(parsedPdf.parse_status || "parse_partial"),
          parse_error: String(parsedPdf.parse_error || ""),
        },
        created_by: state.user?.id || null,
        updated_at: nowISO(),
      };
      const upsertResult = await upsertKsInvoiceRecord(record);
      if (!upsertResult.ok){
        const reason = upsertResult.reason || "record save failed";
        summary.failed += 1;
        summary.errors.push(`${entryName}: db save failed (${reason})`);
        summary.file_results.push({
          source_filename: baseName,
          result: "failed",
          stage: "db-save",
          reason,
          extracted_invoice_number: parsedInvoiceNumber || null,
          extracted_node_name: parsedPdf.node_name || null,
        });
        console.error("[ks-import] file failed", {
          source_filename: baseName,
          stage: "db-save",
          reason,
          extracted_invoice_number: parsedInvoiceNumber || null,
          extracted_node_name: parsedPdf.node_name || null,
        });
        continue;
      }
      if (parsedPdf.parse_status !== "parsed" && parsedPdf.parse_error){
        summary.warnings.push(`${entryName}: ${parsedPdf.parse_error}`);
      }
      summary.file_results.push({
        source_filename: baseName,
        result: existing ? "updated" : "saved",
        stage: parsedPdf.parse_status === "parsed" ? "completed" : "completed-with-parse-warnings",
        reason: parsedPdf.parse_error || "",
        extracted_invoice_number: parsedInvoiceNumber || null,
        extracted_node_name: parsedPdf.node_name || null,
      });
      if (existing){
        summary.duplicates += 1;
      } else {
        summary.imported += 1;
      }
      existingByNorm.set(normalizedInvoice, record);
    }
    summary.finished_at = nowISO();
    summary.skipped = Math.max(summary.skipped, 0);
    const mergedRecords = Array.from(existingByNorm.values()).sort((a, b) => {
      return new Date(b.imported_at || 0).getTime() - new Date(a.imported_at || 0).getTime();
    });
    state.ksInvoices.records = mergedRecords;
    state.ksInvoices.batches = [{
      id: batchId,
      org_id: orgId,
      project_id: state.activeProject?.id || null,
      uploaded_zip_name: file.name,
      total_files: summary.total,
      imported_count: summary.imported,
      skipped_count: summary.skipped,
      failed_count: summary.failed,
      created_at: nowISO(),
      created_by: state.user?.id || null,
      summary,
    }, ...(state.ksInvoices.batches || []).filter((row) => String(row?.id || "") !== String(batchId))].slice(0, 100);
    state.ksInvoices.lastSummary = summary;
    state.ksInvoices.lastWarnings = summary.warnings || [];
    persistKsInvoiceLocalFallback();
    await finalizeKsInvoiceBatch(batchId, summary);
    await loadInvoiceFiles(state.activeProject?.id || null);
    await loadKsInvoiceWorkspace(state.activeProject?.id || null);
    toast("K&S invoice import complete", `Imported ${summary.imported}. Skipped ${summary.skipped}. Failed ${summary.failed}.`);
  } catch (err){
    toast("ZIP import failed", err?.message || "Unable to process ZIP.", "error");
  } finally {
    state.ksInvoices.importing = false;
    renderInvoicePanel();
  }
}

function renderKsInvoiceImportCard(){
  const summary = state.ksInvoices.lastSummary;
  const importing = state.ksInvoices.importing;
  const warnings = state.ksInvoices.lastWarnings || [];
  const errors = Array.isArray(summary?.errors) ? summary.errors : [];
  const failedDetails = Array.isArray(summary?.file_results)
    ? summary.file_results.filter((row) => String(row?.result || "") === "failed")
    : [];
  const orgMissing = Boolean(state.ksInvoices.missingOrgContext || state.orgContextRequired || !getInvoiceScopeOrgId());
  return `
    <div class="card" style="margin-top:12px;">
      <div class="row" style="justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">
        <div>
          <h3 style="margin:0;">K &amp; S Electric Invoice Import</h3>
          <div class="muted small">Upload a ZIP of PDF invoices. Non-invoice files are skipped safely.</div>
        </div>
        <label class="btn secondary small file-btn ${importing ? "disabled" : ""}">
          ${importing ? "Importing..." : "Upload ZIP"}
          <input id="ksInvoiceZipInput" type="file" accept=".zip,application/zip" ${importing ? "disabled" : ""} />
        </label>
      </div>
      <div class="muted small" style="margin-top:8px;">
        Source format example: SpecCom_TDS_001.pdf ... SpecCom_TDS_014.pdf
      </div>
      ${orgMissing ? `
        <div class="note warning" style="margin-top:10px;">
          <div style="font-weight:800;">Organization context required</div>
          <div class="muted small" style="margin-top:6px;">Select or create a project/org, then retry import.</div>
          <div class="row" style="margin-top:8px; gap:8px; flex-wrap:wrap;">
            <button class="btn ghost small" type="button" data-office-action="resolveOrgContext">Resolve Org Context</button>
            ${state.ksInvoices.pendingImportFile ? `<button class="btn ghost small" type="button" data-office-action="retryPendingInvoiceImport">Retry Pending Import</button>` : ""}
          </div>
        </div>
      ` : ""}
      ${summary ? `
        <div class="note" style="margin-top:10px;">
          <div><strong>Batch:</strong> ${escapeHtml(summary.batch_id || "-")}</div>
          <div><strong>Total:</strong> ${summary.total || 0} | <strong>Imported:</strong> ${summary.imported || 0} | <strong>Skipped:</strong> ${summary.skipped || 0} | <strong>Failed:</strong> ${summary.failed || 0} | <strong>Duplicates:</strong> ${summary.duplicates || 0}</div>
        </div>
      ` : ""}
      ${warnings.length ? `
        <div class="muted small" style="margin-top:8px;">
          ${warnings.slice(0, 8).map((msg) => `<div>- ${escapeHtml(msg)}</div>`).join("")}
        </div>
      ` : ""}
      ${errors.length ? `
        <div class="muted small" style="margin-top:8px; color:#b91c1c;">
          <div style="font-weight:800; margin-bottom:4px;">Import errors</div>
          ${errors.slice(0, 12).map((msg) => `<div>- ${escapeHtml(msg)}</div>`).join("")}
        </div>
      ` : ""}
      ${failedDetails.length ? `
        <div class="muted small" style="margin-top:8px;">
          <div style="font-weight:800; margin-bottom:4px;">Failed file details</div>
          ${failedDetails.slice(0, 12).map((row) => `
            <div>
              ${escapeHtml(row.source_filename || "-")} | stage: ${escapeHtml(row.stage || "-")} | invoice: ${escapeHtml(row.extracted_invoice_number || "-")} | node: ${escapeHtml(row.extracted_node_name || "-")} | error: ${escapeHtml(row.reason || "-")}
            </div>
          `).join("")}
        </div>
      ` : ""}
    </div>
  `;
}

function renderKsInvoiceList(){
  const rows = state.ksInvoices.records || [];
  if (!rows.length){
    return `
      <div class="card" style="margin-top:12px;">
        <h3 style="margin:0;">Imported K&amp;S Invoices</h3>
        <div class="muted small" style="margin-top:8px;">No K &amp; S invoices imported yet.</div>
      </div>
    `;
  }
  return `
    <div class="card" style="margin-top:12px;">
      <div class="row" style="justify-content:space-between; align-items:center;">
        <h3 style="margin:0;">Imported K&amp;S Invoices</h3>
        <div class="muted small">${rows.length} invoices</div>
      </div>
      <div style="overflow:auto; margin-top:8px;">
        <table class="table">
          <thead><tr><th>Invoice #</th><th>Node</th><th>Project</th><th>Imported</th><th>Source File</th><th>Status</th><th></th></tr></thead>
          <tbody>
            ${rows.map((row) => `
              <tr>
                <td><button class="btn ghost small" type="button" data-office-action="openKsInvoice" data-office-invoice-number="${escapeHtml(row.id || row.invoice_number || "")}">${escapeHtml(row.invoice_number || "-")}</button></td>
                <td>${escapeHtml(row.node_name || row.extracted_data?.node_name || "-")}</td>
                <td>${escapeHtml(row.project_name || row.extracted_data?.project_name || "-")}</td>
                <td>${escapeHtml(new Date(row.imported_at || Date.now()).toLocaleString())}</td>
                <td>${escapeHtml(row.source_filename || "-")}</td>
                <td>${escapeHtml(row.parse_status || row.status || "imported")}</td>
                <td class="row" style="gap:6px; flex-wrap:wrap;">
                  <button class="btn ghost small" type="button" data-office-action="openKsInvoice" data-office-invoice-number="${escapeHtml(row.id || row.invoice_number || "")}">Open</button>
                  <button class="btn ghost small" type="button" data-office-action="copyKsInvoiceLink" data-office-invoice-number="${escapeHtml(row.id || row.invoice_number || "")}">Copy Link</button>
                </td>
              </tr>
            `).join("")}
          </tbody>
        </table>
      </div>
    </div>
  `;
}

function renderKsInvoiceDetailView(invoice){
  const extracted = invoice?.extracted_data && typeof invoice.extracted_data === "object" ? invoice.extracted_data : {};
  const lineItems = Array.isArray(invoice?.line_items) ? invoice.line_items : (Array.isArray(extracted.line_items) ? extracted.line_items : []);
  const sourceUrl = invoice?.source_file_url || "";
  const invoiceNumber = invoice?.invoice_number || extracted.invoice_number || "-";
  const invoiceKey = invoice?.invoice_key || extracted.invoice_key || buildKsInvoiceKey(invoiceNumber);
  const invoiceDate = invoice?.invoice_date || extracted.invoice_date || "-";
  const weekEnding = invoice?.week_ending || extracted.week_ending || "-";
  const projectName = invoice?.project_name || extracted.project_name || "-";
  const nodeName = invoice?.node_name || extracted.node_name || "-";
  const billToCompany = invoice?.bill_to_company || extracted.bill_to_company || "-";
  const grandTotal = Number.isFinite(Number(invoice?.grand_total))
    ? Number(invoice.grand_total)
    : (Number.isFinite(Number(extracted?.grand_total)) ? Number(extracted.grand_total) : null);
  const parseStatus = invoice?.parse_status || extracted.parse_status || "-";
  const parseError = invoice?.parse_error || extracted.parse_error || "";
  const warningLines = Array.isArray(invoice?.warnings) ? invoice.warnings : [];
  const parseNeedsAttention = /partial|failed/i.test(String(parseStatus || "")) || Boolean(parseError) || warningLines.length > 0;
  return `
    <div class="card" style="margin-top:12px;">
      <div class="row" style="justify-content:space-between; align-items:center; gap:8px; flex-wrap:wrap;">
        <div>
          <h3 style="margin:0;">K &amp; S Invoice ${escapeHtml(invoiceNumber)}</h3>
          <div class="muted small">${escapeHtml(invoice?.customer_name || "K & S Electric")}</div>
        </div>
        <div class="row" style="gap:8px; flex-wrap:wrap;">
          <button class="btn ghost small" type="button" data-office-action="backToInvoiceList">Back to Invoice List</button>
          <button class="btn ghost small" type="button" data-office-action="copyKsInvoiceLink" data-office-invoice-number="${escapeHtml(invoice?.id || invoiceNumber || "")}">Copy Link</button>
        </div>
      </div>
      ${parseNeedsAttention ? `
        <div class="note warning" style="margin-top:10px;">
          <div style="font-weight:800;">Parse review needed</div>
          <div class="muted small" style="margin-top:6px;">Status: ${escapeHtml(parseStatus || "-")}</div>
          ${parseError ? `<div class="muted small" style="margin-top:6px;">Error: ${escapeHtml(parseError)}</div>` : ""}
          ${warningLines.length ? `<div class="muted small" style="margin-top:6px;">${warningLines.map((w) => `<div>- ${escapeHtml(w)}</div>`).join("")}</div>` : ""}
        </div>
      ` : ""}
      <div class="grid cols-2" style="margin-top:10px;">
        <div><div class="small muted">Invoice Number</div><div>${escapeHtml(invoiceNumber)}</div></div>
        <div><div class="small muted">Invoice Key</div><div>${escapeHtml(invoiceKey || "-")}</div></div>
        <div><div class="small muted">Node</div><div>${escapeHtml(nodeName)}</div></div>
        <div><div class="small muted">Project</div><div>${escapeHtml(projectName)}</div></div>
        <div><div class="small muted">Invoice Date</div><div>${escapeHtml(invoiceDate)}</div></div>
        <div><div class="small muted">Week Ending</div><div>${escapeHtml(weekEnding)}</div></div>
        <div><div class="small muted">Bill To Company</div><div>${escapeHtml(billToCompany)}</div></div>
        <div><div class="small muted">Source Filename</div><div>${escapeHtml(invoice?.source_filename || "-")}</div></div>
        <div><div class="small muted">Grand Total</div><div>${escapeHtml(grandTotal != null ? formatMoney(grandTotal) : "-")}</div></div>
        <div><div class="small muted">Parse Status</div><div>${escapeHtml(parseStatus || "-")}</div></div>
      </div>
      <div style="margin-top:10px;">
        <div class="small muted">Source PDF</div>
        ${sourceUrl ? `<a class="btn ghost small" href="${escapeHtml(sourceUrl)}" target="_blank" rel="noopener noreferrer">Open source PDF</a>` : `<div class="muted small">No source PDF URL available.</div>`}
      </div>
      <div style="margin-top:10px;">
        <div class="small muted">Import metadata</div>
        <div class="muted small">Batch: ${escapeHtml(invoice?.import_batch_id || "-")} | Imported: ${escapeHtml(new Date(invoice?.imported_at || Date.now()).toLocaleString())} | Source file: ${escapeHtml(invoice?.source_filename || "-")}</div>
      </div>
      <div style="margin-top:10px;">
        <div class="small muted">Line items</div>
        ${lineItems.length
          ? `<div style="overflow:auto; margin-top:6px;">
              <table class="table billing-table">
                <thead><tr><th>Code</th><th>Description</th><th>Qty</th><th>Rate</th><th>Total</th></tr></thead>
                <tbody>
                  ${lineItems.map((item) => `
                    <tr>
                      <td>${escapeHtml(item?.code || "-")}</td>
                      <td>${escapeHtml(item?.description || "-")}</td>
                      <td>${escapeHtml(String(item?.qty ?? "-"))}</td>
                      <td>${escapeHtml(item?.rate != null ? formatMoney(item.rate) : "-")}</td>
                      <td>${escapeHtml(item?.total != null ? formatMoney(item.total) : "-")}</td>
                    </tr>
                  `).join("")}
                </tbody>
              </table>
            </div>`
          : `<div class="muted small" style="margin-top:6px;">No extracted line items yet (phase 1 filename import).</div>`
        }
      </div>
      <div style="margin-top:10px;">
        <div class="small muted">Notes</div>
        <div>${escapeHtml(invoice?.notes || "-")}</div>
      </div>
    </div>
  `;
}

function renderOfficeInvoiceRouteSidebar(activeInvoiceRef){
  const activeNorm = normalizeKsInvoiceLookup(activeInvoiceRef);
  const ksRows = (state.ksInvoices.records || []).map((row) => {
    const ref = String(row?.id || row?.invoice_number || row?.invoice_key || "").trim();
    const title = String(row?.invoice_number || row?.invoice_key || row?.id || "K&S invoice").trim();
    const subtitle = [row?.node_name, row?.project_name].filter(Boolean).join(" | ") || "Imported invoice";
    const amount = Number.isFinite(Number(row?.grand_total)) ? formatMoney(row.grand_total) : "";
    const selected = normalizeKsInvoiceLookup(ref) === activeNorm;
    return { ref, title, subtitle, amount, selected, kind: "K&S" };
  }).filter((row) => row.ref);
  const officeRows = (state.officeInvoices.records || []).map((row) => {
    const ref = String(row?.invoice_number || row?.id || "").trim();
    const title = String(row?.invoice_number || row?.id || "Office invoice").trim();
    const subtitle = [row?.company_creating_invoice, row?.location].filter(Boolean).join(" | ") || "Office invoice";
    const amount = Number.isFinite(Number(row?.total)) ? formatMoney(row.total) : "";
    const selected = normalizeKsInvoiceLookup(ref) === activeNorm;
    return { ref, title, subtitle, amount, selected, kind: "Office" };
  }).filter((row) => row.ref);
  const renderRows = (rows) => rows.length
    ? rows.map((row) => `
        <button class="btn ghost small" type="button" data-office-action="openInvoiceDeepLink" data-office-invoice-number="${escapeHtml(row.ref)}" style="width:100%; justify-content:space-between; text-align:left; border-color:${row.selected ? "#2563eb" : "rgba(148,163,184,0.35)"}; background:${row.selected ? "rgba(37,99,235,0.12)" : "transparent"};">
          <span style="display:grid; gap:2px; justify-items:start;">
            <span style="font-weight:700;">${escapeHtml(row.title)}</span>
            <span class="muted small">${escapeHtml(row.subtitle)}</span>
          </span>
          <span style="text-align:right;">
            <span class="status-pill" style="margin-bottom:4px; display:inline-block;">${escapeHtml(row.kind)}</span>
            ${row.amount ? `<span style="display:block; font-weight:700;">${escapeHtml(row.amount)}</span>` : ""}
          </span>
        </button>
      `).join("")
    : `<div class="muted small">No invoices in this section.</div>`;
  return `
    <div class="card" style="margin-top:12px;">
      <div class="row" style="justify-content:space-between; align-items:center; margin-bottom:8px; gap:8px;">
        <h3 style="margin:0;">Invoice list</h3>
        <button class="btn ghost small" type="button" data-office-action="closeInvoiceDeepLink">Back</button>
      </div>
      <div class="field-stack" style="gap:12px;">
        <div>
          <div class="small muted" style="margin-bottom:6px;">Imported K&amp;S invoices</div>
          <div class="field-stack" style="gap:6px; max-height:240px; overflow:auto;">${renderRows(ksRows)}</div>
        </div>
        <div>
          <div class="small muted" style="margin-bottom:6px;">Office invoices</div>
          <div class="field-stack" style="gap:6px; max-height:240px; overflow:auto;">${renderRows(officeRows)}</div>
        </div>
      </div>
    </div>
  `;
}

