  const mapFieldPanel = $("mapFieldPanel");
  if (mapFieldPanel){
    mapFieldPanel.addEventListener("input", (e) => {
      const input = e.target?.closest?.("[data-field-visit-input]");
      if (input){
        updateMapFieldVisitDraftFromInputs(input.dataset.siteId || state.map.fieldVisitDraft?.siteId || "");
        refreshMapFieldCloseoutValidationState(input.dataset.siteId || state.map.fieldVisitDraft?.siteId || "");
        return;
      }
      const closeoutInput = e.target?.closest?.("[data-field-closeout-input]");
      if (closeoutInput){
        updateMapFieldCloseoutDraftFromInputs(closeoutInput.dataset.siteId || state.map.fieldCloseoutDraft?.siteId || "");
        refreshMapFieldCloseoutValidationState(closeoutInput.dataset.siteId || state.map.fieldCloseoutDraft?.siteId || "");
      }
    });
    mapFieldPanel.addEventListener("change", (e) => {
      const input = e.target?.closest?.("[data-field-visit-input]");
      if (input){
        updateMapFieldVisitDraftFromInputs(input.dataset.siteId || state.map.fieldVisitDraft?.siteId || "");
        refreshMapFieldCloseoutValidationState(input.dataset.siteId || state.map.fieldVisitDraft?.siteId || "");
        return;
      }
      const closeoutInput = e.target?.closest?.("[data-field-closeout-input]");
      if (closeoutInput){
        updateMapFieldCloseoutDraftFromInputs(closeoutInput.dataset.siteId || state.map.fieldCloseoutDraft?.siteId || "");
        renderMapFieldPanel();
      }
    });
    const handleMapFieldPanelClick = async (e) => {
      const actionBtn = e.target.closest("[data-map-field-action]");
      if (actionBtn){
        const action = String(actionBtn.dataset.mapFieldAction || "");
        const siteId = actionBtn.dataset.siteId;
        if (action === "rootOpenView"){
          const viewId = String(actionBtn.dataset.rootView || "");
          if (isEffectiveRootRole() && viewId && isViewAllowed(viewId)) setActiveView(viewId);
          return;
        }
        if (action === "rootOpenProjects"){
          if (isEffectiveRootRole()) openProjectsModal();
          return;
        }
        if (action === "rootMasterSearch"){
          if (canUseMasterLocationSearch()) openMasterLocationSearch($("mapRootMasterSearch")?.value || "");
          return;
        }
        if (action === "rootCreateLocation"){
          if (!isEffectiveRootRole()) return;
          if (!state.activeProject?.id){
            toast("Project required", "Select a project before creating a location.");
            return;
          }
          setMapFieldCreateOpen(true);
          return;
        }
        if (action === "rootImportLocations"){
          if (isEffectiveRootRole()) await handleLocationImport(null);
          return;
        }
        if (action === "rootXrayOn"){
          await enableRootProjectXray();
          return;
        }
        if (action === "rootXrayOff"){
          if (isEffectiveRootRole()) disableRootProjectXray();
          return;
        }
        if (action === "node54Start"){
          activateNode54Diagnostics();
          return;
        }
        if (action === "node54Exit"){
          deactivateNode54Diagnostics();
          return;
        }
        if (action === "node54Back"){
          state.node54Diagnostics.currentStepIndex = Math.max(0, state.node54Diagnostics.currentStepIndex - 1);
          state.node54Diagnostics.pendingPhoto = null;
          persistNode54Session();
          renderMapFieldPanel();
          return;
        }
        if (action === "node54Next"){
          const stop = getNode54Stop();
          state.node54Diagnostics.currentStepIndex = Math.min(stop.steps.length - 1, state.node54Diagnostics.currentStepIndex + 1);
          state.node54Diagnostics.pendingPhoto = null;
          persistNode54Session();
          renderMapFieldPanel();
          return;
        }
        if (action === "node54Photo"){
          $("node54PhotoInput")?.click();
          return;
        }
        if (action === "node54Save"){
          await saveNode54Reading();
          return;
        }
        if (action === "node54SaveDevice"){
          saveNode54DeviceCheck();
          return;
        }
        if (action === "node54Navigate"){
          selectNode54Stop(actionBtn.dataset.stopId || state.node54Diagnostics.suggestedStopId);
          return;
        }
        if (action === "node54Focus"){
          focusNode54Stop(actionBtn.dataset.stopId || state.node54Diagnostics.currentStopId);
          return;
        }
        if (action === "startFieldDay"){
          await startFieldDay();
          return;
        }
        if (action === "startFieldDayEvent"){
          const eventType = actionBtn.dataset.fieldDayEvent || "";
          if (eventType) await startFieldDayEvent(eventType);
          return;
        }
        if (action === "endFieldDayEvent"){
          await endFieldDayEvent({ toastLabel: "Activity ended" });
          return;
        }
        if (action === "endFieldDay"){
          await endFieldDay();
          return;
        }
        if (action === "searchVisitLocation"){
          await searchMapFieldVisitLocation($("mapFieldVisitSearch")?.value || "");
          return;
        }
        if (!siteId) return;
        if (action === "selectWorklistSite"){
          setMapFieldSelectedSite(siteId);
          focusSiteOnMap(siteId);
          hideMapFloatPanelForMapAction();
          void hydrateMapFieldSiteActivity(siteId);
          return;
        }
        if (action === "startFieldLocation"){
          const site = getVisibleSiteByIdKey(siteId);
          const draft = site ? updateMapFieldVisitDraftFromInputs(siteId) || getMapFieldVisitDraft(site) : null;
          await startFieldDayEvent(FIELD_DAY_EVENT_TYPES.LOCATION_WORK, { siteId, label: draft?.visitLabel || "" });
          return;
        }
        if (action === "endFieldLocation"){
          state.map.fieldCloseoutOpen = true;
          renderMapFieldPanel();
          return;
        }
        if (action === "openCloseout"){
          state.map.fieldCloseoutOpen = true;
          renderMapFieldPanel();
          return;
        }
        if (action === "cancelCloseout"){
          updateMapFieldCloseoutDraftFromInputs(siteId);
          state.map.fieldCloseoutOpen = false;
          renderMapFieldPanel();
          return;
        }
        if (action === "finalizeFieldLocation"){
          await finalizeFieldDayLocation(siteId);
          return;
        }
        if (action === "setCloseoutAnswer"){
          setMapFieldCloseoutAnswer(siteId, actionBtn.dataset.closeoutKey || "", actionBtn.dataset.closeoutValue || "");
          return;
        }
        if (action === "uploadVisitPhoto"){
          await uploadMapFieldVisitPhotos(siteId, actionBtn.dataset.photoType || "visit_issue");
          return;
        }
        if (action === "addDraftMaterial"){
          addMapFieldDraftMaterial(siteId);
          return;
        }
        if (action === "addDraftCode"){
          addMapFieldDraftCode(siteId);
          return;
        }
        if (action === "removeDraftItem"){
          removeMapFieldDraftListItem(siteId, actionBtn.dataset.listName || "", actionBtn.dataset.listIndex);
          return;
        }
        if (action === "open"){
          await openLocationForField(siteId, { center: true, forAdd: false });
          return;
        }
        if (action === "note"){
          await openLocationForField(siteId, { center: false, forAdd: true });
          const noteInput = $("siteNotesInput");
          if (noteInput){
            noteInput.focus();
          } else {
            toast("Location opened", "Add note in location details.");
          }
          return;
        }
        if (action === "photo"){
          await openLocationForField(siteId, { center: false, forAdd: true });
          const mediaInput = $("siteMediaInput");
          if (mediaInput){
            mediaInput.click();
          } else {
            toast("Location opened", "Upload reference media in location details.");
          }
          return;
        }
        if (action === "saveWorkLog"){
          await saveMapFieldWorkLog(siteId);
          return;
        }
        if (action === "complete"){
          setSiteWorkflowStatus(siteId, MAP_FIELD_STATUS.COMPLETE);
          toast("Status updated", "Location marked complete.");
        }
        return;
      }
      const id = e.target?.id;
      if (id === "btnMapCaptureLocation"){
        await requestMapCurrentLocation({ center: true, silent: false });
        return;
      }
      if (id === "btnMapOpenNearbyLocation"){
        if (state.map.nearestSiteId){
          await openLocationForField(state.map.nearestSiteId, { center: true, forAdd: false });
        }
        return;
      }
      if (id === "btnMapAddToNearbyLocation"){
        if (state.map.nearestSiteId){
          await openLocationForField(state.map.nearestSiteId, { center: true, forAdd: true });
        }
        return;
      }
      if (id === "btnMapShowCreateLocation"){
        if (Date.now() < Number(state.map.fieldCreateRecentlyClosedUntil || 0)) return;
        setMapFieldCreateOpen(true);
        return;
      }
      if (id === "btnMapFieldImportLocations"){
        await handleLocationImport(null);
        return;
      }
      if (id === "btnMapFieldCancelCreate"){
        setMapFieldCreateOpen(false);
        return;
      }
      if (id === "btnMapFieldDismissCreate"){
        setMapFieldCreateOpen(false);
        return;
      }
      if (id === "btnMapFieldCreateClose"){
        setMapFieldCreateOpen(false);
        return;
      }
      if (id === "btnMapFieldTakePhoto"){
        await handleMapFieldTakePhotoClick();
        return;
      }
      if (id === "btnMapFieldCreateLocation"){
        await createFieldLocationFromCurrentGps();
      }
    };
    mapFieldPanel.addEventListener("click", (e) => {
      const pressedBtn = e.target.closest("button");
      setButtonBusy(pressedBtn, true);
      handleMapFieldPanelClick(e).finally(() => setButtonBusy(pressedBtn, false));
    });
    mapFieldPanel.addEventListener("keydown", (e) => {
      if (e.key !== "Enter" || e.target?.id !== "mapRootMasterSearch") return;
      e.preventDefault();
      openMasterLocationSearch(e.target.value || "");
    });
    mapFieldPanel.addEventListener("change", (e) => {
      const diagnosticStop = e.target.closest("[data-node54-stop-select]");
      if (diagnosticStop){
        selectNode54Stop(diagnosticStop.value);
        return;
      }
      const diagnosticPhoto = e.target.closest("#node54PhotoInput");
      if (diagnosticPhoto){
        const file = diagnosticPhoto.files?.[0] || null;
        diagnosticPhoto.value = "";
        if (!file) return;
        const photoId = globalThis.crypto?.randomUUID?.() || `node54_photo_${Date.now()}`;
        storeNode54Photo(file, photoId).then(() => {
          state.node54Diagnostics.pendingPhoto = { id: photoId, name: file.name, type: file.type };
          renderMapFieldPanel();
          toast("Photo attached", "Diagnostic photo stored on this device until a server evidence store is approved.");
        }).catch((error) => {
          console.error("Node 54 photo storage error", error);
          toast("Photo not stored", "This browser could not retain the diagnostic photo.", "error");
        });
        return;
      }
      const select = e.target.closest("#mapFieldStatusSelect");
      if (select){
        const siteId = select.dataset.siteId;
        if (!siteId) return;
        setSiteWorkflowStatus(siteId, select.value);
        return;
      }
      const photoInput = e.target.closest("#mapFieldPhotoInput");
      if (photoInput){
        const file = photoInput.files?.[0] || null;
        const captureMeta = state.map._pendingPhotoCapture || null;
        photoInput.value = "";
        if (!file) return;
        if (!captureMeta?.gps){
          toast("GPS required", "Take Photo must capture GPS before the proof photo can be attached.");
          return;
        }
        if (!Array.isArray(state.map._pendingProofPhotos)){
          state.map._pendingProofPhotos = [];
        }
        state.map._pendingProofPhotos.push({
          file,
          previewUrl: URL.createObjectURL(file),
          gps: captureMeta.gps,
          captured_at: captureMeta.captured_at || nowISO(),
          source: "camera",
          proof_type: captureMeta.proof_type || "live_field_proof",
          device_user_agent: captureMeta.device_user_agent || navigator.userAgent || "",
        });
        state.map._pendingPhotoCapture = null;
        renderMapFieldPendingProofs();
      }
    });
  }
