// ============================================================
// LIVE BOARD
// ============================================================
let lbMessages = [];
let lbChannel = null;

async function loadLiveBoard(){
  if (!state.client || !state.user || isDemo) return;
  try {
    const { data } = await state.client
      .from("messages")
      .select("id, sender_id, body, created_at, channel, recipient_id")
      .eq("channel", "BOARD")
      .order("created_at", { ascending: false })
      .limit(30);
    lbMessages = (data || []).reverse();
    const senderIds = [...new Set(lbMessages.map(m => m.sender_id))];
    if (senderIds.length) {
      const { data: profiles } = await state.client
        .from("profiles")
        .select("id, display_name")
        .in("id", senderIds);
      (profiles || []).forEach(p => {
        if (p?.id) state.map.userNames = state.map.userNames || new Map();
        state.map.userNames?.set(p.id, p.display_name || "");
      });
    }
    renderLiveBoard();
  } catch(e) {
    dlog("[liveboard] load error", e);
  }
}

function renderLiveBoard(){
  const feed = document.getElementById("liveboard-feed");
  if (!feed) return;
  if (!lbMessages.length) {
    feed.innerHTML = `<span class="liveboard-feed-msg"><span class="liveboard-msg-body" style="color:rgba(140,180,150,0.5);">No messages yet — say something!</span></span>`;
    return;
  }
  const html = lbMessages.slice(-15).map(msg => {
    const name = state.map?.userNames?.get(msg.sender_id) || "User";
    const body = String(msg.body || "").slice(0, 120);
    return `<span class="liveboard-feed-msg"><span class="liveboard-msg-name">${escapeHtml(name)}:</span><span class="liveboard-msg-body">${escapeHtml(body)}</span></span>`;
  }).join("");
  feed.innerHTML = html;
}

async function sendLiveBoardMessage(){
  const input = document.getElementById("liveboardInput");
  const modeEl = document.getElementById("liveboardMode");
  const recipientEl = document.getElementById("liveboardRecipient");
  if (!input || !state.client || !state.user) return;
  const body = String(input.value || "").trim();
  if (!body) return;
  const mode = modeEl?.value || "board";
  const recipientId = mode === "dm" ? String(recipientEl?.value || "").trim() : null;
  if (mode === "dm" && !recipientId) {
    alert("Select a recipient for direct messages.");
    return;
  }
  const orgId = typeof getMessageOrgId === "function" ? getMessageOrgId() : null;
  const payload = {
    sender_id: state.user.id,
    channel: mode === "dm" ? "DM" : "BOARD",
    body,
    org_id: orgId || null,
    project_id: state.activeProject?.id || null,
  };
  if (mode === "dm") payload.recipient_id = recipientId;
  try {
    const { error } = await state.client.from("messages").insert(payload);
    if (error) { dlog("[liveboard] send error", error); return; }
    input.value = "";
    await loadLiveBoard();
  } catch(e) {
    dlog("[liveboard] send exception", e);
  }
}

function subscribeLiveBoard(){
  if (!state.client || lbChannel) return;
  lbChannel = state.client
    .channel("liveboard-messages")
    .on("postgres_changes", {
      event: "INSERT",
      schema: "public",
      table: "messages",
      filter: "channel=eq.BOARD",
    }, (payload) => {
      lbMessages.push(payload.new);
      if (lbMessages.length > 30) lbMessages.shift();
      renderLiveBoard();
    })
    .subscribe();
}

function subscribeTeamLocations(){
  if (!state.client || state._teamLocChannel) return;
  state._teamLocChannel = state.client
    .channel("team-locations")
    .on("postgres_changes", {
      event: "*",
      schema: "public",
      table: "user_locations",
    }, () => {
      refreshTeamLocations();
    })
    .subscribe();
}

async function populateLiveBoardRecipients(){
  const sel = document.getElementById("liveboardRecipient");
  if (!sel || !state.client || !state.user) return;
  try {
    const { data: profiles } = await state.client
      .from("profiles")
      .select("id, display_name")
      .neq("id", state.user.id);
    if (!profiles?.length) return;
    // Keep first blank option, rebuild rest
    while (sel.options.length > 1) sel.remove(1);
    profiles.forEach(p => {
      const name = p.display_name || "Unknown";
      const shortId = p.id.slice(0, 8) + "…";
      if (p.id) state.messageIdentityMap.set(p.id, name);
      const opt = document.createElement("option");
      opt.value = p.id;
      opt.textContent = `${name} (${shortId})`;
      opt.title = p.id;
      sel.appendChild(opt);
    });
  } catch(e) { dlog("[liveboard] recipients error", e); }
}

function initLiveBoardUI(){
  const lb = document.getElementById("liveboard");
  if (lb) lb.style.removeProperty("display");
  const sendBtn = document.getElementById("btnLiveboardSend");
  const input = document.getElementById("liveboardInput");
  const modeEl = document.getElementById("liveboardMode");
  const recipientSel = document.getElementById("liveboardRecipient");
  const myIdBtn = document.getElementById("btnMyId");

  if (sendBtn) sendBtn.addEventListener("click", sendLiveBoardMessage);
  if (input) input.addEventListener("keydown", e => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); sendLiveBoardMessage(); }
  });
  if (modeEl && recipientSel) {
    modeEl.addEventListener("change", () => {
      const isDm = modeEl.value === "dm";
      recipientSel.style.display = isDm ? "" : "none";
      if (isDm) populateLiveBoardRecipients();
    });
  }

  if (myIdBtn) {
    myIdBtn.addEventListener("click", () => {
      const uid = state.user?.id || "";
      if (!uid) return;
      navigator.clipboard.writeText(uid).then(() => {
        myIdBtn.textContent = "COPIED!";
        myIdBtn.classList.add("copied");
        setTimeout(() => {
          myIdBtn.textContent = "MY ID";
          myIdBtn.classList.remove("copied");
        }, 2000);
      }).catch(() => {
        prompt("Your User ID (copy this):", uid);
      });
    });
  }

  const menuUploadBtn = document.getElementById("btnMenuUploadProject");
  if (menuUploadBtn) {
    menuUploadBtn.addEventListener("click", () => {
      const uploadInput = document.getElementById("kmzUploadInput") || document.querySelector('input[type="file"][accept*="kmz"]');
      if (uploadInput) uploadInput.click();
      const menu = document.getElementById("menuModal");
      if (menu) menu.style.display = "none";
    });
  }
}

// ============================================================
// REALTIME PRESENCE — who's online right now
// ============================================================
let _presenceChannel = null;

function renderOnlineUsers(presenceState){
  const rail = document.getElementById("online-users-rail");
  const badge = document.getElementById("online-count-badge");
  const recipientSel = document.getElementById("liveboardRecipient");
  if (!rail) return;

  const entries = Object.values(presenceState || {}).flat();
  const myId = state.user?.id || "";

  // Sort: me first, then alphabetical
  entries.sort((a, b) => {
    if (a.user_id === myId) return -1;
    if (b.user_id === myId) return 1;
    return (a.display_name || "").localeCompare(b.display_name || "");
  });

  if (badge) badge.textContent = `${entries.length} online`;

  rail.innerHTML = entries.map(u => {
    const isMe = u.user_id === myId;
    const name = escapeHtml(u.display_name || "User");
    const role = escapeHtml(u.role || "");
    const shortRole = role.slice(0, 10);
    return `<button class="online-chip${isMe ? " is-me" : ""}" type="button"
        data-uid="${escapeHtml(u.user_id)}"
        data-name="${name}"
        title="${name}${role ? " · " + role : ""}${isMe ? " (You)" : " — click to DM"}">
      <span class="online-chip-dot"></span>
      <span class="online-chip-name">${name}${isMe ? " ✦" : ""}</span>
      ${shortRole ? `<span class="online-chip-role">${shortRole}</span>` : ""}
    </button>`;
  }).join("");

  // Click chip → switch to DM and pre-select that user
  rail.querySelectorAll(".online-chip").forEach(chip => {
    chip.addEventListener("click", () => {
      const uid = chip.dataset.uid;
      const name = chip.dataset.name;
      if (uid === myId) return; // clicking yourself does nothing
      const modeEl = document.getElementById("liveboardMode");
      if (modeEl) {
        modeEl.value = "dm";
        modeEl.dispatchEvent(new Event("change"));
      }
      if (recipientSel) {
        // Ensure option exists
        let opt = recipientSel.querySelector(`option[value="${uid}"]`);
        if (!opt) {
          opt = document.createElement("option");
          opt.value = uid;
          opt.textContent = `${name} (${uid.slice(0,8)}…)`;
          recipientSel.appendChild(opt);
        }
        recipientSel.value = uid;
        recipientSel.style.display = "";
      }
      const input = document.getElementById("liveboardInput");
      if (input) input.focus();
    });
  });

  // Also keep recipient dropdown in sync with who's online
  if (recipientSel) {
    const existing = new Set(Array.from(recipientSel.options).map(o => o.value));
    entries.forEach(u => {
      if (u.user_id === myId) return;
      if (!existing.has(u.user_id)) {
        const opt = document.createElement("option");
        opt.value = u.user_id;
        opt.textContent = `${u.display_name || "User"} (${u.user_id.slice(0,8)}…)`;
        recipientSel.appendChild(opt);
      }
    });
  }
}

async function subscribePresence(){
  if (!state.client || !state.user) return;
  if (_presenceChannel) return;

  const myName = state.profile?.display_name || state.user.email || "User";
  const myRole = state.profile?.role || "";

  _presenceChannel = state.client.channel("room:speccom-online", {
    config: { presence: { key: state.user.id } },
  });

  _presenceChannel
    .on("presence", { event: "sync" }, () => {
      renderOnlineUsers(_presenceChannel.presenceState());
    })
    .on("presence", { event: "join" }, () => {
      renderOnlineUsers(_presenceChannel.presenceState());
    })
    .on("presence", { event: "leave" }, () => {
      renderOnlineUsers(_presenceChannel.presenceState());
    })
    .subscribe(async (status) => {
      if (status === "SUBSCRIBED") {
        await _presenceChannel.track({
          user_id: state.user.id,
          display_name: myName,
          role: myRole,
          online_at: new Date().toISOString(),
        });
      }
    });
}
